
/* ============ helpers ============ */
const $ = (s, r=document) => r.querySelector(s);
const $$ = (s, r=document) => [...r.querySelectorAll(s)];
window.addEventListener('keydown', e => { try { glbKey(e); } catch(err){} }, true);   /* The Grand's photo viewer sits above every layer, so its keys go first (glbKey: "The Grand as it really is") */
const uid = () => Math.random().toString(36).slice(2, 9);
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const r1 = v => Math.round(v * 100) / 100;
function hexToRgb(h){ h = String(h||'#888').replace('#',''); if(h.length===3) h = h.split('').map(c=>c+c).join(''); const n = parseInt(h,16)||0; return [n>>16&255, n>>8&255, n&255]; }
function shade(h, amt){ const f = v => Math.round(amt < 0 ? v*(1+amt) : v + (255-v)*amt); return '#' + hexToRgb(h).map(v => clamp(f(v),0,255).toString(16).padStart(2,'0')).join(''); }
function lum(h){ const [r,g,b] = hexToRgb(h).map(v => { v/=255; return v <= .03928 ? v/12.92 : ((v+.055)/1.055)**2.4; }); return .2126*r + .7152*g + .0722*b; }
const edgeOf = c => lum(c) > .3 ? shade(c,-.28) : shade(c,.28);
function rng(seed){ let a = seed >>> 0; return () => { a |= 0; a = a + 0x6D2B79F5 | 0; let t = Math.imul(a ^ a >>> 15, 1 | a); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }; }
const deg = d => d * Math.PI / 180;
const isoLocal = (d = new Date()) => d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
