function bloom(x, y, r, c){ return `<circle cx="${r1(x)}" cy="${r1(y)}" r="${r1(r)}" fill="${c}" stroke="${shade(c,-.18)}" stroke-width=".2"/><circle cx="${r1(x)}" cy="${r1(y)}" r="${r1(r*.58)}" fill="${shade(c,-.07)}"/><circle cx="${r1(x)}" cy="${r1(y)}" r="${r1(r*.22)}" fill="${shade(c,-.25)}"/>`; }
