  s += `<circle r="${r + drape}" fill="${shade(L.cloth,-.14)}"/>`;
  for(let i=0;i<48;i++){ const a = deg(i*7.5); s += `<path d="M${r1(r*Math.cos(a))} ${r1(r*Math.sin(a))}L${r1((r+drape)*Math.cos(a))} ${r1((r+drape)*Math.sin(a))}" stroke="${shade(L.cloth,-.26)}" stroke-width=".5"/>`; }
