/* a guest's dietary tags and notes in one line, for the kitchen */
function dietOf(g){ return [...(g.dietTags || []).map(t => DIET_TAGS[t] || t), (g.diet || '').trim()].filter(Boolean).join(', '); }
function orderText(o){
  const sm = seatMap(), L = [];
  L.push(state.event.name, `${fmtDate(state.event.date)} · ${state.event.venue}`, `${state.guests.filter(g => g.rsvp !== 'no').length} attending guests · ${o.seats} chairs`, '');
  L.push('LINENS (need / in stock)'); o.linens.forEach(l => L.push(`  ${l.qty} × ${l.label}, ${l.size}${l.spare ? ` (incl. ${l.spare} spare)` : ''}  [stock ${l.have}${l.have < l.qty ? ', SHORT ' + (l.qty - l.have) : ''}]`));
  L.push('', 'TABLES'); Object.entries(o.furniture).forEach(([k,v]) => L.push(`  ${v} × ${k}`));
  L.push('', 'CHAIRS'); Object.entries(o.chairs).forEach(([k,v]) => L.push(`  ${v} × ${k}`));
  L.push('', 'TABLETOP'); Object.entries(o.table).forEach(([k,v]) => L.push(`  ${v} × ${k}`));
  L.push('', 'FLORALS & DÉCOR'); Object.entries(o.decor).forEach(([k,v]) => L.push(`  ${v} × ${k}`));
  L.push(orderExtrasText());
  L.push('', 'MEALS'); MEALS.forEach(m => L.push(`  ${m}: ${o.meals[m]}`)); L.push(`  Not chosen: ${o.meals['']}`); if(o.mealOff) L.push(`  (includes ${o.mealOff} whose pick is no longer on the menu)`);
  { const dg = state.guests.filter(g => g.rsvp !== 'no' && dietOf(g)); if(dg.length){ const tl = new Map(sortedTables().map(t => [t.id, tableLabel(t)])); L.push('', 'DIETARY & ALLERGIES'); dg.forEach(g => L.push(`  ${g.name}${tl.get(g.tableId) ? ' (' + tl.get(g.tableId) + ')' : ''}: ${dietOf(g)}`)); } }
  L.push('', 'SEATING'); sortedTables().filter(t => t.seats).forEach(t => { L.push(`  ${tableLabel(t)}`); for(let i=0;i<t.seats;i++){ const g = sm.get(t.id + ':' + i); L.push(`    ${i+1}. ${g ? g.name + (g.meal ? ' (' + g.meal + ')' : '') : '—'}`); } });
  return L.join('\n');
}

/* ============ inventory ============ */
