  { const rv = other ? eventsAround(invDate) : reservingEvents(); if(rv.length) $('#inv-sub').textContent += ` ${rv.length} other event${rv.length > 1 ? 's' : ''} ${rv.length > 1 ? 'have' : 'has'} linens out ${other ? 'on ' + shortFmt(invDate) : 'while this event does'} (rental window plus ${laundryDays()} laundry day${laundryDays() === 1 ? '' : 's'}): ${rv.map(e => e.name).join(', ')}.`; }
