  { const keepFab = $('#ia-fab').value; $('#ia-fab').innerHTML = Object.entries(INV_FABRICS[cat]).map(([k,v]) => `<option value="${k}"${k === keepFab ? ' selected' : ''}>${v}</option>`).join(''); }
