  if(name === 'dance'){ const d = state.items.find(i => i.type === 'dance'); if(!d) return camTarget('overview'); return {theta:V.orbit.theta + .9, phi:1.2, r:Math.max(d.w, d.h)*1.15, tx:d.x - W/2, ty:2.5, tz:d.y - H/2}; }
