  if(name === 'guest'){
    const ts = tables().filter(t => t.seats && t.type !== 'sweet'); if(!ts.length) return camTarget('entrance');
    const t = ts[V.guestIdx++ % ts.length], p = seatPositions(t)[0], w = worldPt(t, p);
    const focus = state.items.find(i => i.kind === 'fixture' && i.type === 'dance') || state.items.find(i => i.type === 'sweet') || {x:W/2, y:H/2};
    const cx = w.x - W/2, cz = w.y - H/2; const ow = worldPt(t, {x:p.x*1.25, y:p.y*1.25}); return fromTo(ow.x - W/2, 4.3, ow.y - H/2, (t.x - W/2)*.55 + (focus.x - W/2)*.45, 2.6, (t.y - H/2)*.55 + (focus.y - H/2)*.45);
  }
  return {theta:-.62, phi:1.04, r:S*.98, tx:W*.04, ty:-1, tz:H*.08};
