$('#v-amb').addEventListener('click', e => { const b = e.target.closest('[data-amb]'); if(!b) return; mutate(() => vset().amb = b.dataset.amb); visionBuild(); });
$('#v-up').addEventListener('click', e => { const b = e.target.closest('[data-up]'); if(!b) return; mutate(() => vset().up = b.dataset.up); visionBuild(); });
$('#v-cam').addEventListener('click', e => { const b = e.target.closest('[data-cam]'); if(!b || !V) return; stopSpin(); camPreset(b.dataset.cam); });
$('#v-show').onchange = e => { if(!V) return; V.spin = e.target.checked; if(V.spin) camPreset('overview'); };
$('#v-labels').onchange = e => { if(!V) return; V.labels = e.target.checked; visionBuild(); };
$('#v-lights').onchange = e => { mutate(() => vset().lights = e.target.checked); visionBuild(); };
$('#v-full').onclick = () => { const el = $('#view-vision'); if(document.fullscreenElement){ document.exitFullscreen?.(); return; } const p = el.requestFullscreen?.(); if(p && p.catch) p.catch(() => toast('Full screen isn’t available in this window')); else if(!p) toast('Full screen isn’t available in this window'); };
$('#v-setting').onchange = e => { applySetting(e.target.value); visionBuild(); };
$('#v-guests').onchange = e => { mutate(() => vset().guests = e.target.checked); visionBuild(); };
$('#v-tour').onclick = () => { if(V && V.tour) stopTour(); else startTour(); };
$('#v-to-plan').onclick = () => switchView('floor');

