function bdShapePath(B, x0, y0, W, Hh){
  switch(B.shape){
    case 'arch': { const r = Math.min(W/2, Hh); return `M${x0} ${y0+Hh}V${y0+r}A${r} ${r} 0 0 1 ${x0+W} ${y0+r}V${y0+Hh}Z`; }
    case 'moongate': { const r = Math.min(W, Hh)/2, cx = x0 + W/2, cy = y0 + Hh - r; return `M${cx-r} ${cy}A${r} ${r} 0 1 1 ${cx+r} ${cy}A${r} ${r} 0 1 1 ${cx-r} ${cy}Z`; }
    case 'hex': return `M${x0} ${y0+Hh}V${y0+Hh*.28}L${x0+W/2} ${y0}L${x0+W} ${y0+Hh*.28}V${y0+Hh}Z`;
    case 'triple': { const g = W*.02, sw = W*.31, cw = W - 2*sw - 2*g, sh = Hh*.8; const arch = (x, w, h) => { const r = w/2; return `M${x} ${y0+Hh}V${y0+Hh-h+r}A${r} ${r} 0 0 1 ${x+w} ${y0+Hh-h+r}V${y0+Hh}Z`; }; return arch(x0, sw, sh) + arch(x0+sw+g, cw, Hh) + arch(x0+W-sw, sw, sh); }
    default: return `M${x0} ${y0}H${x0+W}V${y0+Hh}H${x0}Z`;
  }
}
function bdOutline(B, x0, y0, W, Hh){
  let pts = []; const arc = (cx, cy, r, a0, a1, n = 48) => { for(let i=0;i<=n;i++){ const a = a0 + (a1 - a0)*i/n; pts.push([cx + r*Math.cos(a), cy + r*Math.sin(a)]); } };
  switch(B.shape){
    case 'arch': { const r = Math.min(W/2, Hh); pts.push([x0, y0+Hh]); arc(x0+W/2, y0+r, r, Math.PI, Math.PI*2); pts.push([x0+W, y0+Hh]); break; }
    case 'moongate': { const r = Math.min(W, Hh)/2; arc(x0+W/2, y0+Hh-r, r, Math.PI/2 + .3, Math.PI*2.5 - .3, 90); break; }
    case 'hex': pts = [[x0, y0+Hh], [x0, y0+Hh*.28], [x0+W/2, y0], [x0+W, y0+Hh*.28], [x0+W, y0+Hh]]; break;
    case 'triple': { const g = W*.02, sw = W*.31, cw = W - 2*sw - 2*g, sh = Hh*.8; [[x0, sw, sh], [x0+sw+g, cw, Hh], [x0+W-sw, sw, sh]].forEach(([x, w, h], i) => { const r = w/2; if(i === 0) pts.push([x, y0+Hh]); pts.push([x, y0+Hh-h+r]); arc(x+r, y0+Hh-h+r, r, Math.PI, Math.PI*2, 24); }); pts.push([x0+W, y0+Hh]); break; }
    default: pts = [[x0, y0+Hh], [x0, y0], [x0+W, y0], [x0+W, y0+Hh]];
  }
  const L = [0]; for(let i=1;i<pts.length;i++) L.push(L[i-1] + Math.hypot(pts[i][0]-pts[i-1][0], pts[i][1]-pts[i-1][1]));
  const len = L[L.length-1];
  return {len, at(t){ const d = clamp(t,0,1)*len; let i = 1; while(i < L.length-1 && L[i] < d) i++; const f = (d - L[i-1]) / ((L[i] - L[i-1]) || 1); return [pts[i-1][0] + (pts[i][0]-pts[i-1][0])*f, pts[i-1][1] + (pts[i][1]-pts[i-1][1])*f]; }};
}
function bdBloom(x, y, r, c){ const e = shade(c, -.16); return `<circle cx="${r1(x)}" cy="${r1(y)}" r="${r1(r)}" fill="${c}" stroke="${e}" stroke-width="${r1(r*.06)}"/><circle cx="${r1(x - r*.06)}" cy="${r1(y - r*.06)}" r="${r1(r*.62)}" fill="${shade(c,-.07)}"/><circle cx="${r1(x - r*.04)}" cy="${r1(y - r*.04)}" r="${r1(r*.3)}" fill="${shade(c,-.18)}"/><path d="M${r1(x - r*.45)} ${r1(y + r*.1)}q${r1(r*.45)} ${r1(-r*.5)} ${r1(r*.9)} 0" fill="none" stroke="${e}" stroke-width="${r1(r*.05)}"/>`; }
