  if(B.light) defs += `<radialGradient id="${id}-up"><stop offset="0" stop-color="${B.light}" stop-opacity=".75"/><stop offset="1" stop-color="${B.light}" stop-opacity="0"/></radialGradient><linearGradient id="${id}-wash" x1="0" y1="1" x2="0" y2="0"><stop offset="0" stop-color="${B.light}" stop-opacity=".55"/><stop offset=".55" stop-color="${B.light}" stop-opacity="0"/></linearGradient>`;
  if(B.pattern !== 'none') defs += bdPatternDef(B.pattern, B.pcolor, (B.pscale || 1)*u, id + '-pat');
  let back = '', body = '', front = '', top = '';
  if(mode === 'scene'){
    back += `<ellipse cx="${SW/2}" cy="${G}" rx="${W*.62}" ry="${u*.45}" fill="#000" opacity=".22"/>`;
    if(B.light) [x0 + W*.18, x0 + W*.82].forEach(x => back += `<ellipse cx="${x}" cy="${G - u}" rx="${u*2.6}" ry="${u*4.5}" fill="url(#${id}-up)"/>`);
    if((B.floor || []).includes('rug')) back += `<ellipse cx="${SW/2}" cy="${G + u*.45}" rx="${W*.48}" ry="${u*.75}" fill="${c3}" opacity=".7"/><ellipse cx="${SW/2}" cy="${G + u*.45}" rx="${W*.44}" ry="${u*.62}" fill="none" stroke="${shade(c3,-.2)}" stroke-width=".5" stroke-dasharray="1.5 1.2"/>`;
  }
