function tentStructure(G, W, H, peak, amb){
  const eave = 8, long = W >= H, n = Math.max(1, Math.round((long ? W : H) / (long ? H : W)));
  const cloth = new THREE.MeshStandardMaterial({color:lin('#fbf8f1'), roughness:1, side:THREE.DoubleSide, transparent:true, opacity:.94, emissive:lin(amb === 'candle' ? '#4a3418' : '#000000'), emissiveIntensity:amb === 'candle' ? .6 : 0});
  for(let i=0;i<n;i++){ const cone = new THREE.Mesh(geo('tentCone', () => new THREE.ConeGeometry(Math.SQRT1_2, 1, 4, 1, true)), cloth); cone.rotation.y = Math.PI/4; const sw = long ? W/n : W, sd = long ? H : H/n; cone.scale.set(sw, peak - eave, sd); const cx = long ? -W/2 + (i + .5)*sw : 0, cz = long ? 0 : -H/2 + (i + .5)*sd; cone.position.set(cx, eave + (peak - eave)/2, cz); G.add(cone); const pole = new THREE.Mesh(CYL(.18, .22, peak, 10), std('#d9c9a8', .7)); pole.position.set(cx, peak/2, cz); pole.castShadow = true; G.add(pole); }
  const pm = std('#d9c9a8', .7); const per = (len, fn) => { const k = Math.max(2, Math.round(len/10)); for(let i=0;i<=k;i++) fn(-len/2 + i*len/k); };
  per(W, x => [-H/2, H/2].forEach(z => { const p = new THREE.Mesh(CYL(.12, .14, eave, 8), pm); p.position.set(x, eave/2, z); p.castShadow = true; G.add(p); }));
  per(H, z => [-W/2, W/2].forEach(x => { const p = new THREE.Mesh(CYL(.12, .14, eave, 8), pm); p.position.set(x, eave/2, z); G.add(p); }));
  const val = new THREE.MeshStandardMaterial({color:lin('#fbf8f1'), roughness:1, side:THREE.DoubleSide});
  [[0, -H/2, W, 0], [0, H/2, W, 0], [-W/2, 0, H, 1], [W/2, 0, H, 1]].forEach(([x, z, len, r]) => { const v2 = new THREE.Mesh(new THREE.PlaneGeometry(len, 1.2), val); v2.position.set(x, eave - .5, z); if(r) v2.rotation.y = Math.PI/2; G.add(v2); });
}
