  if(kind === 'chandeliers'){ const gold = std('#c9a24a', .25, .9), pts = [], nx = Math.max(1, Math.round(W/22)), nz = Math.max(1, Math.round(H/22)); for(let i=0;i<nx;i++) for(let j=0;j<nz;j++){ const x = -W/2 + (i + .5)*W/nx, z = -H/2 + (j + .5)*H/nz, y = CH - 4; const c = new THREE.Group(); c.position.set(x, y, z); G.add(c); const rod = new THREE.Mesh(CYL(.04, .04, 3, 6), gold); rod.position.y = 2.5; c.add(rod); [[1.5, 0], [1, .7], [.55, 1.3]].forEach(([r, yy]) => { const t = new THREE.Mesh(geo('tor' + r, () => new THREE.TorusGeometry(r, .06, 8, 36)), gold); t.rotation.x = Math.PI/2; t.position.y = yy; c.add(t); for(let k=0;k<Math.round(r*10);k++){ const a = k/Math.round(r*10)*Math.PI*2; const d = new THREE.Mesh(SPH, basic('#fff6e0')); d.position.set(Math.cos(a)*r, yy - .35, Math.sin(a)*r); d.scale.set(.06, .16, .06); c.add(d); } }); pts.push(x, y + .5, z); } const pg = new THREE.BufferGeometry(); pg.setAttribute('position', new THREE.Float32BufferAttribute(pts, 3)); G.add(new THREE.Points(pg, new THREE.PointsMaterial({map:glowTex(), color:lin('#ffd9a0'), size:9, transparent:true, depthWrite:false, blending:THREE.AdditiveBlending}))); }
  if(kind === 'draped'){ const m = new THREE.MeshStandardMaterial({color:lin('#fbf8f1'), roughness:1, transparent:true, opacity:.8, side:THREE.DoubleSide}); const ends = []; for(let i=0;i<20;i++){ const a = i/20*Math.PI*2; const k = Math.min(W/2/Math.abs(Math.cos(a) || 1e-6), H/2/Math.abs(Math.sin(a) || 1e-6)); ends.push([Math.cos(a)*k, Math.sin(a)*k]); } ends.forEach(([ex, ez]) => { const mid = new THREE.Vector3(ex*.5, CH - 3.2, ez*.5); const curve = new THREE.QuadraticBezierCurve3(new THREE.Vector3(0, CH - .4, 0), mid, new THREE.Vector3(ex*.98, CH - .6, ez*.98)); const tube = new THREE.Mesh(new THREE.TubeGeometry(curve, 24, 1.1, 8, false), m); tube.scale.y = 1; G.add(tube); }); const c = new THREE.Mesh(SPH, std('#c9a24a', .3, .8)); c.position.y = CH - 1; c.scale.setScalar(.9); G.add(c); }
