    const cluster = (cx, cy, n, sz) => { for(let i=0;i<n;i++){ const s = new THREE.Mesh(SPH, i%3 === 2 ? std('#4d6a46', .9) : std(i%2 ? L0.flower2 : L0.flower1, .8)); s.position.set(cx + (R() - .5)*sz, cy + (R() - .5)*sz, (R() - .5)*.8); s.scale.setScalar(.22 + R()*.18); s.castShadow = true; g.add(s); } };
