    if(d === 'florals'){ for(let k=0;k<7;k++){ const b = new THREE.Mesh(SPH, k%3 === 2 ? std('#4d6a46', .9) : std(k%2 ? L0.flower2 : L0.flower1, .8)); b.position.set(x + (R() - .5)*.8, .25 + R()*.3, z + (R() - .5)*.8); b.scale.setScalar(.22 + R()*.12); b.castShadow = true; g.add(b); } }
