    if(d === 'candles') [[0, 1.6], [.35, 1.1], [-.3, .7]].forEach(([o, h]) => { const c = new THREE.Mesh(CYL(.16, .16, h, 12), std('#f6efe0', .6)); c.position.set(x + o*side, h/2, z + o); g.add(c); flames.push([g, new THREE.Vector3(x + o*side, h + .08, z + o)]); });
