const BUDGET_CATS = ['Venue','Rentals','Linens','Tabletop','Florals & décor','Backdrops & ceremony','Catering','Cake & bar','Entertainment & lighting','Add-ons & experiences','Vendors','Other'];
const CAT_COLORS = ['#d4b46e','#d98f97','#8fae8b','#7f9cc0','#9a6c94','#c47a54','#6f7f8f','#e0a96d','#c9b08f','#5fa8a0','#b7a4d8','#9c9a94'];
