  'venue:fee':0, 'tent':3.5, 'table:r48':12, 'table:r60':14, 'table:r72':16, 'table:b6':11, 'table:b8':12, 'table:sq':14, 'table:head':12, 'table:sweet':45, 'table:cocktail':18,
