  const chipsC = (key, map) => `<div class="chips">${Object.entries(map).map(([k,v]) => `<button class="chip" data-ck="${key}" data-cv="${k}" aria-pressed="${c[key] === k}">${esc(Array.isArray(v) ? v[0] : v)}</button>`).join('')}</div>`;
