const ADDON_ICONS = {
  'Wow moments':'<path d="M12 2l2.2 6.6H21l-5.5 4 2.1 6.6L12 15.2l-5.6 4 2.1-6.6L3 8.6h6.8z"/>',
  'Entertainment':'<path d="M9 18V6l11-2v12"/><circle cx="6" cy="18" r="3"/><circle cx="17" cy="16" r="3"/>',
  'Food & drink stations':'<path d="M4 11h16M5 11a7 7 0 0114 0M3 15h18M8 19h8"/>',
  'Guest comfort':'<path d="M12 21s-7-4.5-7-10a4 4 0 017-2.6A4 4 0 0119 11c0 5.5-7 10-7 10z"/>',
};
const addons = () => (state.addons ||= {projector:{}, pinspot:{}});
const addonOn = k => !!(state.addons && state.addons[k]);
function addonQty(k){ const A = ADDONS[k], s = addons()[k] || {}, guests = state.guests.filter(g => g.rsvp !== 'no').length; switch(A.model){ case 'unit': return [+s.qty || A.qty, A.unit + 's']; case 'hour': return [+s.hours || A.hours, 'hours']; case 'guest': return [guests, 'guests']; case 'table': return [tables().filter(t => (state.looks.find(l => l.id === t.lookId) || state.looks[0]).centerpiece !== 'none').length, 'tables']; case 'letters': return [String((addons().marquee || {}).text || defaultMarquee()).replace(/\s/g, '').length, 'letters']; case 'sqft': { const d = state.items.find(i => i.type === 'dance'); return [d ? d.w*d.h : 0, 'sq ft']; } default: return [1, 'flat']; } }
function addonPrice(k){ return state.budget?.prices?.['addon:' + k] ?? ADDONS[k].price; }
function addonCost(k){ const [q] = addonQty(k); return q*addonPrice(k); }
function addonLines(){ return Object.keys(addons()).filter(k => ADDONS[k]).map(k => { const [q, u] = addonQty(k); return {k, label:ADDONS[k].label, qty:q, unit:u, price:addonPrice(k)}; }); }
function toggleAddon(k){
  const A = ADDONS[k], on = addonOn(k);
  mutate(() => {
    if(on){ delete addons()[k]; if(state.timeline) state.timeline = state.timeline.filter(x => x.addon !== k); }
    else { addons()[k] = {}; if(A.cue && state.timeline){ const t = state.timeline.find(x => x.title.toLowerCase().includes(A.cue.toLowerCase())); state.timeline.push({id:uid(), time: t ? t.time : '19:30', dur:A.dur || 10, title:A.label, type:'reception', who:'Coordinator', where:'', addon:k}); } }
  });
}
let addonCat = 'all';
function renderAddons(seg){
  const sel = Object.keys(addons()).filter(k => ADDONS[k]), total = sel.reduce((a, k) => a + addonCost(k), 0), outdoor = isOutdoor();
  $('#menu-controls').innerHTML = `${seg}<span class="eyebrow">Add-ons &amp; experiences</span>
    <section class="ctl"><h3>Browse</h3><div class="chips">${['all', ...ADDON_CATS].map(c => `<button class="chip" data-acat="${c}" aria-pressed="${addonCat === c}">${c === 'all' ? 'Everything' : esc(c)}</button>`).join('')}</div></section>
    <section class="ctl"><h3>Your add-ons</h3>${sel.length ? `<ul class="task-list">${sel.map(k => `<li><span>${esc(ADDONS[k].label)}</span><span class="task-meta"><span class="mono">${money(addonCost(k))}</span><button class="x" data-aon="${k}" aria-label="Remove ${esc(ADDONS[k].label)}">×</button></span></li>`).join('')}<li><b>Total</b><b class="mono">${money(total)}</b></li></ul>` : '<p class="muted">Nothing added yet. Pick experiences on the right.</p>'}
      <p class="muted" style="font-size:12px">Add-ons with a cue are added to the run of show, and all of them go in the budget. Fog, sparks, projection and the LED floor also show in the Vision.</p></section>`;
  const list = Object.entries(ADDONS).filter(([, A]) => addonCat === 'all' || A.cat === addonCat);
  $('#menu-preview').innerHTML = `<div class="pv-head"><div><span class="eyebrow">Add-ons · ${sel.length} chosen</span><h2>${money(total)}</h2></div>${sel.some(k => ADDONS[k].fx) ? '<button class="btn" data-ato="vision">See it in the Vision</button>' : ''}</div>
    ${ADDON_CATS.filter(c => list.some(([, A]) => A.cat === c)).map(c => `<h3 class="addon-cat"><svg viewBox="0 0 24 24" aria-hidden="true">${ADDON_ICONS[c]}</svg>${esc(c)}</h3><div class="addon-grid">${list.filter(([, A]) => A.cat === c).map(([k, A]) => { const on = addonOn(k), [q, u] = addonQty(k), s = addons()[k] || {}; return `<div class="addon${on ? ' on' : ''}">
      <div class="addon-top"><b>${esc(A.label)}</b><button class="addon-toggle" data-aon="${k}" aria-pressed="${on}" aria-label="${on ? 'Remove' : 'Add'} ${esc(A.label)}">${on ? 'Added' : 'Add'}</button></div>
      <p>${esc(A.desc)}</p>${addonExtra(k, on)}
      ${A.outdoor && !outdoor ? '<span class="pill caution">Best for outdoor venues</span>' : ''}
      <div class="addon-foot">${A.model === 'unit' || A.model === 'hour' ? `<label class="addon-q"><input type="number" min="1" max="${A.model === 'hour' ? 12 : 20}" data-aq="${k}" data-af="${A.model === 'unit' ? 'qty' : 'hours'}" value="${A.model === 'unit' ? (+s.qty || A.qty) : (+s.hours || A.hours)}" aria-label="${A.model === 'unit' ? 'How many' : 'Hours'}"> ${A.model === 'unit' ? esc(A.unit) + 's' : 'hours'}</label>` : `<span class="muted">${A.model === 'flat' ? 'Flat rate' : `${q.toLocaleString()} ${u}`}</span>`}
        <span class="addon-price"><label class="bu-money">$<input class="qty-in" type="number" min="0" step="0.5" data-aprice="${k}" value="${addonPrice(k)}" aria-label="Price"></label><small>${({flat:'', unit:'/' + (A.unit || 'each'), hour:'/hour', guest:'/guest', sqft:'/sq ft', letters:'/letter', table:'/table'})[A.model]}</small></span></div>
      ${on ? `<div class="addon-total">${money(addonCost(k))}${A.cue ? ` · cued at “${esc(A.cue)}”` : ''}</div>` : ''}</div>`; }).join('')}</div>`).join('')}`;
}
$('#view-menu').addEventListener('click', e => {
  const hq = e.target.closest('[data-hq]'); if(hq){ mutate(() => hors()[hq.dataset.hq] = hq.dataset.hv); renderMenu(); return; }
  const hi = e.target.closest('[data-hitem]'); if(hi){ const h = hors(), k = hi.dataset.hitem; mutate(() => h.items = h.items.includes(k) ? h.items.filter(x => x !== k) : [...h.items, k]); renderMenu(); return; }
  if(e.target.closest('[data-hcopy]')){ const r = horsCalc(); copyText([`HORS D'OEUVRES · ${state.event.name}`, `${r.guests} guests · ${HORS_STYLE[hors().style][0]} · ${r.total} pieces`, '', ...r.rows.map(x => `${x.pcs} × ${x.label} (${x.pcs/12} dozen)${x.tags ? ' · ' + x.tags : ''}`), '', `${r.servers} ${hors().service === 'passed' ? 'servers' : 'attendants'}`].join('\n'), 'Hors d’oeuvres order copied'); return; }
  const ac = e.target.closest('[data-acat]'); if(ac){ addonCat = ac.dataset.acat; renderMenu(); return; }
  const ao = e.target.closest('[data-aon]'); if(ao){ const k = ao.dataset.aon, was = addonOn(k); toggleAddon(k); renderMenu(); updateTabs(); toast(`${was ? 'Removed' : 'Added'} ${ADDONS[k].label}`); return; }
  if(e.target.closest('[data-ato]')) switchView('vision');
});
$('#view-menu').addEventListener('change', e => {
  const t = e.target;
  if(t.id === 'hq-hours'){ mutate(() => hors().hours = clamp(+t.value || 1, .5, 6)); renderMenu(); }
  if(t.dataset.hprice){ mutate(() => { budget().prices['hors:' + t.dataset.hprice] = Math.max(0, +t.value || 0); }); renderMenu(); }
  if(t.dataset.aprice){ mutate(() => { budget().prices['addon:' + t.dataset.aprice] = Math.max(0, +t.value || 0); }); renderMenu(); updateTabs(); }
  if(t.dataset.aq){ const k = t.dataset.aq; if(!addonOn(k) && ADDONS[k]) toggleAddon(k); mutate(() => { if(!addons()[k]) addons()[k] = {}; addons()[k][t.dataset.af] = clamp(+t.value || 1, 1, t.dataset.af === 'hours' ? 12 : 20); }); renderMenu(); updateTabs(); }
});

/* ---- add-on effects in 3D ---- */
function addLedFloor(f, g){
  const up = effVis().up || '#ad8cf0';
  const tex = canvasTex(256, 256, (x, w) => { const R = rng(8); const n = 8, s = w/n; for(let i=0;i<n;i++) for(let j=0;j<n;j++){ const k = R(); x.fillStyle = k < .35 ? up : k < .6 ? '#ffffff' : k < .8 ? shade(up, -.4) : '#1a1420'; x.fillRect(i*s + 2, j*s + 2, s - 4, s - 4); } }, true);
  tex.repeat.set(f.w/8, f.h/8);
  const m = new THREE.Mesh(new THREE.PlaneGeometry(f.w, f.h), new THREE.MeshStandardMaterial({map:tex, emissiveMap:tex, emissive:lin('#ffffff'), emissiveIntensity:.9, roughness:.3}));
  m.rotation.x = -Math.PI/2; m.position.y = .045; g.add(m);
}
function addonEffects3D(G, W, H){
  V.sparks = null; V.clouds = null;
  const d = state.items.find(i => i.type === 'dance'); if(!d) return;
  const toW = (x, y) => [x - W/2, y - H/2];
  if(addonOn('clouds')){
    const cg = new THREE.Group(), [cx, cz] = toW(d.x, d.y); cg.position.set(cx, 0, cz); cg.rotation.y = -deg(d.rot || 0);
    const m = new THREE.MeshBasicMaterial({color:lin('#f4f2f6'), transparent:true, opacity:.22, depthWrite:false});
    const R = rng(77), n = Math.round(d.w*d.h/6);
    for(let i=0;i<n;i++){ const s = new THREE.Mesh(SPH, m); s.position.set((R() - .5)*d.w*1.05, .3 + R()*.6, (R() - .5)*d.h*1.05); s.scale.set(1.6 + R()*1.8, .35 + R()*.4, 1.6 + R()*1.8); cg.add(s); }
    const pts = []; for(let i=0;i<n*14;i++) pts.push((R() - .5)*d.w*1.1, .1 + R()*.9, (R() - .5)*d.h*1.1);
    const pg = new THREE.BufferGeometry(); pg.setAttribute('position', new THREE.Float32BufferAttribute(pts, 3));
    cg.add(new THREE.Points(pg, new THREE.PointsMaterial({map:glowTex(), color:lin('#ffffff'), size:2.2, transparent:true, opacity:.28, depthWrite:false})));
    G.add(cg); V.clouds = cg;
  }
  if(addonOn('coldsparks')){
    const nF = clamp(+(addons().coldsparks.qty) || 4, 1, 12), per = 160, total = nF*per;
    const origins = []; for(let i=0;i<nF;i++){ const t = i/nF*Math.PI*2 + Math.PI/4, ox = Math.cos(t)*d.w*.55, oz = Math.sin(t)*d.h*.55; const w = worldPt(d, {x:ox, y:oz}); const [x, z] = toW(w.x, w.y); origins.push([x, z]); const base = new THREE.Mesh(BOX(.8,.6,.8), std('#1d1c1e', .4, .5)); base.position.set(x, .3, z); G.add(base); }
    const pos = new Float32Array(total*3), vel = new Float32Array(total*3), R = rng(5);
    const reset = (i, fresh) => { const o = origins[Math.floor(i/per)]; pos[i*3] = o[0]; pos[i*3+1] = .6 + (fresh ? R()*9 : 0); pos[i*3+2] = o[1]; vel[i*3] = (R() - .5)*1.6; vel[i*3+1] = 12 + R()*6; vel[i*3+2] = (R() - .5)*1.6; };
    for(let i=0;i<total;i++) reset(i, true);
    const geom = new THREE.BufferGeometry(); geom.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    const pts = new THREE.Points(geom, new THREE.PointsMaterial({map:glowTex(), color:lin('#ffd27a'), size:.55, transparent:true, depthWrite:false, blending:THREE.AdditiveBlending}));
    G.add(pts); V.sparks = {pts, pos, vel, reset, total, last:0};
  }
}
function updateSparks(t){
  const S = V.sparks, dt = Math.min(.05, S.last ? (t - S.last)/1000 : .016); S.last = t;
  for(let i=0;i<S.total;i++){ S.vel[i*3+1] -= 22*dt; S.pos[i*3] += S.vel[i*3]*dt; S.pos[i*3+1] += S.vel[i*3+1]*dt; S.pos[i*3+2] += S.vel[i*3+2]*dt; if(S.pos[i*3+1] < .5) S.reset(i, false); }
  S.pts.geometry.attributes.position.needsUpdate = true;
}
function orderExtras2HTML(){
  let rows = '';
  if(hasCake()){ const c = cake(); rows += `<tr class="sub"><td colspan="2">Cake</td></tr><tr><td>${c.tiers.length}-tier ${esc(CAKE_FINISH[c.finish][0].toLowerCase())} cake in ${esc(colorName(c.color).toLowerCase())}, ${esc(CAKE_DECOR[c.decor].toLowerCase())}, ${esc(CAKE_STAND[c.stand].toLowerCase())}<br><span class="muted" style="font-size:12px">${c.tiers.map(t => `${t.size}″ ${esc(t.flavor.toLowerCase())} / ${esc(t.filling.toLowerCase())}`).join(' · ')}</span></td><td class="num">${cakeServings(c) + (+c.sheet || 0)} servings</td></tr>`; }
  if(state.bar){ const r = barCalc(); rows += `<tr class="sub"><td colspan="2">Bar · ${esc(BAR_STYLES[bar().style])}</td></tr>` + r.list.filter(l => ['Spirits','Wine & beer','Liqueurs & aperitifs'].includes(l.cat)).map(l => `<tr><td>${esc(l.label)}</td><td class="num">${l.qty} × ${esc(l.unit)}</td></tr>`).join('') + `<tr><td class="muted">Full shopping list on Menu, cake &amp; bar → Bar</td><td class="num">${money(r.cost)}</td></tr>`; }
  if(state.hors){ const r = horsCalc(); rows += `<tr class="sub"><td colspan="2">Hors d’oeuvres</td></tr>` + r.rows.map(x => `<tr><td>${esc(x.label)}</td><td class="num">${x.pcs} pcs</td></tr>`).join(''); }
  const ao = addonLines(); if(ao.length) rows += `<tr class="sub"><td colspan="2">Add-ons</td></tr>` + ao.map(l => `<tr><td>${esc(l.label)}</td><td class="num">${l.unit === 'flat' ? '1' : `${l.qty.toLocaleString()} ${esc(l.unit)}`}</td></tr>`).join('');
  return rows ? `<section class="wide"><h2>Cake, bar, food &amp; add-ons</h2><table class="qty"><tbody>${rows}</tbody></table></section>` : '';
}

/* ============ marquee letters & throne chairs ============ */
ADDONS.marquee = {label:'Marquee light-up letters', cat:'Wow moments', model:'letters', price:65, desc:'4-ft light-up letters and numbers, like LOVE, XV or 2027.', fx:true};
ADDONS.throne = {label:'Throne chairs', cat:'Wow moments', model:'unit', unit:'chair', qty:1, price:275, desc:'Velvet high-back thrones for the honoree, couple or court.', fx:true};
const THRONE_COLORS = {gold:['Ivory & gold','#f3ecdc','#c9a24a'], silver:['White & silver','#fbfbf8','#c3c7ce'], blush:['Blush & rose gold','#ecc9c3','#d4a58a'], noir:['Black & gold','#1d1c1e','#c9a24a'], royal:['Royal red & gold','#6b1f2d','#c9a24a'], navy:['Navy & gold','#1f2a44','#c9a24a']};
const EVENT_TYPES = {wedding:'Wedding', quince:'Quinceañera', corporate:'Corporate', holiday:'Holiday party', graduation:'Graduation', prom:'Prom & school dance', community:'Community event'};
function eventYear(){ const d = eventDate(); return String(d ? d.getFullYear() : new Date().getFullYear() + 1); }
const withYear = t => String(t ?? '').replace(/\b2027\b/g, eventYear());
function defaultMarquee(){ return ({quince:'XV', graduation:eventYear(), prom:'PROM', holiday:'NOEL', corporate:eventYear(), community:'GALA'})[state.eventType] || 'LOVE'; }
function addonExtra(k, on){
  if(k === 'marquee') return `<label class="fld" style="margin:0"><span>Letters</span><input data-mtext="1" value="${esc((addons().marquee || {}).text || defaultMarquee())}" maxlength="12" ${on ? '' : 'disabled'}></label>`;
  if(k === 'throne'){ const c = (addons().throne || {}).color || 'gold'; return `<div class="chips">${Object.entries(THRONE_COLORS).map(([key, [n, a, b]]) => `<button class="chip" data-tcolor="${key}" aria-pressed="${c === key}" ${on ? '' : 'disabled'}><i style="--c:${a};box-shadow:inset 0 0 0 3px ${b}"></i>${n}</button>`).join('')}</div>`; }
  return '';
}
$('#view-menu').addEventListener('input', e => { if(e.target.dataset.mtext && addonOn('marquee')) mutate(() => addons().marquee.text = e.target.value.toUpperCase(), 'mtext'); });
$('#view-menu').addEventListener('change', e => { if(e.target.dataset.mtext) renderMenu(); });
$('#view-menu').addEventListener('click', e => { const t = e.target.closest('[data-tcolor]'); if(t && addonOn('throne')){ mutate(() => addons().throne.color = t.dataset.tcolor); renderMenu(); } });
function marqueeMesh(text){
  const chars = [...text.replace(/\s+/g, ' ')], n = Math.max(1, chars.length), cw = 200, ch = 300;
  const c = document.createElement('canvas'); c.width = cw*n; c.height = ch; const x = c.getContext('2d');
  x.textAlign = 'center'; x.textBaseline = 'middle'; x.font = `900 ${ch*.92}px Manrope, 'Arial Black', sans-serif`;
  chars.forEach((ch1, i) => { x.fillStyle = '#f7f1e6'; x.fillText(ch1, cw*i + cw/2, ch*.54); });
  const img = x.getImageData(0, 0, c.width, ch).data, bulbs = [];
  for(let yy = 14; yy < ch; yy += 26) for(let xx = 14; xx < c.width; xx += 26){ if(img[(yy*c.width + xx)*4 + 3] > 200) bulbs.push([xx, yy]); }
  x.globalCompositeOperation = 'source-atop'; const gr = x.createLinearGradient(0, 0, 0, ch); gr.addColorStop(0, '#fffaf0'); gr.addColorStop(1, '#e6d6b8'); x.fillStyle = gr; x.fillRect(0, 0, c.width, ch);
  x.globalCompositeOperation = 'source-over';
  bulbs.forEach(([bx, by]) => { const g = x.createRadialGradient(bx, by, 0, bx, by, 11); g.addColorStop(0, '#ffffff'); g.addColorStop(.4, '#ffe2a0'); g.addColorStop(1, 'rgba(255,200,110,0)'); x.fillStyle = g; x.beginPath(); x.arc(bx, by, 11, 0, Math.PI*2); x.fill(); });
  const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace;
  const W = 2.6*n, H = 4;
  const m = new THREE.Mesh(new THREE.PlaneGeometry(W, H), new THREE.MeshBasicMaterial({map:t, transparent:true, alphaTest:.1, side:THREE.DoubleSide}));
  const grp = new THREE.Group(); m.position.y = H/2; grp.add(m);
  const pts = []; bulbs.forEach(([bx, by], i) => { if(i % 2) return; pts.push(bx/c.width*W - W/2, H - by/ch*H, .05); });
  const pg = new THREE.BufferGeometry(); pg.setAttribute('position', new THREE.Float32BufferAttribute(pts, 3));
  grp.add(new THREE.Points(pg, new THREE.PointsMaterial({map:glowTex(), color:lin('#ffcf8f'), size:.8, transparent:true, depthWrite:false, blending:THREE.AdditiveBlending})));
  return grp;
}
function throneMesh(colorKey){
  const [, fab, metal] = THRONE_COLORS[colorKey] || THRONE_COLORS.gold, g = new THREE.Group(), gm = std(metal, .3, .85), vm = std(fab, .95);
  const add = (geom, m, x, y, z, rx = 0) => { const o = new THREE.Mesh(geom, m); o.position.set(x, y, z); o.rotation.x = rx; o.castShadow = true; g.add(o); return o; };
  [[-.95,-.85],[.95,-.85],[-.95,.85],[.95,.85]].forEach(([x, z]) => add(CYL(.09,.12,1.5,10), gm, x, .75, z));
  add(BOX(2.1,.3,1.95), gm, 0, 1.55, 0); add(BOX(1.9,.32,1.75), vm, 0, 1.85, -.03);
  add(BOX(2.3,4.4,.32), gm, 0, 4.1, .9); add(BOX(1.95,3.9,.2), vm, 0, 4.05, .76);
  for(let r=0;r<4;r++) for(let c=0;c<3;c++) add(SPH, std(shade(fab,-.25), .8), -.6 + c*.6, 2.7 + r*.85, .65).scale.setScalar(.06);
  const crest = add(geo('crest', () => new THREE.CylinderGeometry(1.15, 1.15, .32, 32, 1, false, 0, Math.PI)), gm, 0, 6.3, .9, Math.PI/2); crest.rotation.z = Math.PI/2; crest.rotation.y = Math.PI/2;
  [-1.1, 0, 1.1].forEach((x, i) => add(SPH, gm, x, i === 1 ? 7.55 : 6.4, .9).scale.setScalar(i === 1 ? .22 : .16));
  [-1.05, 1.05].forEach(x => { add(BOX(.22,.9,1.8), gm, x, 2.35, 0); add(BOX(.3,.15,1.9), vm, x, 2.85, 0); });
  return g;
}
function themedAddons3D(G, W, H){
  const d = state.items.find(i => i.type === 'dance'), toW = (x, y) => [x - W/2, y - H/2];
  if(addonOn('marquee')){
    const text = ((addons().marquee || {}).text || defaultMarquee()).trim() || 'LOVE', mm = marqueeMesh(text);
    let p, rot = 0; if(d){ const w = worldPt(d, {x:0, y:-d.h/2 - 2.2}); p = toW(w.x, w.y); rot = -deg(d.rot || 0); } else p = [0, -H/2 + 6];
    mm.position.set(p[0], 0, p[1]); mm.rotation.y = rot; G.add(mm);
  }
  if(addonOn('throne')){
    const color = (addons().throne || {}).color || 'gold', want = clamp(+(addons().throne.qty) || 1, 1, 6);
    let spots = (V.thronePts || []).slice(0, want);
    if(spots.length < want && d){ for(let i = spots.length; i < want; i++){ const off = (i - (want - 1)/2)*3.2, w = worldPt(d, {x:off, y:-d.h/2 - 5.5}); const [x, z] = toW(w.x, w.y); spots.push([x, z, -deg(d.rot || 0) + Math.PI]); } }
    spots.forEach(([x, z, ry]) => { const t = throneMesh(color); t.position.set(x, 0, z); t.rotation.y = ry; G.add(t); });
  }
}

