function applyEventTheme(type, key, opts){
  const E = ET[type], T = E.themes[key];
  mutate(() => {
    state.eventType = type; state.sample = false; state.themeLabel = T.label; if(state.package && state.package.type !== type){ delete state.package; } pkgType = null;
    state.event.name = opts.name || withYear(E.name); state.event.honoree = opts.honoree || withYear(E.honoree);
    const L = state.looks[0]; Object.assign(L, defaultLook(L.name), {id:L.id, name:T.label}, T.look);
    state.looks = [L].concat(state.looks.slice(1).map(x => Object.assign(x, T.look, {id:x.id, name:x.name})));
    if(state.looks[1]){ state.looks[1].cloth = T.pal[1]; state.looks[1].centerpiece = 'tall'; }
    const v = venue(), S = SETTINGS[T.setting]; if(!(typeof grandRoomFinish === 'function' && grandRoomFinish(v))){ v.setting = T.setting; v.floor = S.floor; if(S.kind === 'indoor'){ v.wall = S.wall; v.ceiling = S.ceiling; } if(S.h) v.ceilingH = S.h; }   /* a room of The Grand keeps its own finishes */
    vset().amb = T.amb; vset().up = T.up; vset().lights = true;
    const bt = JSON.parse(JSON.stringify(BD_THEMES[T.bd])); delete bt.label;
    if(opts.rebuild) buildThemedLayout(type, opts.guests || 100);
    ensureBackdrops();
    const photo = state.items.find(i => i.kind === 'fixture' && (i.type === 'photo' || i.type === 'stage'));
    let B = bdList()[0]; if(!B){ B = newBackdrop(T.bd, 'Photo backdrop'); state.backdrops.push(B); }
    Object.assign(B, bt, T.bdo || {}, {theme:T.bd, signText: type === 'quince' ? `Mis XV ${state.event.honoree}` : state.event.honoree, sign2:shortDate(), placedAt: photo ? photo.id : B.placedAt});
    Object.assign(cake(), T.cake, {topperText: type === 'quince' ? 'XV' : state.event.honoree, topper: type === 'corporate' || type === 'community' ? 'none' : type === 'quince' ? 'monogram' : 'script'});
    const b = bar(); b.title = T.bar; if(T.dry){ b.style = 'dry'; b.mocktail = b.mocktail === 'none' ? 'berry' : b.mocktail; } else if(b.style === 'dry') b.style = 'full';
    state.addons = {}; T.addons.forEach(k => { state.addons[k] = {}; }); if(T.marquee) state.addons.marquee = {text:withYear(T.marquee)}; if(T.throne) state.addons.throne = {color:T.throne, qty:type === 'wedding' ? 2 : 1};
    if(ET_TIMELINE[type]) state.timeline = ET_TIMELINE[type].map(([time, dur, title, tp, who, where]) => ({id:uid(), time, dur, title, type:tp, who:who || '', where:where || ''})).concat(defaultTimeline().filter(x => x.type === 'vendor' || x.type === 'prep'));
    else state.timeline = defaultTimeline();
    T.addons.forEach(k => { const A = ADDONS[k]; if(A && A.cue){ const t = state.timeline.find(x => x.title.toLowerCase().includes(A.cue.toLowerCase().split(' ')[0])); if(t) state.timeline.push({id:uid(), time:t.time, dur:A.dur || 10, title:A.label, type:'reception', who:'Coordinator', where:'', addon:k}); } });
    state.tasks = defaultTasks(); (ET_TASKS[type] || []).forEach((title, i) => state.tasks.push({id:uid(), title, m:[6,4,3,2,1][i] ?? 2, done:false}));
  });
}
function buildThemedLayout(type, guests){
  const per = type === 'corporate' ? 10 : 8, tType = type === 'corporate' ? 'r72' : 'r60', T = TABLE_TYPES[tType];
  const seatedShare = type === 'prom' ? .55 : 1, nTables = Math.max(2, Math.ceil(guests*seatedShare/per));
  let area = nTables*(T.d + 6.5)**2 + (type === 'prom' ? 28*24 : 20*16)*2.2 + 1400 + (type === 'corporate' || type === 'community' ? 400 : 0) + (type === 'prom' ? guests*6 : 0), W = Math.round(Math.sqrt(area*1.45)/2)*2, H = Math.round(area/W/2)*2;
  const items = [], F = (k, x, y, rot = 0, w, h) => { const it = {id:uid(), kind:'fixture', type:k, x, y, rot, w:w ?? FIXTURES[k].w, h:h ?? FIXTURES[k].h, label:FIXTURES[k].label}; items.push(it); return it; };
  const hasDance = type !== 'community' || true, danceW = type === 'prom' ? 28 : type === 'corporate' ? 16 : 20, danceH = type === 'prom' ? 24 : 16;
  const dx = W/2, dy = 6 + danceH/2 + (type === 'corporate' || type === 'community' ? 9 : 2);
  if(type === 'corporate' || type === 'community') F('stage', W/2, 5, 0, 20, 8);
  if(hasDance) F('dance', dx, dy, 0, danceW, danceH);
  F('dj', type === 'corporate' || type === 'community' ? W/2 + 13 : W/2, type === 'corporate' || type === 'community' ? 5 : dy + danceH/2 + 2.5);
  F('bar', W - 2.5, H/2, 90); F('photo', W - 6, H - 6); F('gift', 5, H - 3); F('cake', 4, 4);
  if(type !== 'prom') F('buffet', 2.5, H/2, 90, 12, 3);
  let spots = [];
  for(let tries = 0; tries < 10; tries++){ spots = []; const stepX0 = T.d + 6.5, av0 = items.map(f => ({x:f.x, y:f.y, w:(f.rot ? f.h : f.w)/2 + T.d/2 + 2.8, h:(f.rot ? f.w : f.h)/2 + T.d/2 + 2.8})); for(let y = 5 + T.d; y < H - 4; y += stepX0) for(let x = 5 + T.d; x < W - 5; x += stepX0){ if(av0.some(a => Math.abs(x - a.x) < a.w && Math.abs(y - a.y) < a.h)) continue; spots.push([x, y]); } if(spots.length >= nTables) break; W += 8; H += 6; items.forEach(it => { if(it.type === 'bar'){ it.x = W - 2.5; it.y = H/2; } if(it.type === 'photo'){ it.x = W - 6; it.y = H - 6; } if(it.type === 'gift') it.y = H - 3; if(it.type === 'buffet') it.y = H/2; if(it.type === 'dance' || it.type === 'stage') it.x = W/2; if(it.type === 'dj') it.x = it.x > W/2 - 9 && it.x < W/2 + 20 && items.some(i => i.type === 'stage') ? W/2 + 13 : W/2; }); }
  const stepX = T.d + 6.5, stepY = T.d + 6.5, avoid = items.map(f => ({x:f.x, y:f.y, w:(f.rot ? f.h : f.w)/2 + T.d/2 + 2.8, h:(f.rot ? f.w : f.h)/2 + T.d/2 + 2.8}));
  void avoid; void stepY;
  const ddx = W/2; spots.sort((a, b) => Math.hypot(a[0] - ddx, a[1] - dy) - Math.hypot(b[0] - ddx, b[1] - dy)); void 0 && spots.sort((a, b) => Math.hypot(a[0] - dx, a[1] - dy) - Math.hypot(b[0] - dx, b[1] - dy));
  const look = state.looks[0].id, tablesOut = [];
  if(type === 'wedding') { const sw = {id:uid(), kind:'table', type:'sweet', x:W/2, y:dy - danceH/2 - 4, rot:0, seats:2, number:'', name:'Sweetheart', lookId:state.looks[1]?.id || look}; tablesOut.push(sw); }
  if(type === 'quince') { const sw = {id:uid(), kind:'table', type:'head', x:W/2, y:dy - danceH/2 - 4, rot:0, seats:5, number:'', name:'Quinceañera & court', lookId:state.looks[1]?.id || look}; tablesOut.push(sw); }
  spots.slice(0, nTables).sort((a, b) => (Math.round(a[1]/6) - Math.round(b[1]/6)) || (a[0] - b[0])).forEach(([x, y], i) => tablesOut.push({id:uid(), kind:'table', type:tType, x:r1(x), y:r1(y), rot:0, seats:per, number:String(i + 1), name:'', lookId:look}));
  if(type === 'prom') for(let i=0;i<Math.ceil(guests/14);i++){ const a = i/Math.ceil(guests/14)*Math.PI*2; tablesOut.push({id:uid(), kind:'table', type:'cocktail', x:r1(W/2 + Math.cos(a)*(danceW/2 + 3)), y:r1(dy + Math.sin(a)*(danceH/2 + 3)), rot:0, seats:0, number:'', name:'', lookId:look}); }
  state.items = items.concat(tablesOut); state.room = {w:W, h:H};
  state.guests.forEach(g => { g.tableId = null; g.seat = null; });
  state.backdrops = (state.backdrops || []).map(b => Object.assign(b, {placedAt:''}));
  autoSeat();
}
let themeType = 'wedding', themePick = 'garden';
function openThemes(){
  themeType = state.eventType || 'wedding'; themePick = Object.keys(ET[themeType].themes)[0];
  renderThemes(); $('#themes').hidden = false;
}
function renderThemes(){
  const E = ET[themeType], attending = expectedHeads() || 100;
  $('#themes-body').innerHTML = `<div class="chips th-types">${Object.entries(ET).map(([k, e]) => `<button class="chip" data-ttype="${k}" aria-pressed="${themeType === k}">${esc(e.label)}</button>`).join('')}</div>
    <div class="th-grid">${Object.entries(E.themes).map(([k, T]) => { const B = Object.assign({}, newBackdrop(T.bd), JSON.parse(JSON.stringify(BD_THEMES[T.bd])), T.bdo || {}, {id:'thm' + k, w:8, h:8, signText:withYear(E.honoree), sign2:''}); return `<button class="th-card" data-tpick="${k}" aria-pressed="${themePick === k}">
      <div class="th-art" style="background:linear-gradient(135deg, ${T.pal[0]}, ${T.pal[1]})">${backdropSVG(B, {mode:'export', id:'thm-' + k, dens:.25})}</div>
      <div class="th-pal">${T.pal.map(c => `<i style="background:${c}"></i>`).join('')}</div>
      <b>${esc(T.label)}</b><span>${esc(withYear(T.desc))}</span><small>${esc(SETTINGS[T.setting].label)} · ${T.addons.map(a => ADDONS[a]?.label).filter(Boolean).slice(0, 3).join(', ')}</small></button>`; }).join('')}</div>
    <div class="fld-row th-fields"><label class="fld"><span>Event name</span><input id="th-name" value="${esc(state.eventType === themeType ? state.event.name : withYear(E.name))}"></label><label class="fld"><span>${themeType === 'wedding' ? 'Couple' : themeType === 'quince' ? 'Quinceañera' : themeType === 'graduation' ? 'Graduate or class' : 'Featured name'} (for signs)</span><input id="th-honoree" value="${esc(state.eventType === themeType && state.event.honoree ? state.event.honoree : withYear(E.honoree))}"></label></div>
    <div class="fld-row th-fields"><label class="toggle" style="padding-left:0"><input type="checkbox" id="th-rebuild" ${state.eventType !== themeType ? 'checked' : ''}> Rebuild the floor plan for a ${esc(E.label.toLowerCase())}</label><label class="fld"><span>Guests for the layout</span><input type="number" id="th-guests" min="10" max="1000" value="${attending}"></label></div>`;
}
$('#themes').addEventListener('click', e => {
  if(e.target.id === 'themes') { $('#themes').hidden = true; return; }
  const ty = e.target.closest('[data-ttype]'); if(ty){ themeType = ty.dataset.ttype; themePick = Object.keys(ET[themeType].themes)[0]; renderThemes(); return; }
  const tp = e.target.closest('[data-tpick]'); if(tp){ themePick = tp.dataset.tpick; $$('#themes [data-tpick]').forEach(b => b.setAttribute('aria-pressed', b === tp)); return; }
  if(e.target.id === 'th-cancel'){ $('#themes').hidden = true; return; }
  if(e.target.id === 'th-apply'){
    applyEventTheme(themeType, themePick, {name:$('#th-name').value.trim(), honoree:$('#th-honoree').value.trim(), rebuild:$('#th-rebuild').checked, guests:+$('#th-guests').value || 100});
    $('#themes').hidden = true; sel = null; picked = null; activeLook = state.looks[0].id; activeBd = null; if(V) V.placed = false; viewInit = false; save(); renderAll(); fit(); switchView('vision');
    toast(`${ET[themeType].themes[themePick].label} applied. Ctrl+Z undoes it.`);
  }
});

