let DB = null, USER = null, portalMode = 'local', portalEvents = [], portalUnsub = null, canAdmin = true, clientMode = false, portalQ = '', portalStatus = 'all', portalOpen = null, portalSaving = false, portalSavedAt = 0, portalErr = '', pendingDelete = null, catalogDraft = null;
