const _saveToPortalBs = saveToPortal; saveToPortal = async function(){ const fresh = !state.portalId, r = await _saveToPortalBs.apply(this, arguments);
  if(fresh && r && state.portalId === r && !clientMode && currentView === 'client'){ try { keepScroll('#view-client', renderClient); } catch(e){} } return r; };
function summaryChoices(ev){ const c = ev.choices || {}; const row = (k, v) => v && (Array.isArray(v) ? v.length : true) ? `<dt>${k}</dt><dd>${Array.isArray(v) ? v.map(esc).join('<br>') : esc(v)}</dd>` : ''; return `<dl class="spec">${row('Venue', `${ev.setting || ''}${ev.venue ? ' · ' + ev.venue : ''}`)}${row('Theme', ev.theme)}${row('Package', c.package)}${row('Music', c.music)}${row('Tables', c.tables)}${row('Backdrops', c.backdrops)}${row('Menu', c.menu)}${row('Hors d’oeuvres', c.hors)}${row('Cake', c.cake)}${row('Bar', c.bar)}${row('Add-ons', c.addons)}${row('Staff', (ev.staff || []).map(id => staffById(id)?.name).filter(Boolean).join(', '))}${row('Contract', ev.contractSigned ? 'Signed by client' : '')}${row('Payments', ev.paid ? money(ev.paid) + ' collected' : '')}${row('Approvals', ev.approved ? ev.approved + ' of 8 approved' : '')}${row('Changes requested', ev.changesRequested)}${row('Latest message', ev.lastNote ? `${ev.lastNote.name}: ${String(ev.lastNote.text).slice(0, 140)}` : '')}${row('Last activity', ev.lastActivity ? ev.lastActivity.text : '')}${row('Client', [ev.client?.name, ev.client?.email, ev.client?.phone].filter(Boolean).join(' · '))}</dl>`; }
/* events list order; remembered per browser */
let portalSort = (() => { try { return localStorage.getItem('tablescape-portal-sort') || 'updated'; } catch(e){ return 'updated'; } })();
function sortEvents(list, now){
  if(portalSort === 'name') return list.slice().sort((a, b) => String(a.name || '').localeCompare(String(b.name || '')));
  if(portalSort !== 'soon') return list;
  const t = e => { const d = new Date((e.date || '') + 'T00:00'); return isNaN(d) ? null : +d; };
  return list.slice().sort((a, b) => { const x = t(a), y = t(b), ax = x == null ? 2 : x < +now ? 1 : 0, by = y == null ? 2 : y < +now ? 1 : 0; return ax - by || (ax === 0 ? x - y : ax === 1 ? y - x : 0); });
}
