    <div class="inv-stats"><div class="stat"><b>${upcoming.length}</b><span>upcoming events</span></div><div class="stat"><b>${money(booked)}</b><span>booked value · ${money(portalEvents.reduce((a, e) => a + (+e.paid || 0), 0))} collected</span></div><div class="stat"><b>${upcoming.reduce((a, e) => a + (+e.guests || 0), 0).toLocaleString()}</b><span>guests upcoming</span></div><div class="stat"><b>${portalEvents.filter(e => e.status === 'inquiry' || e.status === 'proposal').length}</b><span>open inquiries &amp; proposals</span></div></div>
