/* environment reflections */
function envTexture(amb, outdoor){
  const k = 'env' + amb + (outdoor ? 'o' : 'i'); if(MC.has(k)) return MC.get(k);
  const s = new THREE.Scene(), hdr = (c, m) => new THREE.Color(c).multiplyScalar(m);
  const base = outdoor ? (amb === 'day' ? '#9fc0de' : amb === 'golden' ? '#9c6e66' : '#14172a') : (amb === 'day' ? '#cfc6bc' : '#2a2026');
  s.add(new THREE.Mesh(new THREE.BoxGeometry(30, 14, 30), new THREE.MeshBasicMaterial({color:hdr(base, 1), side:THREE.BackSide})));
  const panel = (x, y, z, w, h, c, m, rx = 0, ry = 0) => { const p = new THREE.Mesh(new THREE.PlaneGeometry(w, h), new THREE.MeshBasicMaterial({color:hdr(c, m), side:THREE.DoubleSide})); p.position.set(x, y, z); p.rotation.set(rx, ry, 0); s.add(p); };
  const warm = amb === 'day' ? '#ffffff' : amb === 'golden' ? '#ffd2a0' : '#ffcf8f';
  panel(0, 6.8, 0, 10, 10, warm, outdoor ? (amb === 'candle' ? 1 : 4) : (amb === 'candle' ? 3 : 5), Math.PI/2);
  [[-14.5, 0, Math.PI/2], [14.5, 0, -Math.PI/2]].forEach(([x, z, ry]) => panel(x, 3, z, 6, 3, warm, amb === 'candle' ? 2.2 : 3, 0, ry));
  if(outdoor){ panel(0, -6.8, 0, 30, 30, amb === 'day' ? '#7d9a5f' : '#3d3a2a', .8, Math.PI/2); if(amb === 'golden') panel(0, 1.5, -14.5, 12, 3, '#ffb46e', 6); }
  else for(let i=0;i<6;i++) panel(-10 + i*4, 5.5, -14.5, 1.2, 1.2, '#ffd9a0', amb === 'candle' ? 5 : 2);
  const pm = new THREE.PMREMGenerator(V.renderer), tex = pm.fromScene(s, .035).texture; pm.dispose();
  MC.set(k, tex); return tex;
}
/* contact shadows */
