    seated.forEach(([cx, cz, ry, gid]) => list.push({x:cx, z:cz, ry, seated:true, seed:[...String(gid)].reduce((a, c) => a*31 + c.charCodeAt(0) >>> 0, 7)}));
    if(d){ const n = Math.min(48, Math.round(seated.length*.3) + 6); for(let i=0;i<n;i++){ const w = worldPt(d, {x:(R() - .5)*d.w*.85, y:(R() - .5)*d.h*.85}); const [x, z] = toW(w.x, w.y); list.push({x, z, ry:R()*6.28, seated:false, dress:R() < .5, dance:R() < .45, seed:Math.floor(R()*1e6)}); } }
