$('#view-music').addEventListener('change', e => { const t = e.target; if(t.dataset.lang && +t.value === 0){ const m = music(); if(Object.keys(m.langs).length > 1) mutate(() => delete m.langs[t.dataset.lang]); } if(t.dataset.lang || t.dataset.energy || t.dataset.moment || t.dataset.mlist){ const y = $('#music-preview').scrollTop, open = !!document.querySelector('.egroup[open]'); renderMusic(); $('#music-preview').scrollTop = y; if(open) document.querySelector('.egroup').open = true; } });

/* ============ preset packages ============ */
const PKG_TIERS = {essentials:'Essentials', signature:'Signature', luxe:'Luxe'};
const PKG_PRICE = {wedding:[95,165,260], quince:[75,130,210], corporate:[85,140,225], holiday:[65,110,180], graduation:[45,80,130], prom:[55,90,145], community:[50,85,140]};
const PKG_MIN = {essentials:50, signature:75, luxe:100};
let pkgType = null, pkgPrices = null;
function pkgSpec(type, tier){
  const T = {
    essentials:{tag:'Everything you need, done beautifully', look:{fabric:'poly', charger:'none', plate:'white', flatware:'silver', centerpiece:'bud', chair:'crossback', sash:false, runner:'none'}, cake:[2, 'buttercream', 'greenery'], bar:{style:'beerwine', sig:[]}, service:'buffet', mains:2, hors:2, addons:['projector'], bd:{base:'fabric', florals:'corner', sign:'acrylic', floor:[]}, staff:'Day-of coordinator', dj:'DJ & MC, 5 hours', extras:['Tables, chairs and linens', 'Basic uplighting']},
    signature:{tag:'Our most-loved package', look:{fabric:'satin', charger:'goldBead', plate:'goldRim', flatware:'gold', centerpiece:'low', chair:'chiavariGold', sash:false}, cake:[3, 'buttercream', 'cascade'], bar:{style:'full', sig:['espresso','paloma']}, service:'plated', mains:3, hors:4, addons:['projector','pinspot','marquee'], bd:{base:'flowers', florals:'none', sign:'neon', floor:['pillars']}, staff:'Lead planner + day-of coordinator', dj:'DJ & MC, 6 hours', extras:['Custom invitation suite', 'Uplighting in your color', 'Seating chart sign']},
    luxe:{tag:'Every detail, nothing held back', look:{fabric:'velvet', charger:'mirror', plate:'goldRim', flatware:'gold', glass:'clear', centerpiece:'tall', chair:'chiavariGold', sash:true}, cake:[4, 'fondant', 'cascade'], bar:{style:'full', sig:['espresso','paloma','french75']}, service:'stations', mains:3, hors:6, addons:['projector','pinspot','marquee','clouds','coldsparks','ledfloor','tower','booth360'], bd:{base:'flowers', florals:'full', sign:'neon', floor:['pillars','florals']}, staff:'Full-service planning team', dj:'DJ & MC, 7 hours + live musician', extras:['Custom invitation suite with foil', 'Pin-spots and uplighting', 'Seating chart sign', 'Valet parking']},
  }[tier];
  const s = JSON.parse(JSON.stringify(T)); s.tier = tier; s.type = type;
  if(type === 'quince'){ s.addons = s.addons.concat(tier === 'essentials' ? ['throne'] : ['throne','clouds']).filter((v, i, a) => a.indexOf(v) === i); s.extras.unshift(tier === 'luxe' ? 'Choreographer for the court waltz' : 'Throne chair for the quinceañera'); s.bar = {style: tier === 'luxe' ? 'full' : 'signature', sig: tier === 'essentials' ? [] : ['mojito']}; }
  if(type === 'corporate'){ s.addons = s.addons.filter(a => !['clouds','tower','throne'].includes(a)).concat(['slideshow']); s.extras.unshift('Stage, podium and AV package'); s.dj = tier === 'essentials' ? 'Background music & PA' : tier === 'signature' ? 'DJ & emcee, 4 hours' : 'Live band, 4 hours'; if(tier === 'luxe') s.addons.push('valet'); }
  if(type === 'prom'){ s.bar = {style:'dry', sig:[]}; s.addons = s.addons.filter(a => !['tower'].includes(a)).concat(tier === 'essentials' ? [] : ['booth360']); s.extras.unshift('Security and chaperone check-in'); s.service = 'buffet'; }
  if(type === 'graduation'){ s.addons = s.addons.filter(a => !['clouds','tower','coldsparks'].includes(a)).concat(['lawn', tier !== 'essentials' ? 'latenight' : 'dessert']); s.bar = tier === 'essentials' ? {style:'dry', sig:[]} : {style:'beerwine', sig:[]}; s.service = 'buffet'; }
  if(type === 'holiday'){ s.addons = s.addons.filter(a => a !== 'clouds' || tier === 'luxe').concat(['coffee']); s.extras.unshift('Holiday décor package'); }
  if(type === 'community'){ s.addons = s.addons.filter(a => !['clouds','coldsparks','tower','ledfloor','throne'].includes(a)).concat(['slideshow', tier === 'luxe' ? 'valet' : 'kids']); s.extras.unshift('Program stage and PA'); s.service = tier === 'luxe' ? 'plated' : 'buffet'; }
  s.addons = [...new Set(s.addons)];
  return s;
}
function pkgPrice(type, tier){ const i = Object.keys(PKG_TIERS).indexOf(tier); return +((pkgPrices && pkgPrices[type] && pkgPrices[type][i]) ?? PKG_PRICE[type][i]); }
function pkgIncludes(s){
  const cps = CENTERPIECES[s.look.centerpiece].label, ch = CHARGERS[s.look.charger];
  return [`${FABRICS[s.look.fabric]} ${linensWord(s.look.fabric)}${s.look.charger !== 'none' ? `, ${ch.toLowerCase()} chargers` : ''}`, `${cps} centerpieces`, `${CHAIRS[s.look.chair].label} chairs${s.look.sash ? ' with sashes' : ''}`,
    `${SERVICE_STYLES[s.service][0]} dinner, ${s.mains} entrée choices`, `${s.hors} passed hors d’oeuvres`, `${s.cake[0]}-tier ${CAKE_FINISH[s.cake[1]][0].toLowerCase()} cake`,
    s.bar.style === 'dry' ? 'Mocktail & soda bar' : `${BAR_STYLES[s.bar.style]}${s.bar.sig.length ? ` (${s.bar.sig.length} signature cocktail${s.bar.sig.length > 1 ? 's' : ''})` : ''}`,
    `${BD_BASES[s.bd.base]} backdrop${s.bd.sign !== 'none' ? ' with ' + BD_SIGNS[s.bd.sign].toLowerCase() + ' sign' : ''}`, s.dj, s.staff, ...s.extras, ...s.addons.map(a => ADDONS[a]?.label).filter(Boolean)];
}
function applyPackage(type, tier){
  const s = pkgSpec(type, tier), guests = expectedHeads();
  mutate(() => {
    state.looks.forEach((L, i) => { Object.assign(L, s.look); if(i > 0 && tier !== 'essentials'){ L.centerpiece = tier === 'luxe' ? 'candelabra' : 'tall'; } });
    const sizes = {2:[10,6], 3:[12,9,6], 4:[14,12,9,6]}[s.cake[0]], c = cake(); c.tiers = sizes.map((z, i) => ({size:z, shape:'round', flavor:(c.tiers[i] || {}).flavor || 'Vanilla bean', filling:(c.tiers[i] || {}).filling || 'Raspberry'})); c.finish = s.cake[1]; c.decor = s.cake[2];
    const b = bar(); b.style = s.bar.style; b.signatures = s.bar.sig.slice(); if(s.bar.style === 'dry' && b.mocktail === 'none') b.mocktail = 'berry';
    const mc = menuChoices(); mc.service = s.service; const mainC = catalog.courses.find(x => x.id === 'main'); if(mainC && !(mc.picks.main || []).length) mc.picks.main = mainC.options.slice(0, s.mains).map(o => o.id); ['starter','sides','dessert'].forEach(id => { const co = catalog.courses.find(x => x.id === id); if(co && !(mc.picks[id] || []).length) mc.picks[id] = co.options.slice(0, id === 'sides' ? 2 : 1).map(o => o.id); });
    hors().items = Object.keys(HORS).filter(k => HORS[k][2].includes('V')).slice(0, Math.ceil(s.hors/2)).concat(Object.keys(HORS).filter(k => !HORS[k][2].includes('V')).slice(0, Math.floor(s.hors/2)));
    const keep = state.addons || {}; state.addons = {}; s.addons.forEach(k => state.addons[k] = keep[k] || {});
    ensureBackdrops(); const B = bdList()[0]; if(B) Object.assign(B, {base:s.bd.base, florals:s.bd.florals, sign:s.bd.sign, floor:s.bd.floor.slice()});
    if(tier !== 'essentials' && !bdList().some(x => x.shape === 'chart')){ const ch = Object.assign(newBackdrop('chart', 'Seating chart'), JSON.parse(JSON.stringify(BD_THEMES.chart)), {signText:'Find your seat', w:6, h:6, placedAt:''}); delete ch.label; state.backdrops.push(ch); }
    state.package = {type, tier, label:`${ET[type]?.label || EVENT_TYPES[type]} · ${PKG_TIERS[tier]}`, perGuest:pkgPrice(type, tier), guests};
    syncMeals();
  });
}
function renderPackages(){
  pkgType = pkgType || state.eventType || 'wedding';
  const guests = expectedHeads() || 100, item = Math.round(budgetTotals(budgetLines()).total), cur = state.package, pkgTot = cur ? Math.max(cur.perGuest*guests, cur.perGuest*(PKG_MIN[cur.tier] || 0)) : 0;
  const tiers = Object.keys(PKG_TIERS).map(t => [t, pkgSpec(pkgType, t)]);
  $('#packages').innerHTML = `<header class="sheet-head"><div><span class="eyebrow">Packages</span><h1>Choose a package</h1><p class="muted" style="margin:4px 0 0">Three tiers for each kind of event. Applying one sets up linens, tableware, florals, chairs, cake, bar, dinner, hors d’oeuvres, backdrop and add-ons, keeping your theme’s colors.</p></div></header>
    <div class="chips">${Object.entries(EVENT_TYPES).map(([k, n]) => `<button class="chip" data-ptype="${k}" aria-pressed="${pkgType === k}">${esc(n)}</button>`).join('')}</div>
    ${cur ? `<div class="pkg-current"><div><span class="eyebrow">This event</span><b>${esc(cur.label)}</b><span class="muted">${money(cur.perGuest)} per guest × ${guests} guests = <b>${money(Math.max(cur.perGuest*guests, cur.perGuest*PKG_MIN[cur.tier]))}</b> package price</span></div><div><span class="eyebrow">Itemized estimate</span><b>${money(item)}</b><span class="muted">${item > pkgTot ? `The package saves your client about ${money(item - pkgTot)}` : `Itemized is ${money(pkgTot - item)} below the package price`}</span></div><button class="btn" data-pkgclear="1">Remove package</button></div>` : ''}
    <div class="pkg-grid">${tiers.map(([t, s]) => { const per = pkgPrice(pkgType, t), total = Math.max(per*guests, per*PKG_MIN[t]), on = cur && cur.type === pkgType && cur.tier === t; return `<div class="pkg${t === 'signature' ? ' featured' : ''}${on ? ' on' : ''}">
      ${t === 'signature' ? '<span class="pkg-flag">Most popular</span>' : ''}<span class="eyebrow">${esc(EVENT_TYPES[pkgType])}</span><h2>${esc(PKG_TIERS[t])}</h2><p class="muted">${esc(s.tag)}</p>
      <div class="pkg-price"><b>${money(per)}</b><span>per guest</span></div><p class="muted" style="margin:0;font-size:12.5px">${money(total)} for ${guests} guests${per*guests < total ? ` (minimum ${PKG_MIN[t]} guests)` : ''}</p>
      ${canAdmin ? `<label class="bu-money pkg-edit">Price per guest $<input class="qty-in" type="number" min="0" step="1" data-pkgprice="${t}" value="${per}"></label>` : ''}
      <ul class="pkg-list">${pkgIncludes(s).map(x => `<li>${esc(x)}</li>`).join('')}</ul>
      <button class="btn ${on ? '' : 'primary'}" data-pkgapply="${t}">${on ? 'Applied to this event' : 'Apply to this event'}</button></div>`; }).join('')}</div>
    <div class="inv-card table-scroll"><table class="qty pkg-compare"><thead><tr><th>Compare</th>${tiers.map(([t]) => `<th>${PKG_TIERS[t]}</th>`).join('')}</tr></thead><tbody>
      ${[['Linens', s => FABRICS[s.look.fabric]], ['Chargers', s => s.look.charger === 'none' ? '—' : CHARGERS[s.look.charger]], ['Centerpieces', s => CENTERPIECES[s.look.centerpiece].label], ['Chairs', s => CHAIRS[s.look.chair].label + (s.look.sash ? ' + sash' : '')], ['Dinner', s => `${SERVICE_STYLES[s.service][0]}, ${s.mains} entrées`], ['Hors d’oeuvres', s => s.hors + ' kinds'], ['Cake', s => `${s.cake[0]} tiers`], ['Bar', s => s.bar.style === 'dry' ? 'Mocktails' : BAR_STYLES[s.bar.style]], ['Backdrop', s => BD_BASES[s.bd.base]], ['Music', s => s.dj], ['Planning', s => s.staff], ['Add-ons', s => s.addons.length + ' included'], ['Per guest', s => money(pkgPrice(pkgType, s.tier))]].map(([n, f]) => `<tr><td>${n}</td>${tiers.map(([, s]) => `<td>${esc(f(s))}</td>`).join('')}</tr>`).join('')}
    </tbody></table></div>
    ${canAdmin ? `<div class="btn-row" style="margin:0"><button class="btn" data-pkgsave="1">Save package prices for everyone</button><span class="muted" style="font-size:12px">Prices are starting points for planning. Edit them to match your business.</span></div>` : ''}`;
}
$('#view-packages').addEventListener('click', async e => {
  const t = e.target;
  const pt = t.closest('[data-ptype]'); if(pt){ pkgType = pt.dataset.ptype; renderPackages(); return; }
  const pa = t.closest('[data-pkgapply]'); if(pa){ if(pkgType !== (state.eventType || 'wedding')) mutate(() => state.eventType = pkgType); applyPackage(pkgType, pa.dataset.pkgapply); renderPackages(); updateTabs(); toast(`${PKG_TIERS[pa.dataset.pkgapply]} package applied. Ctrl+Z undoes it.`); return; }
  if(t.closest('[data-pkgclear]')){ mutate(() => delete state.package); renderPackages(); return; }
  if(t.closest('[data-pkgsave]')){ try { if(DB) await DB.doc('catalog/packages').set({prices:pkgPrices || PKG_PRICE, updatedAt:Date.now()}); else ls.set('tablescape-pkg-prices', JSON.stringify(pkgPrices || PKG_PRICE)); toast('Package prices saved'); } catch(err){ toast(err.code === 'invalid_argument' ? 'Only editors can change package prices.' : 'Couldn’t save the prices.'); } }
});
$('#view-packages').addEventListener('change', e => { const t = e.target; if(t.dataset.pkgprice){ pkgPrices = pkgPrices || JSON.parse(JSON.stringify(PKG_PRICE)); pkgPrices[pkgType] = pkgPrices[pkgType] || PKG_PRICE[pkgType].slice(); pkgPrices[pkgType][Object.keys(PKG_TIERS).indexOf(t.dataset.pkgprice)] = Math.max(0, +t.value || 0); if(state.package && state.package.type === pkgType && state.package.tier === t.dataset.pkgprice) mutate(() => state.package.perGuest = +t.value || 0); renderPackages(); } });
async function initPackages(){ try { const lp = ls.get('tablescape-pkg-prices'); if(lp) pkgPrices = JSON.parse(lp); } catch(e){} if(DB){ try { DB.doc('catalog/packages').onSnapshot(s => { if(s.exists && s.data().prices){ pkgPrices = JSON.parse(JSON.stringify(s.data().prices)); if(currentView === 'packages') renderPackages(); } }, () => {}); } catch(e){} } }

/* ============ company profile & staff (shared) ============ */
let company = {name:TS_CO_DEFAULT, email:'', phone:'', address:''}, staffList = [];   /* the built-in name until the real one loads (tsCoName) */
const STAFF_COLORS = ['#d4b46e','#d98f97','#8fae8b','#7f9cc0','#9a6c94','#c47a54','#5fa8a0','#b7a4d8'];
async function initBusiness(){
  try { const c = ls.get('tablescape-company'); if(c) company = JSON.parse(c); const st = ls.get('tablescape-staff'); if(st) staffList = JSON.parse(st); } catch(e){}
  if(DB){ try { DB.doc('catalog/company').onSnapshot(s => { if(s.exists){ company = Object.assign(company, s.data()); renderPortalIfOpen(); } }, () => {}); DB.doc('catalog/staff').onSnapshot(s => { if(s.exists && Array.isArray(s.data().members)){ staffList = JSON.parse(JSON.stringify(s.data().members)); renderPortalIfOpen(); } }, () => {}); } catch(e){} }
  const stm = (location.hash || '').match(/^#staff-([A-Za-z0-9_-]+)$/); if(stm) openPortalEvent(stm[1]).then(ok => { if(ok) openStaff(); });
  const sim = (location.hash || '').match(/^#site-([A-Za-z0-9_-]+)$/); if(sim) openSite(sim[1]);
  const vm = (location.hash || '').match(/^#vendor-([A-Za-z0-9_-]+)\.([A-Za-z0-9_-]+)$/); if(vm) openVendorSheet(vm[1], vm[2]);
}
async function saveShared(doc, data, lsKey){ try { if(DB) await DB.doc('catalog/' + doc).set(Object.assign({}, data, {updatedAt:Date.now()})); else ls.set(lsKey, JSON.stringify(data.members || data)); return true; } catch(e){ toast(e.code === 'invalid_argument' ? 'Only editors can change this.' : 'Couldn’t save right now.'); return false; } }

/* ============ payments ============ */
const PAY_METHODS = ['Card','Bank transfer','Check','Cash','Zelle','Venmo'];
function contractTotal(){ const p = state.package, guests = expectedHeads(); if(state.payments && state.payments.totalOverride) return +state.payments.totalOverride; if(p) return Math.round(Math.max(p.perGuest*guests, p.perGuest*(PKG_MIN[p.tier] || 0))); return Math.round(budgetTotals(budgetLines()).total); }
function payments(){
  if(!state.payments){ const d = eventDate(), today = new Date(), iso = x => isoLocal(x), off = days => { if(!d) return iso(today); const x = new Date(d); x.setDate(x.getDate() + days); return iso(x < today ? today : x); };
    state.payments = {totalOverride:null, schedule:[{id:uid(), label:'Retainer (due at signing)', pct:30, due:iso(today), paid:null}, {id:uid(), label:'Second payment', pct:40, due:off(-90), paid:null}, {id:uid(), label:'Final balance', pct:30, due:off(-14), paid:null}], invoiceSeq:1001}; }
  return state.payments;
}
/* Scheduled amount for one payment. When the plan adds up to 100%, the last payment absorbs rounding and any difference in what was actually paid earlier, so the schedule always collects the full contract total. */
function payAmt(s, total){ const S = payments().schedule, i = S.indexOf(s); if(total == null) total = contractTotal(); const base = x => Math.round(total*(+x.pct || 0)/100); if(i < 0 || i !== S.length - 1 || S.length < 2 || S.reduce((a, x) => a + (+x.pct || 0), 0) !== 100) return base(s); return Math.max(0, total - S.slice(0, -1).reduce((a, x) => a + (x.paid && x.paid.amount != null && x.paid.amount !== '' ? +x.paid.amount || 0 : base(x)), 0)); }
function payStatus(){ const P = payments(), total = contractTotal(), today = new Date(); today.setHours(0,0,0,0); let paid = 0, overdue = 0; P.schedule.forEach(s => { const amt = payAmt(s, total); if(s.paid) paid += +s.paid.amount || amt; else if(new Date(s.due + 'T00:00') < today) overdue += amt; }); return {total, paid, balance: total - paid, overdue}; }
function invoiceHTML(s, i){
  const P = payments(), total = contractTotal(), amt = payAmt(s, total), cl = state.client || {};
  return `<div class="invoice"><div class="inv-h"><div><b class="inv-co">${esc(company.name)}</b><span>${esc([company.email, company.phone].filter(Boolean).join(' · '))}</span></div><div class="inv-meta"><span class="eyebrow">${s.paid ? 'Receipt' : 'Invoice'}</span><b>#${P.invoiceSeq + i}</b><span>Due ${esc(shortFmt(s.due))}</span></div></div>
    <div class="inv-to"><span class="eyebrow">Bill to</span><b>${esc(cl.name || 'Client')}</b><span>${esc([cl.email, cl.phone].filter(Boolean).join(' · '))}</span></div>
    <table class="qty"><thead><tr><th>Description</th><th class="num">Amount</th></tr></thead><tbody><tr><td>${esc(s.label)} · ${s.pct}% of ${money(total)}<br><span class="muted" style="font-size:12px">${esc(state.event.name)} · ${esc(fmtDate(state.event.date))}${state.package ? ' · ' + esc(state.package.label) + ' package' : ''}</span></td><td class="num">${money(amt)}</td></tr><tr><td><b>${s.paid ? 'Amount received' : 'Amount due'}</b></td><td class="num"><b>${money(s.paid && s.paid.amount != null ? +s.paid.amount || 0 : amt)}</b></td></tr></tbody></table>${(() => { const st = payStatus(); return `<p class="muted" style="font-size:12px;margin:0 0 8px">Contract total ${money(st.total)} · paid to date ${money(st.paid)} · remaining balance ${money(st.balance)}</p>`; })()}
    ${s.paid ? `<p class="pill ok">Paid ${esc(shortFmt(s.paid.date))} by ${esc(s.paid.method)}</p>` : '<p class="muted" style="font-size:12px;margin:0">Payment methods are arranged directly with your planner.</p>'}</div>`;
}
function invoiceText(s, i){ const P = payments(), total = contractTotal(), amt = payAmt(s, total); return `${s.paid ? 'RECEIPT' : 'INVOICE'} #${P.invoiceSeq + i}\n${company.name}\n\nBill to: ${(state.client || {}).name || 'Client'}\nEvent: ${state.event.name}, ${fmtDate(state.event.date)}\n\n${s.label} (${s.pct}% of ${money(total)}): ${money(amt)}\nDue: ${shortFmt(s.due)}${s.paid ? `\nPAID ${money(s.paid.amount != null ? +s.paid.amount || 0 : amt)} on ${shortFmt(s.paid.date)} by ${s.paid.method}. Thank you!` : ''}\n\nContract total ${money(payStatus().total)} · paid to date ${money(payStatus().paid)} · remaining balance ${money(payStatus().balance)}`; }

/* ============ contract & e-signature ============ */
const CLAUSES = {cancel:['Cancellation','If the client cancels more than 180 days before the event, payments other than the retainer are refunded. Within 180 days, payments made are non-refundable. The retainer secures the date and is non-refundable.'], changes:['Changes & guest count','Final guest count and selections are due 21 days before the event. Additions after that date are billed at the per-guest rate; reductions are not refunded.'], damage:['Damage & rentals','The client is responsible for loss of or damage to rented items beyond normal wear, billed at replacement cost.'], force:['Force majeure','Neither party is liable for failure to perform due to events beyond reasonable control. Payments made will be applied to a rescheduled date within 12 months.'], photo:['Photo release','The company may use photos of décor and design from the event in its portfolio, without identifying guests.'], alcohol:['Alcohol service','Alcohol is served only by licensed bartenders to guests 21 and over. Service may be refused to anyone who appears intoxicated.']};
const contract = () => (state.contract ||= {clauses:['cancel','changes','damage','force','photo'], extra:'', status:'draft', sentAt:null, client:null, company:null});
function contractText(){
  const C = contract(), cl = state.client || {}, total = contractTotal(), P = payments(), p = state.package;
  const inc = p ? pkgIncludes(pkgSpec(p.type, p.tier)) : [];
  const L = [`EVENT SERVICES AGREEMENT`, ``, `This agreement is between ${company.name} ("the Company") and ${cl.name || '[client name]'} ("the Client") for ${state.event.name} on ${fmtDate(state.event.date)} at ${state.event.venue || '[venue]'}.`, ``,
    `1. SERVICES`, p ? `The Company will provide the ${p.label} package, including:` : 'The Company will provide the services described in the attached proposal, including:', ...(inc.length ? inc : ['Floor plan and table design', 'Linens, tableware and décor as designed', 'Coordination on the day of the event']).map(x => `   • ${x}`),
    `   Expected guest count: ${expectedHeads()}.`, ``,
    `2. FEES & PAYMENT`, `The total fee is ${money(total)}, paid as follows:`, ...P.schedule.map(s => `   • ${s.label}: ${s.pct}% (${money(payAmt(s, total))}) due ${shortFmt(s.due)}`), ``];
  if(!Array.isArray(C.clauses)) C.clauses = ['cancel', 'changes', 'damage', 'force', 'photo']; if(typeof C.extra !== 'string') C.extra = ''; /* older or partial agreement records */
  C.clauses.filter(k => CLAUSES[k]).forEach((k, i) => L.push(`${i + 3}. ${CLAUSES[k][0].toUpperCase()}`, CLAUSES[k][1], ''));
  if(C.extra.trim()) L.push(`${C.clauses.length + 3}. ADDITIONAL TERMS`, C.extra.trim(), '');
  L.push('SIGNATURES', `Client: ${C.client ? `${C.client.name}, signed ${new Date(C.client.at).toLocaleString()}` : '______________________'}`, `Company: ${C.company ? `${C.company.name}, signed ${new Date(C.company.at).toLocaleString()}` : '______________________'}`);
  return L.join('\n');
}
let sigPad = null;
function sigPadHTML(who){ return `<div class="sigbox"><canvas id="sig-canvas" width="560" height="170" aria-label="Draw your signature"></canvas><div class="btn-row" style="margin:6px 0 0"><input class="cat-in" id="sig-name" placeholder="Type your full name" style="flex:1"><button class="btn sm" data-sig="clear">Clear</button><button class="btn sm primary" data-sig="adopt" data-who="${who}">Sign as ${who === 'client' ? 'client' : 'company'}</button></div><p class="muted" style="font-size:11.5px;margin:4px 0 0">Draw with your mouse or finger, or just type your name. Signing records your name, signature and the time.</p></div>`; }
function bindSigPad(){
  const c = $('#sig-canvas'); if(!c) return; const x = c.getContext('2d'); x.lineWidth = 2.4; x.lineCap = 'round'; x.strokeStyle = '#1d1a26'; let drawing = false, any = false;
  const pos = e => { const r = c.getBoundingClientRect(); return [(e.clientX - r.left)*c.width/r.width, (e.clientY - r.top)*c.height/r.height]; };
  c.onpointerdown = e => { drawing = true; any = true; c.setPointerCapture(e.pointerId); const [a, b] = pos(e); x.beginPath(); x.moveTo(a, b); };
  c.onpointermove = e => { if(!drawing) return; const [a, b] = pos(e); x.lineTo(a, b); x.stroke(); };
  c.onpointerup = () => drawing = false;
  sigPad = {canvas:c, has:() => any, clear:() => { x.clearRect(0, 0, c.width, c.height); any = false; }};
}
function sigData(){ if(!sigPad || !sigPad.has()) return null; const c = document.createElement('canvas'); c.width = 280; c.height = 85; c.getContext('2d').drawImage(sigPad.canvas, 0, 0, 280, 85); return c.toDataURL('image/png'); }

/* ============ proposal ============ */
let clientTab = 'proposal', coverShot = null;
function snapshot3D(){
  if(!window.THREE) return null; if(!visionInit()) return null;
  try { visionBuild(); const r = V.renderer, cam = V.camera, keep = r.getSize(new THREE.Vector2()), O = Object.assign({}, V.orbit); Object.assign(V.orbit, camTarget('overview'));
    cam.position.set(V.orbit.tx + V.orbit.r*Math.sin(V.orbit.phi)*Math.sin(V.orbit.theta), V.orbit.ty + V.orbit.r*Math.cos(V.orbit.phi), V.orbit.tz + V.orbit.r*Math.sin(V.orbit.phi)*Math.cos(V.orbit.theta)); cam.lookAt(V.orbit.tx, V.orbit.ty, V.orbit.tz);
    r.setSize(1400, 760, false); cam.aspect = 1400/760; cam.updateProjectionMatrix(); r.render(V.scene, cam); const url = r.domElement.toDataURL('image/jpeg', .86);
    r.setSize(keep.x || 800, keep.y || 500, false); cam.aspect = (keep.x || 800)/(keep.y || 500); cam.updateProjectionMatrix(); Object.assign(V.orbit, O); return url; } catch(e){ return null; }
}
function proposalHTML(){
  const p = state.package, L = state.looks[0], st = payStatus(), P = payments(), guests = expectedHeads(), C = contract();
  const tl = (state.timeline || []).filter(x => x.type !== 'vendor' && x.type !== 'prep').sort((a, b) => toMin(a.time) - toMin(b.time));
  const sec = (eyebrow, title, body, cls = '') => `<section class="prop-sec ${cls}"><span class="eyebrow">${eyebrow}</span><h2>${title}</h2>${body}</section>`;
  return `<div class="prop">
    <div class="prop-cover">${coverShot ? `<img src="${coverShot}" alt="3D render of the event">` : `<div class="prop-cover-ph">${previewSVG(L, 60)}</div>`}<div class="prop-cover-txt"><span class="eyebrow">A proposal from ${esc(company.name)}</span><h1>${esc(state.event.name)}</h1><p>${esc(fmtDate(state.event.date))} · ${esc(state.event.venue || '')} · ${guests} guests</p></div></div>
    ${ceremonyShot ? sec('The ceremony', esc((SETTINGS[cerSpace().venue.setting] || {}).label || 'Ceremony'), `<img class="prop-img" src="${ceremonyShot}" alt="3D render of the ceremony">${(state.processional || []).length ? `<p class="prop-lede">Processional: ${state.processional.map(p => esc(p.who)).join(' · ')}</p>` : ''}`) : ''}
    ${sec('The vision', esc(state.themeLabel || L.name), `<div class="prop-pal">${[L.cloth, L.napkin, L.flower1, L.flower2, chairColor(L)].map(c => `<i style="background:${c}"></i>`).join('')}</div><p class="prop-lede">${esc(SETTINGS[venue().setting].label)} setting with ${esc(colorName(L.cloth).toLowerCase())} ${esc(FABRICS[L.fabric].toLowerCase())} ${linensWord(L.fabric)}, ${L.charger !== 'none' ? esc(CHARGERS[L.charger].toLowerCase()) + ' chargers, ' : ''}${esc(CENTERPIECES[L.centerpiece].label.toLowerCase())} centerpieces in ${esc(colorName(L.flower1).toLowerCase())} and ${esc(colorName(L.flower2).toLowerCase())}, and ${esc(CHAIRS[L.chair].label.toLowerCase())} chairs.</p><div class="prop-two"><div class="prop-art">${previewSVG(L, 60)}</div><div class="prop-art">${bdList()[0] ? backdropSVG(bdList()[0]) : ''}</div></div>`)}
    ${p ? sec('Your package', esc(p.label), `<div class="prop-pkg"><div><b>${money(p.perGuest)}</b><span>per guest</span></div><ul class="pkg-list">${pkgIncludes(pkgSpec(p.type, p.tier)).map(x => `<li>${esc(x)}</li>`).join('')}</ul></div>`) : ''}
    ${sec('Stationery', 'Invitation suite', `<div class="prop-three"><div class="prop-art">${inviteSVG('invitation', {id:'p1'})}</div><div class="prop-art">${inviteSVG('savedate', {id:'p2'})}</div><div class="prop-art">${inviteSVG('rsvp', {id:'p3'})}</div></div>`)}
    ${sec('Dining', hasCake() ? 'Menu, cake &amp; bar' : 'Menu &amp; bar', `<div class="prop-three"><div class="prop-art">${dinnerMenuSVG()}</div><div class="prop-art">${hasCake() ? cakeSVG(cake()) : ''}</div><div class="prop-art">${barMenuSVG()}</div></div>`)}
    ${tl.length ? sec('The day', 'Run of show', `<ol class="prop-tl">${tl.map(x => `<li><b>${esc(fmt12(x.time))}</b><span>${esc(x.title)}</span></li>`).join('')}</ol>`) : ''}
    ${sec('Investment', money(st.total), `<table class="qty"><tbody>${P.schedule.map(s => `<tr><td>${esc(s.label)}</td><td>${esc(shortFmt(s.due))}</td><td class="num">${money(payAmt(s, st.total))}</td><td>${s.paid ? '<span class="pill ok">Paid</span>' : ''}</td></tr>`).join('')}</tbody></table>${p ? `<p class="muted" style="font-size:12.5px">Based on the ${esc(p.label)} package for ${guests} guests.</p>` : '<p class="muted" style="font-size:12.5px">Based on the itemized estimate for your selections.</p>'}`)}
    ${sec('Next step', C.client ? 'Signed. Thank you!' : 'Review &amp; sign', `<p class="prop-lede">${C.client ? `Signed by ${esc(C.client.name)} on ${new Date(C.client.at).toLocaleDateString()}.` : 'Read the agreement and sign online to reserve your date.' + holdNote()}</p><button class="btn primary" data-ctab="contract">${C.client ? 'View the agreement' : 'Review and sign the agreement'}</button>`, 'prop-cta')}
  </div>`;
}
function renderClient(){
  const seg = `<div class="seg" role="tablist">${[['proposal','Proposal'],['approvals','Approvals'],['contract','Contract'],['payments','Payments'],['messages','Messages']].map(([k, n]) => `<button data-ctab="${k}" aria-pressed="${clientTab === k}">${n}</button>`).join('')}</div>`;
  const st = payStatus(), C = contract();
  let body = '';
  if(clientTab === 'proposal'){ body = `<div class="btn-row" style="margin:0">${state.portalId ? `<button class="btn" data-plink="${state.portalId}">Copy client link</button>` : '<button class="btn" data-cact2="save">Save the event to share it</button>'}<button class="btn" data-cact2="shot">${coverShot ? 'Refresh the 3D renders' : 'Add 3D renders'}</button>${coverShot ? '<button class="btn" data-dl="cover:jpg">Download 3D render</button>' : ''}</div>${proposalHTML()}`; }
  if(clientTab === 'contract'){
    const status = C.client && C.company ? ['ok','Fully signed'] : C.client ? ['caution','Signed by client'] : C.sentAt ? ['caution','Sent to client'] : ['', 'Draft'];
    body = `<div class="contract-grid"><div class="inv-card"><div class="sheet-head" style="padding-bottom:10px"><div><span class="eyebrow">Agreement</span><h2 style="font-family:var(--display);font-weight:400;font-size:26px">Event services agreement</h2></div><span class="pill ${status[0]}">${status[1]}</span></div><pre class="contract-doc">${esc(contractText())}</pre>
      <div class="sig-row">${['client','company'].map(w => { const s = C[w]; return `<div class="sig-slot"><span class="eyebrow">${w === 'client' ? 'Client' : esc(company.name)}</span>${s ? `${s.sig ? `<img src="${s.sig}" alt="Signature">` : `<b class="sig-typed">${esc(s.name)}</b>`}<span>${esc(s.name)} · ${new Date(s.at).toLocaleString()}</span>` : '<span class="muted">Not signed</span>'}</div>`; }).join('')}</div>
      ${!C.client ? sigPadHTML('client') : !C.company && canAdmin && !clientMode ? sigPadHTML('company') : ''}</div>
      ${!clientMode ? `<div class="inv-card ctrl-col"><span class="eyebrow">Clauses</span>${Object.entries(CLAUSES).map(([k, [n]]) => `<label class="toggle" style="padding-left:0"><input type="checkbox" data-clause="${k}" ${C.clauses.includes(k) ? 'checked' : ''} ${C.client ? 'disabled' : ''}> ${n}</label>`).join('')}
        <label class="fld" style="margin-top:8px"><span>Additional terms</span><textarea class="iv-msg" rows="4" id="ct-extra" ${C.client ? 'disabled' : ''}>${esc(C.extra)}</textarea></label>
        <label class="fld"><span>Client name</span><input id="ct-client" value="${esc((state.client || {}).name || '')}" ${C.client ? 'disabled' : ''}></label>
        <div class="btn-row" style="margin:0"><button class="btn" data-cact2="copy-contract">Copy agreement text</button><button class="btn" data-dl="contract:txt">Download PDF</button>${state.portalId ? `<button class="btn" data-cact2="send-contract">Copy signing link</button>` : ''}${C.client || C.company ? '<button class="btn danger" data-cact2="unsign">Clear signatures</button>' : ''}</div>
        <p class="muted" style="font-size:11.5px">This is a signature record for your own use, not legal advice. Have your attorney review your terms.</p></div>` : ''}</div>`;
  }
  if(clientTab === 'payments'){
    const P = payments();
    body = `<div class="inv-stats"><div class="stat"><b>${money(st.total)}</b><span>contract total</span></div><div class="stat"><b style="color:var(--ok)">${money(st.paid)}</b><span>paid</span></div><div class="stat"><b>${money(st.balance)}</b><span>balance due</span></div><div class="stat"><b style="color:${st.overdue ? 'var(--warn)' : 'inherit'}">${money(st.overdue)}</b><span>overdue</span></div></div>
      ${!clientMode ? `<div class="inv-card fld-row" style="align-items:end"><label class="fld"><span>Contract total</span><input type="number" id="pay-total" min="0" step="50" value="${P.totalOverride ?? ''}" placeholder="${contractTotal()}"></label><p class="muted" style="font-size:12px;margin:0">Leave blank to use ${state.package ? 'the package price' : 'the itemized budget'}.${!state.package && typeof quoteBillHint === 'function' ? quoteBillHint() : ''}</p></div>` : ''}
      <div class="pay-list">${P.schedule.map((s, i) => { const amt = payAmt(s, st.total), late = !s.paid && new Date(s.due + 'T00:00') < new Date(new Date().toDateString()); return `<div class="pay${s.paid ? ' paid' : ''}${late ? ' late' : ''}">
        <div class="pay-main">${clientMode ? `<b>${esc(s.label)}</b>` : `<input class="cat-title" data-pf="label" data-pid="${s.id}" value="${esc(s.label)}" aria-label="Payment name">`}<span>${clientMode ? `${s.pct}% · due ${esc(shortFmt(s.due))}` : `<input type="number" class="qty-in" min="0" max="100" data-pf="pct" data-pid="${s.id}" value="${s.pct}" aria-label="Percent">% · due <input type="date" class="cat-in" data-pf="due" data-pid="${s.id}" value="${s.due}" style="width:auto" aria-label="Due date">`}</span></div>
        <b class="pay-amt">${money(s.paid && s.paid.amount != null ? +s.paid.amount || 0 : amt)}</b>
        <div class="pay-act">${s.paid ? `<span class="pill ok">Paid ${esc(shortFmt(s.paid.date))} · ${esc(s.paid.method)}${s.paid.amount != null && +s.paid.amount !== amt && !clientMode ? ` · ${+s.paid.amount < amt ? money(amt - s.paid.amount) + ' short' : money(s.paid.amount - amt) + ' over'}` : ''}</span>${!clientMode ? `<button class="btn sm" data-unpay="${s.id}">Undo</button>` : ''}` : late ? '<span class="pill warn">Overdue</span>' : '<span class="pill">Upcoming</span>'}
          ${!s.paid && !clientMode ? `<select data-method="${s.id}" aria-label="Payment method">${PAY_METHODS.map(m => `<option>${m}</option>`).join('')}</select><span class="bu-money" title="Amount received. Enter less for a partial payment; the difference moves to the final balance.">$<input type="number" class="qty-in" min="0" step="1" data-payamt="${s.id}" value="${amt}" aria-label="Amount received" style="width:84px"></span><button class="btn sm primary" data-pay="${s.id}">Record payment</button>` : ''}<button class="btn sm" data-invoice="${i}">${s.paid ? 'Receipt' : 'Invoice'}</button>${!clientMode && !s.paid ? `<button class="x" data-paydel="${s.id}" aria-label="Remove">×</button>` : ''}</div></div>`; }).join('')}</div>
      ${!clientMode ? `<div class="btn-row" style="margin:0"><button class="btn" data-cact2="add-pay">Add a payment</button>${P.schedule.reduce((a, s) => a + (+s.pct || 0), 0) !== 100 ? `<span class="pill warn">Payments add up to ${P.schedule.reduce((a, s) => a + (+s.pct || 0), 0)}%, not 100%</span>` : ''}</div>` : ''}
      <div id="invoice-view"></div>
      <p class="muted" style="font-size:12px;margin:0">Payments are recorded here for tracking. Collect them through your usual payment processor.${!clientMode ? ' Record a partial payment by changing the amount; when the plan adds up to 100%, the last payment picks up any difference so the full total is collected.' : ''}</p>`;
  }
  if(clientTab === 'messages') body = messagesHTML();
  if(clientTab === 'approvals') body = approvalsHTML();
  $('#client').innerHTML = `<header class="sheet-head"><div><span class="eyebrow">Proposal &amp; billing</span><h1>${esc(state.event.name)}</h1><p class="muted" style="margin:4px 0 0">${esc((state.client || {}).name || 'No client name yet')} · ${money(st.total)} · ${money(st.paid)} paid</p></div>${seg}</header>${body}`;
  if(clientTab === 'contract') bindSigPad();
}
$('#view-client').addEventListener('click', async e => {
  const t = e.target, C = contract(), P = payments();
  const ct = t.closest('[data-ctab]'); if(ct){ clientTab = ct.dataset.ctab; renderClient(); $('#view-client').scrollTop = 0; return; }
  const lk = t.closest('[data-plink]'); if(lk){ copyText(`${ARTIFACT_URL}#ev-${lk.dataset.plink}${tsTok(lk.dataset.plink)}`, 'Client link copied'); return; }
  const sg = t.closest('[data-sig]'); if(sg){ if(sg.dataset.sig === 'clear'){ sigPad && sigPad.clear(); return; } const name = ($('#sig-name').value || '').trim(), sig = sigData(); if(!name){ toast('Type your full name to sign.'); return; } mutate(() => { C[sg.dataset.who] = {name, sig, at:Date.now()}; if(sg.dataset.who === 'client' && state.portalStatus !== 'completed') state.portalStatus = 'booked'; logActivity(`${name} signed the agreement as ${sg.dataset.who}`); }); if(state.portalId) saveToPortal(true); renderClient(); toast('Signed. Thank you!'); return; }
  const a2 = t.closest('[data-cact2]'); if(a2){ const a = a2.dataset.cact2;
    if(a === 'save') saveToPortal();
    if(a === 'shot'){ toast('Rendering the 3D cover…'); setTimeout(() => { coverShot = snapshot3D(); if(state.items.some(i => i.space === 'ceremony')){ switchSpace('ceremony', true); ceremonyShot = snapshot3D(); switchSpace('reception', true); } renderClient(); if(!coverShot) toast('The 3D view isn’t available in this browser.'); }, 50); }
    if(a === 'copy-contract') copyText(contractText(), 'Agreement copied');
    if(a === 'send-contract'){ mutate(() => C.sentAt = C.sentAt || Date.now()); copyText(`${ARTIFACT_URL}#ev-${state.portalId}${tsTok(state.portalId)}`, 'Signing link copied. The client opens Proposal & billing → Contract.'); renderClient(); }
    if(a === 'unsign'){ mutate(() => { C.client = null; C.company = null; }); renderClient(); }
    if(a === 'add-pay'){ mutate(() => P.schedule.push({id:uid(), label:'Additional payment', pct:0, due:state.event.date || isoLocal(), paid:null})); renderClient(); }
    return; }
  const py = t.closest('[data-pay]'); if(py){ const s = P.schedule.find(x => x.id === py.dataset.pay), m = (document.querySelector(`[data-method="${s.id}"]`) || {}).value || 'Card', ai = document.querySelector(`[data-payamt="${s.id}"]`), due = payAmt(s, contractTotal()), got = ai && ai.value !== '' ? Math.max(0, Math.round((+ai.value || 0)*100)/100) : due; if(!got){ toast('Enter the amount received.'); return; } mutate(() => { s.paid = {date:isoLocal(), method:m, amount:got}; logActivity(`Payment recorded: ${s.label}, ${money(s.paid.amount)} by ${m}`); }); renderClient(); renderPortalIfOpen(); toast('Payment recorded'); return; }
  const up = t.closest('[data-unpay]'); if(up){ mutate(() => { const s = P.schedule.find(x => x.id === up.dataset.unpay); s.paid = null; if(typeof plClaimDrop === 'function') plClaimDrop(s); }); renderClient(); return; }   /* an old "I've paid" claim doesn't come back */
  const pd = t.closest('[data-paydel]'); if(pd){ mutate(() => P.schedule = P.schedule.filter(x => x.id !== pd.dataset.paydel)); renderClient(); return; }
  const iv = t.closest('[data-invoice]'); if(iv){ const i = +iv.dataset.invoice, s = P.schedule[i]; $('#invoice-view').innerHTML = `${invoiceHTML(s, i)}<div class="btn-row"><button class="btn" data-invcopy="${i}">Copy ${s.paid ? 'receipt' : 'invoice'} text</button><button class="btn" data-dl="invoice:${i}">Download PDF</button></div>`; $('#invoice-view').scrollIntoView({block:'nearest', behavior:'smooth'}); return; }
  const ic = t.closest('[data-invcopy]'); if(ic) copyText(invoiceText(P.schedule[+ic.dataset.invcopy], +ic.dataset.invcopy), 'Invoice copied');
});
$('#view-client').addEventListener('change', e => {
  const t = e.target, C = contract(), P = payments();
  if(t.dataset.clause){ const k = t.dataset.clause; mutate(() => C.clauses = t.checked ? [...C.clauses, k] : C.clauses.filter(x => x !== k)); renderClient(); }
  if(t.id === 'ct-extra'){ mutate(() => C.extra = t.value); renderClient(); }
  if(t.id === 'ct-client'){ mutate(() => { state.client = state.client || {name:'', email:'', phone:''}; state.client.name = t.value; }); renderClient(); }
  if(t.id === 'pay-total'){ mutate(() => P.totalOverride = t.value === '' ? null : Math.max(0, +t.value || 0)); renderClient(); }
  if(t.dataset.pf){ const s = P.schedule.find(x => x.id === t.dataset.pid); mutate(() => s[t.dataset.pf] = t.dataset.pf === 'pct' ? clamp(+t.value || 0, 0, 100) : t.value); renderClient(); }
});

/* ============ vendor sheets ============ */
function vendorItems(plan, v){
  const key = (v.role + ' ' + (v.name || '')).toLowerCase().split(/[\s/&]+/).filter(w => w.length > 2);
  return (plan.timeline || []).filter(x => { const w = (x.who + ' ' + x.title).toLowerCase(); return key.some(k => w.includes(k)); }).sort((a, b) => toMin(a.time) - toMin(b.time));
}
function vendorNeeds(v){
  const r = v.role.toLowerCase(), o = buildOrder(), L = [];
  if(/rental|linen/.test(r)){ o.linens.forEach(l => L.push(`${l.qty} × ${l.label}, ${l.size}`)); Object.entries(o.furniture).forEach(([k, n]) => L.push(`${n} × ${k} table`)); Object.entries(o.chairs).forEach(([k, n]) => L.push(`${n} × ${k}`)); }
  if(/flor/.test(r)){ Object.entries(o.decor).forEach(([k, n]) => L.push(`${n} × ${k}`)); bdList().forEach(b => b.florals !== 'none' || b.base === 'flowers' ? L.push(`Backdrop florals: ${b.name} (${b.florals !== 'none' ? BD_FLORALS[b.florals] || b.florals : BD_BASES[b.base] || 'flowers'})`) : 0); state.items.filter(i => i.type === 'aisle' && i.decor && i.decor !== 'none').forEach(a => L.push(`Aisle ${AISLE_DECOR[a.decor].toLowerCase()}`)); }
  if(/cater|food/.test(r)){ Object.entries(o.meals).forEach(([m, n]) => n && L.push(`${n} × ${m || 'meal not chosen'}`)); state.guests.filter(g => (g.diet || (g.dietTags || []).length) && g.rsvp !== 'no').forEach(g => L.push(`Dietary: ${g.name}: ${[...(g.dietTags || []).map(t => DIET_TAGS[t]), g.diet].filter(Boolean).join(', ')}`)); state.guests.filter(g => (g.needs || []).length && g.rsvp !== 'no').forEach(g => L.push(`Access: ${g.name}: ${g.needs.map(n => NEEDS[n]).join(', ')}`)); if(state.hors) horsCalc().rows.forEach(x => L.push(`${x.pcs} × ${x.label}`)); }
  if(/dj|band|music/.test(r)) L.push(...djBrief().split('\n').slice(3));
  if(/cake|bak/.test(r) && hasCake()){ const c = cake(); L.push(`${c.tiers.length} tiers: ${c.tiers.map(t => t.size + '″ ' + t.flavor.toLowerCase() + ' / ' + t.filling.toLowerCase()).join('; ')}`, `${CAKE_FINISH[c.finish][0]}, ${CAKE_DECOR[c.decor].toLowerCase()}, ${CAKE_STAND[c.stand].toLowerCase()}`); }
  if(/photo|video/.test(r)) (state.timeline || []).filter(x => x.type !== 'vendor').forEach(x => L.push(`${fmt12(x.time)} ${x.title}`));
  if(/venue/.test(r)) L.push(`${tables().length} tables, ${tables().reduce((a, t) => a + t.seats, 0)} seats`, ...state.items.filter(i => i.kind === 'fixture').map(f => `${f.label}: ${f.w}×${f.h} ft`));
  if(/bar|bartend/.test(r) && state.bar) barCalc().list.forEach(l => L.push(`${l.qty} × ${l.label} (${l.unit})`));
  return L;
}
function vendorSheetHTML(plan, v){
  const saved = state; state = plan; let html = '';
  try { const items = vendorItems(plan, v), needs = vendorNeeds(v), all = (plan.timeline || []).slice().sort((a, b) => toMin(a.time) - toMin(b.time));
    html = `<div class="vsheet"><span class="eyebrow">Vendor sheet · ${esc(v.role)}</span><h1>${esc(plan.event.name)}</h1><p class="muted">${esc(fmtDate(plan.event.date))} · ${esc(plan.event.venue || '')}</p>
      <div class="inv-stats"><div class="stat"><b>${v.arrive ? esc(fmt12(v.arrive)) : '—'}</b><span>arrival</span></div><div class="stat"><b>${v.depart ? esc(fmt12(v.depart)) : '—'}</b><span>departure</span></div><div class="stat"><b>${plan.guests.filter(g => g.rsvp !== 'no').length}</b><span>guests</span></div><div class="stat"><b style="font-size:18px">${esc(company.name)}</b><span>${esc(company.phone || company.email || 'your coordinator')}</span></div></div>
      ${v.notes ? `<p class="note">${esc(v.notes)}</p>` : ''}
      <div class="sheet-grid"><section><h2>Your schedule</h2>${items.length ? `<ol class="prop-tl">${items.map(x => `<li><b>${esc(fmt12(x.time))}</b><span>${esc(x.title)}${x.where ? ' · ' + esc(x.where) : ''}</span></li>`).join('')}</ol>` : '<p class="muted">No items assigned to you yet.</p>'}</section>
      <section><h2>What we need from you</h2>${needs.length ? `<ul class="task-list">${needs.map(n => `<li><span>${esc(n)}</span></li>`).join('')}</ul>` : '<p class="muted">Your coordinator will share details.</p>'}</section>
      <section class="wide"><h2>Full run of show</h2><ol class="prop-tl">${all.map(x => `<li><b>${esc(fmt12(x.time))}</b><span>${esc(x.title)}${x.who ? ' · ' + esc(x.who) : ''}</span></li>`).join('')}</ol></section></div></div>`;
  } finally { state = saved; }
  return html;
}
async function openVendorSheet(eid, vid){
  const plan = await store.load(eid), o = $('#rsvp-page');
  if(!plan){ o.innerHTML = '<div class="rsvp-inner"><h2>This vendor sheet couldn’t be found</h2><p class="muted">Ask your coordinator for a new link.</p></div>'; o.hidden = false; return; }
  const v = (plan.vendors || []).find(x => x.id === vid); if(!v){ o.innerHTML = '<div class="rsvp-inner"><h2>This vendor isn’t on the event anymore</h2></div>'; o.hidden = false; return; }
  o.innerHTML = `<div class="rsvp-inner">${vendorSheetHTML(plan, v)}</div>`; o.hidden = false;
}
$('#view-plan').addEventListener('click', e => {
  const vl = e.target.closest('[data-vlink]'); if(vl){ if(!state.portalId){ toast('Save the event first to create vendor links.'); return; } copyText(`${ARTIFACT_URL}#vendor-${state.portalId}.${vl.dataset.vlink}${tsVTok(state.portalId, vl.dataset.vlink)}`, 'Vendor link copied'); return; }
  const vp = e.target.closest('[data-vprev]'); if(vp){ const v = state.vendors.find(x => x.id === vp.dataset.vprev); const o = $('#rsvp-page'); o.innerHTML = `<div class="rsvp-inner"><div class="btn-row" style="justify-content:flex-end"><button class="btn" id="vclose">Close preview</button></div>${vendorSheetHTML(state, v)}</div>`; o.hidden = false; $('#vclose').onclick = () => o.hidden = true; }
});

/* ============ portal calendar & staff ============ */
let portalView = 'list', calMonth = null, staffFilter = '';
function staffById(id){ return staffList.find(s => s.id === id); }
function staffConflicts(){ const map = {}, out = []; portalEvents.filter(e => e.date && e.status !== 'cancelled').forEach(e => (e.staff || []).forEach(sid => { const k = sid + '|' + e.date; (map[k] ||= []).push(e); })); Object.entries(map).forEach(([k, evs]) => { if(evs.length > 1) out.push({sid:k.split('|')[0], date:k.split('|')[1], evs}); }); return out; }
function calendarHTML(){
  const now = new Date(); calMonth = calMonth || new Date(now.getFullYear(), now.getMonth(), 1);
  const y = calMonth.getFullYear(), m = calMonth.getMonth(), first = new Date(y, m, 1), startDow = first.getDay(), days = new Date(y, m + 1, 0).getDate(), conf = staffConflicts();
  const evs = portalEvents.filter(e => e.date && (!staffFilter || (e.staff || []).includes(staffFilter)));
  let cells = ''; for(let i=0;i<startDow;i++) cells += '<div class="cal-cell empty"></div>';
  for(let d=1; d<=days; d++){ const iso = `${y}-${String(m + 1).padStart(2,'0')}-${String(d).padStart(2,'0')}`, list = evs.filter(e => e.date === iso), today = iso === isoLocal(now), clash = conf.some(c => c.date === iso);
    cells += `<div class="cal-cell${today ? ' today' : ''}${clash ? ' clash' : ''}"><span class="cal-d">${d}</span>${list.map(e => `<button class="cal-ev" style="--c:${(STATUSES[e.status] || STATUSES.inquiry)[1]}" data-calopen="${e.id}" title="${esc(e.name)}"><b>${esc(e.name)}</b><span>${(e.staff || []).map(s => staffById(s)).filter(Boolean).map(s => `<i style="background:${s.color}">${esc(s.name.split(/\s+/).map(w => w[0]).join('').slice(0, 2))}</i>`).join('')}</span></button>`).join('')}${clash ? '<span class="cal-clash">Staff double-booked</span>' : ''}</div>`; }
  return `<div class="cal-head"><button class="icon-btn" data-calnav="-1" aria-label="Previous month">‹</button><h2>${calMonth.toLocaleDateString(undefined, {month:'long', year:'numeric'})}</h2><button class="icon-btn" data-calnav="1" aria-label="Next month">›</button><button class="btn sm" data-calnav="0">Today</button>
    <select id="staff-filter" aria-label="Filter by staff"><option value="">All staff</option>${staffList.map(s => `<option value="${s.id}"${staffFilter === s.id ? ' selected' : ''}>${esc(s.name)}</option>`).join('')}</select></div>
    <div class="cal-grid">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d => `<div class="cal-dow">${d}</div>`).join('')}${cells}</div>
    ${conf.length ? `<div class="note warn">${conf.map(c => `${esc(staffById(c.sid)?.name || 'A staff member')} is on ${c.evs.length} events on ${esc(shortFmt(c.date))}: ${c.evs.map(e => esc(e.name)).join(', ')}`).join('<br>')}</div>` : ''}`;
}
function staffPanelHTML(){
  const cur = state.staff || [];
  return `<section class="inv-card"><div class="sheet-head" style="padding-bottom:10px"><div><span class="eyebrow">Team</span><h2 style="font-family:var(--display);font-weight:400;font-size:24px">Staff &amp; company</h2></div></div>
    <div class="fld-row"><label class="fld"><span>Company name</span><input id="co-name" value="${esc(company.name)}" ${canAdmin ? '' : 'disabled'}></label><label class="fld"><span>Company email / phone</span><input id="co-contact" value="${esc([company.email, company.phone].filter(Boolean).join(' · '))}" placeholder="hello@company.com · 555-0100" ${canAdmin ? '' : 'disabled'}></label></div>
    <span class="eyebrow">Assign to ${esc(state.event.name)}</span><div class="chips" style="margin:6px 0 12px">${staffList.length ? staffList.map(s => `<button class="chip" data-assign="${s.id}" aria-pressed="${cur.includes(s.id)}"><i style="--c:${s.color}"></i>${esc(s.name)} <small class="muted">${esc(s.role)}</small></button>`).join('') : '<span class="muted">Add your day-of crew below.</span>'}</div>
    ${canAdmin ? `<h3 class="eyebrow" style="margin:6px 0 2px">Day-of crew (no login)</h3><p class="muted" style="font-size:12.5px;margin:0 0 6px">Names for schedules, call times and event assignments. They don’t get a sign-in. ${typeof tsIsSB === 'function' && tsIsSB() ? 'To give someone their own login, invite them under Who can sign in, above.' : 'Logins are set up on app.tablescape.vip, under Who can sign in.'}</p><ul class="task-list">${staffList.map(s => `<li><span><i class="swatch-inline" style="--c:${s.color}"></i>${esc(s.name)} · <span class="muted">${esc(s.role)}</span> · ${portalEvents.filter(e => (e.staff || []).includes(s.id) && e.status !== 'cancelled').length} events</span><button class="x" data-staffdel="${s.id}" aria-label="Remove ${esc(s.name)}">×</button></li>`).join('')}</ul>
    <div class="fld-row" style="margin-top:10px;align-items:end"><label class="fld"><span>Name</span><input id="st-name" placeholder="Jordan Lee"></label><label class="fld"><span>Role</span><input id="st-role" placeholder="Lead planner" list="st-roles"></label></div><datalist id="st-roles"><option value="Lead planner"><option value="Day-of coordinator"><option value="Designer"><option value="Setup crew"><option value="Sales"></datalist>
    <div class="btn-row" style="margin:0"><button class="btn" data-staffadd="1">Add to day-of crew</button><button class="btn primary" data-cosave="1">Save team &amp; company</button></div>` : ''}</section>`;
}
$('#view-events').addEventListener('click', async e => {
  const t = e.target;
  const pv = t.closest('[data-pview]'); if(pv){ portalView = pv.dataset.pview; renderPortal(); return; }
  const cn = t.closest('[data-calnav]'); if(cn){ const k = +cn.dataset.calnav, now = new Date(); calMonth = k === 0 ? new Date(now.getFullYear(), now.getMonth(), 1) : new Date(calMonth.getFullYear(), calMonth.getMonth() + k, 1); renderPortal(); return; }
  const co = t.closest('[data-calopen]'); if(co){ portalView = 'list'; portalOpen = co.dataset.calopen; renderPortal(); return; }
  const as = t.closest('[data-assign]'); if(as){ const id = as.dataset.assign; mutate(() => { state.staff = state.staff || []; state.staff = state.staff.includes(id) ? state.staff.filter(x => x !== id) : [...state.staff, id]; }); if(state.portalId) saveToPortal(true); renderPortal(); return; }
  if(t.closest('[data-staffadd]')){ const name = ($('#st-name').value || '').trim(); if(!name) return; staffList.push({id:'s' + uid(), name, role:($('#st-role').value || '').trim() || 'Team', color:STAFF_COLORS[staffList.length % STAFF_COLORS.length]}); renderPortal(); toast('Added. Save the team to share it.'); return; }
  const sd = t.closest('[data-staffdel]'); if(sd){ staffList = staffList.filter(s => s.id !== sd.dataset.staffdel); renderPortal(); return; }
  if(t.closest('[data-cosave]')){ const cc = ($('#co-contact').value || '').split('·').map(x => x.trim()); company = Object.assign(company, {name:$('#co-name').value.trim() || company.name, email:cc.find(x => x.includes('@')) || '', phone:cc.find(x => !x.includes('@')) || ''}); const a = await saveShared('company', company, 'tablescape-company'), b = await saveShared('staff', {members:staffList}, 'tablescape-staff'); if(a && b) toast('Team and company saved'); }
});
$('#view-events').addEventListener('change', e => { if(e.target.id === 'staff-filter'){ staffFilter = e.target.value; renderPortal(); } });

/* ============ activity log & client messages ============ */
function logActivity(text, who){ (state.activity ||= []).unshift({at:Date.now(), text, who: who || (clientMode ? ((state.client || {}).name || 'Client') : (company.name || 'Team'))}); if(state.activity.length > 150) state.activity.length = 150; }
const _applyPackage = applyPackage; applyPackage = function(type, tier){ _applyPackage(type, tier); logActivity(`Applied the ${PKG_TIERS[tier]} package`); save(); };
const _applyEventTheme = applyEventTheme; applyEventTheme = function(type, key, opts){ _applyEventTheme(type, key, opts); logActivity(`Applied the ${ET[type].themes[key].label} theme`); save(); };
const _toggleAddon = toggleAddon; toggleAddon = function(k){ const was = addonOn(k); _toggleAddon(k); logActivity(`${was ? 'Removed' : 'Added'} ${ADDONS[k].label}`); save(); };
const ago = t => { const s = (Date.now() - t)/1000; return s < 60 ? 'just now' : s < 3600 ? Math.floor(s/60) + ' min ago' : s < 86400 ? Math.floor(s/3600) + ' h ago' : new Date(t).toLocaleDateString(undefined, {month:'short', day:'numeric'}); };
function messagesHTML(){
  const msgs = state.messages || [], act = state.activity || [], me = clientMode ? 'client' : 'company';
  return `<div class="msg-grid"><div class="inv-card msg-card"><span class="eyebrow">Messages with ${esc(clientMode ? company.name : ((state.client || {}).name || 'your client'))}</span>
      <div class="msg-thread" id="msg-thread">${msgs.length ? msgs.map(m => `<div class="msg ${m.from === me ? 'mine' : ''}"><div class="msg-b">${esc(m.text).replace(/\n/g, '<br>')}</div><span>${esc(m.name)} · ${esc(ago(m.at))}</span></div>`).join('') : '<p class="muted" style="text-align:center;padding:30px 0">No messages yet. Questions, ideas and approvals live here with the event.</p>'}</div>
      <form id="msg-form" class="msg-form"><textarea id="msg-text" class="iv-msg" rows="2" placeholder="Write a message…" aria-label="Message"></textarea><button class="btn primary" type="submit">Send</button></form>
      ${!state.portalId ? '<p class="muted" style="font-size:12px;margin:0">Save the event so the other side can see messages.</p>' : ''}</div>
    <div class="inv-card"><span class="eyebrow">Activity</span><ul class="act-list">${act.length ? act.slice(0, 40).map(a => `<li><b>${esc(a.text)}</b><span>${esc(a.who)} · ${esc(ago(a.at))}</span></li>`).join('') : '<li class="muted">Changes like signatures, payments, RSVPs and package choices are logged here.</li>'}</ul></div></div>`;
}
document.addEventListener('submit', e => {
  if(e.target.id !== 'msg-form') return; e.preventDefault();
  const text = ($('#msg-text').value || '').trim(); if(!text) return;
  mutate(() => { (state.messages ||= []).push({from: clientMode ? 'client' : 'company', name: clientMode ? ((state.client || {}).name || 'Client') : company.name, text, at:Date.now()}); if(state.messages.length > 300) state.messages.splice(0, state.messages.length - 300); });
  if(state.portalId) saveToPortal(true); renderClient(); const th = $('#msg-thread'); if(th) th.scrollTop = th.scrollHeight;
});

/* ============ downloads: PDF, PNG, SVG, CSV ============ */
let DL;
async function getDL(){ if(DL !== undefined) return DL; try { DL = window.claude && window.claude.use ? await window.claude.use('downloads') : null; } catch(e){ DL = null; } return DL; }
async function offerFile(filename, data){ const dl = await getDL(); if(!dl){ toast('Downloads aren’t available in this view.'); return false; } try { await dl.save({filename, data}); return true; } catch(e){ if(e.code !== 'declined') toast(e.code === 'rate_limited' ? 'A download is already waiting for your confirmation.' : e.code === 'too_large' ? 'That file is too large. Try PNG instead.' : 'Couldn’t prepare the download.'); return false; } }
const slug = s => String(s || 'event').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 50) || 'event';
function resolveVars(str){ const cs = getComputedStyle(document.documentElement); return str.replace(/var\((--[\w-]+)\)/g, (m, n) => cs.getPropertyValue(n).trim() || '#888888'); }
function standalone(svg, w, h){ let s = svg.replace(/^<svg /, `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" `); return resolveVars(s); }
function svgToCanvas(svgStr, w, h, bg = '#ffffff'){ return new Promise((res, rej) => { const img = new Image(); img.onload = () => { const c = document.createElement('canvas'); c.width = w; c.height = h; const x = c.getContext('2d'); x.fillStyle = bg; x.fillRect(0, 0, w, h); x.drawImage(img, 0, 0, w, h); res(c); }; img.onerror = () => rej(new Error('render')); img.src = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svgStr); }); }
const canvasBlob = c => new Promise(r => c.toBlob(r, 'image/png'));
async function pdfFromCanvases(pages, filename){
  if(!window.jspdf){ toast('The PDF tool didn’t load. Try PNG instead.'); return; }
  if(!pages.length){ toast('Nothing to put in that file yet. Seat a few tables or guests first.'); return; }
  const {jsPDF} = window.jspdf; let doc = null;
  pages.forEach(({canvas, w, h}) => { const o = w > h ? 'l' : 'p'; if(!doc) doc = new jsPDF({unit:'in', format:[w, h], orientation:o}); else doc.addPage([w, h], o); doc.addImage(canvas.toDataURL('image/jpeg', .92), 'JPEG', 0, 0, w, h); });
  await offerFile(filename, doc.output('arraybuffer'));
}
const PLAN_CSS = `.room{fill:var(--floor);stroke:var(--room-line);stroke-width:.14}.g1 path{stroke:var(--grid);stroke-width:.05;fill:none}.g5 path{stroke:var(--grid-major);stroke-width:.07;fill:none}.dim{fill:var(--muted);font:500 .8px 'DM Mono',monospace}.fx{fill:var(--fx);stroke:var(--fx-line);stroke-width:.08}.fx-text{fill:var(--fx-text);font:600 .9px Manrope,sans-serif;text-anchor:middle;dominant-baseline:central}.fx-sub{fill:var(--fx-text);font:400 .6px 'DM Mono',monospace;text-anchor:middle;dominant-baseline:central;opacity:.7}.badge{fill:var(--surface);stroke:var(--accent);stroke-width:.06}.badge-t{fill:var(--ink);font:600 .7px Manrope,sans-serif;text-anchor:middle;dominant-baseline:central}.seat-name{fill:var(--ink);font:600 .54px Manrope,sans-serif;text-anchor:middle;dominant-baseline:central}.sel-ring,.warn-ring{display:none}`;
function planSVGString(){
  const keepSel = sel; sel = null; renderPlan(); const inner = $('#plan-root').innerHTML; sel = keepSel; renderPlan();
  const defs = document.querySelector('body > svg defs, svg[aria-hidden="true"] defs'), W = state.room.w, H = state.room.h, pad = 4, foot = 7;
  const title = `<g transform="translate(0 ${H + 2.5})"><text x="0" y="1.2" style="font:400 2.2px 'Bodoni Moda',Georgia,serif" fill="var(--ink)">${esc(state.event.name)}</text><text x="0" y="3.3" style="font:500 1px Manrope,sans-serif" fill="var(--muted)">${esc(fmtDate(state.event.date))} · ${esc(state.event.venue || '')} · ${tables().length} tables · ${tables().reduce((a, t) => a + t.seats, 0)} seats</text><text x="${W}" y="3.3" text-anchor="end" style="font:500 .9px 'DM Mono',monospace" fill="var(--muted)">Scale: 1 grid square = 1 ft · ${W} × ${H} ft</text></g>`;
  return {svg:`<svg xmlns="http://www.w3.org/2000/svg" viewBox="${-pad} ${-pad} ${W + pad*2} ${H + pad + foot}"><style>${PLAN_CSS}</style>${defs ? defs.outerHTML : ''}<rect x="${-pad}" y="${-pad}" width="${W + pad*2}" height="${H + pad + foot}" fill="var(--surface)"/>${inner}${title}</svg>`, ratio:(W + pad*2)/(H + pad + foot)};
}
async function downloadPlan(fmt){
  const {svg, ratio} = planSVGString(), s = resolveVars(svg), name = slug(state.event.name) + '-floor-plan';
  if(fmt === 'svg') return offerFile(name + '.svg', s);
  const w = 3300, h = Math.round(w/ratio), c = await svgToCanvas(s.replace('<svg ', `<svg width="${w}" height="${h}" `), w, h, getComputedStyle(document.documentElement).getPropertyValue('--surface').trim() || '#fff');
  if(fmt === 'png') return offerFile(name + '.png', await canvasBlob(c));
  const pw = ratio >= 1 ? 11 : 8.5, ph = ratio >= 1 ? Math.min(8.5, 11/ratio) : Math.min(11, 8.5/ratio);
  return pdfFromCanvases([{canvas:c, w:pw, h:ph}], name + '.pdf');
}
const STAT_SIZE = {invitation:[5,7], savedate:[5,7], rsvp:[5,3.5], tablenum:[5,7], escort:[5,7], program:[5,7], menu:[5,7]};
async function pieceCanvas(kind, opts = {}){ const [wi, hi] = STAT_SIZE[kind], W = 500, H = kind === 'rsvp' ? 360 : 700, px = 300; const svg = standalone(inviteSVG(kind, Object.assign({id:'dl'}, opts)), W, H); return {canvas: await svgToCanvas(svg.replace(/width="500" height="(360|700)"/, `width="${wi*px}" height="${hi*px}"`), wi*px, hi*px, invite().paper), w:wi, h:hi}; }
async function downloadPiece(kind, fmt){
  const name = `${slug(state.event.name)}-${slug(INV_KINDS[kind])}`;
  if(fmt === 'svg') return offerFile(name + '.svg', standalone(inviteSVG(kind, {id:'dl'}), 500, kind === 'rsvp' ? 360 : 700));
  if(kind === 'tablenum' || kind === 'escort'){ const pages = []; if(kind === 'tablenum') for(const t of sortedTables().filter(t => t.seats)) pages.push(await pieceCanvas(kind, {table:t, id:'dl' + t.id})); else { const n = Math.max(1, Math.ceil(state.guests.filter(g => (g.tableId || blockWhere(g)) && g.rsvp !== 'no').length/18)); for(let p = 0; p < n; p++) pages.push(await pieceCanvas(kind, {page:p, id:'dl' + p})); } if(!pages.length) return toast('Add tables with seats first, then download these cards.'); if(fmt === 'png') return offerFile(name + '.png', await canvasBlob(pages[0].canvas)); return pdfFromCanvases(pages, name + '.pdf'); }
  const pc = await pieceCanvas(kind); if(fmt === 'png') return offerFile(name + '.png', await canvasBlob(pc.canvas)); return pdfFromCanvases([pc], name + '.pdf');
}
async function downloadSuite(){ toast('Preparing the stationery suite…'); const pages = []; for(const k of ['savedate','invitation','rsvp','program','menu']) pages.push(await pieceCanvas(k)); for(const t of sortedTables().filter(t => t.seats)) pages.push(await pieceCanvas('tablenum', {table:t, id:'s' + t.id})); const n = Math.ceil(state.guests.filter(g => (g.tableId || blockWhere(g)) && g.rsvp !== 'no').length/18); for(let p = 0; p < n; p++) pages.push(await pieceCanvas('escort', {page:p, id:'se' + p})); await pdfFromCanvases(pages, slug(state.event.name) + '-stationery-suite.pdf'); }
const csvRow = a => a.map(v => { v = String(v ?? ''); return /[",\n]/.test(v) ? '"' + v.replace(/"/g, '""') + '"' : v; }).join(',');
function guestsCSV(){ const sm = new Map(tables().map(t => [t.id, t])); return [csvRow(['name','group','rsvp','meal','dietary','access needs','household','table','seat','email','phone','song request','checked in'])].concat(state.guests.map(g => csvRow([g.name, g.group, g.rsvp || 'yes', g.meal, dietOf(g), (g.needs || []).map(n => NEEDS[n] || n).join('; '), g.household ? householdOf(g).map(x => x.name).join(' + ') : '', g.tableId ? (sm.get(g.tableId)?.number || sm.get(g.tableId)?.name || '') : blockWhere(g), g.tableId ? g.seat + 1 : '', g.email, g.phone, g.song, (state.checkin || {})[g.id] ? new Date(state.checkin[g.id]).toLocaleTimeString() : '']))).join('\n'); }
function budgetCSV(){ const lines = budgetLines(), t = budgetTotals(lines); return [csvRow(['category','item','qty','unit','unit price','total'])].concat(lines.map(l => csvRow([l.cat, l.label, l.qty, l.unit, l.price, Math.round(l.qty*l.price*100)/100])), csvRow(['','Service charge','','','',Math.round(t.service)]), csvRow(['','Tax','','','',Math.round(t.tax)]), csvRow(['','Total','','','',Math.round(t.total)])).join('\n'); }
document.addEventListener('click', async e => {
  const d = e.target.closest('[data-dl]'); if(!d) return; e.preventDefault();
  const [what, fmt] = d.dataset.dl.split(':'); d.disabled = true;
  try {
    if(what === 'plan') await downloadPlan(fmt);
    else if(what === 'suite') await downloadSuite();
    else if(what === 'piece') await downloadPiece(invite().kind, fmt);
    else if(what === 'guests') await offerFile(slug(state.event.name) + '-guests.csv', guestsCSV());
    else if(what === 'budget') await offerFile(slug(state.event.name) + '-budget.csv', budgetCSV());
    else if(what === 'bar') await offerFile(slug(state.event.name) + '-bar-shopping-list.csv', [csvRow(['category','item','qty','unit','est cost'])].concat(barCalc().list.map(l => csvRow([l.cat, l.label, l.qty, l.unit, Math.round(l.cost)]))).join('\n'));
    else if(what === 'invoice'){ const i = +fmt, P = payments(), s = P.schedule[i]; const txt = invoiceText(s, i); await offerFile(`${slug(state.event.name)}-invoice-${P.invoiceSeq + i}.txt`, txt); }
    else if(what === 'contract') await offerFile(slug(state.event.name) + '-agreement.txt', contractText());
    else if(what === 'brief') await offerFile(slug(state.event.name) + '-dj-brief.txt', djBrief());
    else if(what === 'cover' && coverShot){ const b = await (await fetch(coverShot)).blob(); await offerFile(slug(state.event.name) + '-3d-render.jpg', b); }
  } catch(err){ toast('Couldn’t prepare that file.'); }
  d.disabled = false;
});

/* ============ guest check-in ============ */
let ciQ = '', ciFilter = 'all';
function checkinListHTML(){
  const ck = state.checkin || {}, sm = new Map(tables().map(t => [t.id, t])), q = ciQ.toLowerCase();
  const list = state.guests.filter(g => g.rsvp !== 'no').filter(g => !q || nameHit8(g.name, q) || nameHit8(g.group, q)).filter(g => ciFilter === 'all' || (ciFilter === 'in' ? ck[g.id] : !ck[g.id])).sort(byLast8);
  return list.length ? list.map(g => { const t = g.tableId && sm.get(g.tableId), at = ck[g.id]; return `<div class="ci${at ? ' in' : ''}"><div class="ci-main"><b>${esc(g.name)}</b><span>${t ? `<em>${esc(t.number ? 'Table ' + t.number : t.name)}</em> · seat ${g.seat + 1}` : blockWhere(g) ? `<em>${esc(blockWhere(g))}</em>` : '<em class="warn-t">No seat yet</em>'}${g.meal ? ' · ' + esc(g.meal) : ''}${g.group ? ' · ' + esc(g.group) : ''}</span>${[...(g.needs || []).map(n => NEEDS[n]), ...(g.dietTags || []).map(t => DIET_TAGS[t])].map(x => `<span class="pill">${esc(x)}</span>`).join('')}${g.diet ? `<span class="pill caution">${esc(g.diet)}</span>` : ''}</div><button class="ci-btn" data-ci="${g.id}" aria-pressed="${!!at}">${at ? `Arrived ${new Date(at).toLocaleTimeString([], {hour:'numeric', minute:'2-digit'})}` : 'Check in'}</button></div>`; }).join('') : '<p class="muted" style="padding:20px">No guests match.</p>';
}
function checkinHTML(){
  const ck = state.checkin || {}, coming = state.guests.filter(g => g.rsvp !== 'no'), arrived = coming.filter(g => ck[g.id]).length;
  return `<div class="ci-top inv-card"><div><span class="eyebrow">Guest check-in</span><h2>${arrived} of ${coming.length} arrived</h2></div><div class="bu-bar" style="flex:1 1 200px;margin:0"><i style="width:${coming.length ? arrived/coming.length*100 : 0}%;background:var(--accent)"></i></div></div>
    <div class="ci-tools"><input type="search" id="ci-q" placeholder="Search a guest’s name" value="${esc(ciQ)}" aria-label="Search guests" autocomplete="off"><div class="seg">${[['all','Everyone'],['out','Not arrived'],['in','Arrived']].map(([k, n]) => `<button data-cif="${k}" aria-pressed="${ciFilter === k}">${n}</button>`).join('')}</div>
      <form id="walkin" class="walkin"><input id="walkin-name" placeholder="Walk-in guest name" aria-label="Walk-in guest name"><button class="btn sm" type="submit">Add walk-in</button></form></div>
    <div class="ci-list" id="ci-list">${checkinListHTML()}</div>
    <p class="muted" style="font-size:12px;margin:0">Check-ins save with the event. If two devices check guests in at once, keep one device as the main check-in station so changes don’t overwrite each other.</p>`;
}
$('#view-plan').addEventListener('click', e => {
  const c = e.target.closest('[data-ci]'); if(c){ const id = c.dataset.ci; mutate(() => { state.checkin = state.checkin || {}; if(state.checkin[id]) delete state.checkin[id]; else state.checkin[id] = Date.now(); }); $('#ci-list').innerHTML = checkinListHTML(); const coming = state.guests.filter(g => g.rsvp !== 'no'); $('.ci-top h2').textContent = `${coming.filter(g => state.checkin[g.id]).length} of ${coming.length} arrived`; return; }
  const f = e.target.closest('[data-cif]'); if(f){ ciFilter = f.dataset.cif; renderPlanning(); }
});
$('#view-plan').addEventListener('input', e => { if(e.target.id === 'ci-q'){ ciQ = e.target.value; $('#ci-list').innerHTML = checkinListHTML(); } });
document.addEventListener('submit', e => { if(e.target.id !== 'walkin') return; e.preventDefault(); const name = ($('#walkin-name').value || '').trim(); if(!name) return; const g = {id:uid(), name, group:'Walk-in', meal:'', tableId:null, seat:null, rsvp:'yes'}; mutate(() => { state.guests.push(g); (state.checkin ||= {})[g.id] = Date.now(); logActivity(`Walk-in guest added: ${name}`); }); renderPlanning(); toast(`${name} checked in. Find them a seat on Guests & seating.`); });

/* ============ reports ============ */
function reportsHTML(){
  const evs = portalEvents.filter(e => e.status !== 'cancelled'), won = evs.filter(e => e.status === 'booked' || e.status === 'completed');
  const rev = e => +e.total || +e.budget || 0, totalRev = won.reduce((a, e) => a + rev(e), 0), collected = won.reduce((a, e) => a + (+e.paid || 0), 0), guests = won.reduce((a, e) => a + (+e.guests || 0), 0);
  const now = new Date(), months = Array.from({length:12}, (_, i) => { const d = new Date(now.getFullYear(), now.getMonth() - 3 + i, 1); const inM = won.filter(e => { const x = new Date((e.date || '') + 'T00:00'); return x.getMonth() === d.getMonth() && x.getFullYear() === d.getFullYear(); }); return {label:d.toLocaleDateString(undefined, {month:'short'}), rev:inM.reduce((a, e) => a + rev(e), 0), paid:inM.reduce((a, e) => a + (+e.paid || 0), 0)}; });
  const maxR = Math.max(1, ...months.map(m => m.rev)), CW = 640, CH = 220, bw = (CW - 50)/12;
  let chart = `<svg viewBox="0 0 ${CW} ${CH}" role="img" aria-label="Booked revenue by month">`; [0, .5, 1].forEach(f => { const y = CH - 30 - f*(CH - 60); chart += `<path d="M44 ${y}H${CW}" stroke="var(--line)"/><text x="40" y="${y + 3}" text-anchor="end" style="font:500 9px 'DM Mono',monospace" fill="var(--muted)">${money(maxR*f)}</text>`; });
  months.forEach((m, i) => { const x = 50 + i*bw, h = m.rev/maxR*(CH - 60), hp = m.paid/maxR*(CH - 60); chart += `<rect x="${x + 4}" y="${CH - 30 - h}" width="${bw - 8}" height="${h}" rx="3" fill="var(--accent)" opacity=".35"><title>${m.label}: ${money(m.rev)} booked</title></rect><rect x="${x + 4}" y="${CH - 30 - hp}" width="${bw - 8}" height="${hp}" rx="3" fill="var(--accent)"><title>${m.label}: ${money(m.paid)} collected</title></rect><text x="${x + bw/2}" y="${CH - 12}" text-anchor="middle" style="font:500 10px Manrope,sans-serif" fill="var(--muted)">${m.label}</text>`; });
  chart += '</svg>';
  const count = (arr, f) => { const m = {}; arr.forEach(e => { const k = f(e); if(k) m[k] = (m[k] || 0) + 1; }); return Object.entries(m).sort((a, b) => b[1] - a[1]); };
  const bars = (rows, total) => rows.length ? `<div class="hbars">${rows.map(([k, n], i) => `<div><span>${esc(k)}</span><i style="width:${n/Math.max(1, total)*100}%;background:${CAT_COLORS[i % CAT_COLORS.length]}"></i><b>${n}</b></div>`).join('')}</div>` : '<p class="muted">Nothing yet.</p>';
  const byType = count(evs, e => EVENT_TYPES[e.eventType]), byPkg = count(evs, e => (e.choices && e.choices.package) ? e.choices.package.split('·').pop().trim() : 'No package'), addOns = {}; evs.forEach(e => ((e.choices || {}).addons || []).forEach(a => addOns[a] = (addOns[a] || 0) + 1)); const topAdd = Object.entries(addOns).sort((a, b) => b[1] - a[1]).slice(0, 8);
  const conv = evs.length ? Math.round(won.length/evs.length*100) : 0;
  return `<div class="inv-stats"><div class="stat"><b>${money(totalRev)}</b><span>booked revenue</span></div><div class="stat"><b>${money(collected)}</b><span>collected · ${totalRev ? Math.round(collected/totalRev*100) : 0}%</span></div><div class="stat"><b>${won.length ? money(totalRev/won.length) : '—'}</b><span>average per event</span></div><div class="stat"><b>${guests ? money(totalRev/guests) : '—'}</b><span>average per guest</span></div></div>
    <div class="inv-card"><h4 class="pv-h4">Revenue by event month <span class="muted" style="text-transform:none;letter-spacing:0">· solid = collected, light = booked</span></h4>${chart}</div>
    <div class="sheet-grid"><section><h2>Conversion</h2><div class="conv"><b>${conv}%</b><span>of ${evs.length} inquiries booked</span></div>${bars(Object.entries(STATUSES).map(([k, [n]]) => [n, portalEvents.filter(e => e.status === k).length]).filter(([, n]) => n), portalEvents.length)}</section>
      <section><h2>Packages sold</h2>${bars(byPkg, evs.length)}</section><section><h2>Events by type</h2>${bars(byType, evs.length)}</section><section><h2>Most popular add-ons</h2>${bars(topAdd, evs.length)}</section></div>`;
}

/* ============ templates ============ */
let templates = [];
function templateFromState(name){
  const p = JSON.parse(JSON.stringify(state));
  ['client','payments','contract','messages','activity','checkin','portalId','portalStatus','staff','package','approvals','followups','linenReturn','seatRules','vendorIn','inquiry','speakers','odoo','holdUntil'].forEach(k => delete p[k]); if(p.invite) p.invite.rsvpBy = ''; if(p.linenQuote){ p.linenQuote.out = ''; p.linenQuote.back = ''; }
  p.guests = []; p.sample = false; p.event = Object.assign({}, p.event, {name, date:''}); (p.tasks || []).forEach(t => t.done = false); if(p.music) p.music.requests_list = []; if(p.dayof) p.dayof = {done:{}};
  (p.items || []).forEach(i => { if(i.kind === 'table') i.number = i.number; }); return p;
}
async function saveTemplate(name){
  const plan = templateFromState(name), id = 't' + Date.now().toString(36) + uid(), L = state.looks[0];
  const doc = {name, eventType:state.eventType || 'wedding', theme:state.themeLabel || L.name, palette:[L.cloth, L.napkin, L.flower1, L.flower2], setting:SETTINGS[venue().setting].label, tables:tables().length, createdAt:Date.now(), plan};
  try { if(DB) await DB.doc('templates/' + id).set(doc); else { const list = JSON.parse(ls.get('tablescape-templates') || '[]'); list.unshift(Object.assign({id}, doc)); ls.set('tablescape-templates', JSON.stringify(list)); templates = list; } toast(`Saved “${name}” as a template`); }
  catch(e){ toast(e.code === 'invalid_argument' ? 'You don’t have permission to save templates.' : 'Couldn’t save the template.'); }
  renderPortalIfOpen();
}
function templatesHTML(){
  return `<section class="inv-card"><div class="sheet-head" style="padding-bottom:10px"><div><span class="eyebrow">Templates</span><h2 style="font-family:var(--display);font-weight:400;font-size:24px">Start from a past design</h2><p class="muted" style="margin:4px 0 0">Saves the layout, designs, backdrops, menu, bar, music, timeline and checklist, without guests, client details or payments.</p></div>
    <form id="tpl-form" class="walkin"><input id="tpl-name" placeholder="Template name, e.g. Garden wedding 150" aria-label="Template name"><button class="btn primary" type="submit">Save current event as template</button></form></div>
    <div class="tpl-grid">${templates.length ? templates.map(t => `<div class="tpl"><div class="ev-pal">${(t.palette || []).map(c => `<i style="background:${esc(c)}"></i>`).join('')}</div><b>${esc(t.name)}</b><span class="muted">${esc(EVENT_TYPES[t.eventType] || '')} · ${esc(t.theme || '')} · ${esc(t.setting || '')} · ${t.tables || 0} tables</span><div class="btn-row" style="margin:0"><button class="btn sm primary" data-tpluse="${t.id}">New event from this</button>${canAdmin ? `<button class="x" data-tpldel="${t.id}" aria-label="Delete template">×</button>` : ''}</div></div>`).join('') : '<p class="muted">No templates yet. Save a finished event to reuse its design.</p>'}</div></section>`;
}
document.addEventListener('submit', e => { if(e.target.id !== 'tpl-form') return; e.preventDefault(); const n = ($('#tpl-name').value || '').trim() || state.event.name + ' template'; saveTemplate(n); });
$('#view-events').addEventListener('click', async e => {
  const u = e.target.closest('[data-tpluse]'); if(u){ const t = templates.find(x => x.id === u.dataset.tpluse); if(!t) return; let plan = t.plan; if(!plan && DB){ const s = await DB.doc('templates/' + t.id).get(); plan = s.exists ? s.data().plan : null; } if(!plan) return; pushUndo(); state = JSON.parse(JSON.stringify(plan)); state.event.name = t.name.replace(/ template$/i, '') + ' (new)'; sel = null; picked = null; activeLook = state.looks[0].id; activeBd = null; if(V) V.placed = false; viewInit = false; logActivity(`Started from the “${t.name}” template`); save(); renderAll(); switchView('floor'); toast('New event created from the template. Add guests and a date, then save it.'); return; }
  const d = e.target.closest('[data-tpldel]'); if(d){ try { if(DB) await DB.doc('templates/' + d.dataset.tpldel).delete(); else { templates = templates.filter(t => t.id !== d.dataset.tpldel); ls.set('tablescape-templates', JSON.stringify(templates)); } toast('Template deleted'); } catch(err){ toast('Couldn’t delete the template.'); } renderPortalIfOpen(); }
});
function initTemplates(){ try { templates = JSON.parse(ls.get('tablescape-templates') || '[]'); } catch(e){} if(DB){ try { DB.collection('templates').orderBy('createdAt', 'desc').limit(100).onSnapshot(s => { templates = s.docs.map(d => { const x = d.data(); return {id:d.id, name:x.name, eventType:x.eventType, theme:x.theme, palette:x.palette, setting:x.setting, tables:x.tables, plan:x.plan}; }); renderPortalIfOpen(); }, () => {}); } catch(e){} } }

/* ============ rental reservations across events ============ */
/* An event holds its linens from the delivery day through the return day plus the laundry turnaround. */
function laundryDays(){ const v = company.laundryDays, n = +v; return v === undefined || v === null || v === '' || !isFinite(n) ? 1 : Math.max(0, Math.min(14, Math.round(n))); }
function holdSpan(e){
  const d = e.date || '', o = e.linenOut || shiftIso(d, -1), b = e.linenBack || shiftIso(d, 1);
  if(!o || !b) return null; const [a, z] = o <= b ? [o, b] : [b, o]; return [a, shiftIso(z, laundryDays())];
}
function curHoldSpan(){ const Q = state.linenQuote || {}; return state.event.date ? holdSpan({date:state.event.date, linenOut:Q.out, linenBack:Q.back}) : null; }
const inSpan = (iso, sp) => !!(iso && sp && iso >= sp[0] && iso <= sp[1]), spansMeet = (a, b) => !!(a && b && a[0] <= b[1] && b[0] <= a[1]);
const holdsLinens = e => e.status !== 'cancelled' && e.date && Array.isArray(e.linens) && e.linens.length;
function peakHeld(sp, skipId, pool){
  const m = new Map(); if(!sp) return m;
  const evs = (pool || portalEvents).filter(e => e.id !== skipId && holdsLinens(e)).map(e => [e, holdSpan(e)]).filter(([, h]) => spansMeet(h, sp));
  for(let iso = sp[0], i = 0; iso && iso <= sp[1] && i < 60; iso = shiftIso(iso, 1), i++){
    const day = new Map(); evs.forEach(([e, h]) => { if(inSpan(iso, h)) e.linens.forEach(([k, q]) => day.set(k, (day.get(k) || 0) + (+q || 0))); });
    day.forEach((q, k) => { if(q > (m.get(k) || 0)) m.set(k, q); });
  }
  return m;
}
function reservedByOthers(){ return peakHeld(curHoldSpan(), state.portalId); }
function reservingEvents(){ const sp = curHoldSpan(); if(!sp) return []; return portalEvents.filter(e => e.id !== state.portalId && holdsLinens(e) && spansMeet(holdSpan(e), sp)); }

/* ============ accessibility & dietary tags ============ */
const NEEDS = {wheelchair:'Wheelchair', mobility:'Mobility: aisle seat', hearing:'Hearing: near speakers/interpreter', vision:'Low vision', highchair:'High chair'};
const DIET_TAGS = {V:'Vegetarian', VG:'Vegan', GF:'Gluten-free', DF:'Dairy-free', NF:'Nut allergy', SF:'Shellfish allergy', Halal:'Halal', Kosher:'Kosher'};
let gDetail = null;
function guestDetailHTML(g){
  return `<li class="gdetail"><div class="chips">${Object.entries(NEEDS).map(([k, n]) => `<button class="chip" data-gneed="${k}" data-g="${g.id}" aria-pressed="${(g.needs || []).includes(k)}">${esc(n)}</button>`).join('')}</div>
    <div class="chips">${Object.entries(DIET_TAGS).map(([k, n]) => `<button class="chip" data-gdiet="${k}" data-g="${g.id}" aria-pressed="${(g.dietTags || []).includes(k)}">${esc(n)}</button>`).join('')}</div>
    <div class="fld-row"><label class="fld"><span>Dietary notes</span><input data-gf="diet" data-g="${g.id}" value="${esc(g.diet || '')}" placeholder="e.g. severe peanut allergy"></label><label class="fld"><span>Email</span><input data-gf="email" data-g="${g.id}" value="${esc(g.email || '')}"></label></div>
    <div class="fld-row"><label class="fld"><span>Company or school</span><input data-gf="company" data-g="${g.id}" value="${esc(g.company || '')}" placeholder="For badges"></label><label class="fld"><span>Title or role</span><input data-gf="title" data-g="${g.id}" value="${esc(g.title || '')}" placeholder="e.g. Keynote speaker"></label></div>
    ${householdHTML(g)}<label class="toggle" style="padding-left:0"><input type="checkbox" data-glock="${g.id}" ${(state.seatRules?.locked || {})[g.id] ? 'checked' : ''}> Keep this guest’s seat when optimizing</label></li>`;
}
const needIcons = g => [(g.needs || []).includes('wheelchair') ? 'W' : '', (g.needs || []).filter(n => n !== 'wheelchair').length ? 'A' : '', ...(g.dietTags || [])].filter(Boolean);
function accessibilityChecks(){
  const out = [], sm = new Map(tables().map(t => [t.id, t]));
  const wc = state.guests.filter(g => (g.needs || []).includes('wheelchair') && g.rsvp !== 'no');
  const ts = tables(), chairs = new Map(ts.map(t => [t.id, seatPositions(t).map(p => worldPt(t, p))]));
  [...new Set(wc.filter(g => g.tableId).map(g => g.tableId))].forEach(tid => { const t = sm.get(tid); if(!t) return; let min = Infinity; ts.forEach(o => { if(o.id === tid) return; chairs.get(tid).forEach(p => chairs.get(o.id).forEach(q => { min = Math.min(min, Math.hypot(p.x - q.x, p.y - q.y)); })); }); if(min < 3.5) out.push(`${tableLabel(t)} has a wheelchair guest but only ${min.toFixed(1)} ft between chairs and the next table. Leave at least 3 ft (5 ft is better).`); });
  wc.filter(g => !g.tableId && !blockWhere(g)).forEach(g => out.push(`${g.name} uses a wheelchair and doesn’t have a seat yet.`));
  return out;
}

/* ============ seating optimizer ============ */
const seatRules = () => state.seatRules || teamObjCS('seatRules', () => ({together:[], apart:[], vip:[], locked:{}}));
function frontPoint(){ const f = state.items.find(i => i.type === 'sweet' || i.type === 'head') || state.items.find(i => i.type === 'dance') || state.items.find(i => i.type === 'stage'); return f ? {x:f.x, y:f.y} : {x:state.room.w/2, y:0}; }
function seatingCost(assign, ctx){
  let c = 0; const {rules, tableOf, groups, cap, fp, maxD} = ctx;
  rules.together.forEach(([a, b]) => { if(assign[a] && assign[b] && assign[a] !== assign[b]) c += 12; });
  rules.apart.forEach(([a, b]) => { if(assign[a] && assign[a] === assign[b]) c += 18; });
  Object.entries(groups).forEach(([gname, ids]) => { const tset = new Set(ids.map(id => assign[id]).filter(Boolean)); const need = Math.ceil(ids.length/ctx.avgCap); c += Math.max(0, tset.size - need)*3; if(rules.vip.includes(gname)) ids.forEach(id => { const t = tableOf[assign[id]]; if(t) c += Math.hypot(t.x - fp.x, t.y - fp.y)/maxD*4; }); });
  ctx.wheel.forEach(id => { const t = tableOf[assign[id]]; if(t && ctx.tight.has(t.id)) c += 6; });
  return c;
}
function optimizeSeating(){
  const rules = seatRules(), ts = tables().filter(t => t.seats > 0 && !['sweet','head'].includes(t.type)), tableOf = Object.fromEntries(ts.map(t => [t.id, t]));
  const fixedT = new Set(tables().filter(t => ['sweet','head'].includes(t.type)).map(t => t.id));
  const movable = state.guests.filter(g => g.rsvp !== 'no' && !rules.locked[g.id] && !fixedT.has(g.tableId) && (g.tableId || !blockWhere(g)));
  const lockedIn = state.guests.filter(g => g.tableId && tableOf[g.tableId] && (rules.locked[g.id]));
  const cap = Object.fromEntries(ts.map(t => [t.id, t.seats - lockedIn.filter(g => g.tableId === t.id).length]));
  const assign = {}; lockedIn.forEach(g => assign[g.id] = g.tableId);
  const load = Object.fromEntries(ts.map(t => [t.id, 0]));
  movable.forEach(g => { if(g.tableId && tableOf[g.tableId] && load[g.tableId] < cap[g.tableId]){ assign[g.id] = g.tableId; load[g.tableId]++; } });
  movable.filter(g => !assign[g.id]).forEach(g => { const t = ts.find(t => load[t.id] < cap[t.id]); if(t){ assign[g.id] = t.id; load[t.id]++; } });
  const groups = {}; state.guests.filter(g => g.rsvp !== 'no').forEach(g => (groups[g.group || 'Other'] ||= []).push(g.id));
  const fp = frontPoint(), maxD = Math.hypot(state.room.w, state.room.h) || 1;
  const ch = new Map(tables().map(t => [t.id, seatPositions(t).map(p => worldPt(t, p))])), tight = new Set();
  ts.forEach(t => { let min = Infinity; tables().forEach(o => { if(o.id === t.id) return; ch.get(t.id).forEach(p => ch.get(o.id).forEach(q => min = Math.min(min, Math.hypot(p.x - q.x, p.y - q.y)))); }); if(min < 3.5) tight.add(t.id); });
  const ctx = {rules, tableOf, groups, cap, fp, maxD, avgCap: ts.reduce((a, t) => a + t.seats, 0)/Math.max(1, ts.length), wheel: state.guests.filter(g => (g.needs || []).includes('wheelchair')).map(g => g.id), tight};
  const before = seatingCost(Object.fromEntries(state.guests.filter(g => g.tableId).map(g => [g.id, g.tableId])), ctx);
  let cost = seatingCost(assign, ctx); const R = rng(Date.now() % 100000), ids = movable.map(g => g.id).filter(id => assign[id]); let temp = 2;
  for(let it = 0; it < 6000 && ids.length > 1; it++){
    const a = ids[Math.floor(R()*ids.length)], ta = assign[a]; let b = null, tb;
    if(R() < .3){ const t = ts[Math.floor(R()*ts.length)]; if(t.id === ta || load[t.id] >= cap[t.id]) continue; assign[a] = t.id; const nc = seatingCost(assign, ctx); if(nc <= cost || R() < Math.exp((cost - nc)/temp)){ load[ta]--; load[t.id]++; cost = nc; } else assign[a] = ta; }
    else { b = ids[Math.floor(R()*ids.length)]; tb = assign[b]; if(ta === tb) continue; assign[a] = tb; assign[b] = ta; const nc = seatingCost(assign, ctx); if(nc <= cost || R() < Math.exp((cost - nc)/temp)) cost = nc; else { assign[a] = ta; assign[b] = tb; } }
    temp *= .9993;
  }
  let moved = 0;
  mutate(() => {
    ts.forEach(t => { const here = state.guests.filter(g => assign[g.id] === t.id); const lockedSeats = new Set(here.filter(g => rules.locked[g.id]).map(g => g.seat)); const free = Array.from({length:t.seats}, (_, i) => i).filter(i => !lockedSeats.has(i));
      const order = here.filter(g => !rules.locked[g.id]).sort((x, y) => (x.group || '').localeCompare(y.group || '') || x.name.split(' ').slice(-1)[0].localeCompare(y.name.split(' ').slice(-1)[0]));
      const seq = []; order.forEach(g => { if(seq.includes(g)) return; seq.push(g); rules.together.forEach(([p, q]) => { const mate = p === g.id ? q : q === g.id ? p : null; const m = mate && order.find(x => x.id === mate); if(m && !seq.includes(m)) seq.push(m); }); });
      seq.forEach((g, i) => { if(g.tableId !== t.id) moved++; g.tableId = t.id; g.seat = free[i]; }); });
    movable.forEach(g => { if(!assign[g.id] && g.tableId && tableOf[g.tableId]){ unassign(g); moved++; } });
    logActivity(`Seating optimized: ${moved} guests moved`);
  });
  return {before:Math.round(before), after:Math.round(cost), moved};
}
function detectCouples(){ const r = seatRules(), byKey = {}; state.guests.filter(g => g.rsvp !== 'no').forEach(g => { const k = (g.group || '') + '|' + g.name.split(' ').slice(-1)[0]; (byKey[k] ||= []).push(g.id); }); let n = 0; Object.values(byKey).forEach(ids => { for(let i = 0; i + 1 < ids.length; i += 2){ if(!r.together.some(([a, b]) => (a === ids[i] && b === ids[i+1]) || (a === ids[i+1] && b === ids[i]))){ r.together.push([ids[i], ids[i+1]]); n++; } } }); return n; }
function seatRulesHTML(){
  const r = seatRules(), gname = id => (state.guests.find(g => g.id === id) || {}).name || 'Removed guest', opts = state.guests.filter(g => g.rsvp !== 'no').sort((a, b) => a.name.localeCompare(b.name)).map(g => `<option value="${g.id}">${esc(g.name)}</option>`).join(''), groupsL = [...new Set(state.guests.map(g => g.group).filter(Boolean))];
  return `<details class="rules"${rulesOpen ? ' open' : ''}><summary>Seating rules &amp; optimizer · ${r.together.length} together · ${r.apart.length} apart</summary>
    <div class="rules-grid"><div><span class="eyebrow">Keep together</span><ul class="task-list">${r.together.map(([a, b], i) => `<li><span>${esc(gname(a))} + ${esc(gname(b))}</span><button class="x" data-rdel="together:${i}" aria-label="Remove rule">×</button></li>`).join('') || '<li class="muted">No rules yet.</li>'}</ul></div>
      <div><span class="eyebrow">Keep apart</span><ul class="task-list">${r.apart.map(([a, b], i) => `<li><span>${esc(gname(a))} ≠ ${esc(gname(b))}</span><button class="x" data-rdel="apart:${i}" aria-label="Remove rule">×</button></li>`).join('') || '<li class="muted">No rules yet.</li>'}</ul></div></div>
    <div class="rule-add"><select id="rule-a" aria-label="First guest">${opts}</select><select id="rule-kind" aria-label="Rule"><option value="together">sits with</option><option value="apart">doesn’t sit with</option></select><select id="rule-b" aria-label="Second guest">${opts}</select><button class="btn sm" data-radd="1">Add rule</button><button class="btn sm" data-rcouples="1">Detect couples</button></div>
    <span class="eyebrow">Seat near the front</span><div class="chips">${groupsL.map(g => `<button class="chip" data-rvip="${esc(g)}" aria-pressed="${r.vip.includes(g)}">${esc(g)}</button>`).join('')}</div>
    <div class="btn-row"><button class="btn primary" data-ropt="1">Optimize seating</button><span class="muted" style="font-size:12px">Keeps groups together, follows your rules, seats priority groups near the front, keeps wheelchair guests at roomy tables, and leaves locked guests where they are. Ctrl+Z undoes it.</span></div></details>`;
}
document.addEventListener('click', e => {
  if(currentView !== 'guests') return; const t = e.target, r = seatRules();
  const gd = t.closest('[data-gdetail]'); if(gd){ gDetail = gDetail === gd.dataset.gdetail ? null : gd.dataset.gdetail; renderGuestList(); return; }
  const gn = t.closest('[data-gneed]'); if(gn){ const g = state.guests.find(x => x.id === gn.dataset.g), k = gn.dataset.gneed; mutate(() => { g.needs = g.needs || []; g.needs = g.needs.includes(k) ? g.needs.filter(x => x !== k) : [...g.needs, k]; }); renderGuestList(); renderPlan(); return; }
  const gt = t.closest('[data-gdiet]'); if(gt){ const g = state.guests.find(x => x.id === gt.dataset.g), k = gt.dataset.gdiet; mutate(() => { g.dietTags = g.dietTags || []; g.dietTags = g.dietTags.includes(k) ? g.dietTags.filter(x => x !== k) : [...g.dietTags, k]; }); renderGuestList(); return; }
  const rd = t.closest('[data-rdel]'); if(rd){ const [k, i] = rd.dataset.rdel.split(':'); mutate(() => r[k].splice(+i, 1)); renderBoard(); return; }
  if(t.closest('[data-radd]')){ const a = $('#rule-a').value, b = $('#rule-b').value, k = $('#rule-kind').value; if(a === b){ toast('Pick two different guests.'); return; } mutate(() => r[k].push([a, b])); renderBoard(); return; }
  if(t.closest('[data-rcouples]')){ let n; mutate(() => n = detectCouples()); renderBoard(); toast(n ? `Found ${n} likely couples (same last name and group)` : 'No new couples found'); return; }
  const rv = t.closest('[data-rvip]'); if(rv){ const g = rv.dataset.rvip; mutate(() => r.vip = r.vip.includes(g) ? r.vip.filter(x => x !== g) : [...r.vip, g]); renderBoard(); return; }
  if(t.closest('[data-ropt]')){ const res = optimizeSeating(); renderGuests(); renderPlan(); updateTabs(); toast(`Seating optimized: ${res.moved} guests moved. Rule score ${res.before} → ${res.after} (lower is better).`); }
});
document.addEventListener('change', e => { const t = e.target; if(t.dataset.glock){ mutate(() => { const r = seatRules(); if(t.checked) r.locked[t.dataset.glock] = true; else delete r.locked[t.dataset.glock]; }); } });
document.addEventListener('input', e => { const t = e.target; if(t.dataset.gf){ const g = state.guests.find(x => x.id === t.dataset.g); if(g) mutate(() => g[t.dataset.gf] = t.value, 'gf-' + g.id + t.dataset.gf); } });

/* ============ client approvals ============ */
const APPROVAL_AREAS = {floor:'Floor plan', tables:'Table designs', backdrop:'Backdrops', invites:'Invitations', menu:'Dinner menu', cake:'Cake', bar:'Bar', music:'Music & vibe'};
const hashStr = s => { let h = 5381; for(let i = 0; i < s.length; i++) h = (h*33 ^ s.charCodeAt(i)) >>> 0; return h.toString(36); };
function areaHash(a){ const x = {floor: state.items.map(i => [i.type, Math.round(i.x), Math.round(i.y), i.rot || 0]), tables: state.looks, backdrop: state.backdrops, invites: state.invite ? Object.assign({}, state.invite, {template:null}) : null, menu: state.menuChoices, cake: state.cake, bar: state.bar, music: state.music ? Object.assign({}, state.music, {requests_list:null}) : null}[a]; return hashStr(JSON.stringify(x || null)); }
const approvals = () => state.approvals || teamObjCS('approvals', () => ({}));
function approvalState(a){ const ap = approvals()[a]; if(!ap) return 'pending'; if(ap.status === 'approved' && ap.hash !== areaHash(a)) return 'updated'; return ap.status; }
const AP_LABEL = {pending:['Awaiting review',''], approved:['Approved','ok'], changes:['Changes requested','warn'], updated:['Updated since approval','caution']};
function approvalsHTML(){
  const thumb = {floor: () => `<div class="ap-floor">${tables().length} tables · ${tables().reduce((a, t) => a + t.seats, 0)} seats</div>`, tables: () => previewSVG(state.looks[0], 60), backdrop: () => bdList()[0] ? backdropSVG(bdList()[0], {mode:'export', id:'apb', dens:.4}) : '', invites: () => inviteSVG('invitation', {id:'api'}), menu: () => dinnerMenuSVG(), cake: () => hasCake() ? cakeSVG(cake()) : '<p class="muted">No cake yet</p>', bar: () => barMenuSVG(), music: () => `<pre class="brief" style="max-height:180px">${esc(djBrief().split('\n').slice(3, 14).join('\n'))}</pre>`};
  const n = Object.keys(APPROVAL_AREAS).filter(a => approvalState(a) === 'approved').length;
  return `<div class="bu-bar" aria-hidden="true"><i style="width:${n/8*100}%;background:var(--ok)"></i></div><p class="muted" style="margin:0">${n} of 8 areas approved${clientMode ? '. Approve each design, or ask for changes with a note.' : '. Clients approve or request changes from their link.'}</p>
    <div class="ap-grid">${Object.entries(APPROVAL_AREAS).map(([a, n]) => { const st = approvalState(a), ap = approvals()[a] || {}; return `<div class="ap ${st}"><div class="ap-head"><b>${esc(n)}</b><span class="pill ${AP_LABEL[st][1]}">${AP_LABEL[st][0]}</span></div><div class="ap-art">${thumb[a]()}</div>
      ${ap.note ? `<p class="ap-note">“${esc(ap.note)}”<br><span class="muted">${esc(ap.by || '')} · ${esc(ago(ap.at))}</span></p>` : ''}
      <textarea class="iv-msg" rows="2" id="apn-${a}" placeholder="${clientMode ? 'What would you like changed?' : 'Note (optional)'}"></textarea>
      <div class="btn-row" style="margin:0"><button class="btn sm primary" data-approve="${a}">Approve</button><button class="btn sm" data-changes="${a}">Request changes</button>${!clientMode ? `<button class="btn sm" data-apgo="${a}">Open</button>` : ''}</div></div>`; }).join('')}</div>`;
}
$('#view-client').addEventListener('click', e => {
  const ap = e.target.closest('[data-approve]'), ch = e.target.closest('[data-changes]'), go = e.target.closest('[data-apgo]');
  if(ap || ch){ const a = (ap || ch).dataset[ap ? 'approve' : 'changes'], note = ($('#apn-' + a) || {}).value || ''; if(ch && !note.trim()){ toast('Add a note describing the changes.'); return; } const by = clientMode ? ((state.client || {}).name || 'Client') : company.name; mutate(() => { approvals()[a] = {status: ap ? 'approved' : 'changes', note:note.trim(), by, at:Date.now(), hash:areaHash(a)}; logActivity(`${APPROVAL_AREAS[a]} ${ap ? 'approved' : 'needs changes'}${note.trim() ? ': ' + note.trim() : ''}`, by); }); if(state.portalId) saveToPortal(true); renderClient(); return; }
  if(go){ switchView({floor:'floor', tables:'style', backdrop:'backdrop', invites:'invites', menu:'menu', cake:'menu', bar:'menu', music:'music'}[go.dataset.apgo]); if(go.dataset.apgo === 'cake'){ menuTab = 'cake'; renderMenu(); } if(go.dataset.apgo === 'bar'){ menuTab = 'bar'; renderMenu(); } if(go.dataset.apgo === 'menu'){ menuTab = 'dinner'; renderMenu(); } }
});

/* ============ follow-ups ============ */
const followState = () => (state.followups ||= {});
function followupsList(){
  const out = [], today = new Date(); today.setHours(0,0,0,0); const cl = state.client || {}, first = (cl.name || 'there').split(' ')[0];
  if(state.payments){ const total = contractTotal(); state.payments.schedule.forEach(s => { if(!s.paid && new Date(s.due + 'T00:00') < today){ const amt = money(payAmt(s, total)); out.push({key:'pay-' + s.id, sev:'warn', title:`${s.label} overdue`, detail:`${amt} was due ${shortFmt(s.due)}`, to:cl.email, subject:`Payment reminder: ${state.event.name}`, msg:`Hi ${first}, a friendly reminder that the ${s.label.toLowerCase()} of ${amt} for ${state.event.name} was due ${shortFmt(s.due)}. Let us know if you have any questions. Thank you!`}); } }); }
  const rb = rsvpByDate(), pend = state.guests.filter(g => g.rsvp === 'pending');
  if(pend.length && rb){ const d = (new Date(rb + 'T00:00') - today)/864e5; if(d <= 7) out.push({key:'rsvp-' + rb, sev: d < 0 ? 'warn' : 'caution', title:`${pend.length} RSVPs ${d < 0 ? 'past the deadline' : 'still pending'}`, detail: d < 0 ? `Deadline was ${shortFmt(rb)}` : `Deadline ${shortFmt(rb)}`, action:'rsvp'}); }
  const C = state.contract; if(C && C.sentAt && !C.client && (Date.now() - C.sentAt) > 3*864e5) out.push({key:'contract', sev:'caution', title:'Agreement not signed yet', detail:`Sent ${ago(C.sentAt)}`, to:cl.email, subject:`Your agreement for ${state.event.name}`, msg:`Hi ${first}, just checking in. Your agreement for ${state.event.name} is ready to sign: ${state.portalId ? `${ARTIFACT_URL}#ev-${state.portalId}${tsTok(state.portalId)}` : ''}`});
  Object.entries(APPROVAL_AREAS).forEach(([a, n]) => { const st = approvalState(a); if(st === 'changes' && !clientMode) out.push({key:'ap-' + a + (approvals()[a] || {}).at, sev:'caution', title:`Client requested changes: ${n}`, detail:(approvals()[a] || {}).note || '', action:'approvals'}); });
  (state.tasks || []).forEach(t => { const td = taskDate(t); if(td && !t.done && td < today) out.push({key:'task-' + t.id, sev:'caution', title:`Overdue task: ${t.title}`, detail:`Was due ${taskDay(td)}`, action:'tasks', task:t.id}); });
  const d = eventDate(); if(d && (d - today)/864e5 < 180) (state.vendors || []).filter(v => v.status === 'inquiring' && v.role !== 'Officiant').forEach(v => out.push({key:'vendor-' + v.id, sev:'caution', title:`${v.role} not booked yet`, detail:'Less than 6 months to go', action:'vendors'}));
  const fs = followState(); return out.filter(f => !(fs[f.key] && (fs[f.key].done || (fs[f.key].until && fs[f.key].until > Date.now()))));
}
function followupsHTML(){
  const list = followupsList();
  return `<div class="ci-top inv-card"><div><span class="eyebrow">Follow-ups</span><h2>${list.length ? `${list.length} thing${list.length > 1 ? 's' : ''} need${list.length > 1 ? '' : 's'} attention` : 'All caught up'}</h2></div></div>
    <div class="rem-list">${list.map(f => `<div class="rem ${f.sev === 'warn' ? 'late' : ''}"><div class="rem-date"><span class="pill ${f.sev}">${esc(f.tag || (f.sev === 'warn' ? 'Overdue' : 'Soon'))}</span></div><div class="rem-main"><b>${esc(f.title)}</b><span>${esc(f.detail)}</span>${f.msg ? `<p>${esc(f.msg)}</p>` : ''}</div>
      <div class="rem-act">${f.msg ? `<button class="btn sm" data-fucopy="${esc(f.key)}">Copy message</button>${f.to ? `<a class="btn sm" href="mailto:${encodeURIComponent(f.to)}?subject=${encodeURIComponent(f.subject)}&body=${encodeURIComponent(f.msg)}" target="_blank" rel="noopener">Email client</a>` : ''}` : ''}${f.action ? `<button class="btn sm" data-fugo="${f.action}">Open</button>` : ''}<button class="btn sm" data-fusnooze="${esc(f.key)}">Snooze 3 days</button><button class="btn sm primary" data-fudone="${esc(f.key)}">Done</button></div></div>`).join('')}</div>
    <p class="muted" style="font-size:12px;margin:0">Follow-ups are worked out from payments, RSVPs, the final guest count, the agreement, approvals, tasks, vendors and linen returns. The page can’t send them for you; copy the message or open your email.</p>`;
}
$('#view-plan').addEventListener('click', e => {
  const t = e.target, fs = followState();
  const c = t.closest('[data-fucopy]'); if(c){ const f = followupsList().find(x => x.key === c.dataset.fucopy); if(f) copyText(f.msg, 'Message copied'); return; }
  const s = t.closest('[data-fusnooze]'); if(s){ mutate(() => fs[s.dataset.fusnooze] = {until:Date.now() + 3*864e5}); renderPlanning(); return; }
  const d = t.closest('[data-fudone]'); if(d){ mutate(() => fs[d.dataset.fudone] = {done:Date.now()}); renderPlanning(); return; }
  const g = t.closest('[data-fugo]'); if(g){ const a = g.dataset.fugo; if(a === 'rsvp'){ sendKind = 'rsvpnudge'; sendFilter = 'pending'; invTab = 'send'; switchView('invites'); } else if(a === 'approvals'){ clientTab = 'approvals'; switchView('client'); } else { planTab = a; renderPlanning(); } }
});
function attentionAcross(){
  const today = isoLocal(), out = [];
  portalEvents.filter(e => e.status !== 'cancelled' && e.status !== 'completed').forEach(e => { (e.dues || []).forEach(d => { if(!d.paid && d.due < today) out.push({e, text:`${d.label} overdue (${money(d.amt)})`, sev:'warn'}); }); if(e.pending && e.rsvpBy && e.rsvpBy <= today) out.push({e, text:`${e.pending} RSVPs past deadline`, sev:'caution'}); if(e.changesRequested) out.push({e, text:`Client requested changes on ${e.changesRequested}`, sev:'caution'}); if(e.status === 'proposal' && !e.contractSigned && e.updatedAt && Date.now() - e.updatedAt > 7*864e5) out.push({e, text:'Proposal waiting over a week', sev:'caution'}); });
  return out;
}

/* ============ sun, light & weather planning ============ */
const CITIES = {'Los Angeles, CA':[34.05,-118.24,-8,'us'],'San Diego, CA':[32.72,-117.16,-8,'us'],'San Jose, CA':[37.34,-121.89,-8,'us'],'San Francisco, CA':[37.77,-122.42,-8,'us'],'Las Vegas, NV':[36.17,-115.14,-8,'us'],'Phoenix, AZ':[33.45,-112.07,-7,''],'Denver, CO':[39.74,-104.99,-7,'us'],'Dallas, TX':[32.78,-96.8,-6,'us'],'Houston, TX':[29.76,-95.37,-6,'us'],'Austin, TX':[30.27,-97.74,-6,'us'],'San Antonio, TX':[29.42,-98.49,-6,'us'],'Chicago, IL':[41.88,-87.63,-6,'us'],'Nashville, TN':[36.16,-86.78,-6,'us'],'Detroit, MI':[42.33,-83.05,-5,'us'],'Atlanta, GA':[33.75,-84.39,-5,'us'],'Miami, FL':[25.76,-80.19,-5,'us'],'Orlando, FL':[28.54,-81.38,-5,'us'],'New York, NY':[40.71,-74.01,-5,'us'],'Boston, MA':[42.36,-71.06,-5,'us'],'Washington, DC':[38.91,-77.04,-5,'us'],'Seattle, WA':[47.61,-122.33,-8,'us'],'Toronto, ON':[43.65,-79.38,-5,'us'],'Mexico City':[19.43,-99.13,-6,''],'Guadalajara':[20.66,-103.35,-6,''],'Cancún':[21.16,-86.85,-5,''],'San Juan, PR':[18.47,-66.11,-4,''],'London':[51.51,-0.13,0,'eu'],'Paris':[48.86,2.35,1,'eu'],'Rome':[41.9,12.5,1,'eu'],'Athens':[37.98,23.73,2,'eu'],'Dubai':[25.2,55.27,4,''],'Beirut':[33.89,35.5,2,'eu'],'Baghdad':[33.31,44.36,3,''],'Erbil':[36.19,44.01,3,''],'Yerevan':[40.18,44.51,4,''],'Mumbai':[19.08,72.88,5.5,''],'Manila':[14.6,120.98,8,''],'Seoul':[37.57,126.98,9,''],'Sydney':[-33.87,151.21,10,'au']};
function dstOn(date, rule){ const y = date.getFullYear(), nthSun = (m, n) => { const d = new Date(y, m, 1); const first = (7 - d.getDay()) % 7 + 1; return new Date(y, m, first + (n - 1)*7); }, lastSun = m => { const d = new Date(y, m + 1, 0); return new Date(y, m, d.getDate() - d.getDay()); };
  if(rule === 'us') return date >= nthSun(2, 2) && date < nthSun(10, 1); if(rule === 'eu') return date >= lastSun(2) && date < lastSun(9); if(rule === 'au') return date < nthSun(3, 1) || date >= nthSun(9, 1); return false; }
function sunTimes(date, lat, lon, tz){
  const rad = Math.PI/180, d0 = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate())), J = d0/864e5 + 2440587.5, n = Math.round(J - 2451545 - 0.0009 - lon/360);
  const Js = 2451545 + 0.0009 + lon/360*-1*-1*0 + n - lon/360*0, M = (357.5291 + 0.98560028*(n + 0.0009 - lon/360)) % 360, C = 1.9148*Math.sin(M*rad) + 0.02*Math.sin(2*M*rad) + 0.0003*Math.sin(3*M*rad), L = (M + C + 180 + 102.9372) % 360;
  const Jt = 2451545 + 0.0009 - lon/360 + n + 0.0053*Math.sin(M*rad) - 0.0069*Math.sin(2*L*rad), dec = Math.asin(Math.sin(L*rad)*Math.sin(23.44*rad));
  const at = h => { const cosw = (Math.sin(h*rad) - Math.sin(lat*rad)*Math.sin(dec))/(Math.cos(lat*rad)*Math.cos(dec)); if(cosw < -1 || cosw > 1) return null; const w = Math.acos(cosw)/rad; return [Jt - w/360, Jt + w/360]; };
  const toLocal = j => { const ms = (j - 2440587.5)*864e5; const m = new Date(ms).getUTCHours()*60 + new Date(ms).getUTCMinutes() + tz*60; return ((m % 1440) + 1440) % 1440; };
  void Js; const sr = at(-0.833), gh = at(6), bh = at(-4), civ = at(-6);
  return sr ? {sunrise:toLocal(sr[0]), sunset:toLocal(sr[1]), goldenStart:gh ? toLocal(gh[1]) : null, blueEnd:bh ? toLocal(bh[1]) : null, dusk:civ ? toLocal(civ[1]) : null, noon:toLocal(Jt)} : null;
}
function moonPhase(date){ const p = ((date - new Date(Date.UTC(2000, 0, 6, 18, 14)))/864e5 % 29.53 + 29.53) % 29.53; return p < 1.8 ? 'New moon' : p < 7.4 ? 'Waxing crescent' : p < 9.2 ? 'First quarter' : p < 14.8 ? 'Waxing gibbous' : p < 16.6 ? 'Full moon' : p < 22.1 ? 'Waning gibbous' : p < 23.9 ? 'Last quarter' : 'Waning crescent'; }
function sunHTML(){
  const v = venue(), city = CITIES[v.city] ? v.city : 'Los Angeles, CA', c = CITIES[city], d = eventDate();
  if(!d) return '<p class="note">Set the event date to see sunset and golden hour.</p>';
  const tz = c[2] + (dstOn(d, c[3]) ? 1 : 0), s = sunTimes(d, c[0], c[1], tz), outdoor = isOutdoor(), m = d.getMonth(), lat = c[0];
  const hot = (lat > 0 ? [5,6,7,8] : [11,0,1,2]).includes(m) && Math.abs(lat) < 38, cold = (lat > 0 ? [11,0,1,2] : [5,6,7,8]).includes(m) && Math.abs(lat) > 30;
  const cer = state.timeline && state.timeline.find(x => /ceremony|misa|blessing/i.test(x.title));
  if(s){ if(s.goldenStart == null) s.goldenStart = s.sunset - 60; if(s.blueEnd == null) s.blueEnd = s.sunset + 30; if(s.dusk == null) s.dusk = s.sunset + 30; }
  const sug = s ? fromMin(s.sunset - 120) : null;
  const strip = s ? (() => { const W = 640, H = 70, X = mm => (mm - 600)/(1380 - 600)*W; const lab = [[s.goldenStart,'Golden hour'],[s.sunset,'Sunset'],[s.blueEnd,'Blue hour ends']].map(([mm, l]) => ({x:clamp(X(mm), 60, W - 60), t:`${l} ${fmt12(fromMin(mm))}`})); lab.forEach((a, i) => { a.row = 0; while(lab.slice(0, i).some(b => b.row === a.row && Math.abs(b.x - a.x) < 130)) a.row++; }); const rows = Math.max(...lab.map(a => a.row)) + 1;
      return `<svg viewBox="0 0 ${W} ${H + 10 + rows*14}" role="img" aria-label="Daylight across the event"><defs><linearGradient id="skyg" x1="0" x2="1"><stop offset="0" stop-color="#9fc4e8"/><stop offset="${clamp((s.goldenStart - 600)/780, 0, 1)}" stop-color="#cfe0ee"/><stop offset="${clamp((s.sunset - 600)/780, 0, 1)}" stop-color="#ffb46e"/><stop offset="${clamp((s.blueEnd - 600)/780, 0, 1)}" stop-color="#3b4a8a"/><stop offset="1" stop-color="#121633"/></linearGradient></defs><rect x="0" y="0" width="${W}" height="${H}" rx="10" fill="url(#skyg)"/>${(state.timeline || []).filter(x => x.type !== 'vendor').map(x => { const xx = X(toMin(x.time)); return xx >= 0 && xx <= W ? `<path d="M${xx} 8V${H - 8}" stroke="#fff" stroke-width="1.5" opacity=".7"/>` : ''; }).join('')}${lab.map(a => `<text x="${a.x}" y="${H + 16 + a.row*14}" text-anchor="middle" style="font:600 10px Manrope,sans-serif" fill="var(--muted)">${a.t}</text>`).join('')}${[600, 780, 960, 1140, 1320].map(mm => `<text x="${X(mm) + 4}" y="14" style="font:500 9px 'DM Mono',monospace" fill="rgba(0,0,0,.45)">${fmt12(fromMin(mm)).replace(':00', '')}</text>`).join('')}</svg>`; })() : '';
  return `<div class="inv-card sun-head"><label class="fld"><span>Venue city</span><select id="sun-city">${Object.keys(CITIES).map(k => `<option${k === city ? ' selected' : ''}>${esc(k)}</option>`).join('')}</select></label><p class="muted" style="margin:0;font-size:12.5px">${esc(fmtDate(state.event.date))} · times are local to the venue${dstOn(d, c[3]) ? ' (daylight saving)' : ''}</p></div>
    ${s ? `<div class="inv-stats"><div class="stat"><b>${fmt12(fromMin(s.sunset))}</b><span>sunset</span></div><div class="stat"><b>${fmt12(fromMin(s.goldenStart))}</b><span>golden hour begins</span></div><div class="stat"><b>${fmt12(fromMin(s.blueEnd))}</b><span>blue hour ends</span></div><div class="stat"><b style="font-size:20px">${moonPhase(d)}</b><span>moon</span></div></div>
    <div class="inv-card">${strip}<p class="muted" style="font-size:12px;margin:8px 0 0">White lines mark your run of show.</p></div>
    <div class="inv-card"><h4 class="pv-h4">Recommendations</h4><ul class="task-list">
      <li><span>Golden-hour portraits: ${fmt12(fromMin(s.goldenStart))}–${fmt12(fromMin(s.sunset))}. ${cer ? `Your ceremony is at ${fmt12(cer.time)}.` : ''}</span>${cer && sug ? `<button class="btn sm" data-sunshift="${sug}">Move ceremony to ${fmt12(sug)}</button>` : ''}</li>
      <li><span>${outdoor ? `Outdoor lighting needs to be on by ${fmt12(fromMin(s.dusk))} (dusk). String lights and lanterns should be lit before then.` : `Sunset is ${fmt12(fromMin(s.sunset))}. If the venue has windows, plan uplighting to take over as daylight fades.`}</span></li>
      ${outdoor ? `<li><span>Rain plan: reserve a tent or indoor backup. A ${state.room.w}×${state.room.h} ft tent covers this site.</span></li>` : ''}
      ${hot && outdoor ? '<li><span>Hot season: shade for the ceremony, water station, fans, and hold the ceremony after peak heat.</span></li>' : ''}
      ${cold && outdoor ? '<li><span>Cool season: patio heaters, blankets or pashminas, and a warm drink station.</span></li>' : ''}
      <li><span>Live forecasts aren’t available inside this page. Check the forecast about 10 days out and again the day before.</span></li></ul></div>` : '<p class="note">The sun doesn’t set on this date at this latitude.</p>'}`;
}
$('#view-plan').addEventListener('change', e => { if(e.target.id === 'sun-city'){ mutate(() => venue().city = e.target.value); renderPlanning(); } });
$('#view-plan').addEventListener('click', e => { const b = e.target.closest('[data-sunshift]'); if(!b) return; const cer = state.timeline.find(x => /ceremony|misa|blessing/i.test(x.title)); if(!cer) return; const delta = toMin(b.dataset.sunshift) - toMin(cer.time); mutate(() => { state.timeline.forEach(x => { if(x.type !== 'vendor' && x.type !== 'prep') x.time = fromMin(toMin(x.time) + delta); }); logActivity(`Schedule moved ${delta > 0 ? 'later' : 'earlier'} by ${Math.abs(delta)} min for golden hour`); }); toast(`Ceremony and reception shifted ${Math.abs(delta)} min ${delta > 0 ? 'later' : 'earlier'}. Vendor times stayed put.`); renderPlanning(); });

/* ============ rental availability across all events ============ */
function availabilityHTML(){
  const today = isoLocal(), up = portalEvents.filter(e => e.date && e.date >= today && e.status !== 'cancelled' && Array.isArray(e.linens)).sort((a, b) => a.date.localeCompare(b.date)).slice(0, 10);
  if(!up.length) return `<section class="inv-card"><span class="eyebrow">Availability across events</span><p class="muted">Saved upcoming events and the linens they hold will show here by date.</p></section>`;
  const onHand = onHandMap(), held = up.map(e => peakHeld(holdSpan(e), null));
  const keys = [...new Set(up.flatMap(e => e.linens.map(([k]) => k)))].sort((a, b) => Math.max(...held.map(h => (h.get(b) || 0)/((onHand.get(b) || 0) || 1))) - Math.max(...held.map(h => (h.get(a) || 0)/((onHand.get(a) || 0) || 1)))).slice(0, 24);
  const label = k => { const [cat, fab, hex, size] = k.split('|'); return `<span class="swatch-inline" style="--c:${hex}"></span>${esc(colorName(hex))} ${esc(fab ? (FABRICS[fab] || INV_FABRICS.runner[fab] || fab).toLowerCase() : '')} ${esc(cat === 'cloth' ? 'cloth' : cat)} <span class="muted">${esc(size)}</span>`; };
  const conflicts = []; keys.forEach(k => up.forEach((e, i) => { const h = held[i].get(k) || 0, s = onHand.get(k) || 0; if(h > s) conflicts.push(`${e.name} (${shortFmt(e.date)}): ${colorName(k.split('|')[2])} ${k.split('|')[3]}, ${h} held vs ${s} owned`); }));
  return `<section class="inv-card"><div class="sheet-head" style="padding-bottom:10px"><div><span class="eyebrow">Availability across events</span><h2 style="font-family:var(--display);font-weight:400;font-size:24px">Linens held by date</h2><p class="muted" style="margin:4px 0 0">Each column is an upcoming event. Numbers show the most held at once during that event’s rental window (delivery to return, plus the laundry turnaround), out of how many you own.</p></div>
    <label style="display:flex;align-items:center;gap:8px;font-size:12.5px;white-space:nowrap" title="Days after linens come back before they can go out again">Laundry turnaround <input id="laundry-days" type="number" min="0" max="14" value="${laundryDays()}" style="width:58px;border:1px solid var(--line-strong);background:var(--surface-2);border-radius:8px;padding:5px 7px" ${canAdmin ? '' : 'disabled'} aria-label="Laundry turnaround in days"> days</label></div>
    ${conflicts.length ? `<p class="note warn">${conflicts.length} shortage${conflicts.length > 1 ? 's' : ''}: ${conflicts.slice(0, 6).map(esc).join(' · ')}${conflicts.length > 6 ? '…' : ''}</p>` : '<p class="note">No shortages across upcoming events.</p>'}
    <div class="table-scroll"><table class="qty avail"><thead><tr><th>Item</th><th class="num">Owned</th>${up.map(e => `<th class="num" title="${esc(e.name)}">${esc(shortFmt(e.date))}<br><span class="muted" style="font-weight:500;text-transform:none;letter-spacing:0">${esc(e.name.slice(0, 14))}</span></th>`).join('')}</tr></thead><tbody>
    ${keys.map(k => { const s = onHand.get(k) || 0; return `<tr><td>${label(k)}</td><td class="num">${s}</td>${up.map((e, i) => { const h = held[i].get(k) || 0, r = s ? h/s : (h ? 2 : 0); return `<td class="num"><span class="av ${r > 1 ? 'over' : r > .8 ? 'tight' : h ? 'ok' : ''}">${h || '·'}</span></td>`; }).join('')}</tr>`; }).join('')}</tbody></table></div></section>`;
}

let rulesOpen = false; document.addEventListener('toggle', e => { if(e.target.classList && e.target.classList.contains('rules')) rulesOpen = e.target.open; }, true);

/* ============ lighting cues ============ */
const lighting = () => (state.lighting ||= {active:null, cues:[
  {id:'arrival', name:'Guest arrival', amb:'golden', up:'#ffae5a', upLevel:.8, pin:true, strings:true, wash:'', party:false},
  {id:'dinner', name:'Dinner', amb:'candle', up:'#f0a4b4', upLevel:.9, pin:true, strings:true, wash:'', party:false},
  {id:'firstdance', name:'First dance', amb:'candle', up:'#f0a4b4', upLevel:.45, pin:false, strings:true, wash:'#fff1d6', party:false},
  {id:'party', name:'Party', amb:'candle', up:'#ad8cf0', upLevel:1.4, pin:false, strings:true, wash:'#ad8cf0', party:true},
  {id:'last', name:'Last dance', amb:'candle', up:'#86b9ff', upLevel:.7, pin:false, strings:true, wash:'#fff1d6', party:false}]});
function effVis(){ const L = state.lighting, c = L && L.active && L.cues.find(x => x.id === L.active); return c ? Object.assign({}, vset(), {amb:c.amb, up:c.up, lights:c.strings, cue:c}) : vset(); }
function cueEffects3D(G, W, H){
  V.beams = null; const c = effVis().cue, d = state.items.find(i => i.type === 'dance'); if(!c || !d) return;
  const [cx, cz] = [d.x - W/2, d.y - H/2], ceil = V.outdoor ? 13 : (V.ceil || 14);
  if(c.wash){ const m = new THREE.Mesh(geo('cplane', () => new THREE.PlaneGeometry(1, 1)), new THREE.MeshBasicMaterial({map:poolTex(), color:lin(c.wash), transparent:true, opacity:.6, depthWrite:false, blending:THREE.AdditiveBlending})); m.rotation.x = -Math.PI/2; m.scale.set(d.w*1.3, d.h*1.3, 1); m.position.set(cx, .07, cz); G.add(m); const pl = new THREE.PointLight(lin(c.wash), 1.3, Math.max(d.w, d.h)*1.6, 2); pl.position.set(cx, ceil - 2, cz); G.add(pl); }
  if(c.party){ V.beams = []; const cols = [c.up, '#ffffff', c.wash || '#86b9ff', '#ff6fb1']; for(let i=0;i<8;i++){ const a = i/8*Math.PI*2, g = new THREE.Group(); g.position.set(cx + Math.cos(a)*d.w*.6, ceil - .5, cz + Math.sin(a)*d.h*.6); const b = new THREE.Mesh(geo('beam' + ceil, () => new THREE.CylinderGeometry(.04, 1.4, ceil - .5, 14, 1, true)), new THREE.MeshBasicMaterial({color:lin(cols[i % cols.length]), transparent:true, opacity:.12, depthWrite:false, blending:THREE.AdditiveBlending, side:THREE.DoubleSide})); b.position.y = -(ceil - .5)/2; g.add(b); G.add(g); V.beams.push(g); } }
}
function lightingHTML(){
  const L = lighting();
  return `<div class="pv-card"><h4>Lighting cues</h4><p class="muted" style="margin:0;font-size:12.5px">Set the look for each part of the night, then preview it in 3D. The active cue also drives the Vision.</p>
    <div class="cue-list">${L.cues.map(c => `<div class="cue${L.active === c.id ? ' on' : ''}"><input class="cat-title" data-lc="name" data-cid="${c.id}" value="${esc(c.name)}" aria-label="Cue name">
      <div class="cue-row"><select data-lc="amb" data-cid="${c.id}" aria-label="Ambience">${[['candle','Candlelight'],['golden','Golden hour'],['day','Daylight']].map(([k, n]) => `<option value="${k}"${c.amb === k ? ' selected' : ''}>${n}</option>`).join('')}</select>
        <label class="cue-c">Uplight <input type="color" data-lc="up" data-cid="${c.id}" value="${c.up || '#000000'}"></label>
        <label class="cue-r">Level <input type="range" min="0" max="1.6" step=".1" data-lc="upLevel" data-cid="${c.id}" value="${c.upLevel}"></label>
        <label class="cue-c">Floor wash <input type="color" data-lc="wash" data-cid="${c.id}" value="${c.wash || '#000000'}"></label></div>
      <div class="cue-row">${[['pin','Pin-spots'],['strings','String lights'],['party','Moving beams']].map(([k, n]) => `<label class="toggle" style="padding-left:0"><input type="checkbox" data-lc="${k}" data-cid="${c.id}" ${c[k] ? 'checked' : ''}> ${n}</label>`).join('')}<button class="btn sm" data-lcwash="${c.id}">No wash</button><button class="btn sm primary" data-lcprev="${c.id}">Preview in 3D</button></div></div>`).join('')}</div>
    <div class="btn-row" style="margin:0"><button class="btn sm" data-lcadd="1">Add a cue</button>${L.active ? '<button class="btn sm" data-lcoff="1">Stop previewing cues</button>' : ''}</div></div>`;
}
const _renderMusic = renderMusic; renderMusic = function(){ _renderMusic(); $('#music-preview').insertAdjacentHTML('beforeend', lightingHTML()); };
$('#view-music').addEventListener('input', e => { const t = e.target; if(!t.dataset.lc) return; const c = lighting().cues.find(x => x.id === t.dataset.cid); if(!c) return; const k = t.dataset.lc; mutate(() => c[k] = t.type === 'checkbox' ? t.checked : t.type === 'range' ? +t.value : (k === 'wash' && t.value === '#000000') ? '' : t.value, 'lc-' + c.id + k); });
