/* ============ day-of staff mode ============ */
let staffTab = 'now', staffQ = '', staffFind = '';
function staffHTML(){
  const tl = (state.timeline || []).slice().sort((a, b) => toMin(a.time) - toMin(b.time)), d = eventDate(), now = new Date(), isToday = d && d.toDateString() === now.toDateString(), clock = isToday ? nowMin() : (dayClock ?? (tl[0] ? toMin(tl[0].time) : 540));
  let body = '';
  if(staffTab === 'now'){ const cur = tl.filter(x => toMin(x.time) <= clock && toMin(x.time) + (+x.dur || 0) > clock), next = tl.filter(x => toMin(x.time) > clock).slice(0, 5);
    body = `<div class="st-clock">${fmt12(fromMin(clock))}${isToday ? '' : '<small>preview: not the event day</small>'}</div><span class="eyebrow">Now</span>${cur.length ? cur.map(x => `<div class="st-card now" style="--c:${(TL_TYPES[x.type] || TL_TYPES.other)[1]}"><b>${esc(x.title)}</b><span>${fmt12(x.time)} · ${x.dur} min${x.who ? ' · ' + esc(x.who) : ''}${x.where ? ' · ' + esc(x.where) : ''}</span></div>`).join('') : '<p class="muted">Nothing scheduled right now.</p>'}
      <span class="eyebrow">Up next</span>${next.map(x => `<div class="st-card" style="--c:${(TL_TYPES[x.type] || TL_TYPES.other)[1]}"><b>${esc(x.title)}</b><span>in ${toMin(x.time) - clock} min · ${fmt12(x.time)}${x.who ? ' · ' + esc(x.who) : ''}</span></div>`).join('') || '<p class="muted">That’s the end of the day.</p>'}`; }
  if(staffTab === 'checkin'){ const ck = state.checkin || {}, coming = state.guests.filter(g => g.rsvp !== 'no'); body = `<div class="st-stat"><b>${coming.filter(g => ck[g.id]).length}</b> of ${coming.length} arrived</div><input type="search" class="st-search" id="st-q" placeholder="Guest name" value="${esc(staffQ)}" autocomplete="off"><div id="st-ci">${staffCheckinList()}</div>`; }
  if(staffTab === 'tasks'){ const done = (state.dayof ||= {done:{}}).done; body = dayOfItems().map(i => `<label class="st-task${done[i.key] ? ' done' : ''}"><input type="checkbox" data-sttask="${esc(i.key)}" ${done[i.key] ? 'checked' : ''}><span>${esc(i.text)}<small>${fmt12(i.time)} · ${esc(i.phase)}</small></span></label>`).join(''); }
  if(staffTab === 'contacts'){ body = `<div class="st-card"><b>${esc(company.name)}</b><span>${esc([company.phone, company.email].filter(Boolean).join(' · ') || 'Add company contact in Events')}</span></div>` + (state.vendors || []).filter(v => v.name || v.contact).map(v => `<div class="st-card"><b>${esc(v.role)}${v.name ? ' · ' + esc(v.name) : ''}</b><span>${esc(v.contact || 'No contact')}${v.arrive ? ' · in ' + fmt12(v.arrive) : ''}</span>${v.contact ? `<button class="btn sm" data-stcopy="${esc(v.contact)}">Copy</button>` : ''}</div>`).join(''); }
  if(staffTab === 'floor'){ const {svg} = planSVGString(); const g = staffFind.trim() ? state.guests.filter(x => nameHit8(x.name, staffFind)).sort(byLast8)[0] || null : null, t = g && g.tableId && state.items.find(i => i.id === g.tableId);
    const mark = t ? `<circle cx="${t.x}" cy="${t.y}" r="4.5" fill="none" stroke="#e0566a" stroke-width=".5"><animate attributeName="r" values="3.5;6;3.5" dur="1.4s" repeatCount="indefinite"/></circle>` : '';
    body = `<input type="search" class="st-search" id="st-find" placeholder="Find a guest’s table" value="${esc(staffFind)}" autocomplete="off">${g ? `<p class="st-found">${esc(g.name)} → ${t ? esc(tableLabel(t)) + ', seat ' + (g.seat + 1) : 'no seat yet'}</p>` : staffFind ? '<p class="muted">No guest found.</p>' : ''}<div class="st-plan">${resolveVars(svg.replace('</svg>', mark + '</svg>'))}</div>`; }
  return `<div class="st-top"><div><span class="eyebrow">Day-of mode</span><b>${esc(state.event.name)}</b></div>${state.portalId ? `<button class="btn sm" data-stcopy="${ARTIFACT_URL}#staff-${state.portalId}${tsSTok(state.portalId)}">Copy staff link</button>` : ''}<button class="btn sm" data-stclose="1">Exit</button></div><div class="st-body">${body}</div>
    <nav class="st-nav">${[['now','Now'],['checkin','Check-in'],['tasks','Tasks'],['contacts','Contacts'],['floor','Floor']].map(([k, n]) => `<button data-sttab="${k}" aria-pressed="${staffTab === k}">${n}</button>`).join('')}</nav>`;
}
function staffCheckinList(){ const ck = state.checkin || {}, sm = new Map(tables().map(t => [t.id, t])), q = staffQ.trim(); const list = state.guests.filter(g => g.rsvp !== 'no' && (q ? nameHit8(g.name, q) : staffCiShow(g))).sort(byLast8), more = q ? 0 : list.length - 60; return (q ? list : list.slice(0, 60)).map(g => { const t = g.tableId && sm.get(g.tableId); return `<button class="st-guest${ck[g.id] ? ' in' : ''}" data-stci="${g.id}"><b>${esc(g.name)}</b><span>${t ? esc(t.number ? 'Table ' + t.number : t.name) : esc(blockWhere(g) || 'No seat')}${g.meal ? ' · ' + esc(g.meal) : ''}${(g.needs || []).length ? ' · ' + g.needs.map(n => NEEDS[n].split(':')[0]).join(', ') : ''}</span><em>${ck[g.id] ? 'Arrived' : 'Tap to check in'}</em></button>`; }).join('') + (more > 0 ? `<p class="muted" style="grid-column:1/-1;text-align:center;font-size:13px">${more} more guest${more > 1 ? 's' : ''} · type a name to find them</p>` : ''); }
