document.addEventListener('change', e => { const t = e.target; if(t.dataset.sttask){ const st = (state.dayof ||= {done:{}}); mutate(() => { if(t.checked) st.done[t.dataset.sttask] = true; else delete st.done[t.dataset.sttask]; }); if(state.portalId) saveToPortal(true); openStaff(); } });
