let siteCtx = null;
async function openSite(eid){ const plan = await store.load(eid), o = $('#rsvp-page'); if(!plan){ o.innerHTML = '<div class="rsvp-inner"><h2>This page isn’t available</h2></div>'; o.hidden = false; return; } siteCtx = {eid, plan}; const saved = state; state = plan; let html; try { html = siteHTML(true); } finally { state = saved; } o.innerHTML = html; o.hidden = false; o.classList.add('as-site'); }
document.addEventListener('submit', e => { if(e.target.id !== 'site-rsvp' || !siteCtx) return; e.preventDefault(); const q = ($('#site-name').value || '').trim().toLowerCase(); if(q.length < 3){ $('#site-msg').textContent = 'Type your full name.'; return; } const nq = normName(q), g = siteCtx.plan.guests.find(x => normName(x.name) === nq) || (nq.includes(' ') ? siteCtx.plan.guests.filter(x => normName(x.name).includes(nq)).find((x, i, a) => a.length === 1) : null); if(!g){ $('#site-msg').textContent = 'We couldn’t find that name. Try the name on your invitation, or contact the host.'; return; } $('#rsvp-page').classList.remove('as-site'); openRsvp(siteCtx.eid, g.id); });

/* ============ vendor directory ============ */
let vendorDir = [], vdCat = 'all', vdQ = '';
const VD_CATS = ['Venue','Caterer','Florist','Photographer','Videographer','DJ / Band','Rentals & linens','Bakery','Officiant','Hair & makeup','Lighting & AV','Transportation','Photo booth','Bartending','Other'];
function vendorDirHTML(){
  const list = vendorDir.filter(v => (vdCat === 'all' || v.category === vdCat) && (!vdQ || [v.name, v.category, v.notes].join(' ').toLowerCase().includes(vdQ.toLowerCase()))).sort((a, b) => (b.preferred - a.preferred) || (b.rating || 0) - (a.rating || 0));
  const stars = v => `<span class="stars" aria-label="${v.rating || 0} of 5">${[1,2,3,4,5].map(n => `<button class="star${(v.rating || 0) >= n ? ' on' : ''}" data-vdrate="${v.id}:${n}" ${canAdmin ? '' : 'disabled'} aria-label="${n} star">★</button>`).join('')}</span>`;
  return `<section class="inv-card"><div class="sheet-head" style="padding-bottom:10px"><div><span class="eyebrow">Vendor directory</span><h2 style="font-family:var(--display);font-weight:400;font-size:24px">Preferred vendors</h2><p class="muted" style="margin:4px 0 0">Shared with your team. Add a vendor to the current event in one click.</p></div></div>
    <div class="inv-tools"><select id="vd-cat" aria-label="Category"><option value="all">All categories</option>${VD_CATS.map(c => `<option${vdCat === c ? ' selected' : ''}>${esc(c)}</option>`).join('')}</select><input type="search" id="vd-q" placeholder="Search vendors" value="${esc(vdQ)}"></div>
    <div class="tpl-grid">${list.length ? list.map(v => `<div class="tpl${v.preferred ? ' pref' : ''}"><div class="vd-head"><b>${esc(v.name)}</b>${v.preferred ? '<span class="pill ok">Preferred</span>' : ''}</div><span class="muted">${esc(v.category)}${v.price ? ' · ' + esc(v.price) : ''}</span>${stars(v)}<span>${esc(v.contact || '')}</span>${v.website ? `<a href="${esc(/^https?:/.test(v.website) ? v.website : 'https://' + v.website)}" target="_blank" rel="noopener" class="muted" style="font-size:12px">${esc(v.website)}</a>` : ''}${v.notes ? `<span class="muted" style="font-style:italic">${esc(v.notes)}</span>` : ''}
      <div class="btn-row" style="margin:0"><button class="btn sm primary" data-vdadd="${v.id}">Add to this event</button>${canAdmin ? `<button class="btn sm" data-vdpref="${v.id}">${v.preferred ? 'Unmark' : 'Mark preferred'}</button><button class="x" data-vddel="${v.id}" aria-label="Remove vendor">×</button>` : ''}</div></div>`).join('') : `<p class="muted">${vendorDir.length ? 'No vendors match.' : 'No vendors yet. Add the vendors your team works with.'}</p>`}</div>
    ${canAdmin ? `<form id="vd-form" class="inv-add" style="margin-top:12px"><label class="fld"><span>Name</span><input id="vd-name" required></label><label class="fld"><span>Category</span><select id="vd-c">${VD_CATS.map(c => `<option>${esc(c)}</option>`).join('')}</select></label><label class="fld"><span>Contact</span><input id="vd-contact" placeholder="Name · phone · email"></label><label class="fld"><span>Website</span><input id="vd-web"></label><label class="fld"><span>Price range</span><select id="vd-price"><option>$</option><option selected>$$</option><option>$$$</option><option>$$$$</option></select></label><label class="fld"><span>Notes</span><input id="vd-notes"></label><div class="fld"><button class="btn primary" type="submit">Add to directory</button></div></form>` : ''}</section>`;
}
async function saveVendorDir(){ try { if(DB) await DB.doc('catalog/vendors').set({list:vendorDir, updatedAt:Date.now()}); else ls.set('tablescape-vendordir', JSON.stringify(vendorDir)); } catch(e){ toast(e.code === 'invalid_argument' ? 'Only editors can change the directory.' : 'Couldn’t save the directory.'); } }
function initVendorDir(){ try { vendorDir = JSON.parse(ls.get('tablescape-vendordir') || '[]'); } catch(e){} if(DB){ try { DB.doc('catalog/vendors').onSnapshot(s => { if(s.exists && Array.isArray(s.data().list)){ vendorDir = JSON.parse(JSON.stringify(s.data().list)); renderPortalIfOpen(); } }, () => {}); } catch(e){} } }
$('#view-events').addEventListener('click', e => {
  const t = e.target;
  const a = t.closest('[data-vdadd]'); if(a){ const v = vendorDir.find(x => x.id === a.dataset.vdadd); ensurePlanning(); const ex = state.vendors.find(x => x.role === v.category && !x.name) ; mutate(() => { if(ex) Object.assign(ex, {name:v.name, contact:v.contact}); else state.vendors.push({id:uid(), role:v.category, name:v.name, contact:v.contact || '', cost:'', deposit:'', status:'inquiring'}); logActivity(`Added ${v.name} (${v.category}) from the vendor directory`); }); toast(`${v.name} added to ${state.event.name}`); return; }
  const r = t.closest('[data-vdrate]'); if(r){ const [id, n] = r.dataset.vdrate.split(':'); const v = vendorDir.find(x => x.id === id); v.rating = +n; saveVendorDir(); renderPortal(); return; }
  const p = t.closest('[data-vdpref]'); if(p){ const v = vendorDir.find(x => x.id === p.dataset.vdpref); v.preferred = !v.preferred; saveVendorDir(); renderPortal(); return; }
  const d = t.closest('[data-vddel]'); if(d){ vendorDir = vendorDir.filter(x => x.id !== d.dataset.vddel); saveVendorDir(); renderPortal(); }
});
$('#view-events').addEventListener('change', e => { if(e.target.id === 'vd-cat'){ vdCat = e.target.value; renderPortal(); } });
$('#view-events').addEventListener('input', e => { if(e.target.id === 'vd-q'){ vdQ = e.target.value; const pos = e.target.selectionStart; renderPortal(); const q = $('#vd-q'); q.focus(); q.setSelectionRange(pos, pos); } });
document.addEventListener('submit', e => { if(e.target.id !== 'vd-form') return; e.preventDefault(); const name = $('#vd-name').value.trim(); if(!name) return; vendorDir.push({id:'v' + uid(), name, category:$('#vd-c').value, contact:$('#vd-contact').value.trim(), website:$('#vd-web').value.trim(), price:$('#vd-price').value, notes:$('#vd-notes').value.trim(), rating:0, preferred:false}); saveVendorDir(); renderPortal(); toast(`${name} added to the directory`); });

/* ============ profit margins ============ */
const COST_DEFAULT = {Venue:1, Rentals:.45, Linens:.3, Tabletop:.4, 'Florals & décor':.42, 'Backdrops & ceremony':.45, Catering:.62, 'Cake & bar':.55, 'Entertainment & lighting':.6, 'Add-ons & experiences':.55, Vendors:.9, Other:.7};
let costRates = Object.assign({}, COST_DEFAULT);
function eventCost(){ const lines = budgetLines(); return Math.round(lines.reduce((a, l) => a + l.qty*l.price*(costRates[l.cat] ?? .6), 0)); }
function marginCard(){ const rev = contractTotal(), cost = eventCost(), gp = rev - cost; return `<div class="inv-card margin-card"><div><span class="eyebrow">Your numbers · team only</span><h4 class="pv-h4" style="margin:4px 0 0">Profit on this event</h4></div><div class="inv-stats" style="border:0"><div class="stat"><b>${money(rev)}</b><span>client pays${state.package ? ' (package)' : ''}</span></div><div class="stat"><b>${money(cost)}</b><span>estimated cost</span></div><div class="stat"><b style="color:${gp >= 0 ? 'var(--ok)' : 'var(--warn)'}">${money(gp)}</b><span>gross profit</span></div><div class="stat"><b>${rev ? Math.round(gp/rev*100) : 0}%</b><span>margin</span></div></div><p class="muted" style="font-size:12px;margin:0">Costs use your cost rates per category (set them in Events → Reports).</p></div>`; }
const _renderBudget = renderBudget; renderBudget = function(){ _renderBudget(); if(!clientMode){ const top = $('#budget .bu-top'); if(top) top.insertAdjacentHTML('afterend', marginCard()); } };
function profitHTML(){
  const won = portalEvents.filter(e => (e.status === 'booked' || e.status === 'completed') && e.total);
  const rev = won.reduce((a, e) => a + (+e.total || 0), 0), cost = won.reduce((a, e) => a + (+e.cost || 0), 0), gp = rev - cost;
  return `<div class="inv-card"><h4 class="pv-h4">Profit · booked &amp; completed events</h4><div class="inv-stats" style="border:0"><div class="stat"><b>${money(rev)}</b><span>revenue</span></div><div class="stat"><b>${money(cost)}</b><span>estimated cost</span></div><div class="stat"><b style="color:${gp >= 0 ? 'var(--ok)' : 'var(--warn)'}">${money(gp)}</b><span>gross profit</span></div><div class="stat"><b>${rev ? Math.round(gp/rev*100) : 0}%</b><span>average margin</span></div></div>
    ${won.length ? `<div class="table-scroll"><table class="qty"><thead><tr><th>Event</th><th>Date</th><th class="num">Revenue</th><th class="num">Cost</th><th class="num">Profit</th><th class="num">Margin</th></tr></thead><tbody>${won.sort((a, b) => { const m = x => ((+x.total || 0) - (+x.cost || 0))/(+x.total || 1); return m(b) - m(a); }).map(e => { const p = (+e.total || 0) - (+e.cost || 0), m = e.total ? Math.round(p/e.total*100) : 0; return `<tr><td>${esc(e.name)}</td><td>${esc(shortFmt(e.date))}</td><td class="num">${money(e.total)}</td><td class="num">${money(e.cost || 0)}</td><td class="num">${money(p)}</td><td class="num"><span class="pill ${m >= 30 ? 'ok' : m >= 15 ? 'caution' : 'warn'}">${m}%</span></td></tr>`; }).join('')}</tbody></table></div>` : '<p class="muted">Profit shows once events are booked and saved.</p>'}
    ${canAdmin ? `<details class="egroup"><summary>Cost rates by category</summary><div class="cost-grid">${Object.entries(costRates).map(([k, v]) => `<label class="fld"><span>${esc(k)}</span><span class="bu-money"><input class="qty-in" type="number" min="0" max="150" step="1" data-cost="${esc(k)}" value="${Math.round(v*100)}">%</span></label>`).join('')}</div><button class="btn sm" data-costsave="1">Save cost rates</button></details>` : ''}</div>`;
}
const _reportsHTML = reportsHTML; reportsHTML = function(){ return _reportsHTML() + profitHTML(); };
$('#view-events').addEventListener('change', e => { const t = e.target; if(t.dataset.cost){ costRates[t.dataset.cost] = clamp(+t.value || 0, 0, 150)/100; } });
$('#view-events').addEventListener('click', async e => { if(e.target.closest('[data-costsave]')){ try { if(DB) await DB.doc('catalog/costs').set({rates:costRates, updatedAt:Date.now()}); else ls.set('tablescape-costs', JSON.stringify(costRates)); toast('Cost rates saved. Profit updates as events are saved.'); } catch(err){ toast('Only editors can change cost rates.'); } renderPortal(); } });
function initCosts(){ try { const c = ls.get('tablescape-costs'); if(c) costRates = Object.assign({}, COST_DEFAULT, JSON.parse(c)); } catch(e){} if(DB){ try { DB.doc('catalog/costs').onSnapshot(s => { if(s.exists && s.data().rates) costRates = Object.assign({}, COST_DEFAULT, s.data().rates); }, () => {}); } catch(e){} } }

/* ============ import guests from a spreadsheet ============ */
const IMP_FIELDS = {skip:'Don’t import', name:'Full name', first:'First name', last:'Last name', group:'Group', email:'Email', phone:'Phone', meal:'Meal', rsvp:'RSVP', diet:'Dietary', needs:'Access needs', table:'Table number', plusone:'Plus-one', company:'Company', title:'Title / role'};
let impRows = null, impMap = [];
function guessField(h){ h = h.toLowerCase(); return /compan|organi|employer|business|school/.test(h) ? 'company' : /title|role|position|job/.test(h) ? 'title' : /^(full )?name$|guest name|^guest$/.test(h) ? 'name' : /first/.test(h) ? 'first' : /last|surname/.test(h) ? 'last' : /group|side|relation|category|party/.test(h) ? 'group' : /mail/.test(h) ? 'email' : /phone|mobile|cell/.test(h) ? 'phone' : /meal|entr/.test(h) ? 'meal' : /rsvp|attend|response|status/.test(h) ? 'rsvp' : /diet|allerg/.test(h) ? 'diet' : /access|needs|wheelchair|mobility/.test(h) ? 'needs' : /table/.test(h) ? 'table' : /plus|\+1|guest of/.test(h) ? 'plusone' : 'skip'; }
function importModalHTML(){
  const head = impRows ? impRows[0] : [];
  return `<div class="modal-card imp-card" role="dialog" aria-modal="true" aria-labelledby="imp-title"><span class="eyebrow">Guest list</span><h2 id="imp-title">Import from a spreadsheet</h2>
    <p class="muted" style="margin:0">Copy your rows from Excel or Google Sheets (with the header row) and paste below, or choose a CSV file.</p>
    <textarea id="imp-text" class="iv-msg" rows="5" placeholder="Name\tGroup\tEmail\tMeal&#10;Ana Torres\tCollege friends\tana@example.com\tFish">${impRows ? '' : ''}</textarea>
    <div class="btn-row" style="margin:0"><label class="btn sm">Choose CSV file<input type="file" id="imp-file" accept=".csv,.tsv,.txt" hidden></label><button class="btn sm" data-imp="read">Read the rows</button></div>
    ${impRows ? `<div class="table-scroll"><table class="qty imp-table"><thead><tr>${head.map((h, i) => `<th><select data-impmap="${i}" aria-label="Column ${i + 1}">${Object.entries(IMP_FIELDS).map(([k, n]) => `<option value="${k}"${impMap[i] === k ? ' selected' : ''}>${n}</option>`).join('')}</select><div class="muted" style="font-weight:500;text-transform:none;letter-spacing:0;margin-top:4px">${esc(h)}</div></th>`).join('')}</tr></thead><tbody>${impRows.slice(1, 6).map(r => `<tr>${head.map((_, i) => `<td>${esc(r[i] || '')}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="muted" style="font-size:12px;margin:0">${impRows.length - 1} rows found. Showing the first 5.</p>
    <label class="toggle" style="padding-left:0"><input type="checkbox" id="imp-dupe" checked> Skip names already on the guest list</label>` : ''}
    <p class="note warn" id="imp-err" hidden></p>
    <div class="btn-row" style="justify-content:flex-end"><button class="btn" data-imp="close">Cancel</button>${impRows ? `<button class="btn primary" data-imp="go">Import ${impRows.length - 1} guests</button>` : ''}</div></div>`;
}
function openImport(){ let o = $('#imp-modal'); if(!o){ o = document.createElement('div'); o.id = 'imp-modal'; o.className = 'modal'; document.body.appendChild(o); } o.innerHTML = importModalHTML(); o.hidden = false; }
function readImport(text){ const rows = parseCSV(text.replace(/\r/g, '')); if(rows.length < 2){ const er = $('#imp-err'); er.textContent = 'Paste at least a header row and one guest.'; er.hidden = false; return; } impRows = rows; impMap = rows[0].map(guessField); openImport(); }
function importNeeds(t){ t = String(t || '').toLowerCase(); return t ? Object.keys(NEEDS).filter(k => t.includes(k) || t.includes(NEEDS[k].toLowerCase().split(':')[0])) : []; }
function doImport(){
  const skipDupe = $('#imp-dupe').checked, existing = new Set(state.guests.map(g => g.name.toLowerCase())); let added = 0, skipped = 0;
  mutate(() => impRows.slice(1).forEach(r => { const v = k => { const i = impMap.indexOf(k); return i >= 0 ? String(r[i] || '').trim() : ''; };
    const name = v('name') || [v('first'), v('last')].filter(Boolean).join(' '); if(!name){ return; } if(skipDupe && existing.has(name.toLowerCase())){ skipped++; return; }
    const rs = v('rsvp').toLowerCase(), meal = MEALS.find(m => m.toLowerCase() === v('meal').toLowerCase()) || (v('meal') ? (MEALS.find(m => m.toLowerCase().startsWith(v('meal').toLowerCase().slice(0, 4))) || '') : '');
    const g = {id:uid(), name, group:v('group'), email:v('email'), phone:v('phone'), meal, diet:v('diet'), company:v('company'), title:v('title'), needs:importNeeds(v('needs')), rsvp: /^(n|no|declin|regret)/.test(rs) ? 'no' : /^(y|yes|attend|accept)/.test(rs) ? 'yes' : rs ? 'pending' : 'yes', tableId:null, seat:null};
    const tn = g.rsvp !== 'no' && v('table'); if(tn){ const t = tables().find(x => x.number === tn); if(t){ const taken = new Set(state.guests.filter(x => x.tableId === t.id).map(x => x.seat)); const free = Array.from({length:t.seats}, (_, i) => i).find(i => !taken.has(i)); if(free != null){ g.tableId = t.id; g.seat = free; } } }
    state.guests.push(g); existing.add(name.toLowerCase()); added++;
    const po = v('plusone'); if(po && !/^(n|no|0|false)$/i.test(po)){ const pname = /^(y|yes|1|true|\+1)$/i.test(po) ? `Guest of ${name}` : po; { const hh = 'h' + uid(); g.household = hh; state.guests.push({id:uid(), name:pname, group:g.group, meal:'', rsvp:g.rsvp, tableId:null, seat:null, household:hh}); } added++; }
  }));
  logActivity(`Imported ${added} guests from a spreadsheet`); save();
  $('#imp-modal').hidden = true; impRows = null; renderGuests(); updateTabs(); toast(`Imported ${added} guests${skipped ? `, skipped ${skipped} already on the list` : ''}.`);
}
document.addEventListener('click', e => {
  if(e.target.closest('[data-impopen]')){ impRows = null; openImport(); return; }
  const b = e.target.closest('[data-imp]'); if(!b) return; const a = b.dataset.imp;
  if(a === 'close'){ $('#imp-modal').hidden = true; impRows = null; } if(a === 'read') readImport($('#imp-text').value || ''); if(a === 'go') doImport();
});
document.addEventListener('change', e => { const t = e.target; if(t.dataset.impmap != null) impMap[+t.dataset.impmap] = t.value; if(t.id === 'imp-file' && t.files[0]){ const r = new FileReader(); r.onload = () => readImport(String(r.result || '')); r.readAsText(t.files[0]); } });

/* ============ grouped navigation ============ */
const NAV_GROUPS = {events:['events'], design:['vision','floor','style','backdrop','packages'], guests:['guests','invites'], experience:['menu','music'], plan:['plan'], business:['client','budget','order','inv']};
const lastInGroup = {};
function groupOf(v){ return Object.keys(NAV_GROUPS).find(g => NAV_GROUPS[g].includes(v)) || 'design'; }
function syncNav(v){ const g = groupOf(v); lastInGroup[g] = v; $$('.grp').forEach(b => b.setAttribute('aria-selected', b.dataset.group === g)); $$('.subnav .tab').forEach(t => t.classList.toggle('in-group', t.dataset.group === g && !(clientMode && t.dataset.view === 'inv'))); const sub = $('#subnav'); if(sub) sub.hidden = NAV_GROUPS[g].length < 2; requestAnimationFrame(() => { revealInRow($(`.grp[data-group="${g}"]`)); revealInRow($(`.subnav .tab[data-view="${v}"]`)); }); }
/* on a phone the nav rows scroll sideways; keep the chosen tab in sight without moving the page */
function revealInRow(el){ if(!el || !el.offsetParent) return; let row = el.parentElement; while(row && row.scrollWidth <= row.clientWidth + 1) row = row.parentElement === document.body ? null : row.parentElement; if(!row) return; const r = el.getBoundingClientRect(), rr = row.getBoundingClientRect(); if(r.left < rr.left + 8) row.scrollLeft -= rr.left + 24 - r.left; else if(r.right > rr.right - 8) row.scrollLeft += r.right - rr.right + 24; }
$$('.grp').forEach(b => b.onclick = () => switchView(lastInGroup[b.dataset.group] || NAV_GROUPS[b.dataset.group][0]));
/* ============ calm UI: quick search, getting started, collapsible panels ============ */
const QUICK = [
  ['All events','events'],['Reports','events',() => { portalView = 'reports'; }],['Calendar','events',() => { portalView = 'calendar'; }],['Vendor directory','events'],['Templates','events'],['Menu catalog','events'],['Staff & company','events'],
  ['3D vision','vision'],['Floor plan','floor'],['Table designs','style'],['Backdrops','backdrop'],['Packages','packages'],['Event themes','events',() => openThemes()],['Venue setting','floor',() => { sel = null; }],['Ceremony seating','floor',() => { sel = {ceremony:true}; }],
  ['Guests & seating','guests'],['Seating optimizer','guests',() => { rulesOpen = true; }],['Import guest spreadsheet','guests',() => setTimeout(() => { impRows = null; openImport(); }, 50)],['Invitations','invites',() => { invTab = 'design'; }],['Send invitations','invites',() => { invTab = 'send'; }],['Reminders','invites',() => { invTab = 'reminders'; }],['Event website','invites',() => { invTab = 'website'; }],['Escort cards','invites',() => { invTab = 'design'; invite().kind = 'escort'; }],['Table numbers','invites',() => { invTab = 'design'; invite().kind = 'tablenum'; }],
  ['Dinner menu','menu',() => { menuTab = 'dinner'; }],['Cake','menu',() => { menuTab = 'cake'; }],['Bar & drinks','menu',() => { menuTab = 'bar'; }],['Hors d’oeuvres','menu',() => { menuTab = 'hors'; }],['Add-ons','menu',() => { menuTab = 'addons'; }],['Music & DJ brief','music',() => { musicTab = 'vibe'; }],['Lighting cues','music',() => { musicTab = 'vibe'; }],['Day-of packet download','plan',() => { planTab = 'show'; }],['Linen rental quote','order'],['Linen availability by date','inv'],
  ['Run of show','plan',() => { planTab = 'show'; }],['Follow-ups','plan',() => { planTab = 'followups'; }],['Day of','plan',() => { planTab = 'dayof'; }],['Guest check-in','plan',() => { planTab = 'checkin'; }],['Sun & weather','plan',() => { planTab = 'sun'; window.__sunJump = true; }],['Checklist','plan',() => { planTab = 'tasks'; }],['Vendors','plan',() => { planTab = 'vendors'; }],['Day-of staff mode','plan',() => setTimeout(openStaff, 50)],
  ['Proposal','client',() => { clientTab = 'proposal'; }],['Approvals','client',() => { clientTab = 'approvals'; }],['Contract','client',() => { clientTab = 'contract'; }],['Payments & invoices','client',() => { clientTab = 'payments'; }],['Messages','client',() => { clientTab = 'messages'; }],['Budget','budget'],['Order sheet','order'],['Linen inventory','inv']];
let qkSel = 0;
function quickOpen(){ let o = $('#quick'); if(!o){ o = document.createElement('div'); o.id = 'quick'; o.className = 'modal quick'; o.innerHTML = '<div class="quick-card" role="dialog" aria-modal="true" aria-label="Go to"><input id="quick-q" placeholder="Go to… (try “cake”, “payments”, “check-in”)" autocomplete="off"><ul id="quick-list" role="listbox"></ul><p class="muted quick-hint"><span class="kbd">↑</span> <span class="kbd">↓</span> to move · <span class="kbd">Enter</span> to open · <span class="kbd">Esc</span> to close</p></div>'; document.body.appendChild(o); o.addEventListener('click', e => { if(e.target === o) quickClose(); const li = e.target.closest('[data-qk]'); if(li) quickGo(+li.dataset.qk); }); $('#quick-q').addEventListener('input', () => { qkSel = 0; quickRender(); }); $('#quick-q').addEventListener('keydown', e => { const n = quickMatches().length; if(e.key === 'ArrowDown'){ e.preventDefault(); qkSel = Math.min(n - 1, qkSel + 1); quickRender(); } if(e.key === 'ArrowUp'){ e.preventDefault(); qkSel = Math.max(0, qkSel - 1); quickRender(); } if(e.key === 'Enter'){ e.preventDefault(); const m = quickMatches()[qkSel]; if(m) quickGo(QUICK.indexOf(m)); } if(e.key === 'Escape') quickClose(); }); }
  o.hidden = false; $('#quick-q').value = ''; qkSel = 0; quickRender(); setTimeout(() => $('#quick-q').focus(), 0); }
function quickClose(){ const o = $('#quick'); if(o) o.hidden = true; }
function quickMatches(){ const q = ($('#quick-q').value || '').toLowerCase().trim(); if(!q) return QUICK.slice(0, 12); return QUICK.filter(([n]) => n.toLowerCase().includes(q) || q.split(' ').every(w => n.toLowerCase().includes(w))).slice(0, 12); }
/* Ctrl K also knows the words owners use (team, invite, settings, deposit, Stripe), the Spanish ones (pagos, invitados, contrato, modo fácil...)
   and BEO, with or without accents. These only add matches after the page names themselves. */
const QUICK_WORDS = {
  'Staff & company':'team teammates employees crew logins sign in invite invitar settings preferences company profile equipo personal empleados usuarios empresa compania ajustes configuracion perfil',
  'Payments & invoices':'deposit deposits retainer pay paid charge collect invoice receipt stripe square zelle venmo cash pagos pago cobrar cobro anticipo deposito factura facturas recibo efectivo',
  'Money owed':'deposit owed balance due unpaid me deben deben deudas saldo pendiente cobrar',
  'Integrations: connect Claude, ChatGPT, Zapier or Slack':'stripe payment links paypal square api webhooks settings ajustes enlaces de pago integraciones conectar',
  'Plans & trial':'subscription billing plan trial settings account suscripcion prueba precio cuenta',
  'Easy mode (simple, big buttons)':'modo facil facil sencillo simple espanol spanish botones grandes',
  'Guests & seating':'invitados lista de invitados asientos acomodar',
  'Invitations':'invitaciones tarjetas',
  'Send invitations':'invite guests enviar invitaciones whatsapp',
  'Contract':'agreement sign signature e-sign contrato firma firmar acuerdo',
  'Proposal':'quote estimate send propuesta cotizacion enviar',
  'Messages':'chat text mensajes escribir',
  'Calendar':'calendario fechas agenda',
  'All events':'eventos fiestas parties home inicio',
  'Reports':'reportes informes ventas numeros',
  'Dinner menu':'menu comida cena platillos food',
  'Cake':'pastel torta',
  'Bar & drinks':'bebidas barra tragos',
  'Music & DJ brief':'musica dj',
  'Floor plan':'plano mesas acomodo layout salon',
  'Table designs':'mesas manteles centros de mesa decoracion',
  'Checklist':'tasks to do tareas pendientes lista',
  'Vendors':'proveedores',
  'Guest check-in':'registro llegada entrada door puerta',
  'Run of show':'timeline schedule programa horario',
  'Budget':'presupuesto costos',
  'Clients (CRM)':'clientes contactos',
  'Event themes':'temas estilos',
  'New inquiry':'lead consulta solicitud prospecto nuevo cliente',
  'Sign out':'log out salir cerrar sesion',
  'Welcome screen':'bienvenida inicio start',
  'Take the tour':'recorrido ayuda help',
  'Day-of staff mode':'staff phones telefonos del personal',
  'Day-of packet download':'beo banquet event order orden de evento',
  'Day-of packet sections':'beo banquet event order orden de evento'};
const qkNorm = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();
const _quickMatchesWords = quickMatches; quickMatches = function(){ const r = _quickMatchesWords.apply(this, arguments), q = qkNorm(($('#quick-q') || {}).value); if(!q || r.length >= 12) return r;
  const ws = q.split(/\s+/).filter(Boolean); return r.concat(QUICK.filter(m => !r.includes(m) && (QUICK_WORDS[m[0]] || m[4]) && ws.every(w => qkNorm(m[0] + ' ' + (QUICK_WORDS[m[0]] || '') + ' ' + (m[4] || '')).includes(w)))).slice(0, 12); };
function quickRender(){ const list = quickMatches(), grpName = {events:'Events', design:'Design', guests:'Guests', experience:'Food & music', plan:'Planning', business:'Business'}; $('#quick-list').innerHTML = list.length ? list.map((m, i) => `<li role="option" aria-selected="${i === qkSel}" data-qk="${QUICK.indexOf(m)}"><b>${esc(m[0])}</b><span>${esc(grpName[groupOf(m[1])] || '')}</span></li>`).join('') : '<li class="muted">Nothing matches.</li>'; }
function quickGo(i){ const [, view, fn] = QUICK[i]; quickClose(); if(clientMode && (view === 'events' || view === 'inv')) return; if(fn) fn(); switchView(view); }
document.addEventListener('keydown', e => { if((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'k'){ e.preventDefault(); quickOpen(); } if(e.key === '/' && !e.target.closest('input,textarea,select,[contenteditable]') && currentView !== 'floor'){ e.preventDefault(); quickOpen(); } });

/* getting started */
function startSteps(){
  const ts = tables(), seated = state.guests.filter(g => g.tableId).length;
  return [
    ['Pick an event theme or package', !!(state.themeLabel || state.package), () => openThemes(), 'Browse themes'],
    ['Set up the venue and floor plan', ts.length > 0 && !state.sample, () => switchView('floor'), 'Open floor plan'],
    ['Design the tables', state.looks.length > 0 && (state.looks[0].name !== 'Main look'), () => switchView('style'), 'Design tables'],
    ['Add guests and seat them', state.guests.length > 0 && seated >= state.guests.filter(g => g.rsvp !== 'no').length*.8, () => switchView('guests'), 'Open guests'],
    ['Choose the menu', !!(state.menuChoices && Object.values(state.menuChoices.picks || {}).some(a => a.length)), () => { menuTab = 'dinner'; switchView('menu'); }, 'Choose dishes'],
    ['Design and send invitations', state.guests.some(g => (g.sent || {}).invitation), () => { invTab = 'design'; switchView('invites'); }, 'Invitations'],
    ['Send the proposal and contract', !!(state.contract && state.contract.client), () => { clientTab = 'proposal'; switchView('client'); }, 'Open proposal'],
    ['Save the event to the portal', !!state.portalId, () => saveToPortal(), 'Save now']];
}
function startCardHTML(){
  if(clientMode || ls.get('tablescape-hide-start') === '1') return '';
  const st = startSteps(), done = st.filter(s => s[1]).length; if(done === st.length) return '';
  return `<section class="inv-card start-card"><div class="start-head"><div><span class="eyebrow">Getting started · ${done} of ${st.length}</span><h2>Plan ${esc(state.event.name)} step by step</h2></div><button class="btn sm" data-starthide="1">Hide</button></div>
    <div class="bu-bar" aria-hidden="true"><i style="width:${done/st.length*100}%;background:var(--accent)"></i></div>
    <ol class="start-list">${st.map(([n, ok], i) => `<li class="${ok ? 'done' : ''}"><span class="start-n">${ok ? '✓' : i + 1}</span><span>${esc(n)}</span>${ok ? '' : `<button class="btn sm" data-startgo="${i}">${esc(st[i][3])}</button>`}</li>`).join('')}</ol>
    <p class="muted" style="font-size:12px;margin:0">Tip: press <span class="kbd">Ctrl</span> <span class="kbd">K</span> anywhere to jump to any page.</p></section>`;
}
const _renderPortalCalm = renderPortal; renderPortal = function(){ _renderPortalCalm(); const head = $('#portal .sheet-head'); if(head) head.insertAdjacentHTML('afterend', startCardHTML()); };
