/* ============ venue architecture & fire code ============ */
Object.assign(FIXTURES, {door:{label:'Entrance', w:6, h:1}, exit:{label:'Emergency exit', w:4, h:1}, column:{label:'Column', w:2, h:2, round:true}, outlet:{label:'Power outlet', w:1, h:1}, restroom:{label:'Restrooms', w:10, h:8}, kitchen:{label:'Kitchen / prep', w:14, h:10}, coat:{label:'Coat check', w:6, h:3}});
function fireChecks(){
  const out = [], area = state.room.w*state.room.h, fx = state.items.filter(i => i.kind === 'fixture');
  const usable = area - fx.filter(f => ['restroom','kitchen'].includes(f.type)).reduce((a, f) => a + f.w*f.h, 0), cap = Math.floor(usable/15), coming = state.guests.filter(g => g.rsvp !== 'no').length;
  if(coming > cap) out.push(`About ${coming} guests in roughly ${Math.round(usable).toLocaleString()} usable sq ft. A common planning guide for seated dinners is 15 sq ft per person (about ${cap} people). Check the venue’s posted occupancy.`);
  if(!isOutdoor()){ const exits = fx.filter(f => f.type === 'exit').length + fx.filter(f => f.type === 'door').length; const need = coming > 1000 ? 4 : coming > 500 ? 3 : coming > 49 ? 2 : 1; if(fx.some(f => f.type === 'door' || f.type === 'exit') && exits < need) out.push(`${coming} guests usually need at least ${need} exits. The plan shows ${exits}. Mark the venue’s exits so aisles stay clear.`); }
  fx.filter(f => f.type === 'exit').forEach(ex => { tables().forEach(t => { if(Math.hypot(t.x - ex.x, t.y - ex.y) < footR(t) + 3) out.push(`${tableLabel(t)} is close to an emergency exit. Keep at least 3 ft clear in front of exits.`); }); });
  return out;
}

