/* ============ ceremony space ============ */
Object.assign(SETTINGS, {chapel:{label:'Chapel', kind:'indoor', floor:'marble', wall:'#efe8dc', ceiling:'beams', h:26, sky:'#efe8dc', ground:'#d9d2c8'}, cathedral:{label:'Cathedral', kind:'indoor', floor:'marble', wall:'#cfc4b4', ceiling:'chandeliers', h:40, sky:'#cfc4b4', ground:'#bdb3a5'}, courtyard:{label:'Courtyard', kind:'outdoor', floor:'tile', sky:'#bfdcf2', ground:'#c7774f'}});
Object.assign(FIXTURES, {pew:{label:'Pew', w:8, h:2.2}, altar:{label:'Altar', w:6, h:3}});
let activeSpace = 'reception', spacePref = 'reception', FULL_ITEMS = null;
