    portalEvents.filter(e => e.date && e.date >= today && e.status !== 'cancelled' && Array.isArray(e.linens)).forEach(e => peakHeld(holdSpan(e), null).forEach((q, k) => want.set(k, Math.max(want.get(k) || 0, q))));
