function avRunSheet(){ return [`AV RUN SHEET · ${state.event.name} · ${fmtDate(state.event.date)}`, '', ...speakers().slice().sort((a, b) => toMin(a.time || '23:59') - toMin(b.time || '23:59')).map(s => `${s.time ? fmt12(s.time) : '—'}  ${s.name || 'Speaker'}${s.org ? ' (' + s.org + ')' : ''}\n   ${s.talk || ''} · ${s.dur || 30} min\n   AV: ${(s.av || []).map(k => SPEAKER_AV[k]).join(', ') || 'nothing special'}${s.notes ? '\n   Notes: ' + s.notes : ''}`)].join('\n'); }
