$('#view-plan').addEventListener('change', e => { const t = e.target; if(!t.dataset.spk) return; const s = speakers().find(x => x.id === t.dataset.sid); if(!s) return; if(t.dataset.spk === 'status') mutate(() => s.status = t.value); if(['status','time','talk','name'].includes(t.dataset.spk)) renderPlanning(); });
