/* ============ speaker headshots, bios & website lineup ============ */
function headshotDataURL(file){ return new Promise((res, rej) => { const fr = new FileReader(); fr.onerror = rej; fr.onload = () => { const img = new Image(); img.onerror = rej; img.onload = () => { const s = 220, c = document.createElement('canvas'); c.width = c.height = s; const x = c.getContext('2d'), m = Math.min(img.width, img.height); x.drawImage(img, (img.width - m)/2, (img.height - m)/2, m, m, 0, 0, s, s); res(c.toDataURL('image/jpeg', .8)); }; img.src = fr.result; }; fr.readAsDataURL(file); }); }
const speakerFace = (s, size = 56) => s.photo ? `<img src="${s.photo}" alt="" style="width:${size}px;height:${size}px;border-radius:50%;object-fit:cover;flex:none">` : `<span style="width:${size}px;height:${size}px;border-radius:50%;display:inline-grid;place-items:center;background:var(--accent-soft);color:var(--accent);font-family:var(--display);font-size:${Math.round(size*.38)}px;flex:none">${esc(initials(s.name || '?').toUpperCase())}</span>`;
