    h = h.replace(`<label class="fld" style="margin-top:8px"><span>Contact &amp; notes</span><input data-spk="notes" data-sid="${s.id}"`, `<label class="fld" style="margin-top:8px"><span>Short bio (shown on the event website)</span><textarea class="iv-msg" rows="2" data-spk="bio" data-sid="${s.id}" placeholder="Two or three sentences">${esc(s.bio || '')}</textarea></label><label class="fld"><span>Contact &amp; notes (team only)</span><input data-spk="notes" data-sid="${s.id}"`);
