    x.save(); x.globalCompositeOperation = 'screen'; x.globalAlpha = opts.bloom ?? .32; x.filter = 'blur(10px)'; x.drawImage(b, 0, 0, w, h); x.restore();
    // tilt-shift depth of field: soften the top and bottom of the frame
    const t = mk(w, h), tx = t.getContext('2d'); tx.filter = `blur(${Math.round(w/450)}px)`; tx.drawImage(out, 0, 0); tx.filter = 'none'; tx.globalCompositeOperation = 'destination-in';
    const g = tx.createLinearGradient(0, 0, 0, h); g.addColorStop(0, 'rgba(0,0,0,.9)'); g.addColorStop(.28, 'rgba(0,0,0,0)'); g.addColorStop(.72, 'rgba(0,0,0,0)'); g.addColorStop(1, 'rgba(0,0,0,.95)'); tx.fillStyle = g; tx.fillRect(0, 0, w, h);
