  const v = x.createRadialGradient(w/2, h*.46, Math.min(w, h)*.35, w/2, h/2, Math.max(w, h)*.72); v.addColorStop(0, 'rgba(0,0,0,0)'); v.addColorStop(1, 'rgba(0,0,0,.45)'); x.fillStyle = v; x.fillRect(0, 0, w, h);
  // film grain
  const n = mk(160, 160), nx = n.getContext('2d'), id = nx.createImageData(160, 160), R = rng(77); for(let i=0;i<id.data.length;i+=4){ const k = 110 + R()*36; id.data[i] = id.data[i+1] = id.data[i+2] = k; id.data[i+3] = 255; } nx.putImageData(id, 0, 0);
