  const oh = onHandMap(), rsv = reservedByOthers(), ld = laundryDays(), others = reservingEvents();
  const short = [...nd].map(([k, v]) => ({k, need:v.qty, own:oh.get(k) || 0, held:rsv.get(k) || 0})).map(x => Object.assign(x, {free:Math.max(0, x.own - x.held)})).filter(x => x.need > x.free).sort((a, b) => (b.need - b.free) - (a.need - a.free));
