  const who = others.length ? ` ${others.length} other event${others.length > 1 ? 's' : ''} overlap${others.length > 1 ? '' : 's'}: ${others.slice(0, 3).map(e => esc(e.name)).join(', ')}${others.length > 3 ? '…' : ''}.` : '';
  const msg = short.length
    ? `<b>${short.length} item${short.length > 1 ? 's' : ''} short</b> for ${win} (rental window plus ${lday}).${who} ${short.slice(0, 4).map(x => `${esc(capFirst(linenKeyText(x.k)))}: need ${x.need}, ${x.free} free${x.held ? ` (${x.held} out with other events)` : ''}`).join(' · ')}${short.length > 4 ? ' …' : ''}`
    : `<b>In stock</b> for ${win} (rental window plus ${lday}).${who}`;
