function linenQuoteText(){
  const q = quoteCalc(), Q = linenQuote(), cl = state.client || {};
  return [`LINEN RENTAL QUOTE · ${company.name}`, [company.email, company.phone].filter(Boolean).join(' · '), '', `Prepared for: ${cl.name || '—'}${cl.email ? ' · ' + cl.email : ''}${cl.phone ? ' · ' + cl.phone : ''}`, `Event: ${state.event.name} · ${fmtDate(state.event.date)}${state.event.venue ? ' · ' + state.event.venue : ''}`, `Delivery: ${shortFmt(q.out) || 'to be set'}${q.outTime ? ' at ' + fmt12(q.outTime) : ''} · Pickup: ${shortFmt(q.back) || 'to be set'}${q.backTime ? ' at ' + fmt12(q.backTime) : ''}`, q.address ? `Deliver to: ${q.address}` : '', q.contact ? `On-site contact: ${q.contact}` : '', '',
    ...q.lines.map(l => `${String(l.qty).padStart(5)} × ${capFirst(l.label)}, ${l.size} @ ${money2(l.unit)} = ${money(l.total)}`), '',
    `Subtotal: ${money(q.sub)}`, `Delivery & pickup: ${money(q.delivery)}`, q.waiver ? `Damage waiver (${+Q.waiver}%): ${money(q.waiver)}` : '', q.tax ? `Sales tax (${+budget().tax}%): ${money(q.tax)}` : '', `TOTAL: ${money(q.total)}`, q.deposit ? `Deposit to reserve the date (${+Q.deposit}%): ${money(q.deposit)}` : '', q.spares ? `Plus ${q.spares} spare piece${q.spares > 1 ? 's' : ''} packed at no charge.` : '', '', Q.notes || ''].filter((x, i, a) => x !== '' || a[i - 1] !== '').join('\n');
}
