$('#view-order').addEventListener('change', e => { const t = e.target, k = t.dataset.lqf; if(!k) return; mutate(() => linenQuote()[k] = k === 'spares' ? clamp(Math.round(+t.value || 0), 0, 25) : ['delivery','waiver','deposit'].includes(k) ? Math.max(0, +t.value || 0) : t.value); rerenderOrderKeep(); });
