/* ============ day-of packet (one file for the binder) ============ */
function dayPacketText(){
  ensurePlanning();
  const L = [`DAY-OF PACKET · ${state.event.name}`, `${fmtDate(state.event.date)}${state.event.venue ? ' · ' + state.event.venue : ''}`, `${company.name}${company.phone ? ' · ' + company.phone : ''}`, `${state.guests.filter(g => g.rsvp !== 'no').length} attending guests · ${tables().filter(t => t.seats).length} tables`, '', timelineText(), '', contactSheet(), ''];
  const items = dayOfItems(); L.push('CHECKLIST'); ['Setup','Getting ready','Ceremony','Reception','Wrap up'].forEach(p => { const is = items.filter(i => i.phase === p); if(!is.length) return; L.push(`  ${p.toUpperCase()}`); is.forEach(i => L.push(`  [ ] ${fmt12(i.time).padStart(8)}  ${i.text}`)); }); L.push('');
  const sm = seatMap(), ts = sortedTables().filter(t => t.seats); if(ts.length){ L.push('SEATING'); ts.forEach(t => { const names = Array.from({length:t.seats}, (_, i) => sm.get(t.id + ':' + i)).filter(Boolean).map(g => g.name); L.push(`  ${tableLabel(t)}: ${names.join(', ') || 'no one seated yet'}`); }); L.push(''); }
  const special = state.guests.filter(g => g.rsvp !== 'no' && (g.diet || (g.dietTags || []).length || (g.needs || []).length));
  if(special.length){ L.push('DIETARY & ACCESS'); special.forEach(g => { const t = g.tableId && byId(g.tableId); L.push(`  ${g.name}${t ? ' (' + tableShort(t) + ')' : blockWhere(g) ? ' (' + blockWhere(g) + ')' : ''}: ${[...(g.needs || []).map(n => NEEDS[n]), ...(g.dietTags || []).map(k => DIET_TAGS[k]), g.diet].filter(Boolean).join(', ')}`); }); L.push(''); }
  L.push('EMERGENCY KIT', ...KIT.map(k => '  [ ] ' + k));
  return L.join('\n');
}
const _renderPlanningPK = renderPlanning; renderPlanning = function(){ _renderPlanningPK(); if(planTab !== 'show') return; const c = $('#planning [data-tl="copy"]'); if(c && !$('#planning [data-dl="packet:txt"]')) c.insertAdjacentHTML('afterend', '<button class="btn sm" data-dl="packet:txt" title="Run of show, contacts, checklist, seating, dietary notes and the floor plan in one PDF">Download day-of packet</button>'); };
document.addEventListener('click', async e => {
  const d = e.target.closest('[data-dl]'); if(!d) return; const [what] = d.dataset.dl.split(':'); if(what !== 'packet' && what !== 'lquote') return;
  try { if(what === 'packet') await offerFile(slug(state.event.name) + '-day-of-packet.txt', dayPacketText()); else await offerFile(slug(state.event.name) + '-linen-quote.txt', linenQuoteText()); } catch(err){ toast('Couldn’t prepare that file.'); }
});

