/* ============ musicians on stage, cue-driven light rig, stage camera & band sets ============ */
const RIG_SKIN = ['#c58c6b', '#8d5a3b', '#e0b49a', '#5a3a28', '#b07a56'];
function rigFigure(parent, x, y, z, rotY, i, pose = 'stand'){
  const g = new THREE.Group(); g.position.set(x, y, z); g.rotation.y = rotY; parent.add(g);
  const CY = geo('fig-cyl', () => new THREE.CylinderGeometry(1, 1, 1, 12)), SP = geo('fig-sph', () => new THREE.SphereGeometry(1, 16, 12));
  const cloth = std(['#1d1c22', '#2a2630', '#18181c', '#302a26'][i % 4], .85), skin = std(RIG_SKIN[i % RIG_SKIN.length], .6), shoe = std('#0d0d0f', .5);
  const part = (geom, m, sx, sy, sz, px, py, pz, rx = 0, rz = 0) => { const o = new THREE.Mesh(geom, m); o.scale.set(sx, sy, sz); o.position.set(px, py, pz); o.rotation.set(rx, 0, rz); o.castShadow = true; g.add(o); return o; };
  const sit = pose === 'sit', hip = sit ? 1.9 : 2.75;
  if(sit){ [-.28, .28].forEach(s => { part(CY, cloth, .15, 1.5, .15, s, hip - .05, .7, Math.PI/2); part(CY, cloth, .13, 1.7, .13, s, hip - .9, 1.45); part(SP, shoe, .17, .1, .26, s, .1 + (y > 1 ? 0 : 0), 1.55); }); }
  else [-.27, .27].forEach(s => { part(CY, cloth, .15, hip, .15, s, hip/2, 0); part(SP, shoe, .17, .1, .28, s, .08, .1); });
  part(CY, cloth, .42, 2.3, .3, 0, hip + 1.1, 0); part(SP, cloth, .44, .2, .32, 0, hip + 2.25, 0);
  part(CY, skin, .12, .3, .12, 0, hip + 2.45, 0); part(SP, skin, .36, .43, .38, 0, hip + 2.9, 0);
  const armF = pose === 'keys' || pose === 'dj' || sit ? .95 : pose === 'guitar' ? .7 : .25;
  [-1, 1].forEach(s => part(CY, cloth, .1, 1.9, .1, s*.55, hip + 1.45, armF * .7, -armF * 1.1, s * .12));
  if(pose === 'guitar'){ part(SP, std('#7a3b1d', .35, .1), .55, .7, .16, .05, hip + .95, .42); part(CY, std('#2a1a10', .4), .05, 1.9, .05, -.65, hip + 1.5, .42, 0, 1.1); }
  return g;
}
const _entRig13 = entRig3D; entRig3D = function(){
  _entRig13();
  const rig = V && V.group && V.group.getObjectByName('entRig'); if(!rig) return;
  const c = effVis().cue, mode = !c ? 'all' : c.party ? 'party' : c.wash ? 'spot' : 'calm';
  V.rigSpeed = mode === 'party' ? 2.2 : mode === 'spot' ? .35 : 1;
  rig.traverse(o => { const r = o.userData.rig; if(!r) return;
    if(r === 'beam'){ o.visible = mode !== 'calm'; if(o.material) o.material.opacity *= mode === 'party' ? 1.8 : mode === 'spot' ? .35 : 1; }
    if(r === 'laser') o.visible = mode === 'all' || mode === 'party';
    if(r === 'spot') o.visible = mode !== 'calm'; });
  if(addonOn('movingheads') && V.beams){ V.beams.forEach(g => g.parent && g.parent.remove(g)); V.beams = null; }
  const E = state.ent || {}, W = V.W, H = V.H, S = fixOf('stage')[0], J = fixOf('dj')[0];
  const at = f => { const g = new THREE.Group(); g.position.set(f.x - W/2, 0, f.y - H/2); g.rotation.y = -deg(f.rot || 0); rig.add(g); return g; };
  if(S && (E.type === 'band' || E.type === 'djband')){
    const g = at(S), y0 = 1.5, BL = bandLayout(S.w, S.h, E.type === 'djband'); let n = 0;
    if(BL.drums) rigFigure(g, 0, y0 + .4, BL.drums.z - 1.5, 0, n++, 'sit');
    if(BL.keys) rigFigure(g, BL.keys.x, y0, BL.keys.z - 1.1, 0, n++, 'keys');
    BL.mics.forEach(x => rigFigure(g, x, y0, S.h/2 - 2.35, 0, n++, 'stand'));
    if(BL.guitar) rigFigure(g, BL.guitar.x, y0, BL.guitar.z, .3, n++, 'guitar');
    if(BL.bass) rigFigure(g, BL.bass.x, y0, BL.bass.z, .3, n++, 'guitar');
    BL.horns.forEach(h => rigFigure(g, h.x, y0, h.z, -.3, n++, 'stand'));
    if(BL.perc) rigFigure(g, BL.perc.x, y0 + .4, BL.perc.z - 1, 0, n++, 'sit');
    if(BL.dj) rigFigure(g, BL.dj.x, y0, BL.dj.z - 1.6, 0, n++, 'dj');
  }
  if(J && (E.type === 'dj' || E.type === 'djband')){ const g = at(J); rigFigure(g, 0, 0, -J.h/2 - .7, 0, 2, 'dj'); }
};
/* stage camera */
const camFromTo = (cx, cy, cz, tx, ty, tz) => { const vx = cx - tx, vy = cy - ty, vz = cz - tz, r = Math.hypot(vx, vy, vz); return {theta:Math.atan2(vx, vz), phi:Math.acos(clamp(vy / r, -1, 1)), r, tx, ty, tz}; };
const _camTarget13 = camTarget; camTarget = function(name){
  if(name !== 'stage') return _camTarget13(name);
  const f = fixOf('stage')[0] || fixOf('dj')[0]; if(!f || !V) return _camTarget13('overview');
  const W = V.W, H = V.H, th = -deg(f.rot || 0), dx = Math.sin(th), dz = Math.cos(th), d = Math.max(f.w, f.h) * 1.15 + 8, cx = f.x - W/2, cz = f.y - H/2;
  return camFromTo(cx + dx*d + dz*3, 7, cz + dz*d - dx*3, cx, f.type === 'stage' ? 5 : 3.5, cz);
};
(function(){ const c = $('#v-cam'); if(c && !c.querySelector('[data-cam="stage"]')) c.insertAdjacentHTML('beforeend', '<button data-cam="stage" hidden>Stage</button>'); })();
const _visionBuild13 = visionBuild; visionBuild = function(){ const r = _visionBuild13.apply(this, arguments); const b = $('#v-cam [data-cam="stage"]'); if(b) b.hidden = !(fixOf('stage')[0] || fixOf('dj')[0]) || (typeof activeSpace !== 'undefined' && activeSpace === 'ceremony'); return r; };
/* band sets in the run of show */
function entSetPlan(){
  const E = ent(), T = (state.timeline || []).filter(x => !x.entSet), dance = T.find(x => /^dancing|open dancing|dance floor opens/i.test(x.title || '')), last = T.find(x => /last dance|send-off|send off/i.test(x.title || ''));
  const start = dance ? toMin(dance.time) : toMin(state.event.time || '18:00') + 150, end = Math.max(start + 60, last ? toMin(last.time) : start + Math.min(E.hours || 4, 4) * 60), out = [];
  if(E.type !== 'band' && E.type !== 'djband') return out;
  let t = start, n = 1; while(t + 30 <= end){ const len = Math.min(45, end - t); out.push({time:hm(t), dur:len, title:`Band set ${n}`}); t += len; if(E.type === 'djband' && t + 15 < end){ out.push({time:hm(t), dur:15, title:'DJ bridge set (band break)'}); } t += 15; n++; }
  return out;
}
function addEntSets(){
  const P = entSetPlan(), E = ent(); if(!P.length){ toast('Sets are for live bands — pick “Live band” or “DJ + live band”.'); return; }
  ensurePlanning(); mutate(() => { state.timeline = state.timeline.filter(x => !x.entSet); P.forEach(p => state.timeline.push({id:uid(), type:'reception', where:'Stage', who:E.vendor || 'Band', entSet:true, ...p})); });
  toast(`Added ${P.filter(p => p.title.startsWith('Band')).length} band sets to the run of show`);
}
const _entControls13 = entertainmentControls; entertainmentControls = function(seg){
  const h = _entControls13(seg), E = ent(); if(E.type !== 'band' && E.type !== 'djband') return h;
  const P = entSetPlan(), has = (state.timeline || []).some(x => x.entSet);
  const box = `<div style="margin-top:10px"><span class="ctl-label">Sets</span><p class="muted" style="font-size:12px;margin:2px 0 6px">${P.length ? P.filter(p => p.title.startsWith('Band')).map(p => fmt12(p.time)).join(' · ') + ' — 45 on, 15 off' : 'Add a “Dancing” moment to the run of show first.'}</p>${P.length ? `<button class="btn sm" data-entsets="1">${has ? 'Update sets in the run of show' : 'Add sets to the run of show'}</button>` : ''}</div>`;
  return h.replace('<div class="btn-row" style="margin:8px 0 0"><button class="btn sm" data-entrider="1">', box + '<div class="btn-row" style="margin:8px 0 0"><button class="btn sm" data-entrider="1">');
};
$('#view-music').addEventListener('click', e => { if(e.target.closest('[data-entsets]')){ addEntSets(); renderMusic(); } });
const _techRider13 = techRider; techRider = function(){ const r = _techRider13(), S = (state.timeline || []).filter(x => x.entSet).sort((a, b) => toMin(a.time) - toMin(b.time)); return S.length ? r + '\nSets:\n' + S.map(x => `  ${fmt12(x.time)} – ${fmt12(hm(toMin(x.time) + (x.dur || 45)))}  ${x.title}`).join('\n') : r; };

/* ============ lifelike performers, staffing plan & lighting cue sheet ============ */
/* performers use the same people as the guests (silhouette or colorful), standing on the stage */
rigFigure = function(parent, x, y, z, rotY, i, pose = 'stand'){
  (parent.__perf ||= []).push({x, y, z, ry:Math.PI + rotY, seated:pose === 'sit', dance:false, dress:false, seed:i*977 + 7, pose});
  if(pose === 'guitar'){ const body = new THREE.Mesh(geo('gtr-body', () => new THREE.SphereGeometry(1, 16, 12)), std('#7a3b1d', .35, .1)); body.scale.set(.55, .7, .16); body.position.set(x + .05, y + 2.25, z + .48); body.castShadow = true; parent.add(body); const neck = new THREE.Mesh(geo('rig-cyl', () => new THREE.CylinderGeometry(1, 1, 1, 18)), std('#2a1a10', .4)); neck.scale.set(.05, 1.9, .05); neck.position.set(x - .7, y + 2.85, z + .48); neck.rotation.z = 1.1; parent.add(neck); }
  if(pose === 'sit'){ const stool = new THREE.Mesh(geo('rig-cyl', () => new THREE.CylinderGeometry(1, 1, 1, 18)), std('#121114', .5, .2)); stool.scale.set(.45, 1.55, .45); stool.position.set(x, y + .78, z - .25); parent.add(stool); }
};
const _entRig14 = entRig3D; entRig3D = function(){
  _entRig14();
  const rig = V && V.group && V.group.getObjectByName('entRig'); if(!rig) return;
  const holders = []; rig.traverse(o => { if(o.__perf && o.__perf.length) holders.push(o); });
  holders.forEach(h => { const byY = {}; h.__perf.forEach(p => (byY[p.y] ||= []).push(p)); Object.entries(byY).forEach(([y, list]) => { const sub = new THREE.Group(); sub.position.y = +y - (list[0].seated ? .35 : 0); h.add(sub); try { buildPeople(sub, list.map(p => ({x:p.x, z:p.z, ry:p.ry, seated:p.seated, dance:p.dance, dress:p.dress, seed:p.seed}))); } catch(e){ console.warn('performers', e); } }); h.__perf = []; });
};

/* ============ staffing plan (Planning → Day of) ============ */
const STAFF_RATES = {lead:55, captain:38, server:30, bartender:45, setup:28, coat:25, security:40};
function staffingPlan(){
  const n = state.guests.filter(g => g.rsvp !== 'no').length, ts = tables().filter(t => t.seats).length, tl = (state.timeline || []).filter(x => x.time && !['vendor','prep','photo'].includes(x.type));
  const start = tl.length ? Math.min(...tl.map(x => toMin(x.time))) : 17*60, end = tl.length ? Math.max(...tl.map(x => toMin(x.time) + (+x.dur || 0))) : start + 300;
  const svc = (state.menuChoices && state.menuChoices.service) || 'plated', per = {plated:20, family:25, buffet:32, stations:30}[svc] || 20;
  /* the setup items in the run of show (deliveries, installs, tables set): the crew is called for the first one and nobody is called before it */
  const su = (state.timeline || []).filter(x => x.time && x.type === 'vendor' && /deliver|install|tables set|set ?up|load.?in/i.test(x.title || '') && toMin(x.time) < start), setupAt = su.length ? Math.min(...su.map(x => toMin(x.time))) : null, setupEnd = su.length ? Math.max(...su.map(x => toMin(x.time) + (+x.dur || 0))) : null;
  const at = m => setupAt == null ? m : Math.max(m, setupAt);
  const barTenders = state.bar ? ((barCalc().list.find(l => l.label === 'Bartenders') || {}).qty || 0) : 0;
  const R = (key, role, qty, call, off, note, inBudget) => ({key, role, qty, call, off, hours: Math.max(1, Math.round((off - call)/30)/2), rate:(state.staffRates || {})[key] ?? STAFF_RATES[key], note, inBudget});
  const rows = [
    R('lead', 'Event lead', n > 150 ? 2 : 1, at(start - 240), end + 60, 'Runs the timeline, vendors and client'),
    R('captain', 'Banquet captain', Math.max(1, Math.ceil(n/100)), at(start - 120), end + 30, 'Leads the floor team'),
    R('server', `Servers (${(SERVICE_STYLES[svc] || ['Plated'])[0].toLowerCase()}, 1 per ${per})`, Math.max(1, Math.ceil(n/per)), at(start - 90), end, 'Food, clearing and table touch-ups'),
    R('setup', 'Setup & breakdown crew', Math.max(2, Math.ceil(ts/6) + 1), setupAt ?? start - 300, setupAt == null ? start - 30 : Math.max(setupAt + 60, Math.min(start - 30, setupEnd)), 'Tables, linens, place settings; back for teardown'),
  ];
  if(barTenders) rows.push(R('bartender', 'Bartenders', barTenders, at(start - 60), end, 'Already priced in the bar estimate', true));
  if(state.items.some(i => i.type === 'coat')) rows.push(R('coat', 'Coat check', 1, at(start - 15), end + 15, ''));
  if(state.eventType === 'prom' || n > 250) rows.push(R('security', 'Security', Math.max(1, Math.ceil(n/100)), at(start - 30), end + 30, state.eventType === 'prom' ? 'Door and chaperone check-in' : 'Door and crowd'));
  rows.forEach(r => { if(r.key === 'setup') r.hours += 2; r.cost = r.inBudget ? 0 : r.qty*r.hours*r.rate; });
  return {n, rows, total: rows.reduce((a, r) => a + r.cost, 0), heads: rows.reduce((a, r) => a + r.qty, 0)};
}
function staffingHTML(){
  const P = staffingPlan(), billed = (budget().extra || []).find(x => x.id === 'staffing');
  return `<section class="inv-card" id="staffing-sec"><div class="sheet-head" style="padding-bottom:10px;border:0"><div><span class="eyebrow">Staffing plan</span><h2 style="font-family:var(--display);font-weight:400;font-size:24px;margin:2px 0 0">${P.heads} staff for ${P.n} guests</h2><p class="muted" style="margin:4px 0 0;font-size:12.5px">Worked out from the guest count, service style, tables and bar. Call times come from the run of show.</p></div>
    <div class="btn-row" style="margin:0"><button class="btn sm" data-stf="copy">Copy staff schedule</button><button class="btn sm primary" data-stf="bill">${billed ? 'Update' : 'Add'} labor in the budget</button></div></div>
    <div class="table-scroll"><table class="qty"><thead><tr><th>Role</th><th class="num">People</th><th>Call</th><th>Off</th><th class="num">Hours</th><th class="num">Rate</th><th class="num">Cost</th></tr></thead><tbody>
    ${P.rows.map(r => `<tr><td>${esc(r.role)}${r.note ? `<br><span class="muted" style="font-size:11.5px">${esc(r.note)}</span>` : ''}</td><td class="num">${r.qty}</td><td>${fmt12(fromMin(r.call))}</td><td>${fmt12(fromMin(r.off))}</td><td class="num">${r.hours}</td><td class="num"><label class="bu-money">$<input class="qty-in" type="number" min="0" step="1" data-stfrate="${r.key}" value="${r.rate}" aria-label="Hourly rate for ${esc(r.role)}"></label></td><td class="num">${r.inBudget ? '<span class="muted">in bar</span>' : money(r.cost)}</td></tr>`).join('')}
    <tr><td><b>Labor total</b></td><td class="num"><b>${P.heads}</b></td><td></td><td></td><td></td><td></td><td class="num"><b>${money(P.total)}</b></td></tr></tbody></table></div></section>`;
}
function staffingText(){ const P = staffingPlan(); return [`STAFF SCHEDULE · ${state.event.name} · ${fmtDate(state.event.date)}`, '', ...P.rows.map(r => `${String(r.qty).padStart(3)} × ${r.role}: ${fmt12(fromMin(r.call))} – ${fmt12(fromMin(r.off))} (${r.hours} h)${r.note ? ' · ' + r.note : ''}`), '', `${P.heads} people · labor ${money(P.total)}`].join('\n'); }
const _renderPlanning14 = renderPlanning; renderPlanning = function(){ _renderPlanning14(); if(planTab !== 'dayof' || clientMode) return; const nc = $('#planning .now-card'); if(nc) nc.insertAdjacentHTML('afterend', staffingHTML()); };
