/* ============ lighting cue sheet: which cue fires at which moment ============ */
const CUE_MATCH = {arrival:/arriv|cocktail|doors|registration|welcome/i, dinner:/dinner|lunch|food|buffet|meal/i, firstdance:/first dance|father|mother|waltz/i, party:/dancing|party|after-party/i, last:/last dance|last song|send-off|send off|closing/i};
function cueTimeline(){
  const tl = (state.timeline || []).filter(x => x.type !== 'vendor' && x.type !== 'prep').slice().sort((a, b) => toMin(a.time) - toMin(b.time));
  return lighting().cues.map(c => { const re = CUE_MATCH[c.id] || new RegExp(c.name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'i'); const x = tl.find(t => re.test(t.title)); return {c, x}; }).filter(o => o.x).sort((a, b) => toMin(a.x.time) - toMin(b.x.time));
}
function cueSheetText(){
  const A = addons(), on = k => !!A[k] && !!ADDONS[k], list = cueTimeline();
  const fx = c => [c.party && on('movingheads') ? 'moving heads FAST' : c.wash && on('movingheads') ? 'moving heads slow & dim' : on('movingheads') ? 'moving heads OFF' : c.party ? 'beams on' : '', c.party && on('lasers') ? 'lasers ON' : '', (c.wash || c.party) && on('followspot') ? 'follow spot on' : '', c.pin ? 'pin-spots on' : '', c.strings ? 'string lights on' : ''].filter(Boolean).join(', ');
  return [`LIGHTING CUE SHEET · ${state.event.name} · ${fmtDate(state.event.date)}`, '', ...(list.length ? list.map(({c, x}) => `${fmt12(x.time).padStart(8)}  ${c.name.toUpperCase()} (at “${x.title}”)\n          Uplights ${c.up || 'off'} at ${Math.round((c.upLevel || 0)*100)}%${c.wash ? ` · floor wash ${c.wash}` : ''}${fx(c) ? `\n          ${fx(c)}` : ''}`) : ['No cues match the run of show yet.'])].join('\n');
}
const _lightingHTML14 = lightingHTML; lightingHTML = function(){ const h = _lightingHTML14(), list = cueTimeline(); return h.replace('<div class="btn-row" style="margin:0"><button class="btn sm" data-lcadd="1">', `${list.length ? `<p class="muted" style="font-size:12px;margin:0">${list.map(({c, x}) => `${esc(fmt12(x.time))} ${esc(c.name)}`).join(' → ')}</p>` : ''}<div class="btn-row" style="margin:0"><button class="btn sm" data-lcsheet="1">Copy cue sheet</button><button class="btn sm" data-lcadd="1">`); };
