  if(L.keys){ add('Keys L', 'DI box'); add('Keys R', 'DI box'); }
  if(L.percussion){ add('Congas', 'SM57'); add('Percussion overhead', 'Small condenser'); }
  for(let i=1;i<=(L.horns | 0);i++) add(`Horn ${i}`, 'Clip-on condenser');
  for(let i=1;i<=(L.vocals | 0);i++) add(`Vocal ${i}`, 'SM58 or wireless');
