      if(GLOW.busy || scene !== V.scene || !glowOn()) return raw(scene, cam);
      const s2 = r.getSize(new THREE.Vector2()); if(s2.x !== GLOW.size[0] || s2.y !== GLOW.size[1]){ c.setSize(s2.x, s2.y); GLOW.size = [s2.x, s2.y]; }
