function inqAvailHTML(){
  const iso = inqDraft.date; if(!iso) return '<span class="muted">Pick a date to see what else is on the calendar and how many linens are already going out.</span>';
  const d = new Date(iso + 'T00:00'); if(isNaN(d)) return '';
  const out = [];
  if(iso < isoLocal()) out.push('<span class="pill warn">That date has passed</span>');
  const same = portalEvents.filter(e => e.date === iso && e.status !== 'cancelled'), firm = same.filter(e => e.status === 'booked' || e.status === 'completed');
  if(!same.length) out.push(`<span class="pill ok">Open</span> Nothing else on ${esc(fmtDate(iso))}.`);
  else out.push(`<span class="pill ${firm.length ? 'warn' : 'caution'}">${same.length} event${same.length > 1 ? 's' : ''} that day</span> ${same.slice(0, 3).map(e => `${esc(e.name)} <span class="muted">(${esc((STATUSES[e.status] || STATUSES.inquiry)[0].toLowerCase())})</span>`).join(', ')}${same.length > 3 ? '…' : ''}.`);
  const busy = new Set(same.flatMap(e => e.staff || [])); if(staffList.length && same.length) out.push(`${busy.size} of ${staffList.length} team members already assigned that day.`);
  const near = eventsAround(iso), pcs = near.reduce((a, e) => a + e.linens.reduce((b, [, q]) => b + (+q || 0), 0), 0);
  if(pcs) out.push(`${pcs.toLocaleString()} linen pieces already out or in the wash that day (${near.length} event${near.length > 1 ? 's' : ''}).`);
  return out.join(' ');
}
function inquiryHTML(){
  const D = inqDraft, f = (k, label, type = 'text', extra = '') => `<label class="fld" style="margin:0"><span>${label}</span><input type="${type}" data-inq="${k}" value="${esc(D[k] ?? '')}" ${extra}></label>`;
  const sel = (k, label, opts) => `<label class="fld" style="margin:0"><span>${label}</span><select data-inq="${k}">${opts.map(([v, n]) => `<option value="${esc(v)}"${D[k] === v ? ' selected' : ''}>${esc(n)}</option>`).join('')}</select></label>`;
  return `<details class="inq" id="inq-box"${inqOpen ? ' open' : ''}><summary>New inquiry · log a call or message in seconds</summary>
    <div class="inq-grid">${f('name', 'Client name', 'text', 'placeholder="Ana Torres" autocomplete="off"')}${f('phone', 'Phone', 'tel', 'autocomplete="off"')}${f('email', 'Email', 'email', 'autocomplete="off"')}
      ${sel('type', 'Event type', Object.entries(EVENT_TYPES))}${f('date', 'Event date', 'date')}${f('guests', 'Guests', 'number', 'min="0" step="5" placeholder="120"')}
      ${f('venue', 'Venue', 'text', 'placeholder="Not booked yet"')}${f('budget', 'Budget ($)', 'number', 'min="0" step="500"')}${sel('source', 'Lead source', LEAD_SOURCES.map(x => [x, x]))}<label class="toggle" style="padding-left:0;align-self:center" title="Opens on the linen rental quote instead of the floor plan"><input type="checkbox" data-inqlinen ${D.linenOnly ? 'checked' : ''}> Linen rental only</label>
      <label class="fld full" style="margin:0"><span>Notes</span><textarea class="iv-msg" rows="2" data-inq="notes" placeholder="Colors, must-haves, linen-only rental, best time to call back">${esc(D.notes || '')}</textarea></label></div>
    <p class="note" id="inq-avail" style="margin:10px 0 0">${inqAvailHTML()}</p>
    <div class="btn-row" style="margin-top:10px"><button class="btn primary" data-inqsave="list">Save inquiry</button><button class="btn" data-inqsave="open">Save and open it</button><button class="btn" data-inqclear="1">Clear</button></div>
    <p class="muted" style="font-size:12px;margin:6px 0 0">Adds it to your events as an inquiry. The event you have open stays as it is.</p></details>`;
}
async function saveInquiry(openAfter){
  const D = inqDraft, name = String(D.name || '').trim(); if(!name){ toast('Add the client’s name first.'); $('[data-inq="name"]')?.focus(); return; }
  const type = EVENT_TYPES[D.type] ? D.type : 'wedding', plan = blankPlan(), id = 'e' + Date.now().toString(36) + uid();
  const linenOnly = !!D.linenOnly;
  plan.event = {name:`${linenOnly ? 'Linen rental' : EVENT_TYPES[type]} · ${name}`, date:D.date || '', venue:String(D.venue || '').trim() || 'Venue'};
  plan.eventType = type; plan.portalId = id; plan.portalStatus = 'inquiry';
  plan.client = {name, email:String(D.email || '').trim(), phone:String(D.phone || '').trim()};
  plan.inquiry = {guests:Math.max(0, Math.round(+D.guests || 0)), budget:Math.max(0, +D.budget || 0), source:D.source || '', notes:String(D.notes || '').trim(), at:Date.now()}; if(linenOnly) plan.inquiry.linenOnly = true;
  if(plan.inquiry.budget) plan.budget = {target:plan.inquiry.budget, prices:{}, extra:[], service:20, tax:8.5, paid:0};
  plan.activity = [{at:Date.now(), text:`${linenOnly ? 'Linen rental inquiry' : 'Inquiry'} logged${plan.inquiry.source ? ' · ' + plan.inquiry.source : ''}${plan.inquiry.guests ? ` · about ${plan.inquiry.guests} guests` : ''}`, who:company.name || 'Team'}];
  const btns = $$('[data-inqsave]'); btns.forEach(b => b.disabled = true);
  try {
    await store.save(id, plan, summaryFor(plan));
    inqDraft = {type, source:D.source || 'Phone call'};
    if(openAfter){ if(state.portalId) await saveToPortal(true); if(await openPortalEvent(id) && linenOnly){ openLinenQuote(); toast('Linen inquiry saved. Add the pieces under Linen-only pieces.'); } else toast(`Inquiry saved. Pick a theme or package to start the design.`); }
    else { toast(`Inquiry saved: ${plan.event.name}`); renderPortal(); }
  } catch(err){ toast(err && err.code === 'invalid_argument' ? 'You don’t have permission to add events here.' : 'Couldn’t save the inquiry. Try again in a moment.'); btns.forEach(b => b.disabled = false); }
}
