$('#view-events').addEventListener('input', e => { const t = e.target; if(!t.dataset.inq) return; inqDraft[t.dataset.inq] = t.value; if(t.dataset.inq === 'date'){ const a = $('#inq-avail'); if(a) a.innerHTML = inqAvailHTML(); } });
$('#view-events').addEventListener('change', e => { const t = e.target; if(t.dataset.inq && t.tagName === 'SELECT') inqDraft[t.dataset.inq] = t.value; if(t.matches('[data-inqlinen]')) inqDraft.linenOnly = t.checked; });
