    const st = (STATUSES[e.status] || STATUSES.inquiry)[0], c = e.client || {}, team = (e.staff || []).map(id => staffById(id)?.name).filter(Boolean);
    if(ev(e.id, e.date, `${e.name}${e.status === 'booked' || e.status === 'completed' ? '' : ' (' + st.toLowerCase() + ')'}`, [`${EVENT_TYPES[e.eventType] || 'Event'} · ${st}`, e.guests ? e.guests + ' guests' : '', [c.name, c.phone, c.email].filter(Boolean).join(' · '), e.theme ? 'Theme: ' + e.theme : '', team.length ? 'Team: ' + team.join(', ') : ''].filter(Boolean).join('\n'), e.venue)) n++;
    (e.dues || []).forEach((d, i) => { if(!d.paid && d.due) ev(`${e.id}-due${i}`, d.due, `Payment due · ${e.name} · ${money(d.amt)}`, `${d.label}: ${money(d.amt)}${c.name ? '\nClient: ' + c.name : ''}${c.phone ? ' · ' + c.phone : ''}`); });
