/* order sheet: linen returns → draft scraps in Odoo (when turned on in Field mapping) */
function odooScrapHTML(){
  const Sc = odooCfg.scrap, X = linenRet().odooScrap, k = ek('scrap');
  if(X){ const un = X.unsent || [], left = un.reduce((a, u) => a + (+u.qty || 0), 0);
    return `<p class="muted" style="font-size:12px;margin:8px 0 0">Sent to Odoo ${esc(new Date(X.at).toLocaleDateString(undefined, {month:'short', day:'numeric'}))} as ${X.ids.length} draft scrap${X.ids.length === 1 ? '' : 's'}. Review and validate them in Odoo.</p>${un.length && odooUI.mcp !== false ? `<p class="note warn" style="margin-top:8px">${un.length} SKU${un.length === 1 ? '' : 's'} didn’t reach Odoo: ${un.slice(0, 6).map(u => esc(u.sku)).join(', ')}${un.length > 6 ? '…' : ''}.</p><div class="btn-row" style="margin:8px 0 0">${oBtn(k, 'scrap-rest', `Send the remaining ${left} piece${left === 1 ? '' : 's'}`, 'Sending…')}</div>` : ''}${oErr(k)}`; }
  const n = pullRows().reduce((a, r) => a + r.dmg + (Sc.includeMissing ? r.missing : 0), 0); if(!n || odooUI.mcp === false) return oErr(k);
  return `<div class="btn-row" style="margin:8px 0 0">${oBtn(k, 'scrap', `Send ${n} ${Sc.includeMissing ? 'damaged &amp; missing' : 'damaged'} piece${n === 1 ? '' : 's'} to Odoo`, 'Sending…')}</div>${oErr(k)}`;
}
const _renderOrder24 = renderOrder; renderOrder = function(){ _renderOrder24(); if(clientMode || !odooCfg.scrap.enabled) return; const sec = $('#pull-sec'); if(sec) sec.insertAdjacentHTML('beforeend', odooScrapHTML()); odooProbe(); };

/* every Odoo button, wherever it renders; writes only ever run from these clicks */
document.addEventListener('click', e => {
  const b = e.target.closest('[data-odoo]'); if(!b || clientMode) return; e.preventDefault();
  const v = b.dataset.odoo, i = v.indexOf(':'), a = i < 0 ? v : v.slice(0, i), arg = i < 0 ? '' : v.slice(i + 1);
  if(a === 'test') odooRun('conn', async () => { odooUI.status = null; odooSetStatus(await odooCall('odoo_status', {})); toast('Connected to Odoo'); });
  if(a === 'refresh') odooRun(ek('refresh'), odooRefreshOrder);
  if(a === 'find') odooRun(ek('find'), odooFindOrder, 'Find in Odoo');
  if(a === 'files') odooDownloadFiles();
  if(a === 'prices') odooRun(ek('prices'), odooPullPrices);
  if(a === 'prices-apply'){ odooApplyPrices(); odooRefresh(); }
  if(a === 'prices-clear'){ odooUI.prices = null; odooRefresh(); }
  if(a === 'invoices') odooRun(ek('invoices'), odooCheckInvoices);
  if(a === 'markpaid'){ odooMarkPaid(); odooRefresh(); }
  if(a === 'stock') odooRun('stock', odooPullStock);
  if(a === 'stock-apply') odooApplyStock();
  if(a === 'stock-clear'){ odooUI.stock = null; delete odooUI.err.stock; odooRefresh(); }
  if(a === 'scrap') odooWrite(ek('scrap'), () => odooSendScrap(false), 'Send linen damage');
  if(a === 'scrap-rest') odooWrite(ek('scrap'), () => odooSendScrap(true), 'Send linen damage');
  if(a === 'check'){ delete odooUI.checks[arg]; odooRun('check:' + arg, () => odooCheck(arg)); }
  if(a === 'save') saveToPortal().then(odooRefresh);
  if(a === 'models'){ const q = $('#odoo-mq'); odooUI.mq = q ? q.value.trim() : odooUI.mq; odooRun('models', async () => { odooUI.models = ((await odooCall('odoo_models', {query:odooUI.mq, limit:20})).models || []).slice(0, 20); }); }
  if(a === 'mcopy') copyText(arg, `Copied ${arg}`);
  if(a === 'map-save') odooSaveMap();
  if(a === 'map-discard'){ odooDraft = null; odooUI.checks = {}; odooRefresh(); }
  if(a === 'map-reset'){ odooDraft = JSON.parse(JSON.stringify(ODOO_DEFAULTS)); odooUI.checks = {}; odooRefresh(); toast('Odoo 19 defaults loaded. Save to apply them for your team.'); }
});
document.addEventListener('input', e => { const t = e.target; if(t.dataset && t.dataset.odoomap != null && t.type !== 'checkbox') odooMapInput(t, false); if(t.id === 'odoo-mq') odooUI.mq = t.value; });
document.addEventListener('change', e => { const t = e.target; if(t.dataset && t.dataset.odoomap != null){ odooMapInput(t, true); if(t.type === 'checkbox') odooRefresh(); } });
document.addEventListener('keydown', e => { if(e.key === 'Enter' && e.target.id === 'odoo-mq'){ e.preventDefault(); const b = $('[data-odoo="models"]'); if(b) b.click(); } });
QUICK.push(['Odoo ERP', 'events', () => odooScrollTo('#odoo-sec'), 'odoo'], ['Odoo quotation', 'client', () => { clientTab = 'proposal'; odooScrollTo('#odoo-ev'); }, 'odoo']);
/* the 4th item marks team-only entries: clients never see or open them in Ctrl+K */
const _quickMatches24 = quickMatches; quickMatches = function(){ const r = _quickMatches24(); return clientMode ? r.filter(m => m[3] !== 'odoo') : r; };
const _quickGo24 = quickGo; quickGo = function(i){ if(clientMode && QUICK[i] && QUICK[i][3] === 'odoo'){ quickClose(); return; } return _quickGo24(i); };

/* ============ throne styles & colors ============ */
/* Nine throne styles (Royal crest stays the default), six more fabric & metal pairs, and a price per style.
   Every style keeps the original convention: seat centered on the origin, backrest toward +z, arms near x ±1.05, seat top ~1.9 ft. */
const THRONE_STYLES = {
  royal:{label:'Royal crest', price:275, seats:1, desc:'Tall tufted back with a carved crest and gold orbs.'},
  louis:{label:'King Louis', price:225, seats:1, desc:'Carved frame, oval medallion back, cabriole legs and padded arms.'},
  baroque:{label:'Grand baroque', price:450, seats:1, desc:'8-ft scrolled back with a crown, lion-paw feet and deep tufting.'},
  peacock:{label:'Peacock rattan', price:175, seats:1, desc:'Big woven fan back on an hourglass base. The fabric is the cushion.'},
  crystal:{label:'Crystal ghost', price:350, seats:1, desc:'Clear acrylic arched back lined with crystals. The fabric is the cushion.'},
  heart:{label:'Heart back', price:300, seats:1, desc:'Tufted heart back with a metal trim and tiara. A quinceañera favorite.'},
  wingback:{label:'Tufted wingback', price:250, seats:1, desc:'Velvet wingback with rolled arms, nailheads and a skirt.'},
  bling:{label:'Crystal bling', price:400, seats:1, desc:'Mirror-finish frame studded with rhinestones, velvet panels.'},
  loveseat:{label:'Royal loveseat', price:495, seats:2, desc:'A 5-ft camelback settee with a carved crest for the couple.'},
};
// [label, fabric, metal, optional painted frame]
Object.assign(THRONE_COLORS, {emerald:['Emerald & gold','#1f5a46','#c9a24a'], lavender:['Lavender & silver','#b9a6d6','#c3c7ce'], bridal:['All white & gold','#fbfbf8','#c9a24a','#f4f0e6'], champagne:['Champagne & gold','#e4d2b0','#c9a24a'], rosegold:['Dusty rose & rose gold','#d6a5a4','#d4a58a'], onyx:['Black & silver','#1d1c1e','#c3c7ce']});
const throneStyleKey = () => { const s = ((state.addons || {}).throne || {}).style; return THRONE_STYLES[s] ? s : 'royal'; };
function throneLabel(){ const c = THRONE_COLORS[((state.addons || {}).throne || {}).color] || THRONE_COLORS.gold; return `${ADDONS.throne.label} · ${THRONE_STYLES[throneStyleKey()].label}, ${c[0].toLowerCase()}`; }

/* 3D materials: velvet with sheen (plain or diamond-tufted), satin and mirror metal, clear acrylic, crystal, natural rattan */
const thGeo = (k, make) => geo('throne-' + k, make);
const TUFT = [.5, .7]; // diamond tufting: button spacing across and row spacing up, in feet
const thTuftTex = () => thGeo('tufttex', () => { const t = canvasTex(256, 256, (x, w) => {
  x.fillStyle = '#a8a8a8'; x.fillRect(0, 0, w, w);
  for(let i = -1; i <= 2; i++) for(let j = -1; j <= 2; j++) [[64 + i*128, j*128], [i*128, 64 + j*128]].forEach(([cx, cy]) => { const g = x.createRadialGradient(cx, cy, 4, cx, cy, 70); g.addColorStop(0, '#ffffff'); g.addColorStop(.6, '#dedede'); g.addColorStop(1, 'rgba(168,168,168,0)'); x.fillStyle = g; x.fillRect(cx - 70, cy - 70, 140, 140); });
  x.strokeStyle = 'rgba(60,60,60,.75)'; x.lineWidth = 2.5; x.beginPath(); for(let k = -2; k <= 4; k++){ x.moveTo(k*128, 0); x.lineTo(k*128 + 256, 256); x.moveTo(k*128, 0); x.lineTo(k*128 - 256, 256); } x.stroke();
  for(let i = 0; i <= 2; i++) for(let j = 0; j <= 2; j++) [[i*128, j*128], [64 + i*128, 64 + j*128]].forEach(([cx, cy]) => { const g = x.createRadialGradient(cx, cy, 0, cx, cy, 16); g.addColorStop(0, 'rgba(40,40,40,1)'); g.addColorStop(1, 'rgba(40,40,40,0)'); x.fillStyle = g; x.fillRect(cx - 16, cy - 16, 32, 32); });
}, true); t.repeat.set(1/(2*TUFT[0]), 1/(2*TUFT[1])); return t; });
function thVelvet(fab, tufted){ return thGeo(`vel-${fab}-${tufted ? 1 : 0}`, () => {
  const m = new THREE.MeshPhysicalMaterial({color:lin(fab), roughness:.95, metalness:0}); m.sheen = lin(shade(fab, lum(fab) < .1 ? .35 : .2));
  const t = tufted ? thTuftTex() : thGeo('velbump', () => { const b = weaveTex('velvet').clone(); b.needsUpdate = true; b.repeat.set(3, 3); return b; });
  if(tufted) m.map = t; m.bumpMap = t; m.bumpScale = tufted ? .05 : .015; return m; }); }
const thRattanImg = () => thGeo('ratimg', () => canvasTex(256, 256, (x, w) => {
  const n = 8, s = w/n, R = rng(23); x.fillStyle = '#4a321b'; x.fillRect(0, 0, w, w);
  for(let i = 0; i < n; i++) for(let j = 0; j < n; j++){ const hz = (i + j) % 2 === 0, x0 = i*s, y0 = j*s;
    for(let k = 0; k < 3; k++){ const l = 56 + R()*10, a = hz ? [x0 + 1, y0 + k*s/3 + 1, s - 2, s/3 - 2] : [x0 + k*s/3 + 1, y0 + 1, s/3 - 2, s - 2], g = hz ? x.createLinearGradient(0, a[1], 0, a[1] + a[3]) : x.createLinearGradient(a[0], 0, a[0] + a[2], 0);
      g.addColorStop(0, `hsl(33,42%,${l - 22}%)`); g.addColorStop(.45, `hsl(36,48%,${l}%)`); g.addColorStop(1, `hsl(32,40%,${l - 26}%)`); x.fillStyle = g; x.fillRect(...a); }
    const e = hz ? x.createLinearGradient(x0, 0, x0 + s, 0) : x.createLinearGradient(0, y0, 0, y0 + s); e.addColorStop(0, 'rgba(30,18,6,.45)'); e.addColorStop(.2, 'rgba(30,18,6,0)'); e.addColorStop(.8, 'rgba(30,18,6,0)'); e.addColorStop(1, 'rgba(30,18,6,.45)'); x.fillStyle = e; x.fillRect(x0, y0, s, s); }
}, true));
function thRattan(rx, ry){ return thGeo(`rat-${rx}-${ry}`, () => { const t = thRattanImg().clone(); t.needsUpdate = true; t.repeat.set(rx, ry); return new THREE.MeshStandardMaterial({map:t, bumpMap:t, bumpScale:.03, roughness:.72, metalness:0, side:THREE.DoubleSide}); }); }
const thAcrylic = () => thGeo('acrylic', () => new THREE.MeshPhysicalMaterial({color:lin('#ffffff'), roughness:.04, metalness:0, clearcoat:1, clearcoatRoughness:.04, transparent:true, opacity:.24, depthWrite:false, envMapIntensity:2.2}));
const thCrystal = () => thGeo('crystal', () => new THREE.MeshStandardMaterial({color:lin('#ffffff'), roughness:.04, metalness:.85, flatShading:true, envMapIntensity:3, emissive:lin('#4a505a')}));
const thGem = () => thGeo('gem', () => new THREE.OctahedronGeometry(1, 0));
function throneKit(colorKey){ // lazy, so a style only builds the materials it uses
  const [, fab, metal, paint] = THRONE_COLORS[colorKey] || THRONE_COLORS.gold, gm = () => std(metal, .3, .85);
  return {frame:() => paint ? std(paint, .42, .04) : gm(), metal:gm, mirror:() => std(metal, .18, 1, {envMapIntensity:2.5}), vel:() => thVelvet(fab, false), tuft:() => thVelvet(fab, true), cane:() => std('#b48a52', .7), ratL:() => thRattan(20, 6), ratF:() => thRattan(26, 9), acr:thAcrylic, crys:thCrystal,
    'i:btn':() => [thGeo('btn', () => new THREE.SphereGeometry(1, 10, 6)), std(shade(fab, -.25), .8)], 'i:gem':() => [thGem(), thCrystal()], 'i:nail':() => [thGeo('nail', () => new THREE.SphereGeometry(1, 8, 4, 0, Math.PI*2, 0, Math.PI/2)), std(metal, .25, .9)]};
}

/* 3D geometry helpers: merge with UVs (one draw call per material), tapered tubes, rounded slabs, tufting lattice, outlines */
function thMerge(list){
  let n = 0; const parts = list.map(([g, m]) => { const x = g.index ? g.toNonIndexed() : g.clone(); if(m) x.applyMatrix4(m); n += x.attributes.position.count; return x; });
  const pos = new Float32Array(n*3), nor = new Float32Array(n*3), uv = new Float32Array(n*2); let o = 0;
  parts.forEach(p => { const c = p.attributes.position.count; pos.set(p.attributes.position.array, o*3); nor.set(p.attributes.normal.array, o*3); if(p.attributes.uv) uv.set(p.attributes.uv.array, o*2); o += c; p.dispose(); });
  const out = new THREE.BufferGeometry(); out.setAttribute('position', new THREE.BufferAttribute(pos, 3)); out.setAttribute('normal', new THREE.BufferAttribute(nor, 3)); out.setAttribute('uv', new THREE.BufferAttribute(uv, 2)); out.computeBoundingSphere(); return out;
}
function thTube(pts, rf, tub = 24, rad = 8, closed = false){
  const c = new THREE.CatmullRomCurve3(pts.map(p => new THREE.Vector3(p[0], p[1], p[2])), closed), g = new THREE.TubeGeometry(c, tub, 1, rad, closed), P = g.attributes.position, v = new THREE.Vector3(), q = new THREE.Vector3();
  for(let i = 0; i <= tub; i++){ c.getPointAt(i/tub, q); const r = typeof rf === 'function' ? rf(i/tub) : rf; for(let j = 0; j <= rad; j++){ const k = i*(rad + 1) + j; v.fromBufferAttribute(P, k).sub(q).multiplyScalar(r).add(q); P.setXYZ(k, v.x, v.y, v.z); } }
  g.computeVertexNormals(); return g;
}
function thRRect(w, h, r){ const s = new THREE.Shape(), x = -w/2, y = -h/2; s.moveTo(x + r, y); s.lineTo(x + w - r, y); s.quadraticCurveTo(x + w, y, x + w, y + r); s.lineTo(x + w, y + h - r); s.quadraticCurveTo(x + w, y + h, x + w - r, y + h); s.lineTo(x + r, y + h); s.quadraticCurveTo(x, y + h, x, y + h - r); s.lineTo(x, y + r); s.quadraticCurveTo(x, y, x + r, y); return s; }
const thExtrude = (shape, depth, bevel, segs = 3) => { const g = new THREE.ExtrudeGeometry(shape, {depth, bevelEnabled:bevel > 0, bevelThickness:bevel, bevelSize:bevel, bevelSegments:segs, curveSegments:24}); g.translate(0, 0, -depth/2); return g; }; // front face at z = -depth/2 - bevel, UVs in feet
const thCushion = (shape, t, b) => thExtrude(shape, t, b).rotateX(-Math.PI/2); // lies flat, centered on y; shape y runs toward -z
const thOval = (a, b) => { const s = new THREE.Shape(); s.absellipse(0, 0, a, b, 0, Math.PI*2, false, 0); return s; };
function thTuftPts(shape, m = .22){ // buttons on the same lattice as the tuft texture, kept m feet inside the outline
  const P = shape.getPoints(36), xs = P.map(p => p.x), ys = P.map(p => p.y), [px, py] = TUFT, out = [];
  const inP = (x, y) => { let c = false; for(let i = 0, j = P.length - 1; i < P.length; j = i++){ const a = P[i], b = P[j]; if((a.y > y) !== (b.y > y) && x < (b.x - a.x)*(y - a.y)/(b.y - a.y) + a.x) c = !c; } return c; };
  const ring = [[0, 0], [m, 0], [-m, 0], [0, m], [0, -m], [m*.7, m*.7], [-m*.7, m*.7], [m*.7, -m*.7], [-m*.7, -m*.7]];
  for(let r = Math.ceil(Math.min(...ys)/(py/2)); r*py/2 <= Math.max(...ys); r++){ const y = r*py/2, off = (r & 1) ? px/2 : 0; for(let x = Math.ceil((Math.min(...xs) - off)/px)*px + off; x <= Math.max(...xs); x += px) if(ring.every(([a, b]) => inP(x + a, y + b))) out.push([x, y]); }
  return out;
}
const thLeg = (k = 1, paw = false) => thGeo(`leg-${k}-${paw ? 1 : 0}`, () => { // cabriole: knee out, slim ankle, scroll toe (or lion paw); top at y 1.42, knee toward +x
  const L = [[thTube([[0, 1.42, 0], [.07, 1.2, 0], [.075, .95, 0], [0, .62, 0], [-.045, .3, 0], [-.02, .1, 0], [.06, .035, 0]], t => k*(t < .2 ? .075 + .125*t : t < .75 ? .1 - (t - .2)*.105 : .042 + (t - .75)*.07), 28, 10)], [SPH, M4(.11*k, 1.17, 0, 0, 0, 0, .045*k, .1*k, .065*k)]];
  if(paw){ L.push([SPH, M4(.08, .075, 0, 0, 0, 0, .15, .085, .14)]); [-.09, -.03, .03, .09].forEach(z => L.push([SPH, M4(.2, .045, z, 0, 0, 0, .05, .045, .045)])); } else L.push([SPH, M4(.07, .03, 0, 0, 0, 0, .085, .035, .07)]);
  return thMerge(L); });
const thLegAt = (k, paw, x, z, sx, sz) => [thLeg(k, paw), M4(x, 0, z, 0, Math.atan2(-sz, sx))]; // knee faces outward (sx, sz)
const thArmPts = (x, h, f, b) => [[x, 1.6, f + .03], [x, 2.15, f - .07], [x, h - .18, f + .03], [x, h - .02, f + .4], [x, h, (f + b)/2 + .2], [x, h - .05, b]];
const thVolute = (r = .09, t = .032) => thGeo(`volute-${r}-${t}`, () => new THREE.TorusGeometry(r, t, 8, 20));
const thScroll = () => thGeo('scroll', () => new THREE.TorusGeometry(.12, .035, 8, 20, Math.PI*1.4));
const thFinial = () => thGeo('finial', () => new THREE.IcosahedronGeometry(1, 0));
function thBaroque(hw, y0, ys, yp){ const s = new THREE.Shape(); s.moveTo(-hw, y0); s.lineTo(-hw, ys); s.bezierCurveTo(-hw, ys + .6, -hw*.84, ys + .9, -hw*.64, ys + .7); s.bezierCurveTo(-hw*.44, ys + .55, -hw*.36, yp - .15, 0, yp); s.bezierCurveTo(hw*.36, yp - .15, hw*.44, ys + .55, hw*.64, ys + .7); s.bezierCurveTo(hw*.84, ys + .9, hw, ys + .6, hw, ys); s.lineTo(hw, y0); s.lineTo(-hw, y0); return s; }
function thHeart(w, h){ const s = new THREE.Shape(), k = w/2; s.moveTo(0, 0); s.bezierCurveTo(-k*.45, h*.25, -k*1.05, h*.45, -k, h*.72); s.bezierCurveTo(-k*.95, h, -k*.35, h*1.07, 0, h*.8); s.bezierCurveTo(k*.35, h*1.07, k*.95, h, k, h*.72); s.bezierCurveTo(k*1.05, h*.45, k*.45, h*.25, 0, 0); return s; }
