function thOgee(hw, y0, ys, yp){ const s = new THREE.Shape(); s.moveTo(-hw, y0); s.lineTo(-hw, ys); s.bezierCurveTo(-hw*.45, ys - .05, -hw*.42, yp - .1, 0, yp); s.bezierCurveTo(hw*.42, yp - .1, hw*.45, ys - .05, hw, ys); s.lineTo(hw, y0); s.lineTo(-hw, y0); return s; }
function thOffset(pts, d){ const cw = THREE.ShapeUtils.isClockWise(pts), n = pts.length, s = cw ? -d : d; return pts.map((p, i) => { const a = pts[(i + n - 1) % n], b = pts[(i + 1) % n], l = Math.hypot(b.x - a.x, b.y - a.y) || 1; return [p.x + (b.y - a.y)/l*s, p.y - (b.x - a.x)/l*s, 0]; }); }

