    let out = bdRect26(g, B.c1) + bdRect26(g, `url(#${id}-folds)`, ' opacity=".9"') + bdRect26(g, `url(#${id}-csh)`);
    out += xs.map(s => `<use href="#${id}-cs${s.v}" x="${r1(x0 + s.x)}" y="${r1(y0 + s.dy)}" color="${tint}"/>`).join('');
    const nsw = Math.max(2, Math.round(B.w/2.6)), sag = Math.min(1.3*u, Hh*.16), sw = W/nsw, bead = (x, y) => `<use href="#${id}-cb" x="${r1(x)}" y="${r1(y)}" color="${tint}"/>`;
    for(let row = 1; row >= 0; row--) for(let i = -row; i < nsw; i++){ const xa = x0 + (i + row*.5)*sw, n = Math.ceil(sw/(.95*k)); for(let j=0;j<=n;j++){ const t = j/n; out += bead(xa + t*sw, y0 + .35*u + row*.4*u + 4*sag*(row ? .7 : 1)*t*(1 - t)); } if(!row && i > 0) for(let j=1;j<=4;j++) out += bead(xa, y0 + .35*u + j*1.05*k*1.15); }
    for(let i=0;i<B.w*B.h*1.3*Math.max(.3, g.dens);i++){ const s = xs[Math.floor(R()*xs.length)]; if(!s) break; const x = x0 + s.x, y = y0 + R()*Hh, z = (.5 + R()*1.1)*k; out += `<circle cx="${r1(x)}" cy="${r1(y)}" r="${r1(z*1.7)}" fill="url(#${id}-spk)"/><path d="M${r1(x)} ${r1(y - z)}L${r1(x + z*.16)} ${r1(y)}L${r1(x)} ${r1(y + z)}L${r1(x - z*.16)} ${r1(y)}ZM${r1(x - z)} ${r1(y)}L${r1(x)} ${r1(y + z*.16)}L${r1(x + z)} ${r1(y)}L${r1(x)} ${r1(y - z*.16)}Z" fill="#fff"/>`; }
    return out;
