    g.defs += `<radialGradient id="${id}-lg"><stop offset="0" stop-color="#fff6d8"/><stop offset=".18" stop-color="#ffd98a" stop-opacity=".85"/><stop offset=".5" stop-color="#ffb84d" stop-opacity=".22"/><stop offset="1" stop-color="#ffb84d" stop-opacity="0"/></radialGradient><radialGradient id="${id}-bk"><stop offset="0" stop-color="#ffe2a6" stop-opacity=".5"/><stop offset=".7" stop-color="#ffe2a6" stop-opacity=".22"/><stop offset="1" stop-color="#ffe2a6" stop-opacity="0"/></radialGradient>`
