    for(let i=0;i<B.w*B.h*.55*Math.max(.3, g.dens);i++) out += `<circle cx="${r1(x0 + R()*W)}" cy="${r1(y0 + R()*Hh)}" r="${r1((1.4 + R()*2.6)*k)}" fill="url(#${id}-bk)" opacity="${r1(.3 + R()*.4)}"/>`;
