      const body = [1, .8, .6, .4].map(f => `<ellipse cx="${r1(sw(.55))}" cy="${r1(-L*.55)}" rx="${r1(w*.85*f)}" ry="${r1(L*.47*f)}" stroke="none" fill-opacity=".2"/>`).join('');
