    let fan = '', ribs = ''; for(let i=0;i<15;i++){ const a = (-160 + i*10)*Math.PI/180, l = (14 + (i%3)*1.5)*k, c = Math.cos(a), s = Math.sin(a), q = (x, y) => `${r1(x*c - y*s)} ${r1(x*s + y*c)}`, fw = .9*k; fan += `M${q(1.2*k, -fw*.3)}Q${q(l*.5, -fw)} ${q(l, 0)}Q${q(l*.5, fw)} ${q(1.2*k, fw*.3)}Z`; ribs += `M${q(1.2*k, 0)}L${q(l*.92, 0)}`; }
