    const palm = () => `<use href="#${id}-pf" transform="translate(${r1(x0 + R()*W)} ${r1(y0 + Hh*(.2 + R()*.75))}) rotate(${r1((R() - .5)*60)}) scale(${r1(.8 + R()*.35)})" fill="${shade(B.c3, (R() - .5)*.1)}" color="${shade(B.c3, -.28)}"/>`;
