    out += list.sort((a, b) => a[5] - b[5]).map(([x, y, a, c, v]) => `<use href="#${id}-pp${v}" transform="translate(${r1(x)} ${r1(y)}) rotate(${r1(a)}) translate(0 ${r1(L*.55)})" fill="${c}" stroke="${c}" color="${shade(c, -.18)}"/>`).join('');
    for(let i=0;i<Math.max(1, Math.round(B.w*B.h/32));i++) out += palm();
