    for(let i=0;i<3;i++){ const p = x0 + W*(.2 + i*.32 + (R() - .5)*.08), bw = W*(.05 + R()*.08); out += `<path d="M${r1(p)} ${y0}h${r1(bw)}L${r1(p + bw - Hh*.6)} ${y0 + Hh}h${r1(-bw)}Z" fill="#fff" fill-opacity="${r1(.05 + R()*.07)}"/>`; }
