  const before = shortUnits(cur), dist = (a, b) => { const p = hexToRgb(a), q = hexToRgb(b); return Math.hypot(p[0] - q[0], p[1] - q[1], p[2] - q[2]); };
  const stockKeys = [...sm.keys()].filter(k => sm.get(k) > 0).map(k => k.split('|'));
  const matches = (L, cat, fab, hex) => cat === 'cloth' ? L.fabric === fab && String(L.cloth).toLowerCase() === hex : cat === 'runner' ? L.runner === fab && String(runnerHex(L) || '').toLowerCase() === hex : cat === 'napkin' ? String(L.napkin).toLowerCase() === hex : cat === 'sash' ? L.sash && String(L.sashColor).toLowerCase() === hex : false;
