    state.room = {w:W, h:H}; const v = venue(); Object.assign(v, {setting:L.setting || Vn.setting, floor:L.floor || Vn.floor, wall:L.wall || v.wall, ceiling:L.ceiling || 'plain', ceilingH:L.ceilingH || v.ceilingH}); if(Vn.city && CITIES[Vn.city]) v.city = Vn.city;
