  if(has('gratin')){ let s = `<g ${sh}><rect x="${cx - 32}" y="${cy - 22}" width="64" height="44" rx="8" fill="#e6bd73"/>`; for(let i = 0; i < 4; i++) s += `<path d="M${cx - 28} ${cy - 12 + i*8}h56" stroke="#f3dca4" stroke-width="2"/>`; return s + pdBlob(rr, cx, cy, 26, 16, 7, ['#b3772f'], 4) + '</g>'; }
  if(has('asparagus')){ let s = `<g ${sh}>`; for(let i = 0; i < 5; i++){ const y = cy - 14 + i*7; s += `<path d="M${cx - 38} ${y + 8}L${cx + 34} ${y - 6}" stroke="#6c9a3c" stroke-width="7" stroke-linecap="round"/><ellipse cx="${cx + 36}" cy="${y - 6.5}" rx="6" ry="4.4" fill="#4c7428" transform="rotate(-11 ${cx + 36} ${y - 6.5})"/>`; } return s + '</g>'; }
  if(has('fries')){ let s = `<g ${sh}>`; for(let i = 0; i < 11; i++){ const x = cx - 26 + rr()*52, y = cy - 18 + rr()*36, a = Math.round(rr()*160 - 80); s += `<rect x="${(x - 3).toFixed(1)}" y="${(y - 22).toFixed(1)}" width="7" height="44" rx="2" fill="${i % 3 ? '#e8b04a' : '#d39a35'}" transform="rotate(${a} ${x.toFixed(1)} ${y.toFixed(1)})"/>`; } return s + '</g>'; }
  if(has('carrot')){ let s = `<g ${sh}>`; for(let i = 0; i < 7; i++){ const x = cx - 20 + rr()*40, y = cy - 10 + rr()*20, a = Math.round(rr()*60 - 30); s += `<rect x="${(x - 4).toFixed(1)}" y="${(y - 20).toFixed(1)}" width="8" height="40" rx="3" fill="#ec8a2f" transform="rotate(${a} ${x.toFixed(1)} ${y.toFixed(1)})"/>`; } return s + '</g>'; }
  if(has('fruit')){ let s = `<g ${sh}>`; for(let i = 0; i < 14; i++){ const a = rr()*Math.PI*2, d = Math.sqrt(rr()), x = cx + Math.cos(a)*26*d, y = cy + Math.sin(a)*20*d; s += `<rect x="${(x - 6).toFixed(1)}" y="${(y - 6).toFixed(1)}" width="12" height="12" rx="3" fill="${['#e44d4d','#f2b33d','#6aaa3a','#7a4fb0','#f28a2e'][i % 5]}" transform="rotate(${Math.round(rr()*90)} ${x.toFixed(1)} ${y.toFixed(1)})"/>`; } return s + '</g>'; }
  if(has('corn')) return `<g ${sh}><ellipse cx="${cx}" cy="${cy}" rx="32" ry="22" fill="#e9c23f"/>${pdBlob(rr, cx, cy, 28, 18, 50, ['#f5d659','#e2b52e'], 3.2)}</g>`;
  if(has('mac')) return `<g ${sh}><ellipse cx="${cx}" cy="${cy}" rx="34" ry="24" fill="#eeb348"/>${pdBlob(rr, cx, cy, 28, 18, 26, ['#f7d27a','#f4c55c'], 4.6)}${pdBlob(rr, cx, cy, 22, 14, 14, ['#b8782f'], 1.8)}</g>`;
  if(has('pilaf') || has('wild rice') || has('quinoa')) return `<g ${sh}><ellipse cx="${cx}" cy="${cy}" rx="34" ry="24" fill="#b88b58"/>${pdBlob(rr, cx, cy, 30, 20, 70, ['#3f3127','#d9b98a','#7a5a3a','#5d8a3a'], 2.6)}</g>`;
  if(has('rice')) return `<g ${sh}><ellipse cx="${cx}" cy="${cy}" rx="34" ry="24" fill="#dd8f48"/>${pdBlob(rr, cx, cy, 30, 20, 60, ['#ecb072','#e9a25e','#6aa23a','#e8692c'], 2.6)}</g>`;
  if(has('bean')) return `<g ${sh}><ellipse cx="${cx}" cy="${cy}" rx="34" ry="24" fill="#6b3f24"/>${pdBlob(rr, cx, cy, 28, 18, 30, ['#a0643a','#8a522e','#5e3420'], 5)}${pdBlob(rr, cx, cy, 24, 14, 8, ['#4c8a2e'], 2.2)}</g>`;
  if(has('veg') || has('broccoli') || has('carrot') || has('squash')){ let s = `<g ${sh}>`; for(let i = 0; i < 13; i++){ const a = rr()*Math.PI*2, d = Math.sqrt(rr()), x = cx + Math.cos(a)*28*d, y = cy + Math.sin(a)*20*d; s += `<rect x="${(x - 7).toFixed(1)}" y="${(y - 5).toFixed(1)}" width="14" height="10" rx="4" fill="${['#e07a2e','#5f8f3a','#c8392f','#e9c46a','#8a5a9a'][i % 5]}" transform="rotate(${Math.round(rr()*180)} ${x.toFixed(1)} ${y.toFixed(1)})"/>`; } return s + '</g>'; }
  const hue = Math.floor(rr()*360); return `<g ${sh}><ellipse cx="${cx}" cy="${cy}" rx="32" ry="22" fill="hsl(${hue} 35% 55%)"/>${pdBlob(rr, cx, cy, 26, 16, 24, [`hsl(${hue} 40% 68%)`, `hsl(${hue} 35% 42%)`], 3)}</g>`;
