/* ---------- prices: sides and garnish belong to each entrée's plate ---------- */
const _pdDinnerCalc = dinnerCalc;
dinnerCalc = function(){ const d = _pdDinnerCalc(), mains = chosenMains(); if(!mains.length || !pdPlated() || d.heavy) return d;   // heavy hors d’oeuvres: no plated mains or sides
  const plateX = mains.reduce((a, o) => a + pdExtras(o.id), 0)/mains.length;
  const was = d.perAdult; d.extras = d.extras.map(([id, p]) => id === 'sides' ? ['sides', plateX] : [id, p]); d.perAdult = (d.avgMain + d.extras.reduce((a, [, p]) => a + p, 0))*d.svc; d.total += (d.perAdult - was)*d.adults; return d; };   // only the adult plate price changes; kids stay priced as the budget prices them
const _pdMenuBudget = menuBudget;
menuBudget = function(add, meals){
  const mc = state.menuChoices; if(!mc || !chosenMains().length) return false; if(!pdPlated()) return _pdMenuBudget(add, meals);
  const svc = (SERVICE_STYLES[mc.service] || SERVICE_STYLES.plated)[1], mains = chosenMains(), plate = o => o.price + pdExtras(o.id), avg = mains.reduce((a, o) => a + plate(o), 0)/mains.length, r2 = v => Math.round(v*100)/100;
  Object.entries(meals).forEach(([m, n]) => { if(m === 'Kids'){ const k = chosen('kids')[0]; add('Catering', 'menu:kids', `Kids’ plate${k ? ': ' + k.name : ''}`, n, 'guest', r2((k ? k.price : 18)*svc)); return; }
    const o = mains.find(x => x.name === m); add('Catering', 'menu:main:' + (o ? o.id : 'unchosen'), o ? `${o.name}${pdSidesText(o.id) ? ' with ' + pdSidesText(o.id) : ''}` : 'Main course, guest hasn’t chosen', n, 'guest', r2((o ? plate(o) : avg)*svc)); });
  const adults = Object.entries(meals).filter(([m]) => m !== 'Kids').reduce((a, [, n]) => a + n, 0);
  ['starter','dessert'].forEach(id => chosen(id).forEach(o => add('Catering', `menu:${id}:${o.id}`, `${o.name} (${catalog.courses.find(c => c.id === id).name.toLowerCase()})`, adults, 'guest', r2(o.price*svc))));
  return true;
};

/* ---------- RSVP: guests pick a soft drink, and see each entrée's sides ---------- */
const _pdOpenRsvp = openRsvp;
openRsvp = async function(eid, gid){
  await _pdOpenRsvp(eid, gid);
  const meal = $('#rs-meal'); if(!meal || !rsvpCtx) return; const plan = rsvpCtx.plan, g = (plan.guests || []).find(x => x.id === gid) || {};
  const saved = state; state = plan; try {
    [...meal.options].forEach(op => { if(op.value === '') return; const name = op.value; op.value = name; const o = chosenMains().find(x => x.name === name); const sd = o && pdSidesText(o.id); if(sd && pdPlated()) op.textContent = `${name} · with ${sd}`; else if(name === 'Kids' && chosen('kids')[0]) op.textContent = `Kids’ meal · ${chosen('kids')[0].name}`; });
    const offered = (plan.menuChoices && plan.menuChoices.drinks) || PD_SOFT_DEFAULT;
    if(offered.length) meal.closest('label').insertAdjacentHTML('afterend', `<label class="fld"><span>Soft drink</span><select id="rs-drink"><option value="">No preference</option>${offered.map(k => `<option value="${k}"${g.drink === k ? ' selected' : ''}>${esc(pdDrinkName(k))}</option>`).join('')}</select></label>`);
  } finally { state = saved; }
};
