let CK = null;
const ckTex = {};
function ckCanvas(key, w, h, draw, color){ if(ckTex[key]) return ckTex[key]; const c = document.createElement('canvas'); c.width = w; c.height = h; draw(c.getContext('2d'), w, h); const t = new THREE.CanvasTexture(c); if(color) t.colorSpace = THREE.SRGBColorSpace; t.wrapS = t.wrapT = THREE.RepeatWrapping; t.anisotropy = 8; ckTex[key] = t; return t; }
