/* any redraw of the cake stage (tab open, a control change) lands here */
const _ckSVG = cakeSVG;
cakeSVG = function(c){ const s = _ckSVG(c); queueMicrotask(() => { const st = document.querySelector('.cake-stage'); if(st && st.querySelector(':scope > svg')) ckMount(); }); return s; };

/* ============ features: client experience: one calm navigation, phone tab bar ============ */
/* In client mode (an event opened from the client link) the team's navigation, tools and internal numbers are replaced by five places:
   Overview, Design, Menu, Guests, Venue. Phones get a fixed bottom tab bar; tablets and desktops get the same five in the header. */
(function(){ const st = document.createElement('style'); st.textContent = `
.cnav{display:none}
body.client-mode .nav-groups,body.client-mode #subnav,body.client-mode #treasure-suite-link,body.client-mode #staff-btn,body.client-mode #portal-save,body.client-mode #undo,body.client-mode #redo,body.client-mode .top-actions .menu,body.client-mode #sample-banner,body.client-mode [data-cact2="shot"],body.client-mode [data-cact2="save"]{display:none!important}
body.client-mode .cnav{display:flex;gap:4px;align-items:center;overflow-x:auto;scrollbar-width:none}
body.client-mode .cnav button{border:0;background:transparent;color:var(--muted);font:500 13.5px var(--body);letter-spacing:.02em;padding:8px 14px;border-radius:999px;display:inline-flex;align-items:center;gap:8px;white-space:nowrap}
body.client-mode .cnav button svg{width:17px;height:17px;flex:none}
body.client-mode .cnav button:hover{color:var(--ink)}
body.client-mode .cnav button[aria-current="page"]{color:var(--ink);background:var(--accent-soft);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--accent) 45%,transparent)}
body.client-mode .cnav-sub{display:flex;gap:6px;grid-column:1/-1;padding:2px 0 0;overflow-x:auto;scrollbar-width:none}
body.client-mode .cnav-sub[hidden]{display:none!important}
body.client-mode .cnav-sub button{border:1px solid var(--line-strong);background:transparent;color:var(--muted);border-radius:999px;padding:5px 13px;font-size:12.5px;white-space:nowrap}
body.client-mode .cnav-sub button[aria-pressed="true"]{border-color:var(--accent);color:var(--ink);background:var(--accent-soft);font-weight:600}
body.client-mode .event-meta input{pointer-events:none}
@media (min-width:761px){body.client-mode .top{grid-template-columns:auto minmax(0,1fr) auto auto}body.client-mode .cnav{order:0;grid-column:auto;border:0;padding:0}body.client-mode .top-actions{order:0}body.client-mode .cnav-sub{order:6}}
@media (min-width:761px) and (max-width:1100px){body.client-mode .cnav button span{display:none}body.client-mode .cnav button{padding:9px 11px}body.client-mode .cnav button[aria-current="page"] span{display:inline}body.client-mode .quick-btn .qlabel{display:none}}
@media (max-width:760px){
  /* compact on a phone, and not sticky: the event, the language switch and help on one row, the sub-tabs under it (about 105 px, not 180),
     and it scrolls away with the page, so a line like "13 invitados · Enviado a su planificador" never slides under it (the tabs at the
     bottom stay) */
  body.client-mode .top{grid-template-columns:auto minmax(0,1fr) auto;gap:6px 10px;padding:8px 16px 10px;position:relative;z-index:20}
  body.client-mode .top>.brand{grid-column:1;grid-row:1;align-self:center}body.client-mode .top>.event-meta{grid-column:2;grid-row:1}
  body.client-mode .top>.top-actions{grid-column:3;grid-row:1;align-self:center}body.client-mode .top>.cnav-sub{grid-column:1/-1;grid-row:2}
  body.client-mode .top>.event-meta{flex-flow:row wrap;align-items:baseline;column-gap:6px;row-gap:0}body.client-mode .top>.event-meta #ev-name{flex:1 1 100%;min-width:0}
  body.client-mode .top>.event-meta #ev-date-cl{flex:none}body.client-mode .top>.event-meta #ev-date-cl.dot::after{content:"·";margin-left:6px}body.client-mode .top>.event-meta #ev-venue{flex:1 1 60px;min-width:0;width:auto}
  body.client-mode .brand{padding-right:0;border:0}body.client-mode .brand-name{display:none}
  body.client-mode .event-meta{grid-column:auto;order:0}body.client-mode #ev-name{font-size:19px}body.client-mode #ev-date,body.client-mode #ev-venue{font-size:11px}
  body.client-mode .quick-btn{display:none!important}
  body.client-mode .cnav{position:fixed;left:0;right:0;bottom:0;z-index:40;display:grid;grid-template-columns:repeat(5,1fr);gap:0;padding:6px 6px calc(6px + env(safe-area-inset-bottom,0px));background:color-mix(in srgb,var(--surface) 88%,transparent);backdrop-filter:blur(16px);-webkit-backdrop-filter:blur(16px);border-top:1px solid var(--line);box-shadow:0 -10px 30px -18px rgba(0,0,0,.45)}
  body.client-mode .cnav button{flex-direction:column;gap:4px;font-size:10.5px;padding:7px 2px;border-radius:14px;min-height:52px;justify-content:center}
  body.client-mode .cnav button svg{width:22px;height:22px}
  body.client-mode .cnav button[aria-current="page"]{box-shadow:none;color:var(--accent)}
  body.client-mode main{padding-bottom:calc(76px + env(safe-area-inset-bottom,0px))}
  body.client-mode .toast{bottom:calc(84px + env(safe-area-inset-bottom,0px))}
}
`; document.head.appendChild(st); })();
