function cnSync(){ if(!clientMode) return; const sec = (CN_ITEMS.find(([, , vs]) => vs.includes(currentView)) || [''])[0];
  document.querySelectorAll('[data-cnav]').forEach(b => b.toggleAttribute('aria-current', false) || (b.dataset.cnav === sec && b.setAttribute('aria-current', 'page')));
  const sub = $('#cnav-sub'); if(sub){ sub.hidden = sec !== 'design'; sub.querySelectorAll('[data-cnsub]').forEach(b => b.setAttribute('aria-pressed', b.dataset.cnsub === currentView)); }
  ['ev-name','ev-date','ev-venue'].forEach(id => { const i = $('#' + id); if(i) i.readOnly = true; }); }
const _cnSwitch = switchView;
