  if(['satin','lace','linenRunner'].includes(L.runner) && !box.querySelector('[data-k="runnerColor"]')){ if(!L.runnerColor) L.runnerColor = '#f3ecdc'; box.querySelector('.chips').insertAdjacentHTML('afterend', swatches('runnerColor', LN_PAL, L, {custom:true})); }
