/* ---------- deeper folds, and runners that fall to the floor ---------- */
skirtGeo = function(rTop, rBot, h, folds){ return geo(`skirt2${rTop},${rBot},${h},${folds}`, () => { const g = new THREE.CylinderGeometry(rTop, rBot + (h > 2 ? .06 : 0), h, 160, 10, true), p = g.attributes.position;
  for(let i = 0; i < p.count; i++){ const x = p.getX(i), y = p.getY(i), z = p.getZ(i), t = (h/2 - y)/h, a = Math.atan2(z, x), r = Math.hypot(x, z) + (.11*Math.sin(a*folds) + .045*Math.sin(a*folds*2.3 + 1.1) + .02*Math.sin(a*folds*5.1))*Math.pow(t, .8); p.setXYZ(i, Math.cos(a)*r, y, Math.sin(a)*r); } g.computeVertexNormals(); return g; }); };
