  const urn = new THREE.Mesh(geo('urn', () => new THREE.LatheGeometry([[0, 0], [.26, 0], [.28, .04], [.12, .1], [.09, .24], [.18, .3], [.42, .48], [.46, .56], [0, .56]].map(([a, b]) => new THREE.Vector2(a, b)), 40)), gold); urn.castShadow = true; cp.add(urn);
  const top = .56;
  /* hydrangea balls: many tiny florets on a sphere */
  const hyd = new THREE.InstancedMesh(geo('floret4', () => { const pts = []; for(let k = 0; k < 4; k++){ const a = k*Math.PI/2; const sh = new THREE.Shape(); sh.moveTo(0, 0); sh.quadraticCurveTo(Math.cos(a - .5)*.07, Math.sin(a - .5)*.07, Math.cos(a)*.075, Math.sin(a)*.075); sh.quadraticCurveTo(Math.cos(a + .5)*.07, Math.sin(a + .5)*.07, 0, 0); pts.push(sh); } return new THREE.ShapeGeometry(pts, 4); }), std(L.flower2 || '#fbfaf6', .7, 0, {side:THREE.DoubleSide}), 5*120), dmy = new THREE.Object3D(); let n = 0;
