  for(let i = 0; i < 26; i++){ const a = R()*Math.PI*2, d = Math.sqrt(R())*.85, y = top + .45 + .55*Math.sqrt(Math.max(0, 1 - (d/.95)**2)); bloom(Math.cos(a)*d, y, Math.sin(a)*d, .17 + R()*.06, i % 3 === 2 ? f2 : f1); }
  /* tall spikes (delphinium, orchid sprays or pampas, by color) */
  /* accents v2 */ const accent = L.accent || 'delphinium';
  if(accent === 'orchid' || accent === 'calla') ckAccent69(cp, L, top, R, accent);
  const spikeCol = L.flower3 || '#6f8fcf', spike = new THREE.InstancedMesh(geo('floret3', () => { const g = new THREE.SphereGeometry(.05, 6, 4); g.scale(1, .55, 1); return g; }), std(spikeCol, .72), 8*34), stem = std('#58703f', .8); n = 0;
  for(let k = 0; k < (accent === 'delphinium' || accent === 'pampas' ? 8 : 0); k++){ const a = k/8*Math.PI*2 + R()*.4, lean = .22 + R()*.25, len = .6 + R()*.45, bx = Math.cos(a)*.35, bz = Math.sin(a)*.35, by = top + .75;
    const st2 = new THREE.Mesh(geo('stem', () => new THREE.CylinderGeometry(.012, .016, 1, 5)), stem); st2.scale.y = len; st2.position.set(bx + Math.cos(a)*lean*len/2, by + len/2, bz + Math.sin(a)*lean*len/2); st2.lookAt(bx + Math.cos(a)*lean*len, by + len, bz + Math.sin(a)*lean*len); st2.rotateX(Math.PI/2); cp.add(st2);
    for(let i = 0; i < 34; i++){ const t = .3 + .7*i/33, ang = i*2.4; dmy.position.set(bx + Math.cos(a)*lean*len*t + Math.cos(ang)*.045*(1.2 - t), by + len*t, bz + Math.sin(a)*lean*len*t + Math.sin(ang)*.045*(1.2 - t)); dmy.scale.setScalar(1.25 - .75*t); dmy.rotation.set(R()*3, R()*3, 0); dmy.updateMatrix(); spike.setMatrixAt(n++, dmy.matrix); } }
