  if(s[0] === 'plans' && s.length === 2) return {kind:'plan', id:s[1], table:'plans'};
  if(s[0] === 'templates' && s.length === 2) return {kind:'cat', key:'template:' + s[1], table:'catalog'};
  if(s[0] === 'catalog' && s.length === 2) return {kind:'cat', key:s[1], table:'catalog'};
