  let docs = rows.map(r => ({id:r.key.slice(prefix.length), data:r.data})); if(Q.order){ const [f, dir] = Q.order; docs.sort((a, b) => ((a.data || {})[f] > (b.data || {})[f] ? 1 : -1)*(dir === 'desc' ? -1 : 1)); }
