      const dt = swDate(R.date), ttl = swName(R.title);
      let d = (R.invoiceNo && one(idx.invoice.get(swName(R.invoiceNo)))) || (ttl && one(idx.title.get(ttl))) || null;
      if(!d){ const c = (em.v && idx.email.get(em.v)) || (swPhoneKey(phone) && idx.phone.get(swPhoneKey(phone))) || (name && idx.name.get(swName(name))) || [];
        const c2 = dt.v ? c.filter(x => x.date === dt.v) : c; d = one(c2) || (c2.length > 1 ? null : one(c)); }
      const kindWord = f.kind === 'invoices' ? 'invoice' : 'payment', what = [R.invoiceNo ? '#' + R.invoiceNo : '', R.label || '', R.title || name].filter(Boolean).join(' · ');
