  m.innerHTML = `<div class="modal-card swi-card" role="dialog" aria-modal="true" aria-labelledby="swi-title">${swiBody()}</div>`; m.hidden = false; m.dataset.step = SWI.step + (SWI.undo ? 'u' : '');
