  SWI.res = swBuild(SWI.files, Object.assign({today:isoLocal(), existing:SWI.existing, existingContacts:SWI.contacts, importedKeys:swiKeys(), have:swiTypes(), typeLabels:EVENT_TYPES, uid}, SWI.opts));
