const swiCompact = lines => lines.slice(0, 4000).map(L => [L.outcome, L.file, L.row, L.kind, String(L.what).slice(0, 120), String(L.why).slice(0, 200)]);
const swiLines = c => (c || []).map(([outcome, file, row, kind, what, why]) => ({outcome, file, row, kind, what, why}));
