  const b = t.closest('button'); if(!b || b.disabled) return; const d = b.dataset;
  if(d.swclose != null){ swiClose(); if(d.swclose === 'events' && typeof switchView === 'function') switchView('events'); return; }
  if(d.swgo){ SWI.err = ''; if(d.swgo === 'check') swiCheck(); else { SWI.step = d.swgo; swiRender(); } return; }
