  if(d.swmap){ const [i, c] = d.swmap.split(':').map(Number), f = SWI.files[i]; if(!f) return; const was = t.value !== 'skip' ? f.map.findIndex((x, j) => x === t.value && j !== c) : -1;
    if(was >= 0){ f.map[was] = 'skip'; f.note = `“${f.headers[was] || `Column ${was + 1}`}” was set to Leave out, since “${f.headers[c] || `Column ${c + 1}`}” now goes into ${SW_FIELDS[t.value]}.`; } else f.note = '';
    f.map[c] = t.value; f.touched = [...new Set((f.touched || []).concat(c, was >= 0 ? [was] : []))]; SWI.res = null; SWI.opts.payTo = {}; swiRender(); return; }
