const CI_TPL_ES = 'Hola {first}, te invitamos a {event} el {date} en {venue}. Por favor confirma tu asistencia antes del {rsvpBy}: {rsvpLink}';
const ciMsgEs = () => invite().lang === 'es' || (invite().lang === 'bi' && ciEs());   /* a bilingual invitation's message is in the client's language (UX audit 2026-10-28) */
