/* ============ features: dietary and allergy check ============ */
/* Reads each attending guest's diet tags and free-text note ("severe peanut allergy", "vegan", "no pork") and checks them against the chosen dinner,
   the hors d'oeuvres and the cake: a vegan guest with no vegan main, shellfish on the pass with a shellfish allergy, nuts in a cake flavor, a guest
   whose chosen meal doesn't suit them. Shown at the top of the Food views when something needs a look; the planner can mark an item as handled. */
const ALLERGEN80 = {
  NF:{label:'nut allergy', re:/\b(nut|nuts|peanut|almond|pecan|walnut|pistachio|cashew|hazelnut|praline|pesto|marzipan|macadamia)/i},
  SF:{label:'shellfish allergy', re:/\b(shrimp|crab|lobster|scallop|prawn|oyster|clam|mussel|shellfish)/i},
  FISH:{label:'fish allergy', re:/\b(salmon|tuna|branzino|cod|halibut|fish|anchov|caesar|sea bass)/i},
  PORK:{label:'no pork', re:/\b(pork|pernil|bacon|ham|prosciutto|chorizo|carnitas|pancetta)/i},
  EGG:{label:'egg allergy', re:/\b(egg|aioli|mayo|meringue|custard|tiramisu|cheesecake|blini)/i},
};
function needs80(g){ const t = new Set(g.dietTags || []), s = String(g.diet || '').toLowerCase();
  if(/vegan|plant[- ]based/.test(s)) t.add('VG'); if(/vegetarian|veggie|no meat/.test(s)) t.add('V'); if(/gluten|celiac|coeliac/.test(s)) t.add('GF'); if(/dairy|lactose|milk/.test(s)) t.add('DF');
  if(/nut|peanut|almond|pecan|walnut|pistachio|cashew/.test(s)) t.add('NF'); if(/shellfish|shrimp|crab|lobster|prawn/.test(s)) t.add('SF'); if(/\bfish\b|seafood|pescat.*allerg/.test(s)) t.add('FISH');
  if(/halal|no pork|pork[- ]free|don.?t eat pork/.test(s)) t.add('PORK'); if(t.has('Halal') || t.has('Kosher')) t.add('PORK'); if(/\begg/.test(s)) t.add('EGG'); if(t.has('VG')){ t.add('V'); t.add('DF'); }
  return t; }
const fits80 = (dish, tag) => { const d = ' ' + (dish.diet || '') + ' '; if(tag === 'V') return / VG? /.test(d) || /\bVG\b/.test(d); if(tag === 'VG') return /\bVG\b/.test(d); if(tag === 'GF') return /\bGF\b/.test(d); if(tag === 'DF') return /\bDF\b/.test(d) || /\bVG\b/.test(d); return true; };
const TAGNAME80 = {V:'vegetarian', VG:'vegan', GF:'gluten-free', DF:'dairy-free'};
function picked80(){ const mc = state.menuChoices || {picks:{}}, out = [];
  (catalog.courses || []).forEach(c => ((mc.picks || {})[c.id] || []).forEach(id => { const o = (c.options || []).find(x => x.id === id); if(o) out.push({course:c.id, courseName:c.name, name:o.name, desc:o.desc || '', diet:o.diet || ''}); }));
  return out; }
function dietIssues80(){ const coming = (state.guests || []).filter(g => g.rsvp !== 'no'), N = coming.map(g => ({g, t:needs80(g)})).filter(x => x.t.size); if(!N.length) return [];
  const dishes = picked80(), mains = dishes.filter(d => /main|entr/i.test(d.course + ' ' + d.courseName)), out = [], H = state.hors && Array.isArray(state.hors.items) ? state.hors.items.map(k => HORS[k] && {name:HORS[k][0], diet:HORS[k][2] || ''}).filter(Boolean) : [];
  const flavors = (((state.cake || {}).tiers) || []).map(t => t.flavor).filter(Boolean), who = L => L.slice(0, 4).map(x => x.g.name).join(', ') + (L.length > 4 ? ` and ${L.length - 4} more` : '');
  /* a main for every preference */
  if(mains.length) for(const tag of ['VG', 'V', 'GF', 'DF']){ const L = N.filter(x => x.t.has(tag) && !((tag === 'V' || tag === 'DF') && x.t.has('VG'))); if(!L.length || mains.some(m => fits80(m, tag))) continue;
    const alt = ((catalog.courses || []).find(c => /main|entr/i.test(c.id + ' ' + c.name)) || {options:[]}).options.filter(o => fits80(o, tag)).slice(0, 2).map(o => o.name);
    out.push({key:'main-' + tag, sev:'warn', text:`${L.length} ${TAGNAME80[tag]} guest${L.length > 1 ? 's' : ''} (${who(L)}) and no ${TAGNAME80[tag]} main is picked.`, fix:alt.length ? `Add ${alt.join(' or ')}, or arrange a special plate with the kitchen.` : 'Arrange a special plate with the kitchen.'}); }
  /* allergens on the menu */
  const all = dishes.map(d => ({what:d.name, text:d.name + ' ' + d.desc, where:'dinner'})).concat(H.map(h => ({what:h.name, text:h.name, where:'hors d’oeuvres'})), flavors.map(f => ({what:f + ' cake', text:f, where:'cake'})));
  for(const [k, A] of Object.entries(ALLERGEN80)){ const L = N.filter(x => x.t.has(k)); if(!L.length) continue; const hits = all.filter(d => A.re.test(d.text) || (k === 'NF' && /pistachio|almond/i.test(d.text))); if(!hits.length) continue;
    out.push({key:'al-' + k + '-' + hits.map(h => h.what).join('|'), sev:k === 'PORK' ? 'caution' : 'warn', text:`${L.length} guest${L.length > 1 ? 's' : ''} ${k === 'PORK' ? (L.length > 1 ? 'who don’t eat pork' : 'who doesn’t eat pork') : 'with a ' + A.label} (${who(L)}). On the menu: ${hits.map(h => `${h.what} (${h.where})`).join(', ')}.`, fix:k === 'PORK' ? 'Make sure they have another option and label it at the buffet or tell their server.' : 'Tell the caterer by name and table, and have servers skip these guests with those items.'}); }
  /* cake for gluten- or dairy-free guests */
  if(flavors.length) for(const tag of ['GF', 'DF', 'VG']){ const L = N.filter(x => x.t.has(tag) && !(tag === 'DF' && x.t.has('VG'))); if(!L.length) continue; out.push({key:'cake-' + tag, sev:'caution', text:`${L.length} ${TAGNAME80[tag]} guest${L.length > 1 ? 's' : ''} (${who(L)}) and a standard cake.`, fix:`Ask the baker for a ${TAGNAME80[tag]} tier or a few ${TAGNAME80[tag]} cupcakes.`}); }
  /* chosen meals that don't suit the guest */
  const byName = new Map(); (catalog.courses || []).forEach(c => (c.options || []).forEach(o => byName.set(o.name.toLowerCase(), o)));
  const bad = N.filter(x => { const m = x.g.meal && byName.get(String(x.g.meal).toLowerCase()); if(!m) return false; return ['VG', 'V', 'GF', 'DF'].some(t => x.t.has(t) && !fits80(m, t)) || ['NF', 'SF', 'FISH', 'PORK'].some(k => x.t.has(k) && ALLERGEN80[k].re.test(m.name + ' ' + (m.desc || ''))); });
  if(bad.length) out.push({key:'meal-' + bad.map(x => x.g.id).join('|'), sev:'warn', text:`${bad.length} guest${bad.length > 1 ? 's' : ''} chose a meal that doesn’t suit their diet: ${bad.slice(0, 4).map(x => `${x.g.name} (${x.g.meal})`).join(', ')}${bad.length > 4 ? '…' : ''}.`, fix:'Confirm with them, or change their meal in Guests.'});
  const done = (state.dietOk80 || {}); return out.filter(i => !done[i.key]); }
function dietCardHTML80(){ if(clientMode) return ''; const I = dietIssues80(); if(!I.length) return '';
  return `<div class="inv-card diet80"><div class="diet80-h"><span class="eyebrow">Dietary &amp; allergy check</span><span class="pill ${I.some(i => i.sev === 'warn') ? 'warn' : 'caution'}">${I.length} to review</span></div>
    ${(() => { const li = i => `<li class="${i.sev}"><b>${esc(i.text)}</b><span>${esc(i.fix)}</span><button class="btn sm" data-diet80="${esc(i.key)}">Handled</button></li>`, top = I.slice(0, 3), rest = I.slice(3); return `<ul>${top.map(li).join('')}</ul>${rest.length ? `<details class="diet80-more"><summary>Show ${rest.length} more</summary><ul>${rest.map(li).join('')}</ul></details>` : ''}`; })()}</div>`; }
const _rm80 = renderMenu;
renderMenu = function(){ const r = _rm80.apply(this, arguments); if(['dinner', 'hors', 'cake', 'gmeals'].includes(menuTab)){ const h = dietCardHTML80(), seg = document.querySelector('#menu-controls .seg'); if(h && seg) seg.insertAdjacentHTML('afterend', h); } return r; };
document.addEventListener('click', e => { const b = e.target.closest('[data-diet80]'); if(!b) return; mutate(() => { (state.dietOk80 ||= {})[b.dataset.diet80] = Date.now(); }); renderMenu(); toast('Marked as handled'); });
(function(){ const st = document.createElement('style'); st.textContent = `
.diet80{display:grid;gap:8px;margin:0 0 14px}.diet80-h{display:flex;justify-content:space-between;align-items:center;gap:8px}.diet80-more summary{cursor:pointer;font-size:12.5px;color:var(--accent);margin:2px 0 6px}.diet80 ul{margin:0;padding:0;list-style:none;display:grid;gap:8px}
.diet80 li{display:grid;grid-template-columns:1fr auto;gap:2px 10px;padding:9px 11px;border-radius:12px;border:1px solid var(--line);border-left:3px solid var(--caution, #d99a2b)}.diet80 li.warn{border-left-color:var(--warn)}
.diet80 li b{font-weight:600;font-size:13px}.diet80 li span{grid-column:1;font-size:12.5px;color:var(--muted)}.diet80 li .btn{grid-column:2;grid-row:1 / span 2;align-self:center}`; document.head.appendChild(st); })();

/* ============ features: dialogs and notices that work for everyone ============ */
/* Dialogs (.modal): focus moves into a dialog when it opens, Tab stays inside it, Escape closes it with its own Close/Cancel button, and focus goes
   back to what you were on. Notices stay up long enough to read (longer for longer text), pause while hovered or focused, and an edit's notice
   offers Undo. */
const FOCUSABLE81 = 'a[href],button:not([disabled]),input:not([disabled]):not([type=hidden]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])';
const shown81 = el => el && !el.hidden && el.offsetParent !== null;
const openModals81 = () => [...document.querySelectorAll('.modal')].filter(shown81);
const back81 = new WeakMap(); let outside81 = null;
document.addEventListener('focusin', e => { if(!e.target.closest || !e.target.closest('.modal')) outside81 = e.target; }, true);
function onShow81(m){ if(back81.has(m)) return; back81.set(m, document.activeElement && !m.contains(document.activeElement) ? document.activeElement : outside81); const card = m.querySelector('[role=dialog]') || m; if(!card.getAttribute('role')){ card.setAttribute('role', 'dialog'); card.setAttribute('aria-modal', 'true'); }
  setTimeout(() => { if(m.contains(document.activeElement)) return; const f = m.querySelector('input:not([type=hidden]):not([disabled]),textarea:not([disabled]),select:not([disabled])') || m.querySelector('.btn.primary,button.primary') || m.querySelector(FOCUSABLE81); if(f) try { f.focus({preventScroll:true}); } catch(e){} }, 30); }
function onHide81(m){ const b = back81.get(m); back81.delete(m); if(b && b.isConnected && !openModals81().length) setTimeout(() => { try { b.focus({preventScroll:true}); } catch(e){} }, 0); }
new MutationObserver(list => { for(const r of list){ const els = r.type === 'attributes' ? [r.target] : [...r.addedNodes].filter(n => n.nodeType === 1);
  for(const el of els){ const ms = el.classList && el.classList.contains('modal') ? [el] : el.querySelectorAll ? [...el.querySelectorAll('.modal')] : []; ms.forEach(m => m.hidden ? onHide81(m) : onShow81(m)); } } })
  .observe(document.body, {subtree:true, childList:true, attributes:true, attributeFilter:['hidden']});
function closeBtn81(m){ return m.querySelector('[id$="-cancel"],[id$="cancel"],[data-close],[data-vpclose],.modal-x,[aria-label="Close"]') || [...m.querySelectorAll('button')].find(b => /^(close|cancel|not now|done|×)$/i.test(b.textContent.trim())); }
window.addEventListener('keydown', e => { const ms = openModals81(); if(!ms.length) return; const m = ms[ms.length - 1];
  if(e.key === 'Escape' && !e.defaultPrevented){ const b = closeBtn81(m); e.preventDefault(); e.stopImmediatePropagation(); if(b) b.click(); else m.hidden = true; return; }
  if(e.key === 'Tab'){ const f = [...m.querySelectorAll(FOCUSABLE81)].filter(x => x.offsetParent !== null); if(!f.length) return; const first = f[0], last = f[f.length - 1];
    if(!m.contains(document.activeElement)){ e.preventDefault(); first.focus(); } else if(e.shiftKey && document.activeElement === first){ e.preventDefault(); last.focus(); } else if(!e.shiftKey && document.activeElement === last){ e.preventDefault(); first.focus(); } } }, true);
