let lastEdit81 = 0, toastHold81 = false;
const _pu81 = pushUndo; pushUndo = function(){ lastEdit81 = Date.now(); return _pu81.apply(this, arguments); };
const _toast81 = toast;
toast = function(msg){ const r = _toast81.apply(this, arguments), t = $('#toast'); if(!t) return r; const text = String(msg ?? '');
  const canUndo = Date.now() - lastEdit81 < 700 && undoStack.length && !/undone|undo|…|\.\.\.|couldn|can’t|can't|isn’t|failed|error|copied|rendering|loading|saving|saved to|offline|reconnect|first\b|choose|remove one|not allowed|need/i.test(text) && !clientMode;
  if(canUndo){ const b = document.createElement('button'); b.className = 'toast-undo81'; b.type = 'button'; b.textContent = 'Undo'; b.onclick = () => { undo(); t.hidden = true; _toast81('Undone'); }; t.appendChild(b); }
  clearTimeout(toastT); const ms = Math.min(9000, Math.max(3200, text.length*55)) + (canUndo ? 2500 : 0);
  const hide = () => { if(toastHold81) { toastT = setTimeout(hide, 800); return; } t.hidden = true; }; toastT = setTimeout(hide, ms); return r; };
(function(){ const t = $('#toast'); if(!t) return; t.addEventListener('pointerenter', () => toastHold81 = true); t.addEventListener('pointerleave', () => toastHold81 = false); t.addEventListener('focusin', () => toastHold81 = true); t.addEventListener('focusout', () => toastHold81 = false);
  const st = document.createElement('style'); st.textContent = `#toast{pointer-events:auto}.toast-undo81{margin-left:12px;border:0;background:none;color:inherit;font:inherit;font-weight:700;text-decoration:underline;text-underline-offset:3px;cursor:pointer;padding:4px 2px;min-height:32px}`; document.head.appendChild(st); })();

/* ============ features: run-of-show checks ============ */
/* A short list above the run of show: someone booked in two places at once, long stretches with nothing happening once guests are there, setup still
   running when guests arrive, teardown starting before the party ends, and moments with nobody responsible. Times after midnight count as late night. */
const GROUP82 = /^(all|everyone|guests|staff|team|venue team|coordinator)$/i;
const people82 = x => String(x.who || '').split(/\s*(?:,|&|\band\b|\s\/\s)\s*/i).map(s => s.trim()).filter(s => s && !GROUP82.test(s));
const isGuest82 = x => x.type === 'ceremony' || x.type === 'reception' || /guest|arriv|cocktail|ceremony|reception/i.test(x.title || '');
const isTear82 = x => /tear ?down|strike|pick ?up|load ?out|clean ?up/i.test(x.title || '');
function rosIssues82(){ const tl = tlByLate().map(x => ({x, s:lm(x.time), e:lm(x.time) + (+x.dur || 0)})), out = []; if(tl.length < 2) return out;
  const t12 = m => fmt12(fromMin(m));
  /* double-booked: the same person in two overlapping moments in different places, or two long overlapping moments */
  const seen = new Set();
  for(let i = 0; i < tl.length; i++) for(let j = i + 1; j < tl.length; j++){ const a = tl[i], b = tl[j], ov = Math.min(a.e, b.e) - Math.max(a.s, b.s); if(ov <= 0) continue;
    const both = people82(a.x).filter(p => people82(b.x).some(q => q.toLowerCase() === p.toLowerCase())); if(!both.length) continue;
    const places = a.x.where && b.x.where && a.x.where.trim().toLowerCase() !== b.x.where.trim().toLowerCase(), long = (+a.x.dur || 0) >= 30 && (+b.x.dur || 0) >= 30 && ov >= 15;
    if(!places && !long) continue; const key = 'dbl-' + a.x.id + '-' + b.x.id; if(seen.has(key)) continue; seen.add(key);
    out.push({key, sev:'warn', text:`${both.join(', ')} ${both.length > 1 ? 'are' : 'is'} booked twice: “${a.x.title}” (${t12(a.s)}) and “${b.x.title}” (${t12(b.s)}) overlap by ${ov} min${places ? `, in ${a.x.where} and ${b.x.where}` : ''}.`, fix:'Move one, shorten it, or give it to someone else.'}); }
  /* guests waiting: after the first guest moment, gaps of 40 minutes or more until the last one ends */
  const g0 = tl.find(t => isGuest82(t.x)), gEnd = Math.max(...tl.filter(t => isGuest82(t.x) && !isTear82(t.x)).map(t => t.e));
  if(g0){ let cover = g0.e; for(const t of tl.filter(t => t.s >= g0.s && !isTear82(t.x) && t.s < gEnd)){ if(t.s - cover >= 40) out.push({key:'gap-' + cover + '-' + t.s, sev:'caution', text:`Nothing is scheduled from ${t12(cover)} to ${t12(t.s)} (${t.s - cover} min) while guests are there.`, fix:'Stretch the moment before, or add something (a toast, a set, a game, dessert).'}); cover = Math.max(cover, t.e); } }
  /* setup still going when guests arrive; teardown before the party ends */
  if(g0) tl.filter(t => t.x.type === 'vendor' && !isTear82(t.x) && t.s < g0.s && t.e > g0.s).forEach(t => out.push({key:'setup-' + t.x.id, sev:'warn', text:`“${t.x.title}” runs until ${t12(t.e)}, after guests arrive at ${t12(g0.s)}.`, fix:'Start it earlier or shorten it so the room is ready.'}));
  if(isFinite(gEnd)) tl.filter(t => isTear82(t.x) && t.s < gEnd).forEach(t => out.push({key:'tear-' + t.x.id, sev:'warn', text:`“${t.x.title}” starts at ${t12(t.s)}, before the last guest moment ends at ${t12(gEnd)}.`, fix:'Start teardown after the send-off.'}));
  /* nobody responsible */
  const none = tl.filter(t => !String(t.x.who || '').trim()); if(none.length) out.push({key:'who-' + none.map(t => t.x.id).join('|'), sev:'caution', text:`${none.length} moment${none.length > 1 ? 's have' : ' has'} no one in charge: ${none.slice(0, 3).map(t => '“' + t.x.title + '”').join(', ')}${none.length > 3 ? '…' : ''}.`, fix:'Add who runs each one so staff sheets and vendor sheets include it.'});
  const ok = state.rosOk82 || {}; return out.filter(i => !ok[i.key]); }
function rosCardHTML82(){ if(clientMode) return ''; const I = rosIssues82(); if(!I.length) return (state.timeline || []).length > 2 ? '<p class="ros82-ok">Run of show checked: no overlaps, gaps or setup clashes.</p>' : '';
  return `<div class="inv-card ros82"><div class="ros82-h"><span class="eyebrow">Run-of-show check</span><span class="pill ${I.some(i => i.sev === 'warn') ? 'warn' : 'caution'}">${I.length} to review</span></div><ul>${I.map(i => `<li class="${i.sev}"><b>${esc(i.text)}</b><span>${esc(i.fix)}</span><button class="btn sm" data-ros82="${esc(i.key)}">Fine as is</button></li>`).join('')}</ul></div>`; }
const _rpl82 = renderPlanning;
renderPlanning = function(){ const r = _rpl82.apply(this, arguments); if(planTab === 'show'){ const at = document.querySelector('#planning .tl-list'), h = rosCardHTML82(); if(at && h) at.insertAdjacentHTML('beforebegin', h); } return r; };
document.addEventListener('click', e => { const b = e.target.closest('[data-ros82]'); if(!b) return; mutate(() => { (state.rosOk82 ||= {})[b.dataset.ros82] = Date.now(); }); const y = $('#view-plan').scrollTop; renderPlanning(); $('#view-plan').scrollTop = y; });
