  const focus = state.items.find(x => spaceOf(x) === activeSpace && x.kind === 'fixture' && x.type === 'dance') || state.items.find(x => spaceOf(x) === activeSpace && x.type === 'sweet') || {x:W/2, y:H/2};
  let fx = focus.x - W/2, fz = focus.y - H/2; const ex = eye.x - W/2, ez = eye.y - H/2; if(Math.hypot(fx - ex, fz - ez) < 4){ fx = t.x - W/2; fz = t.y - H/2; }
  const ty = 3.2, vx = ex - fx, vy = 3.9 - ty, vz = ez - fz, r = Math.hypot(vx, vy, vz);
  V.spin = false; const to = {theta:Math.atan2(vx, vz), phi:Math.acos(Math.max(-1, Math.min(1, vy/r))), r, tx:fx, ty, tz:fz}, from = Object.assign({}, V.orbit); let dt = to.theta - from.theta; dt = ((dt + Math.PI) % (Math.PI*2) + Math.PI*2) % (Math.PI*2) - Math.PI; to.theta = from.theta + dt;
