/* ============ features: room clashes ============ */
/* Two events in the same room on the same day, at overlapping times (or with no times yet), are flagged: on the calendar day, under the calendar,
   and in the open event's follow-ups. Event summaries now carry roomKey (venue + room, or the venue name) and span (first to last moment of the
   run of show, in minutes, after-midnight aware). Inquiries count as soft holds; cancelled and archived events never clash. */
const roomKey98 = () => { const v = String((state.event || {}).venue || '').trim(); if(state.venueId) return `${state.venueId}|${state.venueRoomId || ''}`; return v && !/^(venue|tbd|tba)$/i.test(v) ? 'name|' + v.toLowerCase().replace(/\s+/g, ' ') : ''; };
function span98(){ const tl = (state.timeline || []).filter(x => x.time); if(!tl.length) return null; const s = Math.min(...tl.map(x => lm(x.time))), e = Math.max(...tl.map(x => lm(x.time) + (+x.dur || 0))); return [s, e]; }
