const roomName98 = e => String(e.venue || 'the same room');
function roomClashes98(){ const live = portalEvents.filter(e => e.date && e.roomKey && !e.archived && e.status !== 'cancelled'), by = {}, out = [];
  live.forEach(e => (by[e.date + '#' + e.roomKey] ||= []).push(e));
  Object.values(by).forEach(L => { for(let i = 0; i < L.length; i++) for(let j = i + 1; j < L.length; j++){ const a = L[i], b = L[j], ov = !a.span || !b.span || (a.span[0] < b.span[1] && b.span[0] < a.span[1]); if(ov) out.push({date:a.date, a, b, soft:a.status === 'inquiry' || b.status === 'inquiry'}); } });
  return out; }
const _cal98 = calendarHTML; calendarHTML = function(){ let h = _cal98.apply(this, arguments); const C = roomClashes98(); if(!C.length) return h;
  const days = new Set(C.map(c => c.date)); h = h.replace(/<div class="cal-cell([^"]*)"><span class="cal-d">(\d+)<\/span>/g, (m, cls, d) => { const y = calMonth.getFullYear(), mo = calMonth.getMonth(), iso = `${y}-${String(mo + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`; return days.has(iso) && !/clash/.test(cls) ? `<div class="cal-cell${cls} clash" title="Room double-booked"><span class="cal-d">${d}</span>` : m; });
  return h + `<div class="note warn rc98">${C.map(c => `<b>${esc(roomName98(c.a))}</b> on ${esc(shortFmt(c.date))}: ${esc(c.a.name)} and ${esc(c.b.name)}${c.soft ? ' (one is still an inquiry)' : ''}`).join('<br>')}</div>`; };
