function furnNeed99(){ const n = {}, add = (k, q) => { if(q > 0) n[k] = (n[k] || 0) + q; };
  tables().forEach(t => { add('table:' + t.type, 1); if(t.seats) add('chair:' + (lookOf(t).chair || 'chiavariGold'), t.seats); });
  if(typeof looseAll === 'function') looseAll().forEach(() => add('chair:' + ((state.looks[0] || {}).chair || 'chiavariGold'), 1));
  return n; }
const furnLabel99 = k => { const [c, id] = k.split(':'); return c === 'chair' ? `${(CHAIRS[id] || {label:id}).label} chairs` : `${(TABLE_TYPES[id] || {label:id}).label} tables`; };
