/* ============ features: staff shifts ============ */
/* The Day-of staffing plan gets named people: every slot in every role (event lead, captain, servers, crew, bartenders…) can be given to someone on
   your team. Assigned people join the event's staff, their shifts travel in the event summary (shifts = [{sid, role, call, off}]), a person booked on
   two overlapping shifts the same day is flagged, and each team member's upcoming shifts can be copied as a message (Events › Staff & company). */
function shiftsFor101(){ const P = staffingPlan(), S = state.shifts || {}, out = []; P.rows.forEach(r => (S[r.key] || []).slice(0, r.qty).forEach(sid => { if(sid) out.push({sid, role:r.role.replace(/\s*\(.*\)$/, ''), call:r.call, off:r.off}); })); return out; }
const _es101 = eventSummary; eventSummary = function(){ const s = _es101.apply(this, arguments); if(s) s.shifts = shiftsFor101(); return s; };
function shiftClash101(sid){ const mine = shiftsFor101().filter(x => x.sid === sid), d = state.event.date; if(!mine.length || !d) return [];
  return portalEvents.filter(e => e.id !== state.portalId && e.date === d && e.status !== 'cancelled' && !e.archived && Array.isArray(e.shifts)).flatMap(e => e.shifts.filter(x => x.sid === sid && mine.some(m => m.call < x.off && x.call < m.off)).map(x => ({e, x}))); }
function shiftPickHTML101(){ if(clientMode || !staffList.length) return staffList.length ? '' : '<p class="muted" style="font-size:12.5px;margin:8px 0 0">Add your team under Events › Staff &amp; company to put names on these shifts.</p>';
  const P = staffingPlan(), S = state.shifts || {}, opts = sel => `<option value="">Open</option>${staffList.map(s => `<option value="${esc(s.id)}"${sel === s.id ? ' selected' : ''}>${esc(s.name)}</option>`).join('')}`;
  const clashes = [...new Set(shiftsFor101().map(x => x.sid))].flatMap(sid => shiftClash101(sid).map(c => `${esc((staffById(sid) || {}).name || 'Someone')} is also working ${esc(c.e.name)} (${fmt12(fromMin(c.x.call))}–${fmt12(fromMin(c.x.off))})`));
  const filled = shiftsFor101().length, total = P.rows.reduce((a, r) => a + r.qty, 0);
  return `<div class="sh101"><div class="sh101-h"><span class="eyebrow">Who’s working</span><span class="pill ${filled === total ? 'ok' : ''}">${filled} of ${total} shifts filled</span></div>
    ${P.rows.map(r => `<div class="sh101-row"><b>${esc(r.role.replace(/\s*\(.*\)$/, ''))}</b><span class="muted">${fmt12(fromMin(r.call))} – ${fmt12(fromMin(r.off))}</span><div class="sh101-slots">${Array.from({length:r.qty}, (_, i) => `<select data-sh101="${esc(r.key)}:${i}" aria-label="${esc(r.role)} ${i + 1}">${opts((S[r.key] || [])[i])}</select>`).join('')}</div></div>`).join('')}
    ${clashes.length ? `<p class="note warn" style="margin:8px 0 0">${clashes.join('<br>')}</p>` : ''}</div>`; }
const _sth101 = staffingHTML; staffingHTML = function(){ const h = _sth101.apply(this, arguments); return h.replace(/<\/section>\s*$/, shiftPickHTML101() + '</section>'); };
document.addEventListener('change', e => { const v = e.target.dataset && e.target.dataset.sh101; if(!v) return; const [k, i] = v.split(':'), sid = e.target.value;
  mutate(() => { const S = (state.shifts ||= {}); S[k] = S[k] || []; S[k][+i] = sid || null; if(sid){ state.staff = state.staff || []; if(!state.staff.includes(sid)) state.staff.push(sid); } });
  if(state.portalId) saveToPortal(true); const y = $('#view-plan').scrollTop; renderPlanning(); $('#view-plan').scrollTop = y; });
/* a team member's upcoming shifts, ready to send */
function upcoming101(sid){ const today = isoLocal(); return portalEvents.filter(e => e.date && e.date >= today && e.status !== 'cancelled' && !e.archived && Array.isArray(e.shifts)).flatMap(e => e.shifts.filter(x => x.sid === sid).map(x => ({e, x}))).sort((a, b) => a.e.date.localeCompare(b.e.date) || a.x.call - b.x.call); }
function scheduleText101(sid){ const s = staffById(sid) || {name:'Team member'}, L = upcoming101(sid);
  return [`Hi ${String(s.name).split(' ')[0]}, here are your upcoming shifts with ${company.name}:`, '', ...(L.length ? L.map(({e, x}) => `• ${fmtDate(e.date)}: ${x.role}, ${fmt12(fromMin(x.call))} – ${fmt12(fromMin(x.off))} · ${e.name}${e.venue ? ' at ' + e.venue : ''}`) : ['• No shifts scheduled yet.']), '', 'Reply to confirm. Thank you!'].join('\n'); }
const _spp101 = staffPanelHTML; staffPanelHTML = function(){ let h = _spp101.apply(this, arguments); if(clientMode) return h;
  return h.replace(/(<button class="x" data-staffdel="([^"]+)")/g, (m, a, sid) => { const n = upcoming101(sid).length; return `<button class="btn sm" data-sh101copy="${sid}" title="Copy their upcoming shifts as a message">${n} upcoming shift${n === 1 ? '' : 's'} · Copy</button>${a}`; }); };
document.addEventListener('click', e => { const b = e.target.closest('[data-sh101copy]'); if(!b) return; const s = staffById(b.dataset.sh101copy); copyText(scheduleText101(b.dataset.sh101copy), `${s ? s.name.split(' ')[0] + '’s' : 'The'} schedule copied`); });
(function(){ const st = document.createElement('style'); st.textContent = `
.sh101{display:grid;gap:8px;margin-top:12px;padding-top:12px;border-top:1px solid var(--line)}.sh101-h{display:flex;justify-content:space-between;align-items:center;gap:8px}
.sh101-row{display:grid;grid-template-columns:minmax(120px,180px) 120px 1fr;gap:4px 10px;align-items:center;font-size:13px}.sh101-slots{display:flex;flex-wrap:wrap;gap:6px}.sh101-slots select{width:auto;min-width:130px;padding:5px 8px}
@media (max-width:640px){.sh101-row{grid-template-columns:1fr}}`; document.head.appendChild(st); })();

/* ============ features: inspiration board ============ */
/* Clients (and the team) pin inspiration to the event: photos from their phone (shrunk to about 35 KB each so the plan stays small) and links to
   Pinterest, Instagram or any page, each with an optional note. Shown on Proposal & billing for both sides. state.inspo = [{id, by:'client'|'team',
   name, at, img?, url?, note}]; up to 16 pins, images up to 140 KB in total. On the hosted app a client's pins go through submit_client_update. */
const INSPO_MAX102 = 16, INSPO_BYTES = 140000;
const inspo102 = () => state.inspo || [];
const inspoBytes102 = () => inspo102().reduce((a, p) => a + (p.img ? p.img.length : 0), 0);
function shrink102(file){ return new Promise((res, rej) => { const r = new FileReader(); r.onerror = rej; r.onload = () => { const im = new Image(); im.onerror = rej; im.onload = () => { const s = Math.min(1, 560/Math.max(im.width, im.height)), c = document.createElement('canvas'); c.width = Math.round(im.width*s); c.height = Math.round(im.height*s); c.getContext('2d').drawImage(im, 0, 0, c.width, c.height); let q = .65, d = c.toDataURL('image/jpeg', q); while(d.length > 48000 && q > .3){ q -= .1; d = c.toDataURL('image/jpeg', q); } res(d); }; im.src = r.result; }; r.readAsDataURL(file); }); }
const host102 = u => { try { return new URL(u).hostname.replace(/^www\./, ''); } catch(e){ return 'link'; } };
function inspoHTML102(){ const L = inspo102(), who = clientMode ? 'client' : 'team';
  return `<section class="inv-card insp102"><div class="insp102-h"><div><span class="eyebrow">Inspiration</span><h2>${clientMode ? 'Show us what you love' : 'Client inspiration'}</h2><p class="muted">${clientMode ? 'Add photos or links (Pinterest, Instagram, anywhere). Your planner sees them right away.' : 'Photos and links your client pinned, plus your own.'}</p></div><span class="pill">${L.length}</span></div>
    <div class="insp102-grid">${L.map(p => `<figure class="insp102-pin">${p.img ? `<img src="${p.img}" alt="${esc(p.note || 'Inspiration photo')}">` : `<a class="insp102-link" href="${esc(p.url)}" target="_blank" rel="noopener noreferrer"><b>${esc(host102(p.url))}</b><span>Open link</span></a>`}
      <figcaption>${p.note ? esc(p.note) : ''}<small>${esc(p.by === 'client' ? (p.name || 'Client') : (p.name || company.name))} · ${esc(ago(p.at))}</small></figcaption>${p.by === who ? `<button class="x" data-insdel="${esc(p.id)}" aria-label="Remove">×</button>` : ''}</figure>`).join('') || `<p class="muted insp102-empty">${clientMode ? 'Nothing pinned yet. Add the first photo or link.' : 'Nothing pinned yet.'}</p>`}</div>
    ${L.length < INSPO_MAX102 ? `<div class="insp102-add"><label class="btn sm"><input type="file" accept="image/*" id="ins-file" multiple hidden>Add photos</label><input id="ins-url" type="url" placeholder="Paste a Pinterest or Instagram link" inputmode="url"><input id="ins-note" placeholder="Note (optional)" maxlength="140"><button class="btn sm primary" data-insadd="1">Add link</button></div>` : '<p class="muted" style="font-size:12px">The board is full. Remove a pin to add another.</p>'}</section>`; }
const _rc102 = renderClient; renderClient = function(){ const r = _rc102.apply(this, arguments); if(clientTab === 'proposal'){ const host = $('#client'), anchor = host && (host.querySelector('.ns89') || host.querySelector('.sheet-head')); if(anchor) anchor.insertAdjacentHTML('afterend', inspoHTML102()); } return r; };
const inspoName102 = () => clientMode ? ((state.client || {}).name || 'Client') : (company.name || 'Team');
function addPin102(pin){ mutate(() => { (state.inspo ||= []).push(Object.assign({id:'p' + uid(), by:clientMode ? 'client' : 'team', name:inspoName102(), at:Date.now()}, pin)); logActivity(`${inspoName102()} pinned ${pin.img ? 'a photo' : 'a link'} to the inspiration board`, inspoName102()); }); if(state.portalId) saveToPortal(true); renderClient(); }
document.addEventListener('change', async e => { if(e.target.id !== 'ins-file') return; const files = [...e.target.files].slice(0, INSPO_MAX102 - inspo102().length); const note = (($('#ins-note') || {}).value || '').trim().slice(0, 140);
  for(const f of files){ if(!/^image\//.test(f.type)) continue; let d; try { d = await shrink102(f); } catch(err){ toast('That photo couldn’t be read.'); continue; } if(inspoBytes102() + d.length > INSPO_BYTES){ toast('The board is out of photo space. Add a link instead, or remove a photo.'); break; } addPin102({img:d, note}); }
  e.target.value = ''; });
document.addEventListener('click', e => { if(e.target.closest('[data-insadd]')){ const u = (($('#ins-url') || {}).value || '').trim(), note = (($('#ins-note') || {}).value || '').trim().slice(0, 140);
    if(!/^https?:\/\/\S+\.\S+/.test(u)){ toast('Paste a full link that starts with https://'); return; } addPin102({url:u.slice(0, 500), note}); return; }
  const d = e.target.closest('[data-insdel]'); if(d){ mutate(() => { state.inspo = inspo102().filter(p => p.id !== d.dataset.insdel); }); if(state.portalId) saveToPortal(true); renderClient(); } });
(function(){ const st = document.createElement('style'); st.textContent = `
.insp102{display:grid;gap:10px;margin:0 0 16px}.insp102-h{display:flex;justify-content:space-between;align-items:start;gap:10px}.insp102 h2{font-family:var(--display);font-weight:400;font-size:24px;margin:2px 0}.insp102 .muted{margin:0;font-size:13px}
.insp102-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:10px}.insp102-pin{position:relative;margin:0;border:1px solid var(--line);border-radius:14px;overflow:hidden;background:var(--surface);display:grid}
.insp102-pin img{width:100%;aspect-ratio:4/5;object-fit:cover;display:block}.insp102-link{display:grid;place-content:center;gap:4px;aspect-ratio:4/5;text-align:center;text-decoration:none;color:inherit;background:color-mix(in srgb, var(--accent) 10%, transparent)}.insp102-link span{font-size:12px;color:var(--accent)}
.insp102-pin figcaption{padding:7px 9px;font-size:12.5px;display:grid;gap:2px}.insp102-pin small{color:var(--muted);font-size:11px}.insp102-pin .x{position:absolute;top:6px;right:6px;background:var(--raised);border-radius:999px;width:28px;height:28px;border:1px solid var(--line)}
.insp102-add{display:flex;flex-wrap:wrap;gap:8px;align-items:center}.insp102-add input[type=url]{flex:1 1 220px}.insp102-add #ins-note{flex:1 1 160px}.insp102-add label.btn{cursor:pointer}.insp102-empty{grid-column:1 / -1;padding:10px 0}`; document.head.appendChild(st); })();
/* the client side in Spanish */
Object.assign(ES91, {'Inspiration':'Inspiración', 'Show us what you love':'Muéstrenos lo que le encanta', 'Add photos or links (Pinterest, Instagram, anywhere). Your planner sees them right away.':'Agregue fotos o enlaces (Pinterest, Instagram, cualquier sitio). Su planificador los ve de inmediato.',
  'Nothing pinned yet. Add the first photo or link.':'Todavía no hay nada. Agregue la primera foto o el primer enlace.', 'Add photos':'Agregar fotos', 'Add link':'Agregar enlace', 'Open link':'Abrir enlace', 'Paste a Pinterest or Instagram link':'Pegue un enlace de Pinterest o Instagram',
  'Note (optional)':'Nota (opcional)', 'Remove':'Quitar', 'The board is full. Remove a pin to add another.':'El tablero está lleno. Quite una para agregar otra.'});

/* ============ features: conversation studio ============ */
/* Messages built for shared understanding, not just chat.
   · Recap & confirm: after a call, tasting or walkthrough the planner sends a recap (what we decided, what we need from you, what we'll do, what's
     next). The client confirms each decision with one tap or says "Not quite" with a note, and answers questions inline, so both sides hold the same
     dated record. state.recaps = [{id, at, by, title, next, items:[{id, kind:'decision'|'question'|'todo', text, reply?:{status, note, by, at}, done?}]}]
   · Seen receipts: opening Messages on the client's link records state.clientSeenAt; the team sees "Seen" under its latest message.
   · Clarity coach: while the team writes, gentle hints on the ask, the deadline, long sentences, jargon, tone and unfilled [blanks].
   · Quick starts: messages for the moments that matter, filled with the client's name, dates and amounts, in English or Spanish. */
const RECAP_TITLES103 = ['Planning call recap', 'Tasting recap', 'Walkthrough recap', 'Design meeting recap', 'Final details call'];
let recapDraft103 = null, noteOpen103 = '';
const es103 = () => state.clientLang === 'es';
const dShort103 = (iso, es) => { const d = new Date((iso || '') + 'T00:00'); return isNaN(d) ? '' : d.toLocaleDateString(es ? 'es-MX' : 'en-US', {weekday:'long', month:'long', day:'numeric'}); };
const plus103 = n => { const d = new Date(); d.setDate(d.getDate() + n); return isoLocal(d); };
const clientFirst103 = () => String((state.client || {}).name || '').trim().split(/\s+/)[0] || '';
const recaps103 = () => state.recaps || [];
const openForClient103 = r => (r.items || []).filter(i => i.kind !== 'todo' && !i.reply);

/* ---------- quick starts ---------- */
function quickStarts103(es){
  const first = clientFirst103(), ev = state.event.name || (es ? 'su evento' : 'your event'), date = dShort103(state.event.date, es) || (es ? 'su fecha' : 'your date'), co = company.name || '';
  let pay = null; try { const P = payments(), A = payAmounts(), s = P.schedule.find(x => !x.paid); if(s) pay = {label:s.label, amt:money(A.map[s.id] || 0), due:dShort103(s.due, es)}; } catch(e){}
  const countBy = state.event.date ? dShort103(shiftIso(state.event.date, -14), es) : (es ? '[fecha]' : '[date]'), signBy = dShort103(plus103(7), es);
  const hi = es ? (first ? `Hola ${first},` : 'Hola,') : (first ? `Hi ${first},` : 'Hi there,');
  if(es) return [
    ['welcome', 'Bienvenida y siguientes pasos', `${hi}\n\n¡Gracias por elegir a ${co} para ${ev}! Esto es lo que sigue:\n1. Revise su propuesta y firme el contrato (toma unos dos minutos).\n2. ${pay ? `Su ${pay.label.toLowerCase()} de ${pay.amt} aparta la fecha${pay.due ? ' y vence el ' + pay.due : ''}.` : 'Su anticipo aparta la fecha.'}\n3. Agendaremos su degustación y la visita al lugar.\n\nTodo está en su página del evento y ahí puede escribirnos cuando quiera. ¿Podría firmar el contrato antes del ${signBy}?\n\n${co}`],
    ['paid', 'Pago recibido', `${hi}\n\nRecibimos su pago, ¡muchas gracias! ${ev} el ${date} ya está confirmado en nuestro calendario.\n\n${pay ? `Lo siguiente: ${pay.label.toLowerCase()} de ${pay.amt}${pay.due ? ' para el ' + pay.due : ''}.` : 'Ya no tiene pagos pendientes.'} Pronto le escribiremos para agendar su degustación.\n\n${co}`],
    ['remind', 'Recordatorio de pago amable', `${hi}\n\nLe recordamos que ${pay ? `su ${pay.label.toLowerCase()} de ${pay.amt} vence el ${pay.due || '[fecha]'}` : 'su próximo pago vence el [fecha]'}. Puede ver su saldo en su página del evento.\n\nSi ya lo envió, ¡gracias! Ignore este mensaje.\n\n${co}`],
    ['count', 'Número final de invitados', `${hi}\n\n¡Ya falta poco! ¿Podría enviarnos el número final de invitados antes del ${countBy}? Con él preparamos la comida, las mesas y el personal; después de esa fecha el número solo puede subir.\n\nSi algún invitado tiene alergias o una dieta especial, inclúyalo también.\n\n${co}`],
    ['tasting', 'Confirmar degustación', `${hi}\n\nSu degustación quedó para el [día y hora] en [lugar]. Puede traer hasta [número] personas que ayuden a decidir el menú.\n\n¿Nos confirma antes del [fecha]?\n\n${co}`],
    ['week', 'La semana del evento', `${hi}\n\n¡${ev} es la próxima semana! Este es el plan:\n• El montaje empieza a las [hora]\n• Las puertas abren a las [hora]\n• Su contacto del día es [nombre, teléfono]\n\n¿Cambió algo (invitados, horario, proveedores)? Avísenos antes del [día].\n\n${co}`],
    ['thanks', 'Gracias y reseña', `${hi}\n\nGracias por dejarnos ser parte de ${ev}. Fue un gusto verlo hecho realidad.\n\nSi tiene un minuto, una reseña breve significaría mucho para nuestro equipo: [enlace de reseña]\n\nCon cariño,\n${co}`]];
  return [
    ['welcome', 'Welcome & next steps', `${hi}\n\nThank you for choosing ${co} for ${ev}! Here's what happens next:\n1. Review your proposal and sign the agreement (about two minutes).\n2. ${pay ? `Your ${pay.label.toLowerCase()} of ${pay.amt} holds the date${pay.due ? ', due ' + pay.due : ''}.` : 'Your deposit holds the date.'}\n3. We'll schedule your tasting and walkthrough.\n\nEverything lives on your event page, and you can message us there anytime. Could you sign the agreement by ${signBy}?\n\n${co}`],
    ['paid', 'Payment received', `${hi}\n\nWe received your payment. Thank you! ${ev} on ${date} is officially on our calendar.\n\n${pay ? `Next up: your ${pay.label.toLowerCase()} of ${pay.amt}${pay.due ? ', due ' + pay.due : ''}.` : 'You have no payments left.'} We'll be in touch about your tasting soon.\n\n${co}`],
    ['remind', 'Friendly payment reminder', `${hi}\n\nA quick reminder that ${pay ? `your ${pay.label.toLowerCase()} of ${pay.amt} is due ${pay.due || '[date]'}` : 'your next payment is due [date]'}. You can see your balance on your event page.\n\nIf you've already sent it, thank you, and please ignore this note.\n\n${co}`],
    ['count', 'Final guest count', `${hi}\n\nWe're getting close! Could you send your final guest count by ${countBy}? It sets the food order, seating and staffing, so after that date the count can only go up.\n\nIf any guests have allergies or special meals, please include them too.\n\n${co}`],
    ['tasting', 'Confirm the tasting', `${hi}\n\nYour tasting is set for [day and time] at [place]. You're welcome to bring up to [number] people who help decide the menu.\n\nCould you reply to confirm by [date]?\n\n${co}`],
    ['week', 'Week-of check-in', `${hi}\n\n${ev} is next week! Here's the plan:\n• Setup starts at [time]\n• Doors open at [time]\n• Your day-of contact is [name, phone]\n\nHas anything changed (guest count, timeline, vendors)? Please let us know by [day].\n\n${co}`],
    ['thanks', 'Thank you & review', `${hi}\n\nThank you for letting us be part of ${ev}. It was a joy to see it come together.\n\nIf you have a minute, a short review would mean a lot to our small team: [review link]\n\nWith gratitude,\n${co}`]];
}

/* ---------- clarity coach ---------- */
const JARGON103 = [[/\bBEOs?\b/g, 'event order'], [/\bF&B\b/gi, 'food and drinks'], [/\s?\+\+/g, ' plus tax and service charge'], [/\bplus[- ]plus\b/gi, 'plus tax and service charge'], [/\bfinal guarantee\b/gi, 'final guest count'],
  [/\battrition\b/gi, 'guest-count minimum'], [/\bload[- ]in\b/gi, 'setup arrival time'], [/\bload[- ]out\b/gi, 'pack-up time'], [/\bF\.?O\.?H\.?\b/g, 'front of house'], [/\bP&L\b/g, 'budget'], [/\bper diem\b/gi, 'daily rate'], [/\bINV\b/g, 'invoice']];
const TONE103 = [[/\bas I (?:said|mentioned)( before)?\b/gi, 'To recap', '“As I said” can read as blame.'], [/\bper my last (?:email|message)\b/gi, 'To recap', '“Per my last message” reads as frustrated.'],
  [/\byou need to\b/gi, 'could you', '“You need to” sounds like an order.'], [/\byou forgot\b/gi, 'we still need', '“You forgot” puts them on the spot.'], [/\bobviously\b/gi, '', '“Obviously” can feel condescending.'], [/\bASAP\b/g, 'by [date]', '“ASAP” has no date; give one.'],
  [/\bcomo (?:le )?dije\b/gi, 'Para resumir', '“Como le dije” puede sonar a reproche.'], [/\btiene que\b/gi, 'podría', '“Tiene que” suena a orden.']];
const ASK103 = /\?|¿|\b(please|could you|can you|would you|let me know|let us know|confirm|reply|send|choose|pick|sign|approve|review|por favor|podría|puede|nos confirma|confirme|envíe|elija|firme|avísenos)\b/i;
const WHEN103 = /\b(today|tonight|tomorrow|by|before|until|end of (?:the )?(?:day|week)|this week|next week|monday|tuesday|wednesday|thursday|friday|saturday|sunday|jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|june?|july?|aug(?:ust)?|sept?(?:ember)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?|hoy|mañana|antes del?|para el|esta semana|lunes|martes|miércoles|jueves|viernes|sábado|domingo|enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|octubre|noviembre|diciembre)\b|\d{1,2}\/\d{1,2}/i;
function syll103(w){ w = w.toLowerCase().replace(/[^a-z]/g, ''); if(w.length <= 3) return 1; w = w.replace(/(?:[^laeiouy]es|ed|[^laeiouy]e)$/, '').replace(/^y/, ''); const m = w.match(/[aeiouy]{1,2}/g); return m ? m.length : 1; }
function coach103(text){
  const t = String(text || ''), out = [], words = t.match(/[A-Za-zÀ-ÿ'’]+/g) || [];
  if(words.length < 6) return out;
  const sentences = t.split(/[.!?¿¡\n]+/).map(s => s.trim()).filter(s => s.split(/\s+/).length > 2), avg = sentences.length ? words.length / sentences.length : words.length;
  const blanks = t.match(/\[[^\]\n]{1,40}\]/g);
  if(blanks) out.push({tip:true, msg:`Fill in ${blanks.length === 1 ? blanks[0] : blanks.length + ' blanks like ' + blanks[0]} before sending.`, pri:0});
  const ask = ASK103.test(t), when = WHEN103.test(t);
  if(ask) out.push({tip:false, msg:'Clear ask'}); else if(words.length > 25) out.push({tip:true, msg:'What do you need from them? End with one clear ask.', pri:2});
  if(ask && !when) out.push({tip:true, msg:'Add a “by when” so it doesn’t slip.', pri:1}); else if(ask && when) out.push({tip:false, msg:'Has a deadline'});
  const qs = (t.match(/\?/g) || []).length; if(qs > 2) out.push({tip:true, msg:`${qs} questions in one message. Number them so none get missed.`, fix:'number', pri:2});
  JARGON103.forEach(([re, plain]) => { const m = t.match(re); if(m) out.push({tip:true, msg:`“${m[0].trim()}” is industry talk. Try “${plain.trim()}”.`, fix:'jargon', re, plain, pri:3}); });
  TONE103.forEach(([re, plain, why]) => { const m = t.match(re); if(m) out.push({tip:true, msg:why + (plain ? ` Try “${plain}”.` : ''), fix:'tone', re, plain, pri:1}); });
  const caps = words.filter(w => w.length >= 4 && w === w.toUpperCase() && /[A-Z]/.test(w) && !/^(RSVP|ASAP|BEO|BEOS)$/.test(w)); if(caps.length >= 2) out.push({tip:true, msg:'Words in capitals can read as shouting.', pri:4});
  if(/!{2,}/.test(t)) out.push({tip:true, msg:'One exclamation point reads warm; more can read as alarm.', fix:'bang', pri:4});
  if(avg > 24) out.push({tip:true, msg:'Some sentences run long. Shorter ones are easier on a phone.', pri:4});
  if(words.length > 170) out.push({tip:true, msg:'Long message. Put the ask in the first two lines.', pri:3});
  if(es103() && (t.match(/\b(the|and|you|your|please|we|will|with|for|is)\b/gi) || []).length >= 4 && !(t.match(/\b(el|la|los|las|usted|su|por|para|que|con)\b/gi) || []).length)
    out.push({tip:true, msg:`${clientFirst103() || 'Your client'} reads Spanish. Try the Español quick start, or add a line in Spanish.`, pri:1});
  if(!es103() && avg <= 24){ const syl = words.reduce((a, w) => a + syll103(w), 0), fre = 206.835 - 1.015 * avg - 84.6 * (syl / words.length); if(fre >= 60) out.push({tip:false, msg:'Easy to read'}); else if(fre < 40) out.push({tip:true, msg:'Hard to read. Use shorter words and sentences.', pri:4}); }
  const tips = out.filter(o => o.tip).sort((a, b) => a.pri - b.pri).slice(0, 4), good = out.filter(o => !o.tip);
  return tips.concat(tips.length ? good.slice(0, 1) : good);
}
let coachList103 = [];
