document.addEventListener('click', e => { const b = e.target.closest && e.target.closest('#ez [data-ezcl]'); if(!b) return; EZ.clPick = b.dataset.ezcl;
  b.parentNode.querySelectorAll('[data-ezcl]').forEach(x => { x.setAttribute('aria-pressed', x === b); x.classList.toggle('on', x === b); }); });
