/* ============ features: client final details ============ */
/* A "Final details" tab in Proposal & billing. On the client's link it is a form: key people and how to say their names, special moments (song,
   who, rough time), the client's own vendors, a day-of emergency contact and notes, kept in state.details and saved as they type. "Send to my
   planner" sets submittedAt and also posts the summary as a client message, because the hosted app only syncs messages from client links. The team
   sees the details here (read back from that message when the plan has no copy) and applies them to the run of show, vendors and MC notes. */
const FD_MOMENTS = ['Grand entrance', 'First dance', 'Toasts', 'Cake cutting'], FD_TIMES = {'grand entrance':'18:00', 'toasts':'19:00', 'first dance':'19:30', 'cake cutting':'21:00'};
const FD_CAP = {people:20, moments:15, vendors:15}, FD_HEAD = /^(Updated )?final details for /i;
const fdRow = {people:() => ({id:uid(), name:'', role:'', say:''}), moments:(title = '', std = false) => ({id:uid(), title, std, song:'', who:'', time:''}), vendors:() => ({id:uid(), role:'', name:'', phone:'', email:''})};
const fdBlank = () => ({people:[fdRow.people()], moments:FD_MOMENTS.map(t => fdRow.moments(t, true)), vendors:[fdRow.vendors()], emergency:{name:'', phone:''}, notes:'', submittedAt:null, updatedAt:null});
const fdOne = s => String(s || '').replace(/\s*[\r\n]+\s*/g, ' ').replace(/\s*·\s*/g, ', ').trim();
const fdNorm = s => String(s || '').toLowerCase().replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
function fdFix(D){ ['people', 'moments', 'vendors'].forEach(k => { if(!Array.isArray(D[k])) D[k] = []; D[k].forEach(r => r.id ||= uid()); }); if(!D.emergency || typeof D.emergency !== 'object') D.emergency = {name:'', phone:''}; if(typeof D.notes !== 'string') D.notes = ''; return D; }
const fdPeople = D => D.people.filter(p => fdOne(p.name));
const fdMoments = D => D.moments.filter(m => fdOne(m.title) && (fdOne(m.song) || fdOne(m.who) || m.time));
const fdVendors = D => D.vendors.filter(v => fdOne(v.name) || fdOne(v.phone) || fdOne(v.email));
const fdHasAny = D => !!(fdPeople(D).length || fdMoments(D).length || fdVendors(D).length || fdOne(D.emergency.name) || fdOne(D.emergency.phone) || D.notes.trim());
/* the message the planner reads; one line per entry with " · " between parts, so it can be read back into details on the team side */
function fdSummary(D, again){ const P = fdPeople(D), M = fdMoments(D), V = fdVendors(D), E = D.emergency, L = [`${again ? 'Updated final details' : 'Final details'} for ${fdOne(state.event.name) || 'our event'}`];
  if(P.length) L.push('', 'Key people:', ...P.map(p => '• ' + [fdOne(p.name), fdOne(p.role), fdOne(p.say) && 'say: ' + fdOne(p.say)].filter(Boolean).join(' · ')));
  if(M.length) L.push('', 'Special moments:', ...M.map(m => '• ' + [fdOne(m.title), m.time && 'time: ' + fmt12(m.time), fdOne(m.song) && 'song: ' + fdOne(m.song), fdOne(m.who) && 'who: ' + fdOne(m.who)].filter(Boolean).join(' · ')));
  if(V.length) L.push('', 'My vendors:', ...V.map(v => '• ' + [fdOne(v.role) || 'Vendor', fdOne(v.name), fdOne(v.phone) && 'phone: ' + fdOne(v.phone), fdOne(v.email) && 'email: ' + fdOne(v.email)].filter(Boolean).join(' · ')));
  if(fdOne(E.name) || fdOne(E.phone)) L.push('', 'Day-of emergency contact:', '• ' + [fdOne(E.name) || 'Contact', fdOne(E.phone) && 'phone: ' + fdOne(E.phone)].filter(Boolean).join(' · '));
  if(D.notes.trim()) L.push('', 'Notes:', D.notes.trim());
  const s = L.join('\n'); return s.length > 3990 ? s.slice(0, 3989) + '…' : s; }
function fdParse(text){ const lines = String(text || '').split('\n'); if(!FD_HEAD.test(lines[0] || '')) return null;
  const D = fdBlank(), SEC = {'key people:':'people', 'special moments:':'moments', 'my vendors:':'vendors', 'day-of emergency contact:':'emergency', 'notes:':'notes'}, notes = []; let sec = '';
  D.people = []; D.moments = []; D.vendors = [];
  const t24 = s => { const m = String(s).match(/^(\d{1,2}):(\d{2}) ?(AM|PM)$/i); return m ? `${String((+m[1] % 12) + (/pm/i.test(m[3]) ? 12 : 0)).padStart(2, '0')}:${m[2]}` : ''; };
  const parts = l => { const o = {_:[]}; l.replace(/^•\s*/, '').split(' · ').forEach(p => { const m = p.match(/^(say|time|song|who|phone|email): (.*)$/); if(m) o[m[1]] = m[2]; else o._.push(p); }); return o; };
  lines.slice(1).forEach(l => { if(sec === 'notes'){ notes.push(l); return; } const h = SEC[l.trim().toLowerCase()]; if(h){ sec = h; return; } if(!/^•/.test(l)) return; const o = parts(l);
    if(sec === 'people') D.people.push(Object.assign(fdRow.people(), {name:o._[0] || '', role:o._[1] || '', say:o.say || ''}));
    if(sec === 'moments') D.moments.push(Object.assign(fdRow.moments(o._[0] || '', FD_MOMENTS.includes(o._[0])), {song:o.song || '', who:o.who || '', time:o.time ? t24(o.time) : ''}));
    if(sec === 'vendors') D.vendors.push(Object.assign(fdRow.vendors(), {role:o._[0] || '', name:o._[1] || '', phone:o.phone || '', email:o.email || ''}));
    if(sec === 'emergency') D.emergency = {name:o._[0] === 'Contact' ? '' : o._[0] || '', phone:o.phone || ''}; });
  FD_MOMENTS.forEach(t => { if(!D.moments.some(m => m.title === t)) D.moments.push(fdRow.moments(t, true)); });
  D.notes = notes.join('\n').trim(); return D; }
const fdLastMsg = () => (state.messages || []).filter(m => m.from === 'client' && FD_HEAD.test(m.text || '')).pop() || null;
const fdFromMsg = () => { const M = fdLastMsg(), D = M && fdParse(M.text); if(D){ D.submittedAt = D.updatedAt = M.at; D.fromMsg = true; } return D; };
/* the hosted client link only sends messages back, so the client's own copy is also kept in this browser */
const fdKey = () => 'ts-fd-' + (state.portalId || 'local');
function fdLocal(){ if(!clientMode) return null; try { const v = JSON.parse(localStorage.getItem(fdKey()) || 'null'); return v && typeof v === 'object' ? fdFix(v) : null; } catch(e){ return null; } }
function fdBackup(){ if(!clientMode || !state.details) return; try { localStorage.setItem(fdKey(), JSON.stringify(state.details)); } catch(e){} }
