function fdGet(create){
  /* on the hosted link the plan can carry the team's older copy; once per event, a newer copy in this browser or a newer sent message wins */
  if(state.details && clientMode && fdSeen !== state.portalId){ fdSeen = state.portalId; const cur = fdFix(state.details), best = [fdLocal(), fdFromMsg()].reduce((x, y) => y && (y.updatedAt || 0) > (x.updatedAt || 0) ? y : x, cur); if(best !== cur){ delete best.fromMsg; state.details = best; } }
  if(state.details) return fdFix(state.details);
  if(!fdTemp || fdTemp.ev !== state.portalId){ const a = fdLocal(), b = fdFromMsg(), d = a && b ? ((a.updatedAt || 0) >= (b.updatedAt || 0) ? a : b) : a || b || fdBlank(); delete d.fromMsg; fdTemp = {ev:state.portalId, d}; }
  if(!create) return fdTemp.d; state.details = fdTemp.d; fdTemp = null; return state.details; }
