  if(tbView === 'list'){
    grid.querySelectorAll('input[data-task]').forEach(cb => { const t = state.tasks.find(x => x.id === cb.dataset.task), li = cb.closest('li'), meta = li && li.querySelector('.task-meta'); if(!t || !meta) return;
      const k = tbStatus(t); li.classList.toggle('tb-doing', k === 'doing');
      meta.insertAdjacentHTML('afterbegin', `<select class="v-status" data-tbstat="${esc(t.id)}" aria-label="Status of ${esc(t.title)}" style="max-width:96px">${TB_ST.map(([v, n]) => `<option value="${v}"${k === v ? ' selected' : ''}>${n}</option>`).join('')}</select>`); });
    return r;
  }
