/* ============ fixes: client flow and polish ============ */
/* The ✨ Easy mode switch belongs to the planner's app only. It was decided once at startup, so on the hosted app (where the client page, RSVP page
   or inquiry form opens a moment later) it could sit on a client's screen. It is now checked again whenever the view, the client page or a public
   page changes, and on phones it is a small round button that stays clear of any bottom tab bar. On phones the client section tabs scroll so the
   active tab is in view. */
const fxShown = sel => { const o = document.querySelector(sel); return !!(o && !o.hidden); };
function fxPublic(){ return !!(clientMode || document.body.classList.contains('client-mode') || fxShown('#rsvp-page') || fxShown('#staff-mode') || (typeof TSB !== 'undefined' && TSB.anon) || /^#(rsvp|site|vendor|staff|tk|ev|inquire|reviews)-/.test(location.hash || '')); }
/* lift the switch above a fixed bar along the bottom of the screen */
function fxPillLift(b){ let lift = 0; document.querySelectorAll('.cnav, nav, [role="tablist"], .tabbar, .bottom-bar').forEach(x => { if(x === b || getComputedStyle(x).position !== 'fixed') return; const r = x.getBoundingClientRect();
  if(r.height && r.width && r.bottom >= innerHeight - 4 && r.top > innerHeight/2) lift = Math.max(lift, innerHeight - r.top); }); b.style.bottom = lift ? `${Math.round(lift + 12)}px` : ''; }
