const PAY_METHOD_ES = {Card:'Tarjeta', Cash:'Efectivo', Check:'Cheque', 'Bank transfer':'Transferencia', Zelle:'Zelle', Venmo:'Venmo', Odoo:'Odoo', Credit:'Crédito'};
const MONTH_ES = {January:'enero', February:'febrero', March:'marzo', April:'abril', May:'mayo', June:'junio', July:'julio', August:'agosto', September:'septiembre', October:'octubre', November:'noviembre', December:'diciembre'};
const esDate = d => { const m = String(d).match(/^(January|February|March|April|May|June|July|August|September|October|November|December) (\d{1,2})(?:, (\d{4}))?$/); if(m) return `${m[2]} de ${MONTH_ES[m[1]]}${m[3] ? ' de ' + m[3] : ''}`; return typeof dateEs93 === 'function' ? dateEs93(d) : d; };
RULES91.push([/^(Adds|Removes) (\$[\d,]+(?:\.\d\d)?)\. /, (m, a, v) => `${a === 'Adds' ? 'Suma' : 'Resta'} ${v}. `],
  [/^(#\d+ · [+−-]\$[\d,.]+) · approved$/, (m, a) => `${a} · aprobada`], [/^(#\d+ · [+−-]\$[\d,.]+) · declined$/, (m, a) => `${a} · rechazada`],
  [/^Paid (.+?) (?:·|by) ([^·]+)$/, (m, d, how) => `Pagado el ${esDate(d.trim())} · ${PAY_METHOD_ES[how.trim()] || how.trim()}`],
  [/^Locked at signing · (.+)$/, (m, v) => `Fijado al firmar · ${v}`]);
/* ============ fixes: spanish client screens and printed pieces ============ */
/* A Spanish client link now reads in Spanish on the cake, bar, hors d'oeuvres, dinner menu, backdrop, venue and messages screens, in tooltips and in
   the DJ brief. Printed pieces (invitation, save the date, RSVP card, program, escort and place cards, menu cards, signs, badges, stage plot) keep their
   real wording: they follow the invitation's own Wording setting (English, Español, Bilingual), so a client never approves an English card that looked
   Spanish on screen. A translated <option> keeps its English value, so a choice made on a Spanish screen still saves the real dish, flavor or meal.
   Also: clients never see linen stock counts; a client sees "not booked yet" instead of a default DJ price when no entertainment is planned; a guest
   whose meal is a dish name with no price of its own (before any main is picked) is billed at the unchosen-meal price instead of $0; and saying
   "No cake" reminds the team that the cake table is still on the floor plan. */
const PRINT91 = new Set(['Invitation', 'Save the date', 'RSVP card', 'Program', 'Escort cards', 'Place cards', 'Table number card', 'Dinner menu card', 'Bar menu card', 'Name badges', 'Reserved sign', 'Agenda', 'Stage plot']);
const _apply91P = apply91;
apply91 = function(root){
  if(root && root.querySelectorAll){
    root.querySelectorAll('svg[aria-label]').forEach(s => { if(PRINT91.has(s.getAttribute('aria-label')) && !s.classList.contains('no-tr91')) s.classList.add('no-tr91'); });
    root.querySelectorAll('option:not([value])').forEach(o => { const n = o.firstChild; o.setAttribute('value', n && orig91.has(n) ? orig91.get(n).en : o.textContent); });
  }
  const r = _apply91P.apply(this, arguments);
  if(root && root.querySelectorAll){ const es = lang91() === 'es'; busy91 = true;
    try { root.querySelectorAll('[title]').forEach(el => { const v = el.getAttribute('title'); if(!v) return; const m = origAttr91.get(el) || {};
        if(es){ const en = m.title && m.title.es === v ? m.title.en : v, t = tr91(en); if(t !== en){ m.title = {en, es:t}; origAttr91.set(el, m); if(v !== t) el.setAttribute('title', t); } }
        else if(m.title && v === m.title.es){ el.setAttribute('title', m.title.en); delete m.title; } }); }
    finally { busy91 = false; } }
  return r;
};

