swatches = function(key, list, L, opts){ if(clientMode && Array.isArray(list)){ list = list.map(c => ({name:c.name, hex:c.hex})); opts = Object.assign({}, opts || {}, {showStock:false}); } return _swatchesP.call(this, key, list, L, opts); };
