/* ---- Spanish ---- */
const capP = s => s.charAt(0).toUpperCase() + s.slice(1), lowP = s => s.charAt(0).toLowerCase() + s.slice(1);
const esP = s => { const t = String(s || '').trim(); if(!t) return t; if(ES91[t]) return ES91[t]; if(ES91[capP(t)]) return t === capP(t) ? ES91[capP(t)] : lowP(ES91[capP(t)]); return null; };
const esOr = s => esP(s) || s;
const colP = s => lowP(colCS(capP(String(s || '').trim())));
const MEAL_ES = {Chicken:'Pollo', Beef:'Res', Fish:'Pescado', Vegetarian:'Vegetariano', Vegan:'Vegano', Kids:'Niños', Pork:'Cerdo', Salmon:'Salmón', Steak:'Filete', Pasta:'Pasta', Shrimp:'Camarón'};
const mealP = s => { const t = String(s).trim(), u = t === t.toUpperCase() && /[A-Z]/.test(t), k = capP(t.toLowerCase()); const v = MEAL_ES[t] || MEAL_ES[k] || esP(t); return v ? (u ? v.toUpperCase() : t === t.toLowerCase() ? v.toLowerCase() : v) : null; };
const FLAVOR_ES = {'Vanilla bean':'Vainilla', 'Chocolate':'Chocolate', 'Red velvet':'Terciopelo rojo', 'Lemon':'Limón', 'Almond':'Almendra', 'Carrot':'Zanahoria', 'Funfetti':'Chispas de colores', 'Coconut':'Coco', 'Pistachio':'Pistache', 'Strawberry':'Fresa'};
const FILLING_ES = {'vanilla buttercream':'betún de vainilla', 'chocolate ganache':'ganache de chocolate', 'raspberry':'frambuesa', 'lemon curd':'crema de limón', 'salted caramel':'caramelo salado', 'cream cheese':'queso crema', 'strawberry':'fresa', 'passion fruit':'maracuyá', 'espresso':'espresso', 'mocha':'moka'};
const DJ_HEAD_ES = {'LANGUAGE MIX':'MEZCLA DE IDIOMAS', 'GENRES':'GÉNEROS', 'KEY MOMENTS':'MOMENTOS CLAVE', 'ENERGY BY SEGMENT':'ENERGÍA POR MOMENTO', 'TRADITIONS':'TRADICIONES', 'MUST PLAY':'SÍ TOCAR', 'DO NOT PLAY':'NO TOCAR', 'GUEST REQUESTS':'PETICIONES DE INVITADOS', 'NOTES':'NOTAS'};
const LANG_ES = {English:'Inglés', Spanish:'Español', Arabic:'Árabe', Assyrian:'Asirio', Armenian:'Armenio', Portuguese:'Portugués', French:'Francés', Italian:'Italiano', 'Hindi & Punjabi':'Hindi y punyabí', Korean:'Coreano', Tagalog:'Tagalo', Greek:'Griego', Hebrew:'Hebreo', 'Haitian Creole':'Criollo haitiano', Polish:'Polaco'};
const MC_ES = {'Quiet: announcements only':'Discreto: solo anuncios', 'Balanced: warm and guiding':'Equilibrado: cálido y guía', 'Hype: high-energy host':'Animado: presentador con mucha energía'};
function djBriefEs(txt){
  return txt.split('\n').map(line => { const t = line.trim(), ind = line.slice(0, line.length - line.trimStart().length); let m;
    if(DJ_HEAD_ES[t]) return ind + DJ_HEAD_ES[t];
    if((m = t.match(/^DJ BRIEF · (.*)$/))) return ind + 'GUÍA PARA EL DJ · ' + m[1];
    if((m = t.match(/^(.*) · (\d+) guests$/))) return ind + m[1].split(' · ').map((p, i) => i === 0 && typeof esDate === 'function' ? esDate(p) : p).join(' · ') + ` · ${m[2]} invitados`;
    if((m = t.match(/^MC STYLE: (.*)$/))) return ind + 'ESTILO DEL MC: ' + (MC_ES[m[1]] || m[1]);
    if((m = t.match(/^LYRICS: (.*)$/))) return ind + 'LETRAS: ' + (m[1] === 'Clean edits only' ? 'Solo versiones limpias' : m[1] === 'Explicit is fine' ? 'Se permiten versiones explícitas' : m[1]);
    if((m = t.match(/^REQUESTS: (.*)$/))) return ind + 'PETICIONES: ' + ({'Take requests':'Aceptar peticiones', 'Requests only if they fit the vibe':'Peticiones solo si encajan con el ambiente', 'No requests':'Sin peticiones'}[m[1]] || m[1]);
    if((m = t.match(/^Decades: (.*)$/))) return ind + 'Décadas: ' + (m[1] === 'any' ? 'cualquiera' : m[1].replace(/\bToday\b/, 'Hoy'));
    if((m = t.match(/^(.+): (\d+)%$/)) && LANG_ES[m[1]]) return ind + `${LANG_ES[m[1]]}: ${m[2]}%`;
    if((m = t.match(/^(.+): (lots|some)$/))) return ind + `${esOr(m[1])}: ${m[2] === 'lots' ? 'mucho' : 'algo'}`;
    if((m = t.match(/^(\d{1,2}:\d\d [AP]M) (.+): (\d+)\/100$/))) return ind + `${m[1]} ${esOr(m[2])}: ${m[3]}/100`;
    if(ind && (m = t.match(/^([^:]+): (.+)$/)) && esP(m[1])) return ind + `${esP(m[1])}: ${m[2].replace(/ \(suggested\)$/, ' (sugerida)').replace(/^DJ’s choice$/, 'a elección del DJ')}`;
    return line; }).join('\n');
}
