  const mins = s => { const [h, m] = s.split(':').map(Number), v = h*60 + m; return v < 240 ? v + 1440 : v; }, at = v => { const x = new Date(base); x.setDate(x.getDate() + Math.floor(v/1440)); const r = v % 1440; return `${ymd(x)}T${p2(Math.floor(r/60))}${p2(r % 60)}00`; };
