    const seen = new Set(Array.isArray(plan.linkApplied) ? plan.linkApplied : []), fresh = rs.filter(r => !seen.has(r.id)); let added = 0, gAdd = 0, gVia = '';
    const gIds = new Set((plan.guests || []).flatMap(g => [g.id, ...(g.aliases || [])])), vIds = new Set((plan.vendors || []).map(v => v.id)), hh = new Map();
    const apply = () => { fresh.forEach(r => { const p = r.payload || {}, at = Date.parse(r.created_at) || Date.now();
      if(r.kind === 'song' && p.song){ plan.music ||= {}; const list = plan.music.requests_list = plan.music.requests_list || [];
        if(!list.some(x => String(x.song || '').toLowerCase() === String(p.song).toLowerCase()) && list.length < 300){ list.push({name:p.name || 'A guest', song:p.song, at}); added++;
          (plan.activity ||= []).unshift({at, text:`Song request: ${p.song}${p.name ? ' (' + p.name + ')' : ''}`, who:'Website'}); } }
      if(r.kind === 'staff'){ const ck = plan.checkin ||= {}, dy = plan.dayof ||= {}, dn = dy.done ||= {}, vi = plan.vendorIn ||= {};
        Object.entries(p.checkin || {}).forEach(([k, v]) => { if(bad(k) || !gIds.has(k)) return; if(typeof v === 'number') ck[k] = v; else delete ck[k]; });
        Object.entries(p.done || {}).forEach(([k, v]) => { if(bad(k)) return; if(v === true) dn[k] = true; else if(own(dn, k)) delete dn[k]; });
        Object.entries(p.vin || {}).forEach(([k, v]) => { if(bad(k) || !vIds.has(k)) return; if(typeof v === 'number') vi[k] = v; else delete vi[k]; });
        Object.keys(p.yes || {}).forEach(k => { const g = (plan.guests || []).find(x => x.id === k); if(g && g.rsvp === 'no' && (typeof (p.checkin || {})[k] === 'number' || typeof (plan.checkin || {})[k] === 'number')){ g.rsvp = 'yes'; g.rsvpAt = at; } }); }
      /* guests added through the API or an AI assistant: pending unless yes or no, exact repeats (same name and email) skipped. Ids come from the
         row, so two open apps add the same guests and the save merge keeps one copy. household joins a party whose value it is; other text starts a
         party that calls folded together share (they were all still waiting, so list_guests showed each one's text), with an id from the event, the
         first such call and the text, so two apps agree on it */
      if(r.kind === 'api' && p.op === 'add_guests' && Array.isArray(p.guests)){ const gs = plan.guests ||= [], txt = (v, n) => typeof v === 'string' || typeof v === 'number' ? String(v).trim().slice(0, n) : '', dk = (n, e) => n.toLowerCase() + '\n' + e.toLowerCase();
        const have = new Set(gs.map(g => dk(txt(g.name, 200), txt(g.email, 200)))), hid = s => { const k = s.toLowerCase(); if(!hh.has(k)) hh.set(k, 'ha' + lvH(ev + '|' + r.id + '|' + k)); return hh.get(k); }, via = txt(p.via, 40) || 'the API'; let n = 0;
        p.guests.slice(0, 500).forEach((x, xi) => { if(!x || typeof x !== 'object' || Array.isArray(x) || Object.keys(x).some(bad)) return; const name = txt(x.name, 80), email = txt(x.email, 120), id = 'a' + r.id + '-' + xi; if(!name || gIds.has(id) || have.has(dk(name, email))) return; have.add(dk(name, email));
          const meal = txt(x.meal, 60), h = txt(x.household, 80), g = {id, name, group:'', email, phone:txt(x.phone, 40), meal:MEALS.find(m => m.toLowerCase() === meal.toLowerCase()) || meal, rsvp:x.rsvp === 'yes' || x.rsvp === 'no' ? x.rsvp : 'pending', tableId:null, seat:null};
          if(h) g.household = gs.some(o => o.household === h) ? h : hid(h); gs.push(g); gIds.add(id); n++; });
        if(n){ gAdd += n; gVia = via; (plan.activity ||= []).unshift({at, text:`Added ${n} guest${n > 1 ? 's' : ''} from ${via}`, who:via === 'the API' ? 'API' : via}); } } });
      plan.linkApplied = [...seen, ...fresh.map(r => r.id)].slice(-2000); };
    let saved = false;
    try { if(open){ if(fresh.length){ const B0 = cl31(state); apply(); applyRemote31(B0, plan, ev); save(); try { renderAll(); } catch(e){} if(stOpen()) openStaff(); } saved = !!(await saveToPortal(true)); } else { if(fresh.length) apply(); await store.save(ev, plan, summaryFor(plan)); saved = true; } } catch(e){ saved = false; }
    if(!saved) continue;   /* left for the next pass; phones keep seeing them meanwhile */
    tsCheck(await TSB.sb.from('link_updates').update({applied:true}).in('id', rs.map(r => r.id)));
    if(added && open) toast(added > 1 ? `${added} song requests from the website` : `Song request from the website: ${(fresh.find(r => r.kind === 'song') || {payload:{}}).payload.song || ''}`);
    if(gAdd && open) toast(`Added ${gAdd} guest${gAdd > 1 ? 's' : ''} from ${gVia}`);
