  const chip = (k, label) => `<button class="pill" data-townf="${esc(k)}" aria-pressed="${taskOwner === k}" style="cursor:pointer;border:1px solid ${taskOwner === k ? 'var(--accent)' : 'transparent'}">${esc(label)}</button>`;
  grid.insertAdjacentHTML('beforebegin', `<div class="g-sum" style="margin:10px 0 0"><span class="muted" style="font-size:12px">Who’s on it:</span>${chip('', 'Everyone')}${staffList.map(s => chip(s.id, `${s.name} · ${cnt(s.id)}`)).join('')}${chip('-', `Unassigned · ${cnt('')}`)}</div>`);
