function qkScrollTo(view, label){ setTimeout(() => { const root = $('#view-' + view); if(!root) return; const el = [...root.querySelectorAll('.eyebrow, h2, h4')].find(x => x.textContent.trim() === label); if(el) (el.closest('section, .inv-card') || el).scrollIntoView({block:'start', behavior:'smooth'}); }, 120); }
