/* Warehouse: a printable day sheet for the crew (pull by SKU, bag by event, count returns, sign off) */
async function warehouseDayPDF(iso){
  if(!pdfReady()){ toast('The PDF tool didn’t load. Use Copy pull list instead.'); return; }
  const evs = warehouseEvents(), out = evs.filter(e => e.out === iso), back = evs.filter(e => e.back === iso); if(!out.length && !back.length){ toast('Nothing going out or coming back that day.'); return; }
  const P = pdfDoc(), box = '[   ]', sku = k => { const s = skusFor(k)[0]; return s ? s.sku : ''; };
  P.header('Warehouse day sheet', shortFmt(iso));
  P.text(fmtDate(iso), {font:'times', size:18, gap:2});
  P.text([out.length ? `${out.length} going out · ${out.reduce((a, e) => a + e.pieces, 0).toLocaleString()} pieces` : '', back.length ? `${back.length} coming back · ${back.reduce((a, e) => a + e.pieces, 0).toLocaleString()} pieces` : ''].filter(Boolean).join('   ·   '), {size:10, color:P.soft, gap:10});
  const rush = turnKeys(iso, out);
  if(rush.length) P.text(`${turnLabel()} on ${rush.length} item${rush.length > 1 ? 's' : ''}: ${rush.map(linenKeyText).join('; ')}. ${turnHint()}`, {size:9.5, style:'bold', color:[150, 90, 30], gap:10});
  if(out.length){
    const tot = new Map(); out.forEach(e => e.linens.forEach(([k, q]) => tot.set(k, (tot.get(k) || 0) + (+q || 0))));
    if(out.length > 1){ P.text('GOING OUT · TOTAL TO PULL', {size:8.5, style:'bold', color:P.gold, gap:4});
    P.table([{h:'Pulled', w:.1}, {h:'Qty', w:.1, align:'right'}, {h:'Item', w:.58}, {h:'SKU', w:.22}], [...tot].sort((a, b) => b[1] - a[1]).map(([k, q]) => [box, String(q), linenKeyText(k), sku(k)])); } else P.text('GOING OUT', {size:8.5, style:'bold', color:P.gold, gap:4});
    out.forEach(e => { P.need(70);
      P.text(`BAG FOR: ${e.name}${e.unsaved ? ' (not saved yet)' : ''}`, {size:11, style:'bold', gap:1});
      P.text([e.outTime ? 'Deliver ' + fmt12(e.outTime) : '', e.addr ? 'To ' + e.addr : '', e.contact ? 'Contact ' + e.contact : '', 'Back ' + (shortFmt(e.back) || e.back)].filter(Boolean).join('  ·  '), {size:9, color:P.soft, gap:4});
      P.table([{h:out.length > 1 ? 'Bagged' : 'Pulled', w:.1}, {h:'Qty', w:.1, align:'right'}, {h:'Item', w:.58}, {h:'SKU', w:.22}], [...e.linens].sort((a, b) => (+b[1] || 0) - (+a[1] || 0)).map(([k, q]) => [box, String(q), linenKeyText(k), sku(k)]), {gap:10}); });
  }
  if(back.length){
    P.need(60); P.text('COMING BACK · COUNT EACH LINE', {size:8.5, style:'bold', color:P.gold, gap:1});
    P.text('Back = pieces returned. Short = missing. Damaged = stained, burned or torn. Enter the counts on the event’s Order sheet afterward so charges and stock stay right.', {size:9, color:P.soft, gap:6});
    back.forEach(e => { P.need(70);
      P.text(`RETURN FROM: ${e.name}${e.unsaved ? ' (not saved yet)' : ''}`, {size:11, style:'bold', gap:1});
      P.text([e.backTime ? 'Pickup ' + fmt12(e.backTime) : '', e.addr ? 'At ' + e.addr : '', e.contact ? 'Contact ' + e.contact : ''].filter(Boolean).join('  ·  ') || ' ', {size:9, color:P.soft, gap:4});
      P.table([{h:'Item', w:.55}, {h:'Sent', w:.09, align:'right'}, {h:'Back', w:.12, align:'right'}, {h:'Short', w:.12, align:'right'}, {h:'Damaged', w:.12, align:'right'}], e.linens.map(([k, q]) => [linenKeyText(k), String(q), '____', '____', '____']), {gap:10}); });
  }
  if(back.length){ const loads = laundryLoads(back); if(loads.length){ P.need(80); P.text('LAUNDRY LOADS · AFTER THE COUNT', {size:8.5, style:'bold', color:P.gold, gap:1}); P.text('Sorted by fabric care, then color. Wash stained pieces apart and pre-treat wax and wine.', {size:9, color:P.soft, gap:6});
    P.table([{h:'Load', w:.2}, {h:'Pcs', w:.08, align:'right'}, {h:'What goes in', w:.42}, {h:'Care', w:.3}], loads.map(l => [l.name, l.pieces.toLocaleString(), l.items.map(([k, q]) => `${q} × ${linenKeyText(k)}`).join('\n'), l.care]), {gap:10}); } }
  P.need(70); P.y += 14; const cw = (P.W - 2*P.M - 40)/3;
  ['Pulled by', 'Checked by', back.length && !out.length ? 'Counted by' : 'Loaded by'].forEach((l, i) => { const x = P.M + i*(cw + 20); P.d.setDrawColor(...P.ink); P.d.setLineWidth(.6); P.d.line(x, P.y + 24, x + cw, P.y + 24); P.d.setFont('helvetica', 'normal'); P.d.setFontSize(8.5); P.d.setTextColor(...P.soft); P.d.text(`${l}  ·  time`, x, P.y + 36); });
  P.y += 44;
  P.footer(`${company.name || 'Warehouse'} · Day sheet ${iso}`); await P.save(`warehouse-${iso}.pdf`);
}
const _warehouseHTMLPdf = warehouseHTML; warehouseHTML = function(){
  return _warehouseHTMLPdf().replace(/(<div class="btn-row" style="margin:0;flex-wrap:nowrap">)(<button class="btn sm(?: ghost)?" data-wh(?:pull|back)="([\d-]+)")/g, '$1<button class="btn sm primary" data-whpdf="$3" title="A printable sheet for the crew: what to pull, a checklist per bag, returns to count and sign-off lines">Day sheet PDF</button>$2');
};
$('#view-inv').addEventListener('click', async e => { const b = e.target.closest('[data-whpdf]'); if(!b) return; b.disabled = true; try { await warehouseDayPDF(b.dataset.whpdf); } catch(err){ toast('Couldn’t make that PDF.'); } b.disabled = false; });

/* Reports: linen demand over the next 90 days, to see what earns its shelf space and what to buy */
let ldDays = 90;
function linenDemand(){
  const today = isoLocal(), end = shiftIso(today, ldDays), onHand = onHandMap();
  const evs = portalEvents.filter(e => e.status !== 'cancelled' && e.date && e.date >= today && e.date <= end && Array.isArray(e.linens) && e.linens.length);
  const rows = new Map(), add = (k) => rows.get(k) || rows.set(k, {k, pieces:0, events:0, booked:0, peak:0}).get(k);
  evs.forEach(e => e.linens.forEach(([k, q]) => { const r = add(k); r.pieces += +q || 0; r.events++; if(e.status === 'booked' || e.status === 'completed') r.booked++; }));
  evs.forEach(e => { const m = peakHeld(holdSpan(e), null, portalEvents); m.forEach((q, k) => { const r = rows.get(k); if(r && q > r.peak){ r.peak = q; r.peakOn = e.date; } }); });
  const list = [...rows.values()].map(r => Object.assign(r, {own:onHand.get(r.k) || 0})).map(r => Object.assign(r, {use:r.own ? r.peak/r.own : (r.peak ? Infinity : 0)})).sort((a, b) => b.pieces - a.pieces);
  const usedK = new Set(rows.keys()), idle = [...onHand].filter(([k, q]) => q > 0 && !usedK.has(k));
  return {evs, list, idleLines:idle.length, idleUnits:idle.reduce((a, [, q]) => a + q, 0), short:list.filter(r => r.peak > r.own)};
}
function linenDemandHTML(){
  const D = linenDemand(), seg = `<div class="seg">${[30, 90, 180].map(n => `<button data-lddays="${n}" aria-pressed="${ldDays === n}">${n} days</button>`).join('')}</div>`;
  const head = `<div style="display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:10px"><h4 class="pv-h4" style="margin:0">Linen demand · next ${ldDays} days</h4><div class="btn-row" style="margin:0">${seg}${D.short.length ? '<button class="btn sm" data-ldcopy="1" title="What to buy so every upcoming event is covered">Copy reorder list</button>' : ''}</div></div>`;
  if(!D.list.length) return `<div class="inv-card">${head}<p class="muted" style="margin:0">No saved events with linens in the next ${ldDays} days. As events are saved, this shows which linens are rented most, how close each comes to selling out, and what sits idle.</p></div>`;
  const pill = r => r.peak > r.own ? `<span class="pill warn">Short ${r.peak - r.own}</span>` : r.use >= .85 ? '<span class="pill caution">Tight</span>' : '<span class="pill ok">OK</span>';
  const bar = r => { const w = Math.min(100, Math.round((isFinite(r.use) ? r.use : 1)*100)); return `<span style="display:inline-block;width:90px;height:7px;border-radius:4px;background:var(--line);vertical-align:middle;overflow:hidden"><i style="display:block;height:100%;width:${w}%;background:${r.peak > r.own ? 'var(--warn)' : r.use >= .85 ? 'var(--accent)' : 'var(--ok)'}"></i></span> <span class="mono" style="font-size:11px">${isFinite(r.use) ? Math.round(r.use*100) + '%' : '—'}</span>`; };
  const shorts = D.list.filter(r => r.peak > r.own).sort((a, b) => (b.peak - b.own) - (a.peak - a.own)), shown = shorts.concat(D.list.filter(r => r.peak <= r.own).slice(0, Math.max(0, 12 - shorts.length)));
  return `<div class="inv-card">${head}
    <p class="muted" style="margin:0 0 10px;font-size:12.5px">${D.evs.length} saved event${D.evs.length > 1 ? 's' : ''} with linens (inquiries and proposals included). <b style="font-weight:600">Peak</b> is the most held at once, counting rental windows that overlap (delivery to return plus ${laundryDays()} laundry day${laundryDays() === 1 ? '' : 's'}), against what you own.</p>
    <div class="table-scroll"><table class="qty"><thead><tr><th>Linen</th><th class="num">Events</th><th class="num">Pieces out</th><th class="num">Peak</th><th class="num">Own</th><th>Peak use</th><th></th></tr></thead><tbody>${shown.map(r => `<tr><td>${esc(linenKeyText(r.k))}</td><td class="num">${r.events}${r.booked && r.booked < r.events ? ` <span class="muted" style="font-size:11px">(${r.booked} booked)</span>` : ''}</td><td class="num">${r.pieces.toLocaleString()}</td><td class="num" title="${r.peakOn ? 'Around ' + esc(shortFmt(r.peakOn)) : ''}">${r.peak.toLocaleString()}</td><td class="num">${r.own.toLocaleString()}</td><td style="white-space:nowrap">${bar(r)}</td><td>${pill(r)}</td></tr>`).join('')}</tbody></table></div>
    ${D.list.length > shown.length ? `<p class="muted" style="margin:8px 0 0;font-size:12px">${shorts.length ? `Short lines first, then the top ${shown.length - shorts.length} of ${D.list.length - shorts.length} other linens` : `Top ${shown.length} of ${D.list.length} linens`} by pieces rented.</p>` : ''}
    <p class="muted" style="margin:8px 0 0;font-size:12.5px">${D.idleLines ? `<b style="font-weight:600">${D.idleLines.toLocaleString()} stock line${D.idleLines > 1 ? 's' : ''} (${D.idleUnits.toLocaleString()} pieces)</b> aren’t on any saved event in this window. Good candidates for a promotion or for skipping on the next order.` : 'Every stock line is on at least one saved event in this window.'}</p></div>`;
}
const _reportsHTMLLD = reportsHTML; reportsHTML = function(){ return _reportsHTMLLD() + linenDemandHTML(); };
