/* linen rental: bill straight from the linen quote. Sets payments.totalOverride and, while nothing is paid yet, a deposit + balance schedule */
let billArm = null, billArmT;
function billFromQuote(){
  const q = quoteCalc(), Q = linenQuote(), total = Math.round(q.total); if(!q.lines.length || !total){ toast('Add linens to the quote first.'); return; }
  const cur = contractTotal(); if(cur > total*1.15 && billArm !== total){ billArm = total; clearTimeout(billArmT); billArmT = setTimeout(() => billArm = null, 6000); toast(`That replaces the ${money(cur)} contract total with the ${money(total)} linen quote. Click again to confirm.`); return false; } billArm = null;
  const P = payments(), anyPaid = P.schedule.some(s => s.paid), dep = clamp(Math.round(+Q.deposit || 0), 0, 100), today = isoLocal();
  let due = q.out ? shiftIso(q.out, -7) : (state.event.date ? shiftIso(state.event.date, -7) : today); if(!due || due < today) due = today;
  mutate(() => { P.totalOverride = total; logActivity(`Billing set from the linen quote: ${money(total)}`); if(anyPaid) return;
    P.schedule = dep >= 100 ? [{id:uid(), label:'Payment in full to reserve', pct:100, due:today, paid:null}]
      : dep <= 0 ? [{id:uid(), label:'Balance before delivery', pct:100, due, paid:null}]
      : [{id:uid(), label:`Deposit to reserve (${dep}%)`, pct:dep, due:today, paid:null}, {id:uid(), label:'Balance before delivery', pct:100 - dep, due, paid:null}]; });
  toast(anyPaid ? `Contract total set to ${money(total)}. Recorded payments were kept.` : `Payments set to ${money(total)}${dep > 0 && dep < 100 ? `: ${dep}% now, balance due ${shortFmt(due)}` : ''}.${secDep() ? ' The security deposit stays separate.' : ''}`);
}
