  const on = +payments().totalOverride === total, btn = on ? `<button class="btn sm" data-lqpay title="Payments already bill this quote">Open payments</button>` : `<button class="btn sm" data-billq title="Set the contract total and a deposit + balance schedule from this quote">Bill from this quote</button>`;
