/* ============ warehouse: returned linens sorted into wash loads (by fabric care, then color) ============ */
const WASH_LOADS = [
  ['special', 'Sequin, velvet & lace', 'Inside out in mesh bags, cold and gentle, air dry. No dryer, no iron on sequins.'],
  ['silky', 'Satin & chiffon', 'Cold and gentle, low heat or line dry, press on low.'],
  ['natural', 'Linen & burlap', 'On their own: burlap sheds and linen shrinks in high heat. Cold wash, medium dry, press damp.'],
  ['white', 'Whites & ivories', 'Warm wash, oxygen bleach for wine and wax. Keep away from any color.'],
  ['light', 'Lights & pastels', 'Cold wash, medium dry. Fold warm to cut down on pressing.'],
  ['dark', 'Darks & brights', 'Cold wash with a color catcher; reds and navies can bleed on the first washes.']];
function washLoad(k){
  const [, fab = '', hex = '#888888'] = String(k).split('|'), f = fab.toLowerCase();
  if(/sequin|velvet|lace/.test(f)) return 'special';
  if(/satin|chiffon/.test(f)) return 'silky';
  if(/linen|burlap/.test(f)) return 'natural';
  const [r, g, b] = hexToRgb(hex), sat = (Math.max(r, g, b) - Math.min(r, g, b))/255, L = lum(hex);
  return L > .7 && sat < .2 ? 'white' : L > .3 && sat < .5 ? 'light' : 'dark';
}
function laundryLoads(evs){
  const tot = new Map(); evs.forEach(e => e.linens.forEach(([k, q]) => tot.set(k, (tot.get(k) || 0) + (+q || 0))));
  return WASH_LOADS.map(([id, name, care]) => { const items = [...tot].filter(([k, q]) => q > 0 && washLoad(k) === id).sort((a, b) => b[1] - a[1]); return {id, name, care, items, pieces:items.reduce((a, [, q]) => a + q, 0)}; }).filter(l => l.items.length);
}
const _returnListTextWL = returnListText; returnListText = function(iso){
  const t = _returnListTextWL(iso); if(!t) return t; const loads = laundryLoads(warehouseEvents().filter(e => e.back === iso)); if(!loads.length) return t;
  return t.replace(/\n+$/, '') + '\n\n' + ['LAUNDRY LOADS · once counted (pieces sent; wash stained pieces apart and pre-treat)', ...loads.flatMap(l => ['', `${l.name.toUpperCase()} · ${l.pieces.toLocaleString()} pcs`, `  ${l.care}`, ...l.items.map(([k, q]) => `  ${String(q).padStart(4)} × ${linenKeyText(k)}`)])].join('\n');
};
/* ============ portal "This week": linen pickups from events that already happened ============ */
