  const today = isoLocal(), out1 = q.out || (state.event.date ? shiftIso(state.event.date, -1) : ''); if(!out1 || out1 < today || shiftIso(out1, -7) > today) return res;
  const key = 'linencount-' + out1, fs = followState(); if(fs[key] && (fs[key].done || (fs[key].until && fs[key].until > Date.now()))) return res;
  const cl = state.client || {}, first = cl.name ? firstName(cl.name) : 'there', nm = state.event.name || 'your rental', pcs = q.lines.reduce((a, l) => a + (+l.qty || 0), 0), dleft = Math.round((new Date(out1 + 'T00:00') - new Date(today + 'T00:00'))/864e5);
  const list = q.lines.map(l => `${l.qty} × ${capFirst(l.label)} (${l.size})`).join('\n');
  res.unshift({key, sev: dleft <= 2 ? 'warn' : 'caution', tag:'Rental', title:`Confirm the final linen count before delivery ${dleft === 0 ? 'today' : dleft === 1 ? 'tomorrow' : shortFmt(out1)}`, detail:`${pcs.toLocaleString()} pieces on the quote · colors, sizes, address and drop-off time`, to:cl.email, subject:`Confirming your linens for ${nm}`, action:'lquote',
    msg:`Hi ${first}, we’re getting your linens ready! Here is what we have for ${nm}:\n\n${list}\n\nDelivery: ${fmtDate(out1)}${q.outTime ? ' around ' + fmt12(q.outTime) : ''}${q.address ? ' to ' + q.address : ''}. Pickup: ${q.back ? fmtDate(q.back) : 'the day after'}${q.backTime ? ' around ' + fmt12(q.backTime) : ''}.\n\nCould you confirm the counts, colors and address, and let us know about any table changes? Thank you!${company.name ? '\n' + company.name : ''}`});
  return res;
