document.addEventListener('click', e => { const g = e.target.closest('#view-plan [data-fugo="lquote"]'); if(!g) return; e.stopPropagation(); openLinenQuote(); }, true);

/* ============ Reports: the linen rental side of the business ============ */
function linenBizHTML(){
  const Y = isoLocal().slice(0, 4), pcs = e => (e.linens || []).reduce((a, [, q]) => a + (+q || 0), 0), rev = e => +e.total || +e.budget || 0;
  const lo = portalEvents.filter(e => e.linenOnly && e.status !== 'cancelled'), won = lo.filter(wentOut), open = lo.filter(e => e.status === 'inquiry' || e.status === 'proposal');
  const yr = portalEvents.filter(e => wentOut(e) && (e.date || '').startsWith(Y)), m = new Map(); yr.forEach(e => (e.linens || []).forEach(([k, q]) => m.set(k, (m.get(k) || 0) + (+q || 0))));
  if(!lo.length && !m.size) return '';
  const sum = (a, f) => a.reduce((t, e) => t + f(e), 0), top = [...m].filter(([, q]) => q > 0).sort((a, b) => b[1] - a[1]).slice(0, 6), maxQ = Math.max(1, ...top.map(([, q]) => q));
  const tl = lo.length ? Math.round(won.length/lo.length*100) : 0;
  return `<div class="inv-card" id="lbiz-sec"><h4 class="pv-h4">Linen rentals <span class="muted" style="text-transform:none;letter-spacing:0">· linen-only orders, and the pieces every booked event used in ${Y}</span></h4>
    ${lo.length ? `<div class="inv-stats"><div class="stat"><b>${won.length}</b><span>rentals booked · ${tl}% of ${lo.length} quoted</span></div><div class="stat"><b>${money(sum(won, rev))}</b><span>rental revenue${won.length ? ' · ' + money(sum(won, rev)/won.length) + ' average' : ''}</span></div><div class="stat"><b>${open.length}</b><span>open quotes · ${money(sum(open, rev))}</span></div><div class="stat"><b>${sum(yr, pcs).toLocaleString()}</b><span>pieces out in ${Y}</span></div></div>` : ''}
    ${top.length ? `<p class="muted" style="font-size:12px;margin:10px 0 6px">Most rented in ${Y}, by pieces sent out (rental orders and full events). Worth keeping deep in stock.</p><div class="hbars">${top.map(([k, q]) => { const hex = String(k).split('|')[2] || '#999999'; return `<div style="grid-template-columns:minmax(120px,40%) 1fr 48px"><span title="${esc(capFirst(linenKeyText(k)))}"><i style="display:inline-block;width:10px;height:10px;border-radius:2px;margin-right:6px;vertical-align:-1px;background:${esc(hex)};border:1px solid var(--line)"></i>${esc(capFirst(linenKeyText(k)))}</span><i style="width:${q/maxQ*100}%;background:${esc(hex)};border:1px solid var(--line)"></i><b>${q.toLocaleString()}</b></div>`; }).join('')}</div>` : ''}</div>`;
}
const _reportsHTMLLB = reportsHTML; reportsHTML = function(){ const h = _reportsHTMLLB(), x = linenBizHTML(); if(!x) return h; const i = h.indexOf('<div class="inv-card" id="src-sec">'); return i < 0 ? h + x : h.slice(0, i) + x + h.slice(i); };
QUICK.push(['Linen rental report', 'events', () => { portalView = 'reports'; renderPortal(); setTimeout(() => { const el = $('#lbiz-sec'); if(el) el.scrollIntoView({block:'start', behavior:'smooth'}); }, 80); }]);

/* ============ warehouse: a ready reminder for each client whose linens are past their pickup day ============ */
