const vlFresh = (c, now) => !!c && c.status !== 'out' && Date.parse(c.checkedInAt || c.parkedAt) > now - VL_LIM.lockMin * 6e4;
const vlStartsWith = (s, p) => { const a = Array.from(s || ''), b = Array.from(p || ''); return b.every((ch, i) => a[i] === ch); };
