  if(t.closest('[data-vllang]')){ if(VD.tab === 'checkin') vlFormRead(); vlLS.set(VL_LANGK, vlLang() === 'es' ? 'en' : 'es'); vlDeskRender(); const b = vlPage().querySelector('[data-vllang]'); if(b) try { b.focus(); } catch(err){} return; }
