  const f = VD.form; if(!f) return;
  const col = t.closest('[data-vlcolor]'); if(col){ vlFormRead(); f.color = f.color === col.dataset.vlcolor ? '' : col.dataset.vlcolor; vlPage().querySelectorAll('[data-vlcolor]').forEach(b => b.setAttribute('aria-pressed', String(b.dataset.vlcolor === f.color))); return; }
  const zn = t.closest('[data-vlzone]'); if(zn){ vlFormRead(); f.zone = f.zone === zn.dataset.vlzone ? '' : zn.dataset.vlzone; vlPage().querySelectorAll('[data-vlzone]').forEach(b => b.setAttribute('aria-pressed', String(b.dataset.vlzone === f.zone))); return; }
