  if(card.id === 'ts-co-form' && tsSsoRelay(TSB.email) && !card.querySelector('.ts-sso-relay')){   /* a new account from Apple's private relay address */
    const p = card.querySelector('p.muted'); if(p) p.insertAdjacentHTML('afterend', '<p class="ts-join ts-sso-relay">You signed in with Apple and kept your email private, so this is a new account. Already use Tablescape with your email? Sign out below and sign in with that email instead.</p>'); return; }
  const mode = card.dataset.mode; if(!['welcome', 'signin', 'signup'].includes(mode) || card.querySelector('.ts-sso')) return;
  const html = `<div class="ts-sso" hidden><button type="button" class="ts-sso-apple" data-tssso="apple" hidden>${TS_SSO_APPLE}<span>Continue with Apple</span></button><button type="button" class="ts-sso-google" data-tssso="google" hidden>${TS_SSO_GOOGLE}<span>Continue with Google</span></button></div><p class="ts-sso-or" hidden>${mode === 'welcome' ? 'or' : 'or with email'}</p>`;
  const at = mode === 'welcome' ? card.querySelector('.ts-auth-choice') : card.querySelector('label.fld');
  if(at) at.insertAdjacentHTML('beforebegin', html); else return;
