  if(error || !data || !data.session) throw new Error('That sign-in didn’t work' + (error && error.message ? ': ' + error.message : '') + '. Try again.');
  const s = data.session, set = await TSB.sb.auth.setSession({access_token:s.access_token, refresh_token:s.refresh_token}); if(set.error) throw set.error;
  if(apple && s.provider_refresh_token) tsSsoFn({action:'apple-save', via:'web', refresh_token:s.provider_refresh_token}).catch(e => console.warn('Apple revoke token not kept', e));
