    let fresh = false; try { fresh = !!localStorage.getItem('ts-sso-code-verifier') && sessionStorage.getItem('ts-sso-launch') !== url; sessionStorage.setItem('ts-sso-launch', url); } catch(e){}
    if(!fresh) return;
    for(let n = 0; n < 60 && !TSB.sb; n++) await new Promise(ok => setTimeout(ok, 250));
    if(TSB.sb) tsSsoBack(url);
