const ts2CodesText = () => `Tablescape backup codes (${TSB.email || ''})\n${tsAuT('Each code works once.', 'Cada código sirve una vez.')}\n\n${(TS_2FA.codes || []).join('\n')}\n`;
document.addEventListener('change', e => { if(e.target && e.target.id === 'ts2-saved'){ const d = e.target.closest('.ts-auth-card, .ts2-body').querySelector('[data-ts2="codes-done"]'); if(d) d.disabled = !e.target.checked; } });
