  if(a === 'copycodes'){ copyText(ts2CodesText(), tsAuT('Backup codes copied', 'Códigos copiados')); return; }
  if(a === 'savecodes'){ const blob = new Blob([ts2CodesText()], {type:'text/plain'}), u = URL.createObjectURL(blob), l = document.createElement('a'); l.href = u; l.download = 'tablescape-backup-codes.txt'; document.body.appendChild(l); l.click(); l.remove(); setTimeout(() => URL.revokeObjectURL(u), 30000); return; }
