/* ---------- 4. Your account > Sign‑in and security ---------- */
/* a button that turns itself off while it works shows the spinner here too, like on the sign-in cards */
new MutationObserver(list => { for(const m of list){ const b = m.target; if(b.matches && b.matches('#ts2-modal button.primary[type=submit]')) tsAuBusy(b, b.disabled); } })
