          c.tiers.forEach((t,i)=>{if(i>=count)return;if(!old || n.shape!==old.shape)t.shape=n.shape;if(!old || n.layers[i].flavor!==old.layers[i].flavor)t.flavor=n.layers[i].flavor;if(!old || n.layers[i].filling!==old.layers[i].filling)t.filling=n.layers[i].filling;});
